window.designAudit = {"metadata":{"date":"2026-09-12","screens":117,"legacy_captures":32,"findings":2531,"defects":58,"proposals":2473,"legacy_findings":4,"screens_at_target":58,"mock_screens":26},"screens":[{"id":"absolute_positioning","baseline":"screenshot-baselines/screens/absolute_positioning_720p.png","summary":"Four positioning fixtures expose boundary and text-placement problems. Preserve absolute positioning examples; surrounding measurement aids are proposals.","findings":[{"id":"01","kind":"defect","area":"Translate example","observation":"Pink translate(300,10) overlaps the green label's final characters.","change":"Size the samples so both complete coordinate labels remain visible.","priority":"P1"},{"id":"02","kind":"defect","area":"Corner-pinning right edge","observation":"TR and BR extend beyond the inset demo well.","change":"Compute right anchors from the actual measured well width.","priority":"P2"},{"id":"03","kind":"proposal","area":"Corner-pinning labels","observation":"TL, TR, BL and BR require interpreting abbreviations.","change":"Add an external legend spelling out the four corners.","priority":"P2"},{"id":"04","kind":"proposal","area":"Corner-pinning bounds","observation":"The well's right boundary disappears behind the corner blocks.","change":"Outline the reference rectangle independently of its children.","priority":"P2"},{"id":"05","kind":"proposal","area":"Corner-pinning geometry","observation":"Corner samples look wider than tall.","change":"Print measured width and height beneath the reference rectangle.","priority":"P2"},{"id":"06","kind":"proposal","area":"Corner-pinning spacing","observation":"The two left samples nearly fill the short well vertically.","change":"Increase the well height to make top versus bottom anchoring clearer.","priority":"P2"},{"id":"07","kind":"proposal","area":"Corner-pinning origin","observation":"The top-left block has no marked anchor point.","change":"Draw a small crosshair at the container origin.","priority":"P2"},{"id":"08","kind":"proposal","area":"Translate reference","observation":"The green and pink boxes have no origin or grid.","change":"Add reference ticks at x=0,100,300 outside the specimens.","priority":"P2"},{"id":"09","kind":"proposal","area":"Translate y offsets","observation":"Both translate labels show 10 without a visible vertical measurement.","change":"Add a 10-pixel offset bracket at the left edge.","priority":"P2"},{"id":"10","kind":"proposal","area":"Translate labels","observation":"Coordinate text uses the handwritten display face.","change":"Use a compact monospace face for numeric coordinates.","priority":"P2"},{"id":"11","kind":"proposal","area":"Title","observation":"The cyan title starts flush against its rounded panel edge.","change":"Inset the title text to align with the section headings.","priority":"P2"},{"id":"12","kind":"proposal","area":"Section headings","observation":"Four long technical headings are visually similar to specimen labels.","change":"Increase heading weight while keeping specimen text smaller.","priority":"P2"},{"id":"13","kind":"proposal","area":"Section numbering","observation":"Numbers share the same baseline and weight as full headings.","change":"Use a narrow numbered gutter for faster section scanning.","priority":"P2"},{"id":"14","kind":"proposal","area":"Correct-pattern caption","observation":"The first heading calls the pattern correct without stating the rule.","change":"Add a short note that offsets are relative to the demo container.","priority":"P2"},{"id":"15","kind":"proposal","area":"Flow labels","observation":"Flow A, B and C sit directly on the left edges of their blocks.","change":"Add consistent internal label padding.","priority":"P2"},{"id":"16","kind":"proposal","area":"Flow spacing","observation":"Large gaps between Flow A, B and C have no measurement cues.","change":"Annotate the space-around gaps below the row.","priority":"P2"},{"id":"17","kind":"proposal","area":"Overlay badge","observation":"BADGE is left aligned within a wide pink pill.","change":"Center the badge label with equal horizontal inset.","priority":"P2"},{"id":"18","kind":"proposal","area":"Overlay relationship","observation":"The badge crosses Flow C and the well without explaining its anchor.","change":"Add a leader from the badge to its container anchor.","priority":"P2"},{"id":"19","kind":"proposal","area":"Overlay layer","observation":"The overlay example does not identify its stacking order.","change":"Label the badge layer outside the colored blocks.","priority":"P2"},{"id":"20","kind":"proposal","area":"Percentage samples","observation":"30% and 20% blocks describe screen sizing but omit reference width.","change":"Display viewport width beside the section heading.","priority":"P2"},{"id":"21","kind":"proposal","area":"Percentage heights","observation":"Both blocks show 8% without an absolute height comparison.","change":"Add computed height text below the specimens.","priority":"P2"},{"id":"22","kind":"proposal","area":"Percentage labels","observation":"Text begins at each block's left boundary.","change":"Inset percentage labels by a consistent small padding.","priority":"P2"},{"id":"23","kind":"proposal","area":"Percentage reference","observation":"There is no visual scale for the unused half of screen width.","change":"Add a thin 0–100% ruler outside the samples.","priority":"P2"},{"id":"24","kind":"proposal","area":"Bottom space","observation":"A large empty band follows the fourth fixture.","change":"Use it for a compact coordinate-system legend.","priority":"P2"},{"id":"25","kind":"proposal","area":"Demo wells","observation":"Inset wells and outer section panels are close in tone.","change":"Add subtle well borders so measured container boundaries remain visible.","priority":"P2"}],"sha256":"5d431252bcb87f1bbd4a2a4d4f40cab3615323fec57c7e2661ae43107e3d87c3","evidence":"docs/design-audit/originals/absolute_positioning_720p.png","has_mock":false,"reference":null,"legacy":[]},{"id":"accessibility","baseline":"screenshot-baselines/screens/accessibility_720p.png","summary":"The screenshot demonstrates readable automatic and manual contrast. Recommendations improve evidence and scope of the claims rather than treating intentionally varied swatches as defects.","findings":[{"id":"01","kind":"proposal","area":"WCAG badge","observation":"Theme Passes WCAG AA does not name the checked color pairs.","change":"Add the number of validated theme pairs under the badge.","priority":"P2"},{"id":"02","kind":"proposal","area":"WCAG badge scope","observation":"The badge reads like approval of the entire interface.","change":"Rename it to Theme color pairs pass AA contrast.","priority":"P2"},{"id":"03","kind":"proposal","area":"WCAG threshold","observation":"No required contrast ratio appears beside the badge.","change":"Show the threshold used for normal text.","priority":"P2"},{"id":"04","kind":"proposal","area":"Manual column heading","observation":"Without Automatic Contrast describes implementation only.","change":"Add a subtitle saying text colors were chosen manually.","priority":"P2"},{"id":"05","kind":"proposal","area":"Automatic column heading","observation":"With Automatic Contrast offers no selection rule.","change":"Add a short dark-or-light text explanation.","priority":"P2"},{"id":"06","kind":"proposal","area":"Dark manual sample","observation":"Works Fine is vague compared with the neighboring labels.","change":"Use Manual light text for parallel labeling.","priority":"P2"},{"id":"07","kind":"proposal","area":"Dark sample boundary","observation":"The dark manual tile blends into the surrounding panel.","change":"Add a neutral outline outside the test color area.","priority":"P2"},{"id":"08","kind":"proposal","area":"Dark automatic boundary","observation":"The dark automatic tile also lacks a clear extent.","change":"Outline its bounds with the same reference stroke.","priority":"P2"},{"id":"09","kind":"proposal","area":"Light pair","observation":"The two light samples look identical without a result annotation.","change":"Show chosen foreground values below each tile.","priority":"P2"},{"id":"10","kind":"proposal","area":"Manual note","observation":"Manual text color applied is detached from its two samples.","change":"Place it in the manual column footer with consistent inset.","priority":"P2"},{"id":"11","kind":"proposal","area":"Automatic note","observation":"Automatically picks best contrast uses a bright accent unlike the manual footer.","change":"Give both explanatory footers equal typographic emphasis.","priority":"P2"},{"id":"12","kind":"proposal","area":"Swatch heading","observation":"Various Backgrounds offers no description of the two rows.","change":"Label the rows Light backgrounds and Dark backgrounds.","priority":"P2"},{"id":"13","kind":"proposal","area":"Swatch identity","observation":"All sixteen tiles have the same Auto label.","change":"Give each tile a compact background color identifier.","priority":"P2"},{"id":"14","kind":"proposal","area":"Swatch foreground","observation":"Black or white text choices are visible but unnamed.","change":"Add the chosen foreground value to each swatch caption.","priority":"P2"},{"id":"15","kind":"proposal","area":"Swatch ratios","observation":"No tile exposes its measured contrast.","change":"Show a ratio beneath each test tile.","priority":"P2"},{"id":"16","kind":"proposal","area":"Swatch ordering","observation":"The bright row changes hue without a visible sorting principle.","change":"Group or order samples by luminance and label the order.","priority":"P2"},{"id":"17","kind":"proposal","area":"Dark row pairing","observation":"Dark swatches do not visually establish pairs with the row above.","change":"Add column labels if pairs are intended.","priority":"P2"},{"id":"18","kind":"proposal","area":"Swatch gutters","observation":"Horizontal gaps are much smaller than the gap separating the comparison columns.","change":"Use a clearer equal grid gutter around the swatch set.","priority":"P2"},{"id":"19","kind":"proposal","area":"Swatch type","observation":"Small widely tracked lettering makes color comparisons harder to read.","change":"Use a conventional text face inside the test swatches.","priority":"P2"},{"id":"20","kind":"proposal","area":"Title style","observation":"The title uses a different face from the rest of the panel.","change":"Use one readable family with weight differences for hierarchy.","priority":"P2"},{"id":"21","kind":"proposal","area":"Footer claim","observation":"Text always remains readable is an absolute statement.","change":"Limit the wording to the tested foreground choices.","priority":"P2"},{"id":"22","kind":"proposal","area":"Footer placement","observation":"The footer sits well below the swatches with a large blank gap.","change":"Move the explanation closer to the grid.","priority":"P2"},{"id":"23","kind":"proposal","area":"Separators","observation":"Both divider lines are inset farther than the column content.","change":"Align separator ends to the content grid.","priority":"P2"},{"id":"24","kind":"proposal","area":"Theme identity","observation":"The panel does not name the theme being validated.","change":"Add the theme name alongside validation status.","priority":"P2"},{"id":"25","kind":"proposal","area":"Test context","observation":"The demonstration gives no sample font size near its AA claim.","change":"Display the text size used in the contrast specimens.","priority":"P2"}],"sha256":"f27180479a4b3c01ce4b29d9c698c8396e21114d8db2cf9bfecc393689a11a31","evidence":"docs/design-audit/originals/accessibility_720p.png","has_mock":false,"reference":null,"legacy":[]},{"id":"adaptive_scaling","baseline":"screenshot-baselines/screens/adaptive_scaling_720p.png","summary":"The active wide 100% state is legible, but small diagnostic text and unmeasured examples make scaling difficult to evaluate.","findings":[{"id":"01","kind":"proposal","area":"Logical dimensions","observation":"Logical: 1280x720 is tiny beside the scale controls.","change":"Increase diagnostic text to a readable body size.","priority":"P2"},{"id":"02","kind":"proposal","area":"Header status","observation":"Adaptive 100% repeats the mode and scale controls.","change":"Use the header slot for physical viewport dimensions.","priority":"P2"},{"id":"03","kind":"proposal","area":"Mode button","observation":"Mode: Adaptive does not signal that another mode exists.","change":"Add a change-mode indicator and name the alternate mode in helper text.","priority":"P2"},{"id":"04","kind":"proposal","area":"Scale decrement","observation":"The minus button contains no scale-step hint.","change":"Label the scale control group with its increment.","priority":"P2"},{"id":"05","kind":"proposal","area":"Scale readout","observation":"100% is styled much like its neighboring buttons.","change":"Give the numeric readout a distinct non-action field treatment.","priority":"P2"},{"id":"06","kind":"proposal","area":"Pixel card description","observation":"This card is 280x160 px is extremely small.","change":"Increase its text size and align it to the card heading.","priority":"P2"},{"id":"07","kind":"proposal","area":"Pixel color squares","observation":"Four colored blocks have no dimensions shown.","change":"Add width-by-height captions outside each square.","priority":"P2"},{"id":"08","kind":"proposal","area":"Pixel square comparison","observation":"Color is the only distinction among identical-size samples.","change":"Label their intended comparison explicitly.","priority":"P2"},{"id":"09","kind":"proposal","area":"Pixel buttons","observation":"Button A and Button B do not identify their sizing rule.","change":"Use labels that include their fixed pixel dimensions.","priority":"P2"},{"id":"10","kind":"proposal","area":"Button widths","observation":"Both pixel buttons span nearly the full card.","change":"Show a measured width annotation below the pair.","priority":"P2"},{"id":"11","kind":"proposal","area":"Padding card","observation":"Padding: 14px all sides lacks visible dimension markers.","change":"Add four small padding brackets around Inner content area.","priority":"P2"},{"id":"12","kind":"proposal","area":"Padding inner text","observation":"Inner content area sits against the dark rectangle's left edge.","change":"Inset its label without changing the measured outer padding.","priority":"P2"},{"id":"13","kind":"proposal","area":"Expand heading","observation":"Expand & Flex does not define the 1x, 2x, 3x ratio.","change":"Add a brief ratio caption above the colored segments.","priority":"P2"},{"id":"14","kind":"proposal","area":"Expand segment boundaries","observation":"Red, amber and green segments touch directly.","change":"Add thin neutral dividers that preserve the measured flex widths.","priority":"P2"},{"id":"15","kind":"proposal","area":"Expand numeric labels","observation":"1x, 2x and 3x are small in tall blocks.","change":"Increase their size for distance comparison.","priority":"P2"},{"id":"16","kind":"proposal","area":"Expand explanation","observation":"The long explanation is tiny and widely tracked.","change":"Use larger text and a shorter two-line explanation.","priority":"P2"},{"id":"17","kind":"proposal","area":"Pixel comparison heading","observation":"screen_pct vs pixels omits the h720 sample shown below.","change":"Name all three sizing systems in the heading.","priority":"P2"},{"id":"18","kind":"proposal","area":"px specimen","observation":"px omits its configured magnitude.","change":"Label the specimen with its numeric pixel width.","priority":"P2"},{"id":"19","kind":"proposal","area":"h720 specimen","observation":"h720 is unexplained technical shorthand.","change":"Show its configured value and reference height in a caption.","priority":"P2"},{"id":"20","kind":"proposal","area":"scr% specimen","observation":"scr% does not state its percentage.","change":"Show the exact screen percentage outside the block.","priority":"P2"},{"id":"21","kind":"proposal","area":"Comparison alignment","observation":"Three unequal specimens provide no common ruler.","change":"Add a horizontal pixel scale beneath them.","priority":"P2"},{"id":"22","kind":"proposal","area":"Breakpoint chips","observation":"narrow, medium, wide and short mix width and height categories.","change":"Separate width breakpoints from height breakpoints.","priority":"P2"},{"id":"23","kind":"proposal","area":"Active wide chip","observation":"The wide state is communicated mainly by a blue fill.","change":"Add a checkmark or Active suffix.","priority":"P2"},{"id":"24","kind":"proposal","area":"Breakpoint thresholds","observation":"No width or height thresholds appear beside the chips.","change":"Show the numeric threshold for each breakpoint.","priority":"P2"},{"id":"25","kind":"proposal","area":"Empty lower area","observation":"Most of the bottom fifth is unused.","change":"Add a compact before-and-after size table for the visible examples.","priority":"P2"}],"sha256":"a44d5a368be19a39854736506d6af2265b579ebbeb07a5a5a3b55b6dfcfd16e3","evidence":"docs/design-audit/originals/adaptive_scaling_720p.png","has_mock":false,"reference":null,"legacy":[]},{"id":"advanced_modals","baseline":"screenshot-baselines/screens/advanced_modals_720p.png","summary":"Only the launcher is captured. Sixteen defensible improvements address its sparse composition and discoverability; modal interiors and behavior are outside this screenshot's evidence.","findings":[{"id":"01","kind":"proposal","area":"Title bar","observation":"Advanced Modals starts directly at the blue strip's left edge.","change":"Add consistent text inset.","priority":"P2"},{"id":"02","kind":"proposal","area":"Title hierarchy","observation":"The heading occupies a full-width strip despite little supporting content.","change":"Add one sentence describing the four examples beneath it.","priority":"P2"},{"id":"03","kind":"proposal","area":"Outer canvas","observation":"A black border surrounds the navy page with uneven apparent margins.","change":"Center the page within equal outer margins.","priority":"P2"},{"id":"04","kind":"proposal","area":"Header gap","observation":"A large empty gap separates the title from the first launcher row.","change":"Reduce it to the normal section spacing.","priority":"P2"},{"id":"05","kind":"proposal","area":"Row gap","observation":"The two button rows are separated by about a button-height of empty space.","change":"Use a compact two-column card grid.","priority":"P2"},{"id":"06","kind":"proposal","area":"Login launcher","observation":"Login Form offers no hint of the demonstrated validation.","change":"Add a caption identifying required-field validation.","priority":"P2"},{"id":"07","kind":"proposal","area":"Wizard launcher","observation":"Multi-Step Wizard gives no visible step count.","change":"Show a Three-step setup caption.","priority":"P2"},{"id":"08","kind":"proposal","area":"Settings launcher","observation":"Settings Panel does not identify its control types.","change":"Add a short caption naming the visible settings categories.","priority":"P2"},{"id":"09","kind":"proposal","area":"Feedback launcher","observation":"Feedback Form gives no indication of its example purpose.","change":"Add a brief rating-and-comment caption.","priority":"P2"},{"id":"10","kind":"proposal","area":"Launcher colors","observation":"Blue, ochre, green and dusty red assign unrelated meanings.","change":"Use a shared action style with small category accents.","priority":"P2"},{"id":"11","kind":"proposal","area":"Button shape","observation":"Square buttons sit inside strongly rounded row panels.","change":"Choose a deliberate shared corner system for launchers and panels.","priority":"P2"},{"id":"12","kind":"proposal","area":"Button balance","observation":"Very wide gaps separate paired actions.","change":"Bring each button and its description into a single card.","priority":"P2"},{"id":"13","kind":"proposal","area":"Launch verbs","observation":"All four labels are nouns.","change":"Prefix them with Open to clarify the immediate action.","priority":"P2"},{"id":"14","kind":"proposal","area":"Status instruction","observation":"Open a modal above to get started is small inside a wide strip.","change":"Increase the instruction size and align it to the grid.","priority":"P2"},{"id":"15","kind":"proposal","area":"Status strip inset","observation":"The instruction starts flush against its background edge.","change":"Add horizontal padding equal to the title inset.","priority":"P2"},{"id":"16","kind":"proposal","area":"Default screenshot state","observation":"No modal specimen appears in the baseline.","change":"Provide a separate clearly labeled example-open baseline alongside this launcher.","priority":"P2"}],"sha256":"de1d0ba753e60e3640e31973637edbe78b25c09823a213873115e97c5f86029c","evidence":"docs/design-audit/originals/advanced_modals_720p.png","examples":[{"id":"login_validation","label":"Current example: login validation","path":"docs/design-audit/examples/advanced_modals_login_validation_720p.png"},{"id":"wizard_step1","label":"Current example: wizard setup","path":"docs/design-audit/examples/advanced_modals_wizard_step1_720p.png"},{"id":"settings_open","label":"Current example: settings","path":"docs/design-audit/examples/advanced_modals_settings_open_720p.png"},{"id":"feedback_open","label":"Current example: feedback","path":"docs/design-audit/examples/advanced_modals_feedback_open_720p.png"}],"has_mock":false,"reference":null,"legacy":[]},{"id":"aim_chat","baseline":"screenshot-baselines/screens/aim_chat_720p.png","summary":"The retro desktop is coherent and matches the mock's deliberate HTTP-log example. Proposals refine user-facing content, period-appropriate iconography and hierarchy.","findings":[{"id":"01","kind":"proposal","area":"Conversation history","observation":"The mock's HTTP GET/POST example interrupts the conversation between messages and its timestamp.","change":"Move the developer-log specimen into a separately labeled demo pane.","priority":"P2"},{"id":"02","kind":"proposal","area":"Desktop computer icon","observation":"My Computer uses an empty square outline.","change":"Replace it with a recognizable period-style computer bitmap.","priority":"P2"},{"id":"03","kind":"proposal","area":"Desktop folder icon","observation":"My Documents uses an outlined parallelogram.","change":"Use a folder icon consistent with the runner artwork.","priority":"P2"},{"id":"04","kind":"proposal","area":"Window controls","observation":"Maximize is rendered as literal [] text.","change":"Draw a small square window glyph.","priority":"P2"},{"id":"05","kind":"proposal","area":"Title minimize","observation":"The minimize character appears as text at the bottom of a tiny control.","change":"Use a centered pixel-aligned minimize line.","priority":"P2"},{"id":"06","kind":"proposal","area":"Menu rows","observation":"Each menu item looks like a raised command button.","change":"Use flat menu labels until selected, matching the mock's menu bar.","priority":"P2"},{"id":"07","kind":"proposal","area":"Active window","observation":"Both title bars use equally vivid blue gradients.","change":"Give the inactive buddy window a subdued title bar.","priority":"P2"},{"id":"08","kind":"proposal","area":"Buddy groups","observation":"v and > are used as disclosure markers.","change":"Use consistent small triangle glyphs aligned in one column.","priority":"P2"},{"id":"09","kind":"proposal","area":"Buddy count","observation":"Buddies (3/8) does not explain the denominator.","change":"Use a compact online/total caption in the group header.","priority":"P2"},{"id":"10","kind":"proposal","area":"Offline group","observation":"Offline (12) lacks the count format used above it.","change":"Use one consistent count convention across groups.","priority":"P2"},{"id":"11","kind":"proposal","area":"Buddy selection","observation":"SmarterChild's selected row starts farther right than group labels.","change":"Retain indentation but add a small status icon column.","priority":"P2"},{"id":"12","kind":"proposal","area":"Buddy presence","observation":"Unselected buddy names carry no individual presence marker.","change":"Add compact online indicators beside each name.","priority":"P2"},{"id":"13","kind":"proposal","area":"Buddy action labels","observation":"IM and Chat appear side by side without visible distinction.","change":"Rename the group action to Chat room or clarify the distinction.","priority":"P2"},{"id":"14","kind":"proposal","area":"Availability bar","observation":"I'm Available resembles a text field.","change":"Add a small disclosure arrow to mark it as a status control.","priority":"P2"},{"id":"15","kind":"proposal","area":"Buddy footer banner","observation":"The large AOL banner has more contrast than the buddy list header.","change":"Reduce its height to return emphasis to contacts.","priority":"P2"},{"id":"16","kind":"proposal","area":"Chat identity","observation":"SmarterChild is repeated in the title, profile header and first line.","change":"Keep the profile name but reduce its red emphasis.","priority":"P2"},{"id":"17","kind":"proposal","area":"Warning level","observation":"Warning level: 0% occupies the far edge of the profile header.","change":"Align it with the presence row and reduce its visual priority.","priority":"P2"},{"id":"18","kind":"proposal","area":"Message spacing","observation":"The three short chat lines have substantial vertical spacing.","change":"Tighten line spacing to match a compact instant-message transcript.","priority":"P2"},{"id":"19","kind":"proposal","area":"Timestamp","observation":"Last message received at 2: 02 PM is faint gray on white.","change":"Darken the text enough to read at the existing small size.","priority":"P2"},{"id":"20","kind":"proposal","area":"Formatting toolbar","observation":"A, B, I, U, A, :) and / have unevenly understandable meanings.","change":"Use recognizable font, color, emoticon and link icons.","priority":"P2"},{"id":"21","kind":"proposal","area":"Toolbar grouping","observation":"Text formatting and insertion actions form one undifferentiated row.","change":"Insert narrow separators between formatting and insertion groups.","priority":"P2"},{"id":"22","kind":"proposal","area":"Composer label","observation":"Send to: SmarterChild is much smaller than message text.","change":"Increase the label slightly and align it with composer inset.","priority":"P2"},{"id":"23","kind":"proposal","area":"Composer placeholder","observation":"Type a message is light gray within a large empty white area.","change":"Increase placeholder contrast while keeping it secondary.","priority":"P2"},{"id":"24","kind":"proposal","area":"Send action","observation":"Send has the same weight as Warn and Block.","change":"Give Send the default-button outline and separate moderation actions.","priority":"P2"},{"id":"25","kind":"proposal","area":"Connection footer","observation":"Direct Connection Established (local demo) is tiny at the bottom edge.","change":"Use a readable status line with a small connection indicator.","priority":"P2"}],"sha256":"8bb37a0d438af6d0320177bf5224f6efe12158ac3004a185514ad5de21cb847b","evidence":"docs/design-audit/originals/aim_chat_720p.png","examples":[{"id":"developer_log","label":"Current example: developer log pane","path":"docs/design-audit/examples/aim_chat_developer_log_720p.png"}],"has_mock":true,"reference":null,"legacy":[]},{"id":"alpha_blend_repro","baseline":"screenshot-baselines/screens/alpha_blend_repro_720p.png","summary":"Fading and disappearance under increasingly opaque overlays are intentional. Twenty presentation improvements are defensible; no blend failure is inferred from these fixtures.","findings":[{"id":"01","kind":"proposal","area":"Title claim","observation":"The heading says text should stay readable through the wash, including opaque rows.","change":"Qualify the expectation by opacity range.","priority":"P2"},{"id":"02","kind":"proposal","area":"First section heading","observation":"The full with_custom_background expression is tiny.","change":"Use a readable monospace caption above the fixture.","priority":"P2"},{"id":"03","kind":"proposal","area":"Second section heading","observation":"with_opacity appears in small handwritten lettering.","change":"Use the same monospace heading treatment as the first section.","priority":"P2"},{"id":"04","kind":"proposal","area":"Alpha units","observation":"32 through 255 have no visible alpha-unit label.","change":"Label the right column Alpha / 255.","priority":"P2"},{"id":"05","kind":"proposal","area":"Opacity units","observation":"15% through 100% lack a column heading.","change":"Label that column Overlay opacity.","priority":"P2"},{"id":"06","kind":"proposal","area":"Opaque alpha row","observation":"The final blue row has no visible specimen text, as expected.","change":"Add an external Opaque reference annotation.","priority":"P2"},{"id":"07","kind":"proposal","area":"Opaque opacity row","observation":"The 100% row is also intentionally blank.","change":"Label it Expected complete occlusion outside the overlay.","priority":"P2"},{"id":"08","kind":"proposal","area":"Unwashed reference","observation":"Every text sample is covered by some overlay.","change":"Add one zero-opacity reference row.","priority":"P2"},{"id":"09","kind":"proposal","area":"Underlying text","observation":"The pangram is printed only inside the tested wash.","change":"Repeat the reference text outside the fixtures.","priority":"P2"},{"id":"10","kind":"proposal","area":"Row labels","observation":"Numeric values are very small and far from the specimen start.","change":"Increase their size and use aligned tabular numerals.","priority":"P2"},{"id":"11","kind":"proposal","area":"Row padding","observation":"Pangram text starts flush with the wash's left boundary.","change":"Add consistent text inset without changing the overlay extent.","priority":"P2"},{"id":"12","kind":"proposal","area":"Row gaps","observation":"Several blue rows visually merge together.","change":"Use equal narrow neutral gutters between all rows.","priority":"P2"},{"id":"13","kind":"proposal","area":"Cross-method comparison","observation":"The alpha and opacity sections use different sample values.","change":"Add one matched-value pair for direct comparison.","priority":"P2"},{"id":"14","kind":"proposal","area":"Overlay color","observation":"The blue test color is named only in code syntax.","change":"Add a small labeled RGB swatch outside the test region.","priority":"P2"},{"id":"15","kind":"proposal","area":"Backing surface","observation":"The black background's role is not named.","change":"Label the surface over which alpha is being composited.","priority":"P2"},{"id":"16","kind":"proposal","area":"Expected result","observation":"The two methods have no nearby explanation of their expected relationship.","change":"Add a one-line equivalence note.","priority":"P2"},{"id":"17","kind":"proposal","area":"Text foreground","observation":"The source text color is not stated.","change":"Show its foreground value beside the untouched reference.","priority":"P2"},{"id":"18","kind":"proposal","area":"Section grouping","observation":"Two long stacks run almost edge to edge.","change":"Place each stack in an outlined test region with a shared label gutter.","priority":"P2"},{"id":"19","kind":"proposal","area":"Lower empty area","observation":"The lower quarter contains no interpretive aid.","change":"Use a compact expected-versus-observed comparison legend.","priority":"P2"},{"id":"20","kind":"proposal","area":"Capture context","observation":"The reproduction omits renderer information in the visible frame.","change":"Add a small diagnostic footer with renderer and viewport.","priority":"P2"}],"sha256":"f3a03b7ef25b26fbf8f6ee230b471a13b1addd557845f10c811028254ac6a2e9","evidence":"docs/design-audit/originals/alpha_blend_repro_720p.png","has_mock":false,"reference":null,"legacy":[]},{"id":"angry_birds_settings","baseline":"screenshot-baselines/screens/angry_birds_settings_720p.png","summary":"The baseline closely follows the approved playful settings mock. Findings are design refinements, not rendering failures.","findings":[{"id":"01","kind":"proposal","area":"Audio selected tab","observation":"AUDIO relies on green fill to distinguish it from blue tabs.","change":"Add a small selected underline or check marker.","priority":"P2"},{"id":"02","kind":"proposal","area":"Vibration state","observation":"The OFF icon looks disabled while MUSIC and SOUND look enabled.","change":"Give off-but-interactive controls an explicit toggle marker.","priority":"P2"},{"id":"03","kind":"proposal","area":"State captions","observation":"ON and OFF are much smaller than MUSIC, SOUND and VIBRATION.","change":"Increase state caption size and weight.","priority":"P2"},{"id":"04","kind":"proposal","area":"Sound wording","observation":"SOUND can include the separate music setting.","change":"Rename it SOUND EFFECTS.","priority":"P2"},{"id":"05","kind":"proposal","area":"Vibration icon","observation":"The phone is tilted and flanked by marks at different angles.","change":"Use a more balanced vibration glyph.","priority":"P2"},{"id":"06","kind":"proposal","area":"Music icon","observation":"The note occupies less width than the speaker icon.","change":"Normalize icon optical size within all three buttons.","priority":"P2"},{"id":"07","kind":"proposal","area":"Close control","observation":"The red close button overlaps the outer board edge.","change":"Bring it slightly inward to preserve a consistent safe margin.","priority":"P2"},{"id":"08","kind":"proposal","area":"Close emphasis","observation":"Close is the strongest red object on a non-destructive screen.","change":"Soften the red or reduce its size relative to confirmation.","priority":"P2"},{"id":"09","kind":"proposal","area":"Footer action order","observation":"OK appears before CANCEL and APPLY in a right-aligned group.","change":"Place the primary confirmation at the far right.","priority":"P2"},{"id":"10","kind":"proposal","area":"OK wording","observation":"OK does not explain whether settings save and close.","change":"Use DONE or SAVE & CLOSE.","priority":"P2"},{"id":"11","kind":"proposal","area":"Apply action","observation":"APPLY looks active in the unchanged default state.","change":"Visually distinguish its no-pending-changes state when applicable.","priority":"P2"},{"id":"12","kind":"proposal","area":"Cancel action","observation":"CANCEL has the same glossy emphasis as APPLY.","change":"Use a quieter secondary treatment.","priority":"P2"},{"id":"13","kind":"proposal","area":"Footer spacing","observation":"The footer actions cluster on the right while the left half is empty.","change":"Add a concise saved/unsaved status on the left.","priority":"P2"},{"id":"14","kind":"proposal","area":"Audio instruction","observation":"The tagline says little about the controls.","change":"Add a brief Tap an icon to toggle caption.","priority":"P2"},{"id":"15","kind":"proposal","area":"Tab content association","observation":"The audio controls sit far below the active tab.","change":"Reduce the gap between tab navigation and audio description.","priority":"P2"},{"id":"16","kind":"proposal","area":"Info tab wording","observation":"INFO is broad for credits, support and version details.","change":"Use ABOUT or a more descriptive label.","priority":"P2"},{"id":"17","kind":"proposal","area":"Board size","observation":"The board nearly fills the available height.","change":"Reduce outer ornament height to create breathing room.","priority":"P2"},{"id":"18","kind":"proposal","area":"Outer shadow","observation":"A heavy brown shadow adds a thick band under the board.","change":"Soften it to keep the footer visually lighter.","priority":"P2"},{"id":"19","kind":"proposal","area":"Tab shadows","observation":"Dark tab shadows compete with text outlines.","change":"Reduce shadow depth while retaining the toy-like style.","priority":"P2"},{"id":"20","kind":"proposal","area":"Button border color","observation":"Gray-green outlines sit beside warm brown panel outlines.","change":"Use a consistent warmer outline palette.","priority":"P2"},{"id":"21","kind":"proposal","area":"Audio label color","observation":"Brown labels are muted against the peach surface.","change":"Darken labels slightly for small-screen readability.","priority":"P2"},{"id":"22","kind":"proposal","area":"Separator","observation":"The thin footer rule is easy to lose against the peach background.","change":"Increase its contrast modestly.","priority":"P2"},{"id":"23","kind":"proposal","area":"Background blocks","observation":"Stacked dark blocks on the right remain visually prominent.","change":"Blur or dim them further behind the modal.","priority":"P2"},{"id":"24","kind":"proposal","area":"Bottom white line","observation":"An isolated pale line spans much of the screen below the board.","change":"Remove it or make its purpose clear as a device indicator.","priority":"P2"},{"id":"25","kind":"proposal","area":"Behind-status context","observation":"The mock includes heart and currency status behind the board, absent here.","change":"Restore subdued game context above the panel if matching the reference remains the target.","priority":"P2"}],"sha256":"d40ee477215dcc5d20e24691ede3c4b334571f1536ea3cb5f834115683cb2b12","evidence":"docs/design-audit/originals/angry_birds_settings_720p.png","examples":[{"id":"pending","label":"Current example: Unsaved audio settings","path":"docs/design-audit/examples/angry_birds_pending_720p.png"},{"id":"general","label":"Current example: General settings","path":"docs/design-audit/examples/angry_birds_general_720p.png"},{"id":"language","label":"Current example: Language selection","path":"docs/design-audit/examples/angry_birds_language_720p.png"}],"has_mock":true,"reference":"inspiration/example_angry_birds.jpg","legacy":[]},{"id":"animation_basic","baseline":"screenshot-baselines/screens/animation_basic_720p.png","summary":"The three animations are captured at their endpoints. Eighteen grounded proposals improve comparison; this image does not establish motion defects.","findings":[{"id":"01","kind":"proposal","area":"Header location","observation":"A large empty region sits above Animation Basics.","change":"Move the header upward and reclaim space for diagnostics.","priority":"P2"},{"id":"02","kind":"proposal","area":"Title/subtitle bands","observation":"Title and subtitle occupy separate touching rounded strips.","change":"Combine them into one padded header block.","priority":"P2"},{"id":"03","kind":"proposal","area":"Main specimen group","observation":"The three examples occupy a small area amid large gaps.","change":"Use three equal cards with shared alignment.","priority":"P2"},{"id":"04","kind":"proposal","area":"Slide label order","observation":"Subtitle says Fade, Slide, Scale while columns show Slide, Fade, Scale.","change":"Match subtitle order to the actual columns.","priority":"P2"},{"id":"05","kind":"proposal","area":"Slide measurement","observation":"x offset: 0px shows only the endpoint.","change":"Add start and end values in a caption.","priority":"P2"},{"id":"06","kind":"proposal","area":"Slide reference","observation":"The green square has no start-position marker.","change":"Draw a ghost origin outside its final bounds.","priority":"P2"},{"id":"07","kind":"proposal","area":"Fade reference","observation":"The blue square is fully opaque in the captured state.","change":"Add a checkerboard or reference swatch behind its test area.","priority":"P2"},{"id":"08","kind":"proposal","area":"Scale reference","observation":"The purple square has no visible original-size boundary.","change":"Draw a thin fixed bounds outline behind it.","priority":"P2"},{"id":"09","kind":"proposal","area":"Animation durations","observation":"No example displays its duration.","change":"Add a duration label below each animation name.","priority":"P2"},{"id":"10","kind":"proposal","area":"Animation easing","observation":"Bounce and other timing differences are not described.","change":"Display the easing name per specimen.","priority":"P2"},{"id":"11","kind":"proposal","area":"Metric chips","observation":"The slide chip is wider than the other metric chips.","change":"Use a shared width and aligned metric baseline.","priority":"P2"},{"id":"12","kind":"proposal","area":"Metric typography","observation":"The metrics use tiny handwritten numerals.","change":"Use readable tabular numeric text.","priority":"P2"},{"id":"13","kind":"proposal","area":"Animation phase","observation":"No status says the examples have completed.","change":"Show Ready, Running or Complete beside restart.","priority":"P2"},{"id":"14","kind":"proposal","area":"Restart label","observation":"Restart Animations is the only action but has low dark-teal emphasis.","change":"Increase its contrast relative to the specimen captions.","priority":"P2"},{"id":"15","kind":"proposal","area":"Restart position","observation":"The restart button is distant from the diagnostic row.","change":"Move it nearer the specimens while preserving separation.","priority":"P2"},{"id":"16","kind":"proposal","area":"Independent playback","observation":"One restart action serves all three examples.","change":"Add small individual replay controls for focused comparison.","priority":"P2"},{"id":"17","kind":"proposal","area":"Timeline","observation":"There is no way to compare progress in a static frame.","change":"Add a shared progress track with an elapsed-time marker.","priority":"P2"},{"id":"18","kind":"proposal","area":"Motion comparison","observation":"All endpoints are identical-size blocks.","change":"Provide a clearly labeled strip of start, midpoint and endpoint thumbnails.","priority":"P2"}],"sha256":"410e822f449b8551124446c7bc5b7518ac28580db5c842f1cdb607f7ffc91127","evidence":"docs/design-audit/originals/animation_basic_720p.png","examples":[{"id":"running","label":"Current example: All three playing","path":"docs/design-audit/examples/animation_basic_running_720p.png"},{"id":"scale_running","label":"Current example: Independent scale replay","path":"docs/design-audit/examples/animation_basic_scale_running_720p.png"}],"has_mock":false,"reference":null,"legacy":[]},{"id":"animation_declarative","baseline":"screenshot-baselines/screens/animation_declarative_720p.png","summary":"Eleven specimens combine triggers and motion types. Presentation proposals preserve the examples and add enough context to distinguish them in a settled screenshot.","findings":[{"id":"01","kind":"defect","area":"Appear label","observation":"Appear is flush against the orange tile's left edge while adjacent labels are centered.","change":"Center the label within the specimen.","priority":"P2"},{"id":"02","kind":"defect","area":"Pulse label","observation":"Pulse is flush against its orange tile's left edge.","change":"Apply the same centered alignment as neighboring examples.","priority":"P2"},{"id":"03","kind":"proposal","area":"Row grouping","observation":"Three rows have no section labels.","change":"Label trigger examples, motion examples and composition examples.","priority":"P2"},{"id":"04","kind":"proposal","area":"Hover tile","observation":"Hover names the trigger but not the resulting animation.","change":"Add a caption identifying hover scale.","priority":"P2"},{"id":"05","kind":"proposal","area":"Click tile","observation":"Click! names an input but hides its scale behavior.","change":"Use Click to scale with a compact parameter caption.","priority":"P2"},{"id":"06","kind":"proposal","area":"Both tile","observation":"Both! requires guessing which two inputs combine.","change":"Label it Hover + click.","priority":"P2"},{"id":"07","kind":"proposal","area":"Appear tile","observation":"Appear has no indication that it runs on entry.","change":"Add an On entry caption.","priority":"P2"},{"id":"08","kind":"proposal","area":"Slide tile","observation":"Slide does not state direction or distance.","change":"Show a direction arrow and travel distance.","priority":"P2"},{"id":"09","kind":"proposal","area":"Bounce tile","observation":"Bounce does not reveal its final scale or overshoot.","change":"Add a concise bounce parameter line.","priority":"P2"},{"id":"10","kind":"proposal","area":"Fade tile","observation":"Fade does not state that hover triggers it.","change":"Add the trigger beneath the tile.","priority":"P2"},{"id":"11","kind":"proposal","area":"Pulse tile","observation":"Pulse does not name its repeating behavior.","change":"Add Looping pulse under the specimen.","priority":"P2"},{"id":"12","kind":"proposal","area":"Slide+Rot tile","observation":"Rot abbreviates a motion unlike the full names above.","change":"Spell out Slide + rotate.","priority":"P2"},{"id":"13","kind":"proposal","area":"Rot+Slide tile","observation":"Rot+Slide looks almost identical to its neighboring composition.","change":"Add numbered transform-order labels.","priority":"P2"},{"id":"14","kind":"proposal","area":"All 3 tile","observation":"All 3 does not identify the included transforms.","change":"List Scale + slide + rotate.","priority":"P2"},{"id":"15","kind":"proposal","area":"Composition reference","observation":"The bottom row provides no fixed reference bounds.","change":"Add neutral outlines to expose transform offsets.","priority":"P2"},{"id":"16","kind":"proposal","area":"Third-row layout","observation":"Three bottom tiles sit left of the four-column grid's center.","change":"Center the composition group under its heading.","priority":"P2"},{"id":"17","kind":"proposal","area":"Fourth empty cell","observation":"An unmarked gap remains at the bottom right.","change":"Use it for a small transform-order legend.","priority":"P2"},{"id":"18","kind":"proposal","area":"Click count","observation":"Total clicks: 0 is separated from the clickable specimens.","change":"Place it beside the trigger section heading.","priority":"P2"},{"id":"19","kind":"proposal","area":"Click attribution","observation":"The total counter does not identify which tile was activated.","change":"Add a last-trigger label next to the counter.","priority":"P2"},{"id":"20","kind":"proposal","area":"Footer code","observation":"A full API expression is extremely small across the footer.","change":"Use a readable monospace code block.","priority":"P2"},{"id":"21","kind":"proposal","area":"Footer claim","observation":"Old: ~50 lines of boilerplate is not illustrated.","change":"Replace it with the exact current example configuration.","priority":"P2"},{"id":"22","kind":"proposal","area":"Subtitle","observation":"No boilerplate is promotional wording without explaining the concept.","change":"State that each tile declares its own trigger and animation.","priority":"P2"},{"id":"23","kind":"proposal","area":"Color meaning","observation":"Blue, green, purple and orange repeat with no stated mapping.","change":"Add a legend or assign colors consistently by trigger.","priority":"P2"},{"id":"24","kind":"proposal","area":"Replay discoverability","observation":"Entry animations have no visible restart control.","change":"Add a replay-entry-examples action.","priority":"P2"},{"id":"25","kind":"proposal","area":"Phase evidence","observation":"The static view cannot distinguish idle and completed examples.","change":"Add small phase labels outside the moving specimens.","priority":"P2"}],"sha256":"78051ceaed6f003df9e4b7f12ccdb51de0f13f58f9dc00a7ea560a919cd3a1f9","evidence":"docs/design-audit/originals/animation_declarative_720p.png","has_mock":false,"reference":null,"legacy":[]},{"id":"animation_interactive","baseline":"screenshot-baselines/screens/animation_interactive_720p.png","summary":"The screenshot shows three unpressed animation buttons. Eighteen distinct presentation proposals are supported; unseen press behavior is not judged.","findings":[{"id":"01","kind":"proposal","area":"Header placement","observation":"The title begins below a very large empty top area.","change":"Move it toward the top of the page.","priority":"P2"},{"id":"02","kind":"proposal","area":"Header strips","observation":"Title and instruction have touching rounded backgrounds.","change":"Combine them into one header card.","priority":"P2"},{"id":"03","kind":"proposal","area":"Instruction wording","observation":"Click buttons to see press animations does not explain the difference between them.","change":"Name the compared press effects.","priority":"P2"},{"id":"04","kind":"proposal","area":"Blue button","observation":"Click! gives no animation information.","change":"Label it with its press-scale amount.","priority":"P2"},{"id":"05","kind":"proposal","area":"Green button","observation":"Press! reads like a synonym of Click!.","change":"Use a label naming its distinct response.","priority":"P2"},{"id":"06","kind":"proposal","area":"Purple button","observation":"Tap! implies a different device without describing motion.","change":"Name the actual animation variant.","priority":"P2"},{"id":"07","kind":"proposal","area":"Specimen captions","observation":"None of the buttons has a timing label.","change":"Show duration under each button.","priority":"P2"},{"id":"08","kind":"proposal","area":"Scale comparison","observation":"All three buttons are identical at rest.","change":"Add fixed outlines to make compression visible.","priority":"P2"},{"id":"09","kind":"proposal","area":"Easing comparison","observation":"The screen does not identify the timing curves.","change":"Display each easing name below its specimen.","priority":"P2"},{"id":"10","kind":"proposal","area":"Button grouping","observation":"Three isolated squares lack card or section framing.","change":"Create equal comparison cards with shared diagnostic rows.","priority":"P2"},{"id":"11","kind":"proposal","area":"Color mapping","observation":"Blue, green and purple have no legend.","change":"Associate each color with the named animation variant.","priority":"P2"},{"id":"12","kind":"proposal","area":"Counter label","observation":"Total clicks counts all variants together.","change":"Show individual counts alongside the total.","priority":"P2"},{"id":"13","kind":"proposal","area":"Last action","observation":"The counter cannot identify the most recently pressed specimen.","change":"Add a Last pressed readout.","priority":"P2"},{"id":"14","kind":"proposal","area":"Counter reset","observation":"The count is displayed without a visible reset action.","change":"Add a small Reset count control.","priority":"P2"},{"id":"15","kind":"proposal","area":"Footer type","observation":"The with_scale() note is small and widely tracked.","change":"Use a readable monospace API label.","priority":"P2"},{"id":"16","kind":"proposal","area":"Footer separation","observation":"The implementation note sits far below the examples.","change":"Place it beneath the comparison cards.","priority":"P2"},{"id":"17","kind":"proposal","area":"Motion metrics","observation":"No current scale value appears in the screenshot.","change":"Add live scale percentages outside the animated buttons.","priority":"P2"},{"id":"18","kind":"proposal","area":"Playback aid","observation":"Only direct pressing is represented.","change":"Add a labeled slow-preview action for comparing the three effects.","priority":"P2"}],"sha256":"5d70ef1709f1616d4a9b8e9c9b46cfbbd118d5930a678694903fc45434feebac","evidence":"docs/design-audit/originals/animation_interactive_720p.png","has_mock":false,"reference":null,"legacy":[]},{"id":"animation_looping","baseline":"screenshot-baselines/screens/animation_looping_720p.png","summary":"Loop phase explains the dim glow and moving marker. Twenty supported proposals improve motion diagnosis without judging the captured phase as a defect.","findings":[{"id":"01","kind":"proposal","area":"Header placement","observation":"A large blank area precedes the title.","change":"Move the header upward to make space for diagnostics.","priority":"P2"},{"id":"02","kind":"proposal","area":"Header construction","observation":"Title and subtitle occupy touching rounded strips.","change":"Combine them in one padded header.","priority":"P2"},{"id":"03","kind":"proposal","area":"Breathe label","observation":"Breathe does not state that the sample translates.","change":"Add a Translation caption.","priority":"P2"},{"id":"04","kind":"proposal","area":"Glow label","observation":"Glow does not identify opacity as the animated property.","change":"Add an Opacity caption.","priority":"P2"},{"id":"05","kind":"proposal","area":"Bounce label","observation":"Bounce does not identify its direction.","change":"Add a vertical motion arrow outside the specimen.","priority":"P2"},{"id":"06","kind":"proposal","area":"Spin label","observation":"Spin sits above a stationary-looking brown base and orange marker.","change":"Identify the marker as the orbiting element.","priority":"P2"},{"id":"07","kind":"proposal","area":"Breathe reference","observation":"The blue block has no fixed position outline.","change":"Add an unmoving outline at its center position.","priority":"P2"},{"id":"08","kind":"proposal","area":"Glow reference","observation":"The green sample is dim at this capture phase.","change":"Add a fully opaque reference chip outside the animation.","priority":"P2"},{"id":"09","kind":"proposal","area":"Bounce bounds","observation":"The purple block has no marked travel range.","change":"Draw endpoints beside its motion area.","priority":"P2"},{"id":"10","kind":"proposal","area":"Spin path","observation":"The orange marker's circular path is invisible.","change":"Add a faint orbit guide behind it.","priority":"P2"},{"id":"11","kind":"proposal","area":"Spin center","observation":"The brown base does not mark the orbit center.","change":"Add a small center crosshair.","priority":"P2"},{"id":"12","kind":"proposal","area":"Period labels","observation":"None of the four examples shows its cycle duration.","change":"Print the period below each name.","priority":"P2"},{"id":"13","kind":"proposal","area":"Phase labels","observation":"The captured examples provide no numeric phase.","change":"Add a phase readout beneath each sample.","priority":"P2"},{"id":"14","kind":"proposal","area":"Amplitude labels","observation":"The motion extent is not specified.","change":"Display translation range or opacity range per example.","priority":"P2"},{"id":"15","kind":"proposal","area":"Pause control","observation":"Continuous motion has no visible pause control.","change":"Add a Pause all action above the specimen group.","priority":"P2"},{"id":"16","kind":"proposal","area":"Replay control","observation":"There is no visible common phase reset.","change":"Add Restart cycles beside Pause.","priority":"P2"},{"id":"17","kind":"proposal","area":"Specimen balance","observation":"Spin's small marker is much less prominent than the three solid blocks.","change":"Increase marker visibility without changing its orbit.","priority":"P2"},{"id":"18","kind":"proposal","area":"Color explanation","observation":"Four colors do not map to a stated property legend.","change":"Use captions that pair each color with its animated property.","priority":"P2"},{"id":"19","kind":"proposal","area":"Footer note","observation":"The sin/cos statement is far from the samples and small.","change":"Place a readable formula note under the motion diagnostics.","priority":"P2"},{"id":"20","kind":"proposal","area":"Static capture aid","observation":"A single frame cannot show travel history.","change":"Offer a labeled trail overlay for screenshot comparison.","priority":"P2"}],"sha256":"5fb9423d03357b68de07bef30e5c1c6f36c12648c66d0dc6075e1cee522291ea","evidence":"docs/design-audit/originals/animation_looping_720p.png","examples":[{"id":"cycle_overlay","label":"Current example: Paused cycle samples","path":"docs/design-audit/examples/animation_looping_overlay_720p.png"}],"has_mock":false,"reference":null,"legacy":[]},{"id":"animation_spring","baseline":"screenshot-baselines/screens/animation_spring_720p.png","summary":"The five spring samples are settled. Twenty proposals describe clearer comparison and controls; differing corner shapes are preserved as specimen choices.","findings":[{"id":"01","kind":"proposal","area":"Title wording","observation":"Springy! does not identify the technical comparison.","change":"Add Spring animation variants as a subtitle.","priority":"P2"},{"id":"02","kind":"proposal","area":"Title space","observation":"The title starts beneath a large empty top region.","change":"Move it upward to reduce unused space.","priority":"P2"},{"id":"03","kind":"proposal","area":"Instruction strip","observation":"The instruction stretches across the screen while specimens are narrow.","change":"Align it to the specimen group's width.","priority":"P2"},{"id":"04","kind":"proposal","area":"Boing caption","observation":"Boing! names a personality rather than a motion property.","change":"Add its spring stiffness and damping below.","priority":"P2"},{"id":"05","kind":"proposal","area":"Jelly caption","observation":"Jelly lacks a description of the deformation.","change":"Add a short axis or scale descriptor.","priority":"P2"},{"id":"06","kind":"proposal","area":"Balloon caption","observation":"Balloon does not state its motion direction.","change":"Add a rise/scale descriptor matching the example.","priority":"P2"},{"id":"07","kind":"proposal","area":"Drop caption","observation":"Drop has no marked starting height.","change":"Show a ghost start marker above the square.","priority":"P2"},{"id":"08","kind":"proposal","area":"Rocker caption","observation":"Rocker does not show its pivot.","change":"Add a small pivot marker and angular range.","priority":"P2"},{"id":"09","kind":"proposal","area":"Specimen bounds","observation":"None of the five blocks has a neutral resting outline.","change":"Add fixed reference bounds outside the animated fill.","priority":"P2"},{"id":"10","kind":"proposal","area":"Color-only identification","observation":"The colored blocks contain no persistent identifiers.","change":"Add numbered external labels matching the parameter captions.","priority":"P2"},{"id":"11","kind":"proposal","area":"Label size","observation":"The five names are tiny compared with Springy!.","change":"Increase specimen-name size.","priority":"P2"},{"id":"12","kind":"proposal","area":"Label plates","observation":"120-pixel plates extend wider than their 100-pixel blocks.","change":"Align each label and specimen within a shared card width.","priority":"P2"},{"id":"13","kind":"proposal","area":"Spring parameters","observation":"No visible numeric parameters distinguish the samples.","change":"Add a compact five-column parameter table.","priority":"P2"},{"id":"14","kind":"proposal","area":"Bounce counter","observation":"Bounces: 0 does not define what is counted.","change":"Rename it Activations if it counts clicks, or state the counting rule.","priority":"P2"},{"id":"15","kind":"proposal","area":"Counter placement","observation":"The counter sits alone well below the specimens.","change":"Place it adjacent to the restart control.","priority":"P2"},{"id":"16","kind":"proposal","area":"Counter attribution","observation":"The count does not identify the last activated spring.","change":"Add a last-sample label.","priority":"P2"},{"id":"17","kind":"proposal","area":"Restart wording","observation":"Restart! omits whether it affects all samples.","change":"Use Restart all five.","priority":"P2"},{"id":"18","kind":"proposal","area":"Restart spacing","observation":"A large empty gap separates the counter and restart button.","change":"Bring them into one control row.","priority":"P2"},{"id":"19","kind":"proposal","area":"Motion phase","observation":"No label identifies idle, moving or settled samples.","change":"Show each specimen's phase below its card.","priority":"P2"},{"id":"20","kind":"proposal","area":"Slow comparison","observation":"The page offers no visible slower playback aid.","change":"Add a slow-preview toggle for inspecting overshoot.","priority":"P2"}],"sha256":"206808e13affc56cfa413a2ea5ca5162534a59b8845dadb15c0d761acd9b21d2","has_mock":false,"reference":null,"legacy":[]},{"id":"auto_text_color","baseline":"screenshot-baselines/screens/auto_text_color_720p.png","summary":"The varied foreground colors are intentional tests. Proposals clarify the automatic-color contract and make the specimens easier to compare.","findings":[{"id":"01","kind":"proposal","area":"New default badge","observation":"NEW DEFAULT is a large yellow badge without a version.","change":"Replace it with a smaller Default enabled annotation or version.","priority":"P2"},{"id":"02","kind":"proposal","area":"Title balance","observation":"The badge pulls the combined heading off the visual center.","change":"Center title and status as a balanced group.","priority":"P2"},{"id":"03","kind":"proposal","area":"Subtitle claim","observation":"Against any background reads as an unlimited contrast guarantee.","change":"State that the system chooses between the configured light and dark colors.","priority":"P2"},{"id":"04","kind":"proposal","area":"Default heading","observation":"No config needed omits the relevant API setting.","change":"Add the default flag name in a monospace caption.","priority":"P2"},{"id":"05","kind":"proposal","area":"Dark/light pairs","observation":"Near Black over Near White is the only obvious named pair.","change":"Label columns as paired background families.","priority":"P2"},{"id":"06","kind":"proposal","area":"Color values","observation":"Near Black and Dark Blue give no actual values.","change":"Show compact RGB or hex captions outside the tiles.","priority":"P2"},{"id":"07","kind":"proposal","area":"Chosen foreground","observation":"The samples show results without naming the chosen text color.","change":"Add Light text or Dark text result captions.","priority":"P2"},{"id":"08","kind":"proposal","area":"Contrast ratios","observation":"Best contrast appears twice without measured ratios.","change":"Display contrast ratios for the tested foreground/background pairs.","priority":"P2"},{"id":"09","kind":"proposal","area":"Dark tile borders","observation":"Thin outlines distinguish some dark samples from the page.","change":"Use an explicitly labeled specimen boundary separate from color output.","priority":"P2"},{"id":"10","kind":"proposal","area":"Light tile row","observation":"The lighter row has no row label.","change":"Label the rows Dark backgrounds and Light backgrounds.","priority":"P2"},{"id":"11","kind":"proposal","area":"Mid-tone spelling","observation":"Dk Magenta abbreviates the color inconsistently.","change":"Spell out Dark magenta.","priority":"P2"},{"id":"12","kind":"proposal","area":"Mid-tone comparison","observation":"Six hues appear without a luminance ordering.","change":"Order by luminance or state the intended sequence.","priority":"P2"},{"id":"13","kind":"proposal","area":"Gray specimen","observation":"Gray's dark text choice is difficult to compare against alternatives.","change":"Add a companion light-text reference outside the primary fixture.","priority":"P2"},{"id":"14","kind":"proposal","area":"Teal specimen","observation":"Teal shares a similar brightness with nearby swatches but lacks numeric context.","change":"Show its luminance in the caption.","priority":"P2"},{"id":"15","kind":"proposal","area":"Explicit options heading","observation":"The options look like actions even though they are demonstration specimens.","change":"Label the row Configuration examples.","priority":"P2"},{"id":"16","kind":"proposal","area":"Disabled wording","observation":"Disabled (theme font) can be mistaken for a disabled control.","change":"Use Auto color off: theme font.","priority":"P2"},{"id":"17","kind":"proposal","area":"Auto default specimen","observation":"Auto (default) does not show its selected foreground value.","change":"Add the resolved foreground below it.","priority":"P2"},{"id":"18","kind":"proposal","area":"Custom red specimen","observation":"Custom Red Text does not state that it overrides automatic selection.","change":"Add an Explicit override caption.","priority":"P2"},{"id":"19","kind":"proposal","area":"Explicit comparison","observation":"The middle example uses a different background from the two outer examples.","change":"Add a matched-background comparison row.","priority":"P2"},{"id":"20","kind":"proposal","area":"Theme heading","observation":"Works with Theme Colors Too is longer than neighboring section names.","change":"Use Theme role examples.","priority":"P2"},{"id":"21","kind":"proposal","area":"Background role","observation":"Background has no visible tile boundary because it matches the page.","change":"Add an external outline marking its specimen bounds.","priority":"P2"},{"id":"22","kind":"proposal","area":"Theme identity","observation":"Primary, Accent and Secondary do not name the active theme.","change":"Add the active theme name above the role row.","priority":"P2"},{"id":"23","kind":"proposal","area":"Role ordering","observation":"Primary, Accent, Secondary uses an unusual sequence.","change":"Group Primary and Secondary before Accent.","priority":"P2"},{"id":"24","kind":"proposal","area":"Separators","observation":"Rules start farther inward than section headings.","change":"Align dividers with the headings' content edge.","priority":"P2"},{"id":"25","kind":"proposal","area":"Specimen typography","observation":"All examples use widely spaced handwritten labels.","change":"Use a readable body face while retaining the exact tested colors.","priority":"P2"}],"sha256":"793b23efb505f4f33bd2faca3f7cd534321ed898c64eff637679f51957b3e015","has_mock":false,"reference":null,"legacy":[]},{"id":"bevel_borders","baseline":"screenshot-baselines/screens/bevel_borders_720p.png","summary":"The 1–6 px raised and sunken border matrix is intentional and clean. Eighteen evidence-based proposals improve inspection; twenty-five would require padding this simple fixture.","findings":[{"id":"01","kind":"proposal","area":"Top blank area","observation":"The matrix begins after nearly two hundred pixels of empty space.","change":"Move the title and matrix upward.","priority":"P2"},{"id":"02","kind":"proposal","area":"Title strip","observation":"BEVEL BORDERS occupies an almost full-width bordered bar.","change":"Match the title width to the matrix.","priority":"P2"},{"id":"03","kind":"proposal","area":"Title casing","observation":"All-capital handwritten title is less readable than the subtitle.","change":"Use sentence case with a stronger weight.","priority":"P2"},{"id":"04","kind":"proposal","area":"Explanation","observation":"The raised/sunken lighting rule is written as one dense line.","change":"Split it into two labeled directional diagrams.","priority":"P2"},{"id":"05","kind":"proposal","area":"Row labels","observation":"Raised and Sunken sit far from their first specimen.","change":"Reduce the gap to the row-label gutter.","priority":"P2"},{"id":"06","kind":"proposal","area":"Column labels","observation":"Each thickness is repeated above and inside its squares.","change":"Keep the column heading and replace inner text with a neutral sample mark.","priority":"P2"},{"id":"07","kind":"proposal","area":"Numeric type","observation":"Thickness values use handwritten numerals.","change":"Use tabular numeric text for pixel measurements.","priority":"P2"},{"id":"08","kind":"proposal","area":"One-pixel detail","observation":"The thinnest border is difficult to inspect at normal size.","change":"Add a magnified 1px corner inset.","priority":"P2"},{"id":"09","kind":"proposal","area":"Six-pixel detail","observation":"The widest border lacks a dimension bracket.","change":"Add a 6px bracket outside its specimen.","priority":"P2"},{"id":"10","kind":"proposal","area":"Lighting direction","observation":"No icon indicates the common top-left light source.","change":"Add a small top-left light-direction arrow.","priority":"P2"},{"id":"11","kind":"proposal","area":"Raised edges","observation":"Light and dark edges are not individually identified.","change":"Label one reference square's highlight and shadow edges.","priority":"P2"},{"id":"12","kind":"proposal","area":"Sunken inversion","observation":"The lower row repeats the rule without showing correspondence.","change":"Add a small inversion annotation connecting one raised/sunken pair.","priority":"P2"},{"id":"13","kind":"proposal","area":"Base fill","observation":"The matrix does not name its shared face color.","change":"Add the face-color value in a legend.","priority":"P2"},{"id":"14","kind":"proposal","area":"Edge colors","observation":"Highlight and shadow colors lack a reference swatch.","change":"Show labeled highlight and shadow chips.","priority":"P2"},{"id":"15","kind":"proposal","area":"Baseline control","observation":"All displayed boxes have bevels.","change":"Add a zero-width border reference.","priority":"P2"},{"id":"16","kind":"proposal","area":"Outer dimensions","observation":"The matrix does not state whether outer box sizes are fixed.","change":"Show the shared specimen dimensions.","priority":"P2"},{"id":"17","kind":"proposal","area":"Interior size","observation":"Thicker borders visibly reduce the usable interior.","change":"Add a compact interior-dimension caption per column.","priority":"P2"},{"id":"18","kind":"proposal","area":"Lower blank area","observation":"The bottom quarter is empty.","change":"Use it for a single enlarged annotated bevel cross-section.","priority":"P2"}],"sha256":"873b7f4a6f5ecb8455292eeb4b56c812420ff07f28d4bf94cd29d8bac1740f0d","has_mock":false,"reference":null,"legacy":[]},{"id":"blend_mode_lab","baseline":"screenshot-baselines/screens/blend_mode_lab_720p.png","summary":"Dark multiply output and brighter additive output are expected. Proposals explain the blend inputs, ordering and batch-transition comparison.","findings":[{"id":"01","kind":"proposal","area":"Title","observation":"Blend modes. Real transitions last frame: 24 merges heading and live metric.","change":"Separate the page title from the transition counter.","priority":"P2"},{"id":"02","kind":"proposal","area":"Title inset","observation":"The title begins at the rounded strip's left edge.","change":"Add horizontal padding.","priority":"P2"},{"id":"03","kind":"proposal","area":"Transition definition","observation":"Real transitions is undefined in the visible frame.","change":"Label it GPU blend-state changes or the precise measured operation.","priority":"P2"},{"id":"04","kind":"proposal","area":"Transition scope","observation":"24 does not say whether it includes both specimen rows.","change":"Show a short scope label.","priority":"P2"},{"id":"05","kind":"proposal","area":"Alpha caption","observation":"Alpha omits the configured opacity.","change":"Add the input alpha value.","priority":"P2"},{"id":"06","kind":"proposal","area":"Additive caption","observation":"Additive provides no blending equation.","change":"Add a compact source-plus-destination caption.","priority":"P2"},{"id":"07","kind":"proposal","area":"Multiply caption","observation":"Multiplied differs grammatically from the other mode names.","change":"Use Multiply.","priority":"P2"},{"id":"08","kind":"proposal","area":"Premultiply caption","observation":"AlphaPremultiply is a compressed API identifier.","change":"Use Premultiplied alpha with the API name beneath.","priority":"P2"},{"id":"09","kind":"proposal","area":"Mode title type","observation":"The four mode labels are tiny.","change":"Increase label size while preserving specimen area.","priority":"P2"},{"id":"10","kind":"proposal","area":"Input colors","observation":"Red, green and blue inputs are visible but unspecified.","change":"Add a labeled RGB input legend.","priority":"P2"},{"id":"11","kind":"proposal","area":"Circle order","observation":"Three overlaps do not state draw order.","change":"Number the input circles outside their bounds.","priority":"P2"},{"id":"12","kind":"proposal","area":"Alpha overlap","observation":"The center intersection has no measurement label.","change":"Add a sampled center-color swatch below the panel.","priority":"P2"},{"id":"13","kind":"proposal","area":"Multiply visibility","observation":"Dark output is expected but hard to compare to the background.","change":"Add a labeled magnified sample beside the panel.","priority":"P2"},{"id":"14","kind":"proposal","area":"Premultiply contract","observation":"The panel does not say whether colors are pre-multiplied.","change":"State the source-color preparation in its caption.","priority":"P2"},{"id":"15","kind":"proposal","area":"Backing color","observation":"All modes share a dark panel but its color is unnamed.","change":"Show the shared destination color value.","priority":"P2"},{"id":"16","kind":"proposal","area":"Circle geometry","observation":"The specimens have no fixed geometry caption.","change":"Document shared radius and overlap distance once.","priority":"P2"},{"id":"17","kind":"proposal","area":"Top panel alignment","observation":"Captions sit very close to panel tops.","change":"Give all four captions a consistent clear gap.","priority":"P2"},{"id":"18","kind":"proposal","area":"Batch row headers","observation":"One scope per blit and round the batch are very small.","change":"Increase their size and simplify the wording.","priority":"P2"},{"id":"19","kind":"proposal","area":"Per-blit count","observation":"2 transitions each leaves the total implicit.","change":"Show 8 blits × 2 = 16 transitions.","priority":"P2"},{"id":"20","kind":"proposal","area":"Batch total","observation":"2 total does not identify the number of blits.","change":"Show 8 blits, 2 transitions.","priority":"P2"},{"id":"21","kind":"proposal","area":"Batch item identity","observation":"Eight blue squares per panel have no identifiers.","change":"Number them lightly outside their fills.","priority":"P2"},{"id":"22","kind":"proposal","area":"Batch equivalence","observation":"The two rows look identical without an explicit expected-result note.","change":"State that output should match while state changes differ.","priority":"P2"},{"id":"23","kind":"proposal","area":"Batch boundaries","observation":"The shared scope is described only in text.","change":"Draw one bracket over the batch and separate brackets over per-blit samples.","priority":"P2"},{"id":"24","kind":"proposal","area":"Blank lower region","observation":"A large lower region is unused.","change":"Add a small comparison table of mode and transition count.","priority":"P2"},{"id":"25","kind":"proposal","area":"Capture metadata","observation":"The live count has no frame marker beyond last frame.","change":"Show a stable capture/frame identifier beside the metric.","priority":"P2"}],"sha256":"fa1082878c46a906e6ff63dc7f6ee19f18457d88c16ef6e31b81ee8d2f68fe19","has_mock":false,"reference":null,"legacy":[{"id":"blend_mode_lab","screen":"blend_mode_lab","baseline":"baseline_screenshots/blend_mode_lab.png","current":"screenshot-baselines/screens/blend_mode_lab_720p.png","pixel_identical":true,"size":[1280,720],"summary":"Pixel-identical. Alpha, Additive, Multiply and AlphaPremultiply specimens and batch diagrams share the current findings. The dark Multiply intersection is an intentional test, not failed contrast to repair.","sha256":"fa1082878c46a906e6ff63dc7f6ee19f18457d88c16ef6e31b81ee8d2f68fe19","additional_findings":[]}]},{"id":"button_variants","baseline":"screenshot-baselines/screens/button_variants_720p.png","summary":"The matrix intentionally includes ghost and disabled buttons. Proposals improve its labeling, measurement and theme comparison without changing those test states.","findings":[{"id":"01","kind":"proposal","area":"Title inset","observation":"Button Variants touches the header's left edge.","change":"Align it with the row-label inset.","priority":"P2"},{"id":"02","kind":"proposal","area":"Matrix headings","observation":"Normal, Accent, Secondary and Disabled repeat inside every row.","change":"Add column headings above the matrix.","priority":"P2"},{"id":"03","kind":"proposal","area":"Normal terminology","observation":"Normal occupies the same category position as theme color roles.","change":"Rename the role Primary.","priority":"P2"},{"id":"04","kind":"proposal","area":"Disabled comparison","observation":"Disabled mixes availability with three color roles.","change":"Label the last column Disabled primary.","priority":"P2"},{"id":"05","kind":"proposal","area":"Disabled fixture framing","observation":"Disabled boundaries blend into the panel.","change":"Add neutral external specimen outlines.","priority":"P2"},{"id":"06","kind":"proposal","area":"Ghost framing","observation":"Ghost controls look like disconnected text labels.","change":"Draw optional diagnostic bounds outside the test controls.","priority":"P2"},{"id":"07","kind":"proposal","area":"Outline comparison","observation":"Thin colored outlines are hard to inspect.","change":"Add enlarged corner samples for the outline row.","priority":"P2"},{"id":"08","kind":"proposal","area":"Row separation","observation":"Filled, Outline and Ghost panels touch with scalloped seams.","change":"Use a consistent narrow row gutter.","priority":"P2"},{"id":"09","kind":"proposal","area":"Row-label alignment","observation":"Labels sit far left of their specimen grid.","change":"Bring them closer in a fixed label column.","priority":"P2"},{"id":"10","kind":"proposal","area":"Specimen sizing","observation":"Main matrix controls have no dimensions shown.","change":"Add one shared width and height caption.","priority":"P2"},{"id":"11","kind":"proposal","area":"Small specimen","observation":"Small lacks its numeric size.","change":"Add measured dimensions below it.","priority":"P2"},{"id":"12","kind":"proposal","area":"Medium specimen","observation":"Medium has no padding or text-size annotation.","change":"Add a compact token caption.","priority":"P2"},{"id":"13","kind":"proposal","area":"Large specimen","observation":"Large differs in typography as well as box size.","change":"State both font and control dimensions.","priority":"P2"},{"id":"14","kind":"proposal","area":"Large outline label","observation":"Lg Outline abbreviates a word used fully elsewhere.","change":"Use Large outline.","priority":"P2"},{"id":"15","kind":"proposal","area":"Size row comparison","observation":"Large outline also changes color role.","change":"Keep the role constant or label the extra variable.","priority":"P2"},{"id":"16","kind":"proposal","area":"Theme cards","observation":"Neon Dark, Cozy Kraft and Sage are left clustered.","change":"Distribute the three cards evenly across the specimen area.","priority":"P2"},{"id":"17","kind":"proposal","area":"Theme titles","observation":"Theme names share the small size of specimen labels.","change":"Give card headings a clearer weight.","priority":"P2"},{"id":"18","kind":"proposal","area":"Theme button density","observation":"Filled and Outline buttons touch inside the cards.","change":"Add a small consistent vertical gap.","priority":"P2"},{"id":"19","kind":"proposal","area":"Theme ghost position","observation":"Ghost text sits immediately below outline specimens.","change":"Align it in a reserved equal-height row.","priority":"P2"},{"id":"20","kind":"proposal","area":"Theme dimensions","observation":"Theme samples are much smaller than the main matrix.","change":"State that these are compact previews.","priority":"P2"},{"id":"21","kind":"proposal","area":"Theme output","observation":"No resolved foreground values accompany the theme examples.","change":"Add a concise color-pair caption per card.","priority":"P2"},{"id":"22","kind":"proposal","area":"Main theme identity","observation":"The navy matrix does not identify its active theme.","change":"Name the main theme beside the title.","priority":"P2"},{"id":"23","kind":"proposal","area":"Footer instruction","observation":"Try any variant above is flush against the footer edge.","change":"Add matching horizontal padding.","priority":"P2"},{"id":"24","kind":"proposal","area":"Footer feedback","observation":"The initial instruction does not explain the result of pressing a specimen.","change":"State that the footer reports the chosen variant.","priority":"P2"},{"id":"25","kind":"proposal","area":"Legend","observation":"Variant appearance, color role and size are interleaved without a guide.","change":"Add a compact key distinguishing those three dimensions.","priority":"P2"}],"sha256":"d157b9e5c026abd219326fd4e4584cbb183776982fcb9fce7c9c856b6aecb6ed","has_mock":false,"reference":null,"legacy":[]},{"id":"buttons","baseline":"screenshot-baselines/screens/buttons_720p.png","summary":"The disabled treatment and square-corner sample are intentional. Twenty-five proposals improve the gallery's explanatory value and alignment.","findings":[{"id":"01","kind":"proposal","area":"Title padding","observation":"Button Gallery starts at the strip's edge.","change":"Add the same inset as row labels.","priority":"P2"},{"id":"02","kind":"proposal","area":"Header size","observation":"The title band is much taller than its text requires.","change":"Reduce its height or add a short purpose subtitle.","priority":"P2"},{"id":"03","kind":"proposal","area":"States label","observation":"States contains Accent and Secondary, which are color roles.","change":"Rename the row Roles and availability.","priority":"P2"},{"id":"04","kind":"proposal","area":"Normal button","observation":"Normal does not identify the primary theme role.","change":"Label it Primary.","priority":"P2"},{"id":"05","kind":"proposal","area":"Disabled specimen","observation":"The deliberately dim label is difficult to identify independently.","change":"Add a readable external Disabled caption.","priority":"P2"},{"id":"06","kind":"proposal","area":"Disabled bounds","observation":"The disabled outline is hard to distinguish from the panel.","change":"Add an external diagnostic boundary.","priority":"P2"},{"id":"07","kind":"proposal","area":"State dimensions","observation":"The four specimens show no shared measurement.","change":"Add a dimensions caption for this row.","priority":"P2"},{"id":"08","kind":"proposal","area":"Size naming","observation":"Large Button differs from Small and Medium naming.","change":"Use Large for parallel labels.","priority":"P2"},{"id":"09","kind":"proposal","area":"Size comparison","observation":"Small and Medium appear similar in height.","change":"Print their exact height and padding below them.","priority":"P2"},{"id":"10","kind":"proposal","area":"Size width","observation":"Different label lengths influence perceived button size.","change":"Use a shared test label with external size captions.","priority":"P2"},{"id":"11","kind":"proposal","area":"Size alignment","observation":"Controls are centered vertically but no baseline aid is shown.","change":"Add an optional baseline guide.","priority":"P2"},{"id":"12","kind":"proposal","area":"Group spacing","observation":"One through Four are separated widely despite group-specific corner shapes.","change":"Tighten spacing to show a coherent segmented group.","priority":"P2"},{"id":"13","kind":"proposal","area":"Group semantics","observation":"One, Two, Three and Four provide no shared task.","change":"Use four related view options for the group example.","priority":"P2"},{"id":"14","kind":"proposal","area":"Group boundary","observation":"There is no outer label explaining the asymmetric corner shapes.","change":"Add a caption identifying first, middle and last corners.","priority":"P2"},{"id":"15","kind":"proposal","area":"Group selection","observation":"No visible marker explains whether this is a selection group or independent actions.","change":"State the group's intended behavior in a caption.","priority":"P2"},{"id":"16","kind":"proposal","area":"Custom heading","observation":"Custom combines color and corner experiments.","change":"Split color examples from the corner example visually.","priority":"P2"},{"id":"17","kind":"proposal","area":"Coral sample","observation":"Coral shows no color value.","change":"Add its configured hex value below it.","priority":"P2"},{"id":"18","kind":"proposal","area":"Teal sample","observation":"Teal's text treatment differs from Coral without explanation.","change":"Add a foreground-selection caption.","priority":"P2"},{"id":"19","kind":"proposal","area":"Sharp sample","observation":"Sharp lacks a rounded reference beside it.","change":"Add a matched rounded control for direct comparison.","priority":"P2"},{"id":"20","kind":"proposal","area":"Main color mapping","observation":"Blue, ochre and green are unnamed theme colors.","change":"Add a small role-color legend.","priority":"P2"},{"id":"21","kind":"proposal","area":"Row width","observation":"Most of each full-width row remains empty on the right.","change":"Use the space for short specimen notes.","priority":"P2"},{"id":"22","kind":"proposal","area":"Row alignment","observation":"The largest-size specimen extends farther right than other rows.","change":"Use a shared four-column comparison grid.","priority":"P2"},{"id":"23","kind":"proposal","area":"Panel gaps","observation":"Vertical spacing dominates the compact specimen content.","change":"Reduce gaps to make room for useful captions.","priority":"P2"},{"id":"24","kind":"proposal","area":"Footer padding","observation":"Try any button above begins at the bar edge.","change":"Inset footer text consistently.","priority":"P2"},{"id":"25","kind":"proposal","area":"Footer meaning","observation":"The instruction does not say what activation reports.","change":"Describe the selected-button feedback shown there.","priority":"P2"}],"sha256":"b8ed32e2717dc06fcbdc6c73fe8c9551383a671c49a5730a9bb7c2af4a863ca6","has_mock":false,"reference":null,"legacy":[]},{"id":"cards","baseline":"screenshot-baselines/screens/cards_720p.png","summary":"The gallery's custom colors, sharp corners and translucent example are intentional. Findings target label placement and clearer comparison.","findings":[{"id":"01","kind":"defect","area":"Style specimen labels","observation":"Surface, Primary, Sharp and Custom begin directly on their left borders.","change":"Give each label visible internal padding.","priority":"P2"},{"id":"02","kind":"defect","area":"Nested item labels","observation":"Item 1, Item 2 and Item 3 touch their colored blocks' left edges.","change":"Add consistent inset to nested labels.","priority":"P2"},{"id":"03","kind":"proposal","area":"Title inset","observation":"Cards & Panels Gallery is flush with the brown header's edge.","change":"Align it to the main content inset.","priority":"P2"},{"id":"04","kind":"proposal","area":"Header width","observation":"The header is narrower than the white style and nested rows.","change":"Use a consistent content width.","priority":"P2"},{"id":"05","kind":"proposal","area":"Style row label","observation":"Styles is a dark button-shaped block.","change":"Use a plain section heading to distinguish labels from specimens.","priority":"P2"},{"id":"06","kind":"proposal","area":"Surface example","observation":"The white card almost merges into the white row.","change":"Add an external labeled bounds guide.","priority":"P2"},{"id":"07","kind":"proposal","area":"Primary example","observation":"Primary has no theme-color value shown.","change":"Add its role and resolved color beneath it.","priority":"P2"},{"id":"08","kind":"proposal","area":"Sharp example","observation":"Sharp also changes fill and border weight.","change":"Add a matched rounded specimen or state both changed variables.","priority":"P2"},{"id":"09","kind":"proposal","area":"Custom example","observation":"Custom does not identify what was customized.","change":"Caption the background, border and radius values.","priority":"P2"},{"id":"10","kind":"proposal","area":"Style dimensions","observation":"The card specimens have no size annotation.","change":"Show the shared outer dimensions once.","priority":"P2"},{"id":"11","kind":"proposal","area":"Style gaps","observation":"Wide gaps separate four small cards.","change":"Use a regular matrix with room for parameter captions.","priority":"P2"},{"id":"12","kind":"proposal","area":"Nested section label","observation":"Nested is vertically centered in a button-like plaque.","change":"Move it above the nested examples as a heading.","priority":"P2"},{"id":"13","kind":"proposal","area":"Nested card hierarchy","observation":"Nested Cards has similar typography to its item labels.","change":"Increase heading weight and size.","priority":"P2"},{"id":"14","kind":"proposal","area":"Nested boundaries","observation":"The outer nested card border is faint.","change":"Add a clearer external outline marking the parent bounds.","priority":"P2"},{"id":"15","kind":"proposal","area":"Nested padding","observation":"Parent-child insets are visible but unmeasured.","change":"Annotate the parent padding.","priority":"P2"},{"id":"16","kind":"proposal","area":"Nested item spacing","observation":"The three inner items have no gap value shown.","change":"Add a shared gap caption.","priority":"P2"},{"id":"17","kind":"proposal","area":"Translucent heading","observation":"Semi-Transparent sits in a bright white title strip.","change":"Make the title treatment consistent with Nested Cards.","priority":"P2"},{"id":"18","kind":"proposal","area":"Opacity evidence","observation":"The translucent panel overlays a nearly flat backing color.","change":"Add a checkerboard or stripe behind the sample to expose blending.","priority":"P2"},{"id":"19","kind":"proposal","area":"Opacity value","observation":"Uses opacity does not state the actual alpha.","change":"Display the configured percentage.","priority":"P2"},{"id":"20","kind":"proposal","area":"Opacity copy","observation":"The description wraps into an awkward short second line.","change":"Adjust text width or shorten the explanation.","priority":"P2"},{"id":"21","kind":"proposal","area":"Theme palette label","observation":"Theme Colors is a brown tile that resembles the primary swatch.","change":"Use a neutral section label.","priority":"P2"},{"id":"22","kind":"proposal","area":"Theme palette values","observation":"Five role chips show names without color values.","change":"Add compact resolved values beneath the chips.","priority":"P2"},{"id":"23","kind":"proposal","area":"Background swatch","observation":"Background nearly matches the page around the palette.","change":"Give the specimen an external boundary.","priority":"P2"},{"id":"24","kind":"proposal","area":"Theme identity","observation":"The kraft palette has no visible theme name.","change":"Name Cozy Kraft near the title.","priority":"P2"},{"id":"25","kind":"proposal","area":"Vertical spacing","observation":"Large empty bands separate the three rows.","change":"Tighten spacing and allocate room for card measurements.","priority":"P2"}],"sha256":"70021708e5133a12f2e03373432ad76527f8b0bc9166601659492ec6b05ff9a9","has_mock":false,"reference":null,"legacy":[{"id":"cards","screen":"cards","baseline":"baseline_screenshots/cards.png","current":"screenshot-baselines/screens/cards_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Same arrangement and spacing. Current capture removes the initial Surface focus ring. Small labels, detached Styles/Nested badges and a weak translucency demonstration remain visible in both.","sha256":"5c1873eb68796e5b5d1bc1ea53e5fda7907c427215b331f0a90b8b27918429b8","additional_findings":[]}]},{"id":"casual_settings","baseline":"screenshot-baselines/screens/casual_settings_720p.png","summary":"The screen closely matches the playful settings mock. Proposals clarify saved state, icon meanings and the hierarchy between preferences and support links.","findings":[{"id":"01","kind":"proposal","area":"Music button","observation":"The note icon has no visible label or ON text.","change":"Add MUSIC and its current state beneath the icon.","priority":"P2"},{"id":"02","kind":"proposal","area":"Sound button","observation":"The speaker icon lacks a separate effects label.","change":"Add SOUND EFFECTS and its current state.","priority":"P2"},{"id":"03","kind":"proposal","area":"Vibration button","observation":"Gray fill may read as unavailable rather than off.","change":"Add VIBRATION OFF beneath it.","priority":"P2"},{"id":"04","kind":"proposal","area":"Audio group","observation":"Three icon buttons have no group heading.","change":"Add a compact AUDIO heading.","priority":"P2"},{"id":"05","kind":"proposal","area":"Save/load label","observation":"SAVE/LOAD PROGRESS combines two distinct operations.","change":"Use CLOUD SAVE with a descriptive secondary caption.","priority":"P2"},{"id":"06","kind":"proposal","area":"Save/load icon","observation":"A Wi-Fi symbol can imply connectivity rather than stored progress.","change":"Use a cloud-save icon.","priority":"P2"},{"id":"07","kind":"proposal","area":"Save status","observation":"The save button shows no account or last-sync status.","change":"Add a short saved-state line nearby.","priority":"P2"},{"id":"08","kind":"proposal","area":"Notifications control","observation":"NOTIFICATIONS: OFF looks like a navigation button.","change":"Add a visible switch indicator.","priority":"P2"},{"id":"09","kind":"proposal","area":"Notifications label","observation":"The full label is denser than neighboring actions.","change":"Separate the setting name from the OFF state.","priority":"P2"},{"id":"10","kind":"proposal","area":"Language button","observation":"LANGUAGE does not display the current language.","change":"Show English or the selected language as a secondary value.","priority":"P2"},{"id":"11","kind":"proposal","area":"Credits priority","observation":"CREDITS has the same prominence as core preferences.","change":"Reduce its size or move it into an About group.","priority":"P2"},{"id":"12","kind":"proposal","area":"Support priority","observation":"SUPPORT visually competes with save/load.","change":"Group it with help and legal actions.","priority":"P2"},{"id":"13","kind":"proposal","area":"Legal button","observation":"TERMS AND PRIVACY occupies a large glossy action.","change":"Use a quieter legal-link treatment.","priority":"P2"},{"id":"14","kind":"proposal","area":"Build identifier","observation":"15555-1-114203-20-10200-01 lacks a label.","change":"Prefix it with Build.","priority":"P2"},{"id":"15","kind":"proposal","area":"Version text","observation":"The version uses playful heavy lettering for technical data.","change":"Use a compact readable numeric face.","priority":"P2"},{"id":"16","kind":"proposal","area":"Player identifier","observation":"Player ID is a long uninterrupted number.","change":"Group digits for scanning while preserving the exact value.","priority":"P2"},{"id":"17","kind":"proposal","area":"Metadata alignment","observation":"Build, Version and Player ID are centered as one dense block.","change":"Left-align a compact two-column label/value block.","priority":"P2"},{"id":"18","kind":"proposal","area":"Metadata placement","observation":"Technical identifiers sit under Language without a section label.","change":"Put them in an About footer.","priority":"P2"},{"id":"19","kind":"proposal","area":"Close control","observation":"The close button extends beyond the board's inner edge.","change":"Move it inward slightly for a cleaner safe margin.","priority":"P2"},{"id":"20","kind":"proposal","area":"Close semantics","observation":"There is no visible saved-state reassurance near the sole exit.","change":"Add Changes save automatically if that is the intended behavior.","priority":"P2"},{"id":"21","kind":"proposal","area":"Background currency","observation":"1000 coins appears faintly at the top right without an icon.","change":"Restore a coherent subdued currency chip.","priority":"P2"},{"id":"22","kind":"proposal","area":"Grid grouping","observation":"Preferences and support actions alternate across the two columns.","change":"Group settings on one side and account/help actions on the other.","priority":"P2"},{"id":"23","kind":"proposal","area":"Save text wrapping","observation":"SAVE/LOAD PROGRESS uses a tight two-line block.","change":"Increase line spacing and rebalance icon spacing.","priority":"P2"},{"id":"24","kind":"proposal","area":"Button shadows","observation":"Heavy dark shadows crowd the gaps between rows.","change":"Reduce shadow depth to open the layout.","priority":"P2"},{"id":"25","kind":"proposal","area":"Bottom line","observation":"A long pale line below the board has no clear role.","change":"Remove it unless it represents a deliberate device affordance.","priority":"P2"}],"sha256":"213201c1164f7468f31308d33e64f839d85c223e7602bd1c0a53bd635bed7440","has_mock":true,"reference":"inspiration/example_angry_birds.jpg","legacy":[]},{"id":"chart_lab","baseline":"screenshot-baselines/screens/chart_lab_720p.png","summary":"The chart renders two visible series and a selected first sample. Findings address axis readability, selection context and fixture controls.","findings":[{"id":"01","kind":"defect","area":"Axis labels","observation":"The Y endpoints 11 and 2 are tiny at the far left.","change":"Increase tick-label size and reserve a proper axis gutter.","priority":"P2"},{"id":"02","kind":"proposal","area":"X units","observation":"Seconds appears only in the bottom instruction.","change":"Place seconds next to the X axis.","priority":"P2"},{"id":"03","kind":"proposal","area":"Y units","observation":"Milliseconds appears only in the bottom instruction.","change":"Label the Y axis ms.","priority":"P2"},{"id":"04","kind":"proposal","area":"X ticks","observation":"Only 0 and 1.98 are shown across a wide plot.","change":"Add evenly spaced intermediate time ticks.","priority":"P2"},{"id":"05","kind":"proposal","area":"Y ticks","observation":"Several horizontal grid lines have no numeric values.","change":"Label each major Y tick.","priority":"P2"},{"id":"06","kind":"proposal","area":"Legend","observation":"Update and Render labels are extremely small.","change":"Increase their size and add short line swatches.","priority":"P2"},{"id":"07","kind":"proposal","area":"Series distinction","observation":"The two series differ only by color.","change":"Give one a dashed stroke or different marker shape.","priority":"P2"},{"id":"08","kind":"proposal","area":"Line weight","observation":"Both series are very thin against the dark plot.","change":"Increase line width modestly.","priority":"P2"},{"id":"09","kind":"proposal","area":"Grid color","observation":"Purple grid lines introduce a third color unrelated to the series.","change":"Use a neutral subdued grid color.","priority":"P2"},{"id":"10","kind":"proposal","area":"Selected sample","observation":"Dots at the left mark the first sample without a shared guide.","change":"Draw a vertical selection line through the selected time.","priority":"P2"},{"id":"11","kind":"proposal","area":"Selected time","observation":"Sample 1 of 120 omits the selected time.","change":"Show the corresponding timestamp next to the count.","priority":"P2"},{"id":"12","kind":"proposal","area":"Value labels","observation":"8.00 ms and 6.00 ms float near the first points.","change":"Use a compact selected-sample readout outside the plot.","priority":"P2"},{"id":"13","kind":"proposal","area":"Sample counter","observation":"The count is detached from both value labels.","change":"Group index, time and both series values.","priority":"P2"},{"id":"14","kind":"proposal","area":"Previous action","observation":"Previous sample looks active while sample 1 is selected.","change":"Show the boundary state when no prior sample exists.","priority":"P2"},{"id":"15","kind":"proposal","area":"Preset selection","observation":"Empty, Single, Constant, Negative and Multiple all look identical.","change":"Mark the active dataset preset.","priority":"P2"},{"id":"16","kind":"proposal","area":"Multiple wording","observation":"Multiple does not identify multiple series.","change":"Rename it Multiple series.","priority":"P2"},{"id":"17","kind":"proposal","area":"Single wording","observation":"Single does not distinguish one sample from one series.","change":"Rename it Single sample.","priority":"P2"},{"id":"18","kind":"proposal","area":"Fixture controls","observation":"Dataset buttons and Start live share one appearance.","change":"Separate fixtures from playback controls.","priority":"P2"},{"id":"19","kind":"proposal","area":"Live status","observation":"Start live has no persistent paused/live indicator beside it.","change":"Add a Live off status chip.","priority":"P2"},{"id":"20","kind":"proposal","area":"Chart title","observation":"Charts / frame timings mixes gallery and metric names.","change":"Use Frame timing chart with a demo subtitle.","priority":"P2"},{"id":"21","kind":"proposal","area":"Plot padding","observation":"The chart begins close to the legend and endpoint labels.","change":"Add consistent internal plot padding.","priority":"P2"},{"id":"22","kind":"proposal","area":"Negative fixture cue","observation":"Negative is available without any explanation of why timings can be negative.","change":"Label it Negative-value test data.","priority":"P2"},{"id":"23","kind":"proposal","area":"Instruction density","observation":"Hover, Tab, Enter and axis units are packed into one line.","change":"Separate input help from chart metadata.","priority":"P2"},{"id":"24","kind":"proposal","area":"Sample navigation","observation":"Long Previous sample and Next sample buttons dominate the footer.","change":"Use compact arrows with a clear shared Sample label.","priority":"P2"},{"id":"25","kind":"proposal","area":"Frame budget","observation":"The chart has no contextual timing threshold.","change":"Add an optional labeled frame-budget reference line.","priority":"P2"}],"sha256":"4523faaa397c00e5b02c254990c31030cbe5d0ee8a444261eff6650facb9d863","has_mock":false,"reference":null,"legacy":[]},{"id":"checkboxes","baseline":"screenshot-baselines/screens/checkboxes_720p.png","summary":"The screenshot intentionally includes disabled and minimum-selection examples. Findings improve control geometry, grouping and explanation.","findings":[{"id":"01","kind":"defect","area":"Left labels","observation":"Primary, Secondary and Accent touch their colored row edges.","change":"Add consistent label inset.","priority":"P2"},{"id":"02","kind":"defect","area":"Right labels","observation":"Option A through D begin directly at the row boundary.","change":"Inset labels to match the left column.","priority":"P2"},{"id":"03","kind":"proposal","area":"Checkbox glyphs","observation":"Selections use literal [x] and [ ] text.","change":"Render clear square checkbox marks.","priority":"P2"},{"id":"04","kind":"proposal","area":"Box-only geometry","observation":"Box Only specimens look like wide pills.","change":"Use square specimens or label the pill geometry as intentional.","priority":"P2"},{"id":"05","kind":"proposal","area":"Box-only identity","observation":"Four unlabeled controls have no external identifiers.","change":"Add numbered captions outside the controls.","priority":"P2"},{"id":"06","kind":"proposal","area":"Box-only states","observation":"Two empty pills have no explicit off-state reference.","change":"Add an external on/off legend.","priority":"P2"},{"id":"07","kind":"proposal","area":"With Label heading","observation":"The section heading uses the same teal fill as its controls.","change":"Give headings a neutral treatment.","priority":"P2"},{"id":"08","kind":"proposal","area":"Color role row","observation":"Primary, Secondary and Accent change row fill along with selection state.","change":"Add a matched-state comparison caption.","priority":"P2"},{"id":"09","kind":"proposal","area":"Disabled heading","observation":"Disabled uses bright teal while its examples are intentionally dim.","change":"Use a neutral section header.","priority":"P2"},{"id":"10","kind":"proposal","area":"Disabled ON wording","observation":"ON/OFF terminology differs from checkbox checked state.","change":"Use Checked and Unchecked.","priority":"P2"},{"id":"11","kind":"proposal","area":"Disabled specimens","observation":"Dim text is the only clear explanation of disabled status.","change":"Add readable external Disabled captions.","priority":"P2"},{"id":"12","kind":"proposal","area":"Multi-select heading","observation":"Selected: 2 of 4 is embedded in a long header.","change":"Separate the count into a compact badge.","priority":"P2"},{"id":"13","kind":"proposal","area":"Option names","observation":"Option A through D carry no meaningful choice example.","change":"Use four related preference names.","priority":"P2"},{"id":"14","kind":"proposal","area":"Count duplication","observation":"2 of 4 appears in both the header and tiny footer.","change":"Use one prominent count near the group.","priority":"P2"},{"id":"15","kind":"proposal","area":"Constrained heading","observation":"Select 1–2 options is followed by generic Choice names.","change":"Use a concrete preference-selection example.","priority":"P2"},{"id":"16","kind":"proposal","area":"Choice 1 state","observation":"The selected minimum-bound choice appears disabled with no explanation.","change":"Add a note that one selection must remain.","priority":"P2"},{"id":"17","kind":"proposal","area":"Selection rule","observation":"The maximum of two has no visible state summary beyond the heading.","change":"Show Min 1, max 2 beside the count.","priority":"P2"},{"id":"18","kind":"proposal","area":"Choice color","observation":"Constrained choices use purple while unconstrained choices use teal.","change":"Explain the category mapping or neutralize row fills.","priority":"P2"},{"id":"19","kind":"proposal","area":"Checkbox alignment","observation":"Check marks are far from their labels in long filled rows.","change":"Bring marks closer to the label or align them in a clear trailing column.","priority":"P2"},{"id":"20","kind":"proposal","area":"Column titles","observation":"Left column starts With Label while right starts Multi-Select.","change":"Add equal top-level labels for primitive and grouped examples.","priority":"P2"},{"id":"21","kind":"proposal","area":"Row corner seams","observation":"Touching rounded rows create scalloped edges.","change":"Add narrow regular gutters or shared group corners.","priority":"P2"},{"id":"22","kind":"proposal","area":"Footer size","observation":"Both selection summaries are very small.","change":"Increase summary typography.","priority":"P2"},{"id":"23","kind":"proposal","area":"Footer alignment","observation":"The summaries cluster near the middle instead of centering below their groups.","change":"Align each beneath its associated column.","priority":"P2"},{"id":"24","kind":"proposal","area":"Lower blank space","observation":"The bottom portion of the panel is mostly empty.","change":"Use it for the constrained-selection rule explanation.","priority":"P2"},{"id":"25","kind":"proposal","area":"Title scale","observation":"Checkbox Components dominates the small row labels.","change":"Reduce the title slightly and strengthen section hierarchy.","priority":"P2"}],"sha256":"8803f8f0120ccde187bb361b14b6d4674b1c3e0872d2a2df3e86b126308d25f5","has_mock":false,"reference":null,"legacy":[{"id":"checkboxes","screen":"checkboxes","baseline":"baseline_screenshots/checkboxes.png","current":"screenshot-baselines/screens/checkboxes_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Current capture moves the Primary check value rightward. Colored full-row fills, text-bracket indicators and a large unused lower panel remain in both captures.","sha256":"dbfe1c8df412ebc6d2de2814125a39c29c1c5311db4d3295570013f9bd7c6563","additional_findings":[]}]},{"id":"circular_progress","baseline":"screenshot-baselines/screens/circular_progress_720p.png","summary":"Ring thickness, size and live progress vary intentionally. Twenty-five proposals make those variables and values easier to compare.","findings":[{"id":"01","kind":"proposal","area":"Basic naming","observation":"Basic does not identify its ring width.","change":"Add the stroke width below the title.","priority":"P2"},{"id":"02","kind":"proposal","area":"Animated naming","observation":"Animated shows 35% but no update interval.","change":"Display the cycle duration in its caption.","priority":"P2"},{"id":"03","kind":"proposal","area":"Thick ring","observation":"Thick Ring gives no numerical thickness.","change":"Show its stroke width in pixels.","priority":"P2"},{"id":"04","kind":"proposal","area":"Thin ring","observation":"Thin Ring repeats its heading in the description.","change":"Replace the repeated caption with its stroke width.","priority":"P2"},{"id":"05","kind":"proposal","area":"Basic subtitle","observation":"Static value repeats what the absence of motion already suggests.","change":"State the configured progress and start angle.","priority":"P2"},{"id":"06","kind":"proposal","area":"Top row comparison","observation":"All four rings use different values and colors.","change":"Add a matched-value reference for thickness comparison.","priority":"P2"},{"id":"07","kind":"proposal","area":"Start direction","observation":"The arcs have no stated origin or direction.","change":"Add a small shared clockwise-from-top legend.","priority":"P2"},{"id":"08","kind":"proposal","area":"Animated phase","observation":"35% has no timestamp or phase context.","change":"Add a live status and elapsed-time label.","priority":"P2"},{"id":"09","kind":"proposal","area":"Live controls","observation":"No pause control is visible for the animated sample.","change":"Add a compact Pause action outside the ring.","priority":"P2"},{"id":"10","kind":"proposal","area":"Track contrast","observation":"Unfilled tracks are close to the card background.","change":"Increase track contrast modestly while preserving example colors.","priority":"P2"},{"id":"11","kind":"proposal","area":"Thin track","observation":"The thin ring's unfilled remainder is difficult to locate.","change":"Add a magnified thin-ring inset.","priority":"P2"},{"id":"12","kind":"proposal","area":"Percent placement","observation":"Percent values sit well below the rings.","change":"Bring each value nearer its ring or center it inside.","priority":"P2"},{"id":"13","kind":"proposal","area":"Size card heights","observation":"Five size-variation cards have different bottom edges.","change":"Use equal-height containers while retaining ring sizes.","priority":"P2"},{"id":"14","kind":"proposal","area":"Size ring alignment","observation":"Ring centers move downward as diameter increases.","change":"Align centers on a shared horizontal baseline.","priority":"P2"},{"id":"15","kind":"proposal","area":"28px value","observation":"The smallest example shows 28px but no percentage.","change":"Display its progress outside the ring.","priority":"P2"},{"id":"16","kind":"proposal","area":"40px value","observation":"The second example also lacks a percentage.","change":"Show its value consistently with larger examples.","priority":"P2"},{"id":"17","kind":"proposal","area":"Size units","observation":"28px through 80px do not state diameter versus radius.","change":"Label the row Diameter.","priority":"P2"},{"id":"18","kind":"proposal","area":"Size fill variation","observation":"The size row changes progress as well as diameter.","change":"Use equal percentages for the size-only comparison.","priority":"P2"},{"id":"19","kind":"proposal","area":"Size thickness variation","observation":"Stroke thickness also changes without a caption.","change":"Show stroke width beneath each diameter.","priority":"P2"},{"id":"20","kind":"proposal","area":"Completed ring","observation":"100% is visually a pink ring without a completion cue.","change":"Add a small Completed caption.","priority":"P2"},{"id":"21","kind":"proposal","area":"Size colors","observation":"Five colors lack a stated relationship to size.","change":"Use one color for size comparison or explain the mapping.","priority":"P2"},{"id":"22","kind":"proposal","area":"Section gap","observation":"The Size Variations heading floats between rows.","change":"Align it with the card grid and reduce surrounding gap.","priority":"P2"},{"id":"23","kind":"proposal","area":"Subtitle type","observation":"Radial progress visualization is small and muted.","change":"Increase it slightly or replace it with useful parameter guidance.","priority":"P2"},{"id":"24","kind":"proposal","area":"Footer space","observation":"The bottom fifth is unused.","change":"Add a compact parameter table for all ring specimens.","priority":"P2"},{"id":"25","kind":"proposal","area":"Card padding","observation":"Top specimen titles sit closer to the card edge than lower captions.","change":"Normalize vertical padding within the four main cards.","priority":"P2"}],"sha256":"13e82898d147812c3b0984295efe57900734d6183fb92d31dc1bebf2e8bee9fd","has_mock":false,"reference":null,"legacy":[{"id":"circular_progress","screen":"circular_progress","baseline":"baseline_screenshots/circular_progress.png","current":"screenshot-baselines/screens/circular_progress_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Animated ring is 55% here and 35% in the current capture. This is a captured animation phase, not a regression. Unequal sample-card heights and small legends remain.","sha256":"3987e2ca14a09791ad1a00e0ebb4be006e70cd1e1004d7f66ee35b3f4c4f3eb1","additional_findings":[]}]},{"id":"colors","baseline":"screenshot-baselines/screens/colors_720p.png","summary":"The Midnight palette is intentionally strong and dark. Recommendations clarify semantic roles and numeric color references.","findings":[{"id":"01","kind":"proposal","area":"Theme identity","observation":"Midnight appears only in the bottom sentence.","change":"Move the theme name beside the title.","priority":"P2"},{"id":"02","kind":"proposal","area":"Title color","observation":"The red title strip resembles the Primary specimen.","change":"Label it as theme chrome or use a neutral heading background.","priority":"P2"},{"id":"03","kind":"proposal","area":"Theme values","observation":"Primary through Error/Danger omit their hex values.","change":"Show resolved values below each role.","priority":"P2"},{"id":"04","kind":"proposal","area":"Surface boundary","observation":"The Surface swatch nearly merges with its black tray.","change":"Add an external boundary or neutral backing.","priority":"P2"},{"id":"05","kind":"proposal","area":"Error role","observation":"Error/Danger combines two semantic names.","change":"Choose one canonical role name and explain aliases separately.","priority":"P2"},{"id":"06","kind":"proposal","area":"Primary/error comparison","observation":"Primary red and error coral are close in hue.","change":"Add a caption distinguishing action and error uses.","priority":"P2"},{"id":"07","kind":"proposal","area":"Secondary value","observation":"The gray Secondary tile has no luminance or contrast context.","change":"Add its foreground contrast ratio.","priority":"P2"},{"id":"08","kind":"proposal","area":"Accent foreground","observation":"The yellow Accent uses black text unlike other roles.","change":"Show the resolved foreground choice.","priority":"P2"},{"id":"09","kind":"proposal","area":"Role ordering","observation":"Surface is placed between Accent and Error.","change":"Group action roles, surfaces and status colors explicitly.","priority":"P2"},{"id":"10","kind":"proposal","area":"Theme row heading","observation":"Theme Colors repeats the page title's meaning.","change":"Use Semantic roles.","priority":"P2"},{"id":"11","kind":"proposal","area":"Custom heading","observation":"Custom Colors does not explain independence from theme roles.","change":"Use Fixed custom values.","priority":"P2"},{"id":"12","kind":"proposal","area":"Custom values type","observation":"Hex codes use handwritten characters.","change":"Use monospace text for reliable reading.","priority":"P2"},{"id":"13","kind":"proposal","area":"Custom text alignment","observation":"Color names and hex values form left-aligned blocks inside centered tiles.","change":"Align all blocks to equal internal insets.","priority":"P2"},{"id":"14","kind":"proposal","area":"Red naming","observation":"Red is visually coral-pink.","change":"Use a precise descriptive name while keeping the value.","priority":"P2"},{"id":"15","kind":"proposal","area":"Yellow naming","observation":"Yellow is visibly amber compared with the theme accent.","change":"Name it Amber or Warm yellow.","priority":"P2"},{"id":"16","kind":"proposal","area":"Palette correspondence","observation":"Custom Red matches Error/Danger without explanation.","change":"Show a small equality annotation.","priority":"P2"},{"id":"17","kind":"proposal","area":"Custom foreground","observation":"All custom swatches use black text without a contrast label.","change":"Add the measured foreground ratio below.","priority":"P2"},{"id":"18","kind":"proposal","area":"Tray bounds","observation":"The rightmost tiles extend beyond the black inner tray.","change":"Expand tray padding so all five swatches sit within equal margins.","priority":"P2"},{"id":"19","kind":"proposal","area":"Tile spacing","observation":"The horizontal gaps are inconsistent at the right edge.","change":"Use a five-column grid with uniform gaps.","priority":"P2"},{"id":"20","kind":"proposal","area":"Header alignment","observation":"The title strip and content use different horizontal insets.","change":"Align the title text to the swatch content.","priority":"P2"},{"id":"21","kind":"proposal","area":"Section spacing","observation":"Custom Colors sits close to the upper tray.","change":"Increase the gap before the second section label.","priority":"P2"},{"id":"22","kind":"proposal","area":"Footer density","observation":"One long footer sentence repeats the row organization.","change":"Replace it with a concise theme identifier and legend.","priority":"P2"},{"id":"23","kind":"proposal","area":"Footer gap","observation":"A large empty space separates swatches from the footer.","change":"Move reference details directly under the specimens.","priority":"P2"},{"id":"24","kind":"proposal","area":"Missing background role","observation":"The gallery shows Surface but not a labeled Background specimen.","change":"Add a background swatch within the theme row.","priority":"P2"},{"id":"25","kind":"proposal","area":"Reference context","observation":"The swatches show colors only on black backing.","change":"Add a small light-backing comparison strip outside the primary palette.","priority":"P2"}],"sha256":"a722389bdcea1d33575c9f7ea3aaec86b88725d2e18c7052497a88198bbcc26e","has_mock":false,"reference":null,"legacy":[{"id":"colors","screen":"colors","baseline":"baseline_screenshots/colors.png","current":"screenshot-baselines/screens/colors_720p.png","pixel_identical":true,"size":[1280,720],"summary":"Pixel-identical. Swatches dominate a small central panel, with a large empty band above the footer. Current palette presentation findings apply; do not replace colors that are the actual specimen.","sha256":"a722389bdcea1d33575c9f7ea3aaec86b88725d2e18c7052497a88198bbcc26e","additional_findings":[]}]},{"id":"composer_lab","baseline":"screenshot-baselines/screens/composer_lab_720p.png","summary":"Clipped no-wrap text and the scrolled twelve-line field are explicit fixtures. Proposals preserve them and improve readable diagnostics and test context.","findings":[{"id":"01","kind":"proposal","area":"Title width","observation":"Composer Lab uses a long technical sentence as its title.","change":"Separate the title from a short behavior subtitle.","priority":"P2"},{"id":"02","kind":"proposal","area":"Section 1 heading","observation":"auto-grow + submit_on_enter is tiny.","change":"Use a readable heading with API flags on a second line.","priority":"P2"},{"id":"03","kind":"proposal","area":"First field help","observation":"The editable value doubles as the full instruction.","change":"Move persistent guidance outside the input.","priority":"P2"},{"id":"04","kind":"proposal","area":"Send count","observation":"Sends: 0 is buried in the first heading.","change":"Show a compact submission counter beside the field.","priority":"P2"},{"id":"05","kind":"proposal","area":"Submitted output","observation":"The first example has no visible result area for sent text.","change":"Add a labeled last-submitted preview.","priority":"P2"},{"id":"06","kind":"proposal","area":"Row-cap context","observation":"Capped at 5 rows is named but not visually marked.","change":"Draw a neutral maximum-height outline behind the field.","priority":"P2"},{"id":"07","kind":"proposal","area":"Current rows","observation":"The rows 3 diagnostic is far to the right.","change":"Place current/cap row counts immediately below the first field.","priority":"P2"},{"id":"08","kind":"proposal","area":"State table type","observation":"Composer state keys and values are very small.","change":"Increase diagnostic text size.","priority":"P2"},{"id":"09","kind":"proposal","area":"State alignment","observation":"Keys and values are separated by a wide empty gutter.","change":"Use a compact aligned two-column table.","priority":"P2"},{"id":"10","kind":"proposal","area":"Cursor units","observation":"Cursor 136 does not state bytes, characters or codepoints.","change":"Label the unit explicitly.","priority":"P2"},{"id":"11","kind":"proposal","area":"Row/column indexing","observation":"2/32 has no zero-based or one-based explanation.","change":"State the indexing convention.","priority":"P2"},{"id":"12","kind":"proposal","area":"Scroll units","observation":"scroll y0.0 lacks units.","change":"Display the unit used by the field.","priority":"P2"},{"id":"13","kind":"proposal","area":"Widest measurement","observation":"widest 404px does not identify what width was measured.","change":"Rename it Widest visual line.","priority":"P2"},{"id":"14","kind":"proposal","area":"Second field heading","observation":"Word wrap on competes with the long Enter explanation.","change":"Split behavior label from input instruction.","priority":"P2"},{"id":"15","kind":"proposal","area":"Second field height","observation":"The empty lower area has no visible row guides.","change":"Add optional baseline guides to explain its fixed capacity.","priority":"P2"},{"id":"16","kind":"proposal","area":"No-wrap fixture","observation":"The third line clips intentionally with no external endpoint cue.","change":"Add a small Clipped by design annotation outside the field.","priority":"P2"},{"id":"17","kind":"proposal","area":"No-wrap hidden extent","observation":"The visible line does not show how much content continues.","change":"Add a text-length or horizontal-overflow diagnostic.","priority":"P2"},{"id":"18","kind":"proposal","area":"Scroll fixture","observation":"The fourth field shows ten, eleven, twelve without its current position.","change":"Display Rows 10–12 of 12 beside it.","priority":"P2"},{"id":"19","kind":"proposal","area":"Scroll cue","observation":"The scroll fixture has no visible scrollbar in this capture.","change":"Add an external scroll-range indicator without changing clipping.","priority":"P2"},{"id":"20","kind":"proposal","area":"Key reference","observation":"Keyboard help is tiny and densely packed.","change":"Increase type and group movement, editing and selection.","priority":"P2"},{"id":"21","kind":"proposal","area":"Platform shortcuts","observation":"Alt/Ctrl and Cmd/Ctrl syntax is hard to scan.","change":"Show the active platform's keys first.","priority":"P2"},{"id":"22","kind":"proposal","area":"Mouse help","observation":"Mouse instructions wrap into two distant short lines.","change":"Use a compact list below keyboard help.","priority":"P2"},{"id":"23","kind":"proposal","area":"Two-column balance","observation":"The content occupies only the left two-thirds of the screen.","change":"Widen the examples and diagnostic table proportionally.","priority":"P2"},{"id":"24","kind":"proposal","area":"Section spacing","observation":"The first-to-second field gap is much larger than later gaps.","change":"Use consistent section spacing.","priority":"P2"},{"id":"25","kind":"proposal","area":"Focused example label","observation":"The state table says focused yes without naming the field.","change":"Show the active example number beside the state heading.","priority":"P2"}],"sha256":"73d0972a89851ea849389acbcc7820b7cff5ff67a417f000fd33d388dda71b65","has_mock":false,"reference":null,"legacy":[]},{"id":"config_gap_gallery","baseline":"screenshot-baselines/screens/config_gap_gallery_720p.png","summary":"Clipping, faceted corners and low-contrast explicit text color are intentional. Insets that look equal and the 0x0 measurement need clearer comparison before any rendering diagnosis.","findings":[{"id":"01","kind":"proposal","area":"Page title","observation":"Config options that had no caller describes repository history.","change":"Use Component configuration examples.","priority":"P2"},{"id":"02","kind":"proposal","area":"Panel headings","observation":"API-heavy headings use tiny handwritten text.","change":"Use readable monospace parameter labels.","priority":"P2"},{"id":"03","kind":"proposal","area":"Shadow labels","observation":"hard and soft touch their rectangles' left edges.","change":"Add internal padding or external captions.","priority":"P2"},{"id":"04","kind":"proposal","area":"Shadow comparison","observation":"Hard and soft also differ in fill and radius.","change":"Add matched-shape controls to isolate shadow style.","priority":"P2"},{"id":"05","kind":"proposal","area":"Hard shadow","observation":"The offset is visible but unspecified.","change":"Show its x/y offset in a caption.","priority":"P2"},{"id":"06","kind":"proposal","area":"Soft shadow","observation":"Blur and offset are not labeled.","change":"Display both configured values.","priority":"P2"},{"id":"07","kind":"proposal","area":"Segment example","observation":"3 seg uses an abbreviation and no smooth reference.","change":"Spell out 3 corner segments and add a matched smooth sample.","priority":"P2"},{"id":"08","kind":"proposal","area":"Corner radius","observation":"The three radii differ without numeric labels.","change":"Show 4px, 18px and 20px under the samples.","priority":"P2"},{"id":"09","kind":"proposal","area":"Clamp heading","observation":"The heading promises min/max but omits the limits.","change":"Display min 90px and max 200px.","priority":"P2"},{"id":"10","kind":"proposal","area":"Clamp values","observation":"25%, 55% and 85% show requested widths only.","change":"Add actual resolved pixel widths.","priority":"P2"},{"id":"11","kind":"proposal","area":"Clamp state","observation":"The first and last samples do not identify which bound applies.","change":"Label Min-clamped and Max-clamped.","priority":"P2"},{"id":"12","kind":"proposal","area":"Clamp reference","observation":"No unclamped widths are visible.","change":"Draw thin reference-length lines behind the specimens.","priority":"P2"},{"id":"13","kind":"proposal","area":"Clip boundary","observation":"The clipped region ends immediately under partial content.","change":"Outline its 76px viewport boundary externally.","priority":"P2"},{"id":"14","kind":"proposal","area":"Clip row count","observation":"Rows 0 and 1 are visible without a total count.","change":"Add 4 source rows, viewport 76px.","priority":"P2"},{"id":"15","kind":"proposal","area":"Hide target","observation":"Hide row 2 targets a row mostly below the clip boundary.","change":"Add a small source-row diagram beside the control.","priority":"P2"},{"id":"16","kind":"proposal","area":"Marquee text","observation":"selection begins outside the dashed rectangle's inner edge.","change":"Center it or inset it within the marquee.","priority":"P2"},{"id":"17","kind":"proposal","area":"Marquee parameters","observation":"The dashed rectangle gives no dash or gap measurements.","change":"Display dash 10px, gap 7px outside it.","priority":"P2"},{"id":"18","kind":"proposal","area":"Draw-layer example","observation":"on_draw_bg and on_draw_fg are not visually identified.","change":"Add small labels marking background fill and foreground stroke.","priority":"P2"},{"id":"19","kind":"proposal","area":"Explicit text color","observation":"The deliberately dark red sentence is difficult to read.","change":"Repeat its exact text in a readable external caption.","priority":"P2"},{"id":"20","kind":"proposal","area":"Text inset comparison","observation":"inset 24px and inset 2px appear almost equally flush left.","change":"Add pixel guides and measured inset readouts to expose the comparison.","priority":"P2"},{"id":"21","kind":"proposal","area":"Wrap example","observation":"The wrap-enabled sentence remains one line in the screenshot.","change":"Add a narrow paired specimen that visibly wraps.","priority":"P2"},{"id":"22","kind":"proposal","area":"Activation buttons","observation":"on Press and on Release do not name pointer timing.","change":"Use On pointer down and On pointer up captions.","priority":"P2"},{"id":"23","kind":"proposal","area":"Counter reset","observation":"Both activation counters have no visible reset action.","change":"Add a small shared Reset counters control.","priority":"P2"},{"id":"24","kind":"proposal","area":"Measurement output","observation":"measure_config says 0x0 has no visible probe or expectation.","change":"Show the measured text specimen and expected sizing rule alongside.","priority":"P2"},{"id":"25","kind":"proposal","area":"Focus-selection field","observation":"focus me, all selected is the only explanation of a behavior.","change":"Add an external Select all on focus caption.","priority":"P2"}],"sha256":"2e263b4b7f300c1a7b220cf0f0a3b171ca1d09cbb742392eb0dd2d62d4985161","has_mock":false,"reference":null,"legacy":[]},{"id":"context_menu_lab","baseline":"screenshot-baselines/screens/context_menu_lab_720p.png","summary":"The open context menu provides direct evidence of a clipped first label. Remaining proposals explain point anchoring and improve file/menu hierarchy.","findings":[{"id":"01","kind":"defect","area":"Stage file label","observation":"The open menu shows tage file with the initial S obscured by the selection border.","change":"Inset menu text clear of its selection outline.","priority":"P1"},{"id":"02","kind":"proposal","area":"Menu padding","observation":"Unstage and Copy path begin at the menu's left boundary.","change":"Add consistent horizontal item padding.","priority":"P2"},{"id":"03","kind":"proposal","area":"Menu target","observation":"The open menu obscures rows without identifying its target file.","change":"Show the target filename in a small menu header.","priority":"P2"},{"id":"04","kind":"proposal","area":"Row selection","observation":"No distinct selected-file treatment ties the menu to a row.","change":"Highlight the context-menu target row.","priority":"P2"},{"id":"05","kind":"proposal","area":"Menu action relationship","observation":"Stage file and Unstage are both visually prominent.","change":"Make applicability clear for the target's current staged state.","priority":"P2"},{"id":"06","kind":"proposal","area":"Disabled action","observation":"Discard changes is intentionally dim but unexplained.","change":"Add an external note explaining why it is unavailable for this fixture.","priority":"P2"},{"id":"07","kind":"proposal","area":"Copy shortcut","observation":"Cmd+C is dimmer than Copy path and crowded against the right edge.","change":"Increase shortcut contrast and right inset.","priority":"P2"},{"id":"08","kind":"proposal","area":"Menu grouping","observation":"Stage and Unstage are separated from Copy path only by a narrow gap.","change":"Use a clear separator between repository and utility actions.","priority":"P2"},{"id":"09","kind":"proposal","area":"Menu outline","observation":"The menu border is faint against the file rows.","change":"Increase edge separation or add a subtle shadow.","priority":"P2"},{"id":"10","kind":"proposal","area":"Menu row heights","observation":"The four items have little breathing room around their text.","change":"Use consistent padded menu rows.","priority":"P2"},{"id":"11","kind":"proposal","area":"File list headings","observation":"Files and statuses have no column labels.","change":"Add File and State headers.","priority":"P2"},{"id":"12","kind":"proposal","area":"Status type","observation":"modified, staged and untracked are tiny.","change":"Increase status-label size.","priority":"P2"},{"id":"13","kind":"proposal","area":"State recognition","observation":"All statuses use similar muted text.","change":"Use small labeled status chips.","priority":"P2"},{"id":"14","kind":"proposal","area":"README state","observation":"README.md has no status while other rows do.","change":"Show Clean if the blank means unchanged.","priority":"P2"},{"id":"15","kind":"proposal","area":"Filename type","observation":"Paths use the decorative handwritten font.","change":"Use a readable monospace filename face.","priority":"P2"},{"id":"16","kind":"proposal","area":"File rows","observation":"Six rounded rectangles have large inter-row gaps.","change":"Tighten the list for a clearer file-browser pattern.","priority":"P2"},{"id":"17","kind":"proposal","area":"Title wording","observation":"The title packs the point-anchoring rule into its name.","change":"Use Context menus plus a short subtitle.","priority":"P2"},{"id":"18","kind":"proposal","area":"Top instruction","observation":"right-click either row contradicts the six visible file rows.","change":"Change it to Right-click any file row.","priority":"P2"},{"id":"19","kind":"proposal","area":"Explanation heading","observation":"How this differs from a menu bar is longer than necessary.","change":"Use Point anchoring.","priority":"P2"},{"id":"20","kind":"proposal","area":"Explanation body","observation":"Five small widely spaced lines spread across a large card.","change":"Use a compact readable paragraph with a diagram.","priority":"P2"},{"id":"21","kind":"proposal","area":"Cursor anchor","observation":"The shown menu has no marked anchor point.","change":"Add an optional crosshair at the invocation point.","priority":"P2"},{"id":"22","kind":"proposal","area":"First test button","observation":"right-click me lacks the purpose of its test case.","change":"Label it Open at pointer.","priority":"P2"},{"id":"23","kind":"proposal","area":"Lower test button","observation":"right-click me too includes a long parenthetical.","change":"Label it Bottom-edge flip test.","priority":"P2"},{"id":"24","kind":"proposal","area":"Lower caption","observation":"The bottom explanation is tiny and distant from its test button.","change":"Place it directly above that button.","priority":"P2"},{"id":"25","kind":"proposal","area":"Empty center","observation":"A large unused middle region separates the test cases.","change":"Add a small placement diagram showing below versus flipped above.","priority":"P2"}],"sha256":"eb760be98e16654c0b1003c5fdea3225f19eb4d4c3ab53604dc7b181fd37c3fa","has_mock":false,"reference":null,"legacy":[]},{"id":"cozy_cafe","baseline":"screenshot-baselines/screens/cozy_cafe_720p.png","summary":"The baseline follows the Blossom Cafe mock. Proposals improve customer urgency, action context and readability while retaining the illustrated cafe style.","findings":[{"id":"01","kind":"proposal","area":"Outlined title","observation":"Blossom Cafe uses a very thin dark outline around pale letters.","change":"Strengthen the outline or fill for easier reading.","priority":"P2"},{"id":"02","kind":"proposal","area":"Gold label","observation":"Gold: $1347 mixes a fantasy currency name with a dollar symbol.","change":"Use one currency convention and an icon.","priority":"P2"},{"id":"03","kind":"proposal","area":"Gold number","observation":"The outlined digits are harder to read than neighboring text.","change":"Use solid tabular digits for the balance.","priority":"P2"},{"id":"04","kind":"proposal","area":"Rating stars","observation":"Filled and empty stars differ subtly.","change":"Increase the distinction between earned and unearned stars.","priority":"P2"},{"id":"05","kind":"proposal","area":"Rating value","observation":"Only stars communicate the numeric rating.","change":"Add a small 4/5 value.","priority":"P2"},{"id":"06","kind":"proposal","area":"Customers served","observation":"Customers Served: 23 is tight within the rating box.","change":"Increase inset or put the count on its own quieter line.","priority":"P2"},{"id":"07","kind":"proposal","area":"Special selection","observation":"Lavender Latte differs mainly by border weight.","change":"Add a small Selected marker.","priority":"P2"},{"id":"08","kind":"proposal","area":"Special names","observation":"Outlined white lettering is delicate on pastel fills.","change":"Use stronger solid brown text or a thicker outline.","priority":"P2"},{"id":"09","kind":"proposal","area":"Special economics","observation":"No prices or benefits accompany the three specials.","change":"Add a concise value caption per item.","priority":"P2"},{"id":"10","kind":"proposal","area":"Promote action","observation":"Promote Special does not name the selected special.","change":"Include Lavender Latte in a small action caption.","priority":"P2"},{"id":"11","kind":"proposal","area":"Promote clock","observation":"The clock icon does not state cost or duration.","change":"Show the promotion duration beside it.","priority":"P2"},{"id":"12","kind":"proposal","area":"Customer title","observation":"Customers gives no queue length.","change":"Add a 2 waiting count.","priority":"P2"},{"id":"13","kind":"proposal","area":"Order text","observation":"Emma - Cappuccio puts name and order on one long line.","change":"Separate customer name from the order description.","priority":"P2"},{"id":"14","kind":"proposal","area":"Customer rows","observation":"Emma and Oliver have no visual divider.","change":"Add a subtle separator or distinct row spacing.","priority":"P2"},{"id":"15","kind":"proposal","area":"Wait times","observation":"2m and 5m do not say whether they are elapsed or remaining.","change":"Label the badges Waited or Remaining.","priority":"P2"},{"id":"16","kind":"proposal","area":"Patience labels","observation":"Patience and Patience: LOW are very small.","change":"Increase their text size.","priority":"P2"},{"id":"17","kind":"proposal","area":"Low patience","observation":"The red warning relies on tiny colored text.","change":"Add a clear low-patience icon or badge.","priority":"P2"},{"id":"18","kind":"proposal","area":"Patience bars","observation":"Bars are narrow and visually weak.","change":"Increase their height and show a numeric or verbal status.","priority":"P2"},{"id":"19","kind":"proposal","area":"Serve target","observation":"Serve Next does not reveal which customer will be served.","change":"Show Serve Emma if queue order is fixed.","priority":"P2"},{"id":"20","kind":"proposal","area":"Urgency ordering","observation":"Oliver is low on patience but remains visually secondary.","change":"Use a modest urgency accent on Oliver's row.","priority":"P2"},{"id":"21","kind":"proposal","area":"Music layout","observation":"The slider appears above its label rather than beside it.","change":"Place Music 70% in the same control row.","priority":"P2"},{"id":"22","kind":"proposal","area":"Music track","observation":"The brown unfilled track blends into the warm outline.","change":"Increase filled/unfilled distinction.","priority":"P2"},{"id":"23","kind":"proposal","area":"Chat hierarchy","observation":"Two chat messages share one heavy brown block without a header.","change":"Add a small Guild chat label.","priority":"P2"},{"id":"24","kind":"proposal","area":"Research icon","observation":"A gift icon is labeled Research.","change":"Use a book, flask or research-related symbol.","priority":"P2"},{"id":"25","kind":"proposal","area":"Tool badges","observation":"Inventory 2 and Research! badges are tiny at button corners.","change":"Enlarge badges slightly and explain their counts in tool captions.","priority":"P2"}],"sha256":"55f011da55c9cf312034d99b6f95908098c9273e55a5f98d636fbd9d78e54a24","has_mock":true,"reference":"inspiration/example_cozy_game.png","legacy":[]},{"id":"deadspace_settings","baseline":"screenshot-baselines/screens/deadspace_settings_720p.png","summary":"Layer overlap, subdued rear menu and scan lines are deliberate holographic styling. Findings are refinement proposals grounded in the mock and visible composition.","findings":[{"id":"01","kind":"proposal","area":"Front placement","observation":"The active menu occupies the left half with a large empty right region.","change":"Shift the active stack toward center or reserve the right area for category details.","priority":"P2"},{"id":"02","kind":"proposal","area":"More settings title","observation":"MORE SETTINGS is small relative to the wide active panel.","change":"Increase its spacing and prominence modestly.","priority":"P2"},{"id":"03","kind":"proposal","area":"Settings header","observation":"// SETTINGS repeats the title without navigation context.","change":"Use it as a breadcrumb identifying the parent menu.","priority":"P2"},{"id":"04","kind":"proposal","area":"Active gameplay","observation":"Gameplay uses brighter fill and outline but no shape marker.","change":"Add a slim selection chevron.","priority":"P2"},{"id":"05","kind":"proposal","area":"Active typography","observation":"Gameplay text has similar weight to inactive rows.","change":"Give the selected label a slight weight increase.","priority":"P2"},{"id":"06","kind":"proposal","area":"Scanline intensity","observation":"Horizontal lines run through every label.","change":"Reduce line opacity immediately behind text while preserving the effect.","priority":"P2"},{"id":"07","kind":"proposal","area":"Text edge treatment","observation":"Cyan fringe and thin letters reduce clarity.","change":"Tighten the glow around letter edges.","priority":"P2"},{"id":"08","kind":"proposal","area":"Row interiors","observation":"Labels sit near the left bevel transitions.","change":"Increase left inset beyond the clipped corners.","priority":"P2"},{"id":"09","kind":"proposal","area":"Front header gap","observation":"The heading and Controls row have a larger gap than other rows.","change":"Use a deliberate shared header spacing.","priority":"P2"},{"id":"10","kind":"proposal","area":"Row rhythm","observation":"Eight identical rows provide no category grouping.","change":"Separate legal/about items from gameplay preferences.","priority":"P2"},{"id":"11","kind":"proposal","area":"Policies label","observation":"Policies and Licenses is long and visually equal to core settings.","change":"Place it in a quieter secondary group.","priority":"P2"},{"id":"12","kind":"proposal","area":"Credits placement","observation":"Credits sits directly above the footer with little distinction.","change":"Add a small gap before the footer.","priority":"P2"},{"id":"13","kind":"proposal","area":"Rear menu prominence","observation":"Initial Settings remains detailed enough to compete with the active stack.","change":"Reduce rear text emphasis a little further.","priority":"P2"},{"id":"14","kind":"proposal","area":"Rear active row","observation":"More Settings extends out from behind the front stack.","change":"Use a connector or breadcrumb cue to explain the relationship.","priority":"P2"},{"id":"15","kind":"proposal","area":"Rear title","observation":"INITIAL SETTINGS sits close to the screen's left edge.","change":"Increase its left safe margin.","priority":"P2"},{"id":"16","kind":"proposal","area":"Overlapping footer","observation":"The front footer overlays the rear active-row region.","change":"Offset the rear panel vertically to reduce dense intersections.","priority":"P2"},{"id":"17","kind":"proposal","area":"Footer key labels","observation":"Enter SELECT and Esc BACK are plain text with similar weight.","change":"Render Enter and Esc as distinct keycaps.","priority":"P2"},{"id":"18","kind":"proposal","area":"Footer spacing","observation":"Select and Back cluster at the right end.","change":"Give the two actions consistent grouped spacing.","priority":"P2"},{"id":"19","kind":"proposal","area":"Footer alignment","observation":"The footer extends slightly beyond the active row stack.","change":"Align its outer width with the main panel.","priority":"P2"},{"id":"20","kind":"proposal","area":"Menu depth","observation":"The baseline stacks are flatter than the mock's skewed holographic layers.","change":"Add restrained perspective or skew matching the mock.","priority":"P2"},{"id":"21","kind":"proposal","area":"Selected description","observation":"Gameplay has no descriptive content in the empty right area.","change":"Show a one-sentence category preview.","priority":"P2"},{"id":"22","kind":"proposal","area":"Navigation context","observation":"No visible cue states this is a submenu.","change":"Add Initial settings > More settings as a compact breadcrumb.","priority":"P2"},{"id":"23","kind":"proposal","area":"Category symbols","observation":"Long text rows require reading every item.","change":"Add restrained monochrome category symbols if consistent with the reference.","priority":"P2"},{"id":"24","kind":"proposal","area":"Background grid","observation":"The faint grid ends abruptly behind the active panel region.","change":"Fade its edges more gradually.","priority":"P2"},{"id":"25","kind":"proposal","area":"Scale balance","observation":"Large black margins dominate the composition at 720p.","change":"Increase active-menu scale slightly while retaining the layered layout.","priority":"P2"}],"sha256":"8ec07e7c81831bbac6abef46bd628914522e3e325a1927dc3f68c52ed107feab","has_mock":true,"reference":"inspiration/example_deadspace.jpg","legacy":[]},{"id":"decorative_frame","baseline":"screenshot-baselines/screens/decorative_frame_720p.png","summary":"Frame differences are intentional. Twenty defensible proposals clarify the comparison; the simple three-card fixture does not support twenty-five independent defects.","findings":[{"id":"01","kind":"proposal","area":"Subtitle claim","observation":"The same card is shown with three different titles and body texts.","change":"Use identical card content for a controlled comparison.","priority":"P2"},{"id":"02","kind":"proposal","area":"Frame labels","observation":"KraftPaper is a code-style identifier beside ordinary Simple and Inset labels.","change":"Use Kraft paper and place the API name below.","priority":"P2"},{"id":"03","kind":"proposal","area":"Caption type","observation":"Layered + corners and other captions are tiny.","change":"Increase caption size.","priority":"P2"},{"id":"04","kind":"proposal","area":"Card headings","observation":"Field Notes, Tide Table and Plate 14 vary in apparent line length.","change":"Use the same heading to compare frames fairly.","priority":"P2"},{"id":"05","kind":"proposal","area":"Body text","observation":"The small handwritten body is difficult to inspect from a distance.","change":"Increase body type slightly.","priority":"P2"},{"id":"06","kind":"proposal","area":"Body alignment","observation":"All body text is centered despite short prose fragments.","change":"Use consistent left-aligned content inset.","priority":"P2"},{"id":"07","kind":"proposal","area":"Kraft corner detail","observation":"Four dark corner tabs have no explanation.","change":"Add a small annotated corner enlargement.","priority":"P2"},{"id":"08","kind":"proposal","area":"Kraft layers","observation":"The layered border has no thickness labels.","change":"Show frame-band and inner-padding measurements.","priority":"P2"},{"id":"09","kind":"proposal","area":"Simple border","observation":"A very thin blue outline is hard to inspect.","change":"Add an enlarged reference corner outside the specimen.","priority":"P2"},{"id":"10","kind":"proposal","area":"Inset lighting","observation":"The gray border's light direction is unnamed.","change":"Add a subtle top-left lighting arrow.","priority":"P2"},{"id":"11","kind":"proposal","area":"Inset shadow","observation":"Sunken shadow does not state the shadow dimensions.","change":"Show the configured inset thickness.","priority":"P2"},{"id":"12","kind":"proposal","area":"Frame dimensions","observation":"The cards appear similar in size but dimensions are unstated.","change":"Print shared outer dimensions above the row.","priority":"P2"},{"id":"13","kind":"proposal","area":"Content padding","observation":"Different frame widths leave different visual insets.","change":"Add content-bound guides to compare usable space.","priority":"P2"},{"id":"14","kind":"proposal","area":"Frame colors","observation":"Brown, blue and gray alter more than border treatment.","change":"Add a neutral-color comparison strip.","priority":"P2"},{"id":"15","kind":"proposal","area":"Caption alignment","observation":"Frame names sit close to the bottoms of large cards.","change":"Use equal caption blocks with consistent gap.","priority":"P2"},{"id":"16","kind":"proposal","area":"Card proportion","observation":"Large empty interiors surround two-line texts.","change":"Reduce card height or add more representative content.","priority":"P2"},{"id":"17","kind":"proposal","area":"Footer language","observation":"Pick by weight uses subjective guidance.","change":"State concrete use cases for each frame.","priority":"P2"},{"id":"18","kind":"proposal","area":"Footer typography","observation":"The recommendation is one small line across a wide bar.","change":"Increase size and divide guidance by frame.","priority":"P2"},{"id":"19","kind":"proposal","area":"Footer border","observation":"The recommendation itself has a decorative frame that competes with samples.","change":"Use a quieter note treatment.","priority":"P2"},{"id":"20","kind":"proposal","area":"Lower whitespace","observation":"A large empty band follows the recommendation.","change":"Use it for a compact parameter legend.","priority":"P2"}],"sha256":"681bedb5212f51c9e4a666e7cf75a88d72a406101473ea610d3e7c25b3f5c036","has_mock":false,"reference":null,"legacy":[]},{"id":"decorators","baseline":"screenshot-baselines/screens/decorators_720p.png","summary":"Sharp borders, grids and accent bars are intentional. The small green panel's bracket extent and the first quote's text placement show concrete alignment issues.","findings":[{"id":"01","kind":"defect","area":"Green status brackets","observation":"Green corner brackets extend well beyond the ONLINE panel and around its caption.","change":"Anchor the brackets to the visible ONLINE panel bounds.","priority":"P2"},{"id":"02","kind":"defect","area":"First quote padding","observation":"The first quote starts almost against the thick teal accent bar.","change":"Add a consistent left content inset.","priority":"P2"},{"id":"03","kind":"proposal","area":"Page title","observation":"UI Decorators is small relative to the unused screen area.","change":"Increase title size modestly.","priority":"P2"},{"id":"04","kind":"proposal","area":"Subtitle type","observation":"Composable visual effects via .decorate() is tiny.","change":"Use a readable subtitle with monospace API text.","priority":"P2"},{"id":"05","kind":"proposal","area":"Column headings","observation":"with_brackets(), with_grid_bg() and with_quote() are small and low-emphasis.","change":"Add human-readable headings above the API names.","priority":"P2"},{"id":"06","kind":"proposal","area":"Bracket dimensions","observation":"The cyan and amber brackets have no length annotation.","change":"Show bracket length and stroke width in captions.","priority":"P2"},{"id":"07","kind":"proposal","area":"Status title","observation":"SYSTEM STATUS is small inside a large panel.","change":"Increase title size or reduce panel height.","priority":"P2"},{"id":"08","kind":"proposal","area":"Status message","observation":"All systems operational uses very tiny lettering.","change":"Increase body text size.","priority":"P2"},{"id":"09","kind":"proposal","area":"Warning text","observation":"Hull integrity at 47% is smaller than the available panel allows.","change":"Enlarge it and separate the percentage.","priority":"P2"},{"id":"10","kind":"proposal","area":"Warning punctuation","observation":"! WARNING ! uses text punctuation as the icon.","change":"Use a distinct warning symbol.","priority":"P2"},{"id":"11","kind":"proposal","area":"Online marker","observation":"The green dot is tiny relative to its status word.","change":"Increase it slightly and align its center with the label.","priority":"P2"},{"id":"12","kind":"proposal","area":"Bracket caption","observation":"The caption sits inside the overextended green brackets.","change":"Move it outside specimen bounds after correcting the anchor.","priority":"P2"},{"id":"13","kind":"proposal","area":"Grid labels","observation":"The first two grids have no individual names.","change":"Label them Coarse 20px and Dense grid with actual spacing.","priority":"P2"},{"id":"14","kind":"proposal","area":"Grid dot","observation":"The teal center dot has no stated role.","change":"Label it as the center marker.","priority":"P2"},{"id":"15","kind":"proposal","area":"Dense grid","observation":"Dense lines have no scale reference.","change":"Add a small spacing ruler outside the panel.","priority":"P2"},{"id":"16","kind":"proposal","area":"Sector grid","observation":"SECTOR 7-G has no explanation of combined decorators.","change":"Caption it Grid + brackets.","priority":"P2"},{"id":"17","kind":"proposal","area":"Grid contrast","observation":"The three grid specimens vary in brightness without numeric captions.","change":"Show line opacity values for comparison.","priority":"P2"},{"id":"18","kind":"proposal","area":"Quote examples","observation":"The first quote lacks attribution while the others include it.","change":"Label it No attribution to clarify the variant.","priority":"P2"},{"id":"19","kind":"proposal","area":"First quote wrapping","observation":"The line breaks after you and leaves do. on a short second line.","change":"Adjust content width or text size for a balanced wrap.","priority":"P2"},{"id":"20","kind":"proposal","area":"Quote attribution","observation":"Commander Shepard and GLaDOS labels are tiny.","change":"Increase attribution size while keeping it secondary.","priority":"P2"},{"id":"21","kind":"proposal","area":"Quote bar widths","observation":"Teal, amber and green accent bars vary markedly.","change":"Show their configured widths.","priority":"P2"},{"id":"22","kind":"proposal","area":"Quote alignment","observation":"The first quote starts farther left than the later quotes.","change":"Use a shared content inset across examples.","priority":"P2"},{"id":"23","kind":"proposal","area":"Column height","observation":"The three specimen stacks end on different baselines.","change":"Use aligned example rows with separate captions.","priority":"P2"},{"id":"24","kind":"proposal","area":"Lower blank space","observation":"Nearly the lower third is empty.","change":"Add annotated decorator-parameter references.","priority":"P2"},{"id":"25","kind":"proposal","area":"Color mapping","observation":"Teal, amber and green denote both status and different examples.","change":"Add captions separating semantic color from decorator behavior.","priority":"P2"}],"sha256":"230e50b4dc19158819202eeedf3a3424f12541ffa75298df251addcf4770b30b","has_mock":false,"reference":null,"legacy":[]},{"id":"dialog_confirm","baseline":"screenshot-baselines/screens/dialog_confirm_720p.png","summary":"A clear two-action confirmation is captured over an intentionally dimmed backdrop. Eighteen defensible refinements are listed; focus, dismissal and renderer behavior cannot be judged from this image.","findings":[{"id":"01","kind":"proposal","area":"Dialog title","observation":"Apply changes? does not name the affected settings.","change":"Use Apply display changes?.","priority":"P2"},{"id":"02","kind":"proposal","area":"Change summary","observation":"The dialog describes new settings without listing changed values.","change":"Show a compact old-to-new summary.","priority":"P2"},{"id":"03","kind":"proposal","area":"Restart wording","observation":"Restart the renderer uses implementation terminology.","change":"Describe the visible display interruption.","priority":"P2"},{"id":"04","kind":"proposal","area":"Recovery wording","observation":"Revert from the settings menu afterwards gives no precise route.","change":"Name the Display settings path.","priority":"P2"},{"id":"05","kind":"proposal","area":"Display recovery","observation":"The message assumes the user can still see the screen after applying.","change":"Offer an explicit timed-revert design for unsupported display changes.","priority":"P2"},{"id":"06","kind":"proposal","area":"Body length","observation":"The explanation wraps across three widely tracked lines.","change":"Use a standard body face and shorter sentences.","priority":"P2"},{"id":"07","kind":"proposal","area":"Body spacing","observation":"The title and message are separated by a large gap.","change":"Reduce the title-to-body spacing.","priority":"P2"},{"id":"08","kind":"proposal","area":"Button size","observation":"Cancel and Apply labels are small within their buttons.","change":"Increase action-label size.","priority":"P2"},{"id":"09","kind":"proposal","area":"Apply label","observation":"Apply repeats the vague title verb.","change":"Use Apply display settings.","priority":"P2"},{"id":"10","kind":"proposal","area":"Cancel meaning","observation":"Cancel does not state that current settings remain.","change":"Use Keep current settings where space permits.","priority":"P2"},{"id":"11","kind":"proposal","area":"Button alignment","observation":"The action row is inset farther than the message text.","change":"Align its right edge with the body text column.","priority":"P2"},{"id":"12","kind":"proposal","area":"Button gap","observation":"Cancel and Apply are separated by a large empty gap.","change":"Use a consistent compact action-group gap.","priority":"P2"},{"id":"13","kind":"proposal","area":"Dialog bottom","observation":"Substantial blank space follows the buttons.","change":"Reduce dialog height to fit the content.","priority":"P2"},{"id":"14","kind":"proposal","area":"Dialog edge","observation":"The dark panel has no clear border or shadow against the backdrop.","change":"Add subtle edge separation.","priority":"P2"},{"id":"15","kind":"proposal","area":"Current context","observation":"Visible 2560×1440 and 120Hz values do not identify pending versus current.","change":"Mark the pending fields in the backdrop before dimming.","priority":"P2"},{"id":"16","kind":"proposal","area":"Changed-field cue","observation":"All backdrop rows share the same appearance.","change":"Add a small changed marker to edited settings.","priority":"P2"},{"id":"17","kind":"proposal","area":"Modal heading hierarchy","observation":"The dialog title is only modestly larger than body text.","change":"Increase heading weight.","priority":"P2"},{"id":"18","kind":"proposal","area":"Backdrop chrome","observation":"Harbour Studio and navigation remain visible but do not identify the confirmation source.","change":"Add a Display changes caption within the dialog.","priority":"P2"}],"sha256":"d843a0a32899ab5415002b53ce8c1135365767d681d3358c3b0df865c50ffbda","has_mock":false,"reference":null,"legacy":[]},{"id":"dialog_danger","baseline":"screenshot-baselines/screens/dialog_danger_720p.png","summary":"The destructive action is clearly red and the warning is explicit. Eighteen grounded improvements cover save identification, wording and the reused background fixture.","findings":[{"id":"01","kind":"proposal","area":"Save title","observation":"Delete save? omits the save's identity.","change":"Use the title Delete Chapter 3 autosave?","priority":"P2"},{"id":"02","kind":"proposal","area":"Save name wrapping","observation":"Chapter 3 - Autosave is split across body lines.","change":"Place the save name on its own line.","priority":"P2"},{"id":"03","kind":"proposal","area":"Save metadata","observation":"Only the save name identifies the destructive target.","change":"Add timestamp and playtime for verification.","priority":"P2"},{"id":"04","kind":"proposal","area":"Save preview","observation":"The dialog has no visual identifier for the save slot.","change":"Add a small slot thumbnail or chapter emblem.","priority":"P2"},{"id":"05","kind":"proposal","area":"Warning hierarchy","observation":"Permanent deletion and the object name use equal weight.","change":"Emphasize the save name and irreversible consequence separately.","priority":"P2"},{"id":"06","kind":"proposal","area":"Warning redundancy","observation":"Permanently deletes and cannot be undone repeat the same point.","change":"Use one direct irreversible-action sentence.","priority":"P2"},{"id":"07","kind":"proposal","area":"Delete label","observation":"Delete is generic.","change":"Use Delete save.","priority":"P2"},{"id":"08","kind":"proposal","area":"Cancel label","observation":"Cancel is less explicit than the destructive alternative.","change":"Use Keep save.","priority":"P2"},{"id":"09","kind":"proposal","area":"Danger icon","observation":"Only the button color marks the destructive action visually.","change":"Add a restrained warning icon beside the title.","priority":"P2"},{"id":"10","kind":"proposal","area":"Body font","observation":"The save name uses handwritten characters.","change":"Use a readable body font for the target identifier.","priority":"P2"},{"id":"11","kind":"proposal","area":"Title gap","observation":"A large gap separates title from the warning.","change":"Tighten the vertical rhythm.","priority":"P2"},{"id":"12","kind":"proposal","area":"Button text","observation":"Action labels are small within 132px buttons.","change":"Increase label size.","priority":"P2"},{"id":"13","kind":"proposal","area":"Action spacing","observation":"Cancel and Delete have a wide gap without a grouping cue.","change":"Use a standard action-row gap.","priority":"P2"},{"id":"14","kind":"proposal","area":"Bottom padding","observation":"Large empty space follows the action row.","change":"Reduce panel height.","priority":"P2"},{"id":"15","kind":"proposal","area":"Dialog boundary","observation":"The panel blends into the dark display rows behind it.","change":"Add a subtle border or shadow.","priority":"P2"},{"id":"16","kind":"proposal","area":"Backdrop section","observation":"Save slots appears above Resolution and Refresh rate settings.","change":"Use a small save-slot list behind this fixture.","priority":"P2"},{"id":"17","kind":"proposal","area":"Sidebar context","observation":"Display remains selected behind the save deletion dialog.","change":"Use a Saves navigation item for this demonstration.","priority":"P2"},{"id":"18","kind":"proposal","area":"Selection context","observation":"No visible background item corresponds to Chapter 3 autosave.","change":"Highlight the target save slot behind the scrim.","priority":"P2"}],"sha256":"f33510b0feb265c69d7b72d0e4cf8a292fb2c112a72ba156becb98ffe68d631e","has_mock":false,"reference":null,"legacy":[]},{"id":"dialog_fyi","baseline":"screenshot-baselines/screens/dialog_fyi_720p.png","summary":"The three-action unsaved-changes fixture is readable. Eighteen proposals improve the decision and backdrop context; no unseen save or dismissal behavior is claimed broken.","findings":[{"id":"01","kind":"proposal","area":"Document identity","observation":"The warning refers only to this document.","change":"Show the document name prominently.","priority":"P2"},{"id":"02","kind":"proposal","area":"Title question","observation":"Unsaved changes states a condition without naming the decision.","change":"Use Save changes before leaving?.","priority":"P2"},{"id":"03","kind":"proposal","area":"Trigger context","observation":"The text does not identify whether closing, switching or quitting caused the prompt.","change":"Name the pending action.","priority":"P2"},{"id":"04","kind":"proposal","area":"Body verbosity","observation":"What would you like to do? adds length without decision information.","change":"Replace it with the consequence of leaving.","priority":"P2"},{"id":"05","kind":"proposal","area":"Save label","observation":"Save does not say whether it also completes the pending action.","change":"Use Save and close when that is the demonstrated flow.","priority":"P2"},{"id":"06","kind":"proposal","area":"Keep editing","observation":"Keep editing clearly preserves work but is visually secondary to Save.","change":"Keep it secondary and add a concise return-to-editor cue.","priority":"P2"},{"id":"07","kind":"proposal","area":"Discard wording","observation":"Discard changes does not mention permanent loss of unsaved edits.","change":"Use Discard unsaved changes or supporting text.","priority":"P2"},{"id":"08","kind":"proposal","area":"Discard styling","observation":"Discard changes looks like plain text rather than an action.","change":"Add a clear low-emphasis button boundary.","priority":"P2"},{"id":"09","kind":"proposal","area":"Destructive distinction","observation":"The discard action uses the same pale text as ordinary content.","change":"Use a restrained destructive accent.","priority":"P2"},{"id":"10","kind":"proposal","area":"Action spacing","observation":"Three actions have uneven apparent widths and gaps.","change":"Use a structured row with discard separate from keep/save.","priority":"P2"},{"id":"11","kind":"proposal","area":"Button labels","observation":"Keep editing and Save use very small type.","change":"Increase action-label size.","priority":"P2"},{"id":"12","kind":"proposal","area":"Body measure","observation":"The sentence runs across most of a wide dialog.","change":"Constrain body text to a comfortable line length.","priority":"P2"},{"id":"13","kind":"proposal","area":"Heading weight","observation":"The title differs little from the body style.","change":"Increase heading weight.","priority":"P2"},{"id":"14","kind":"proposal","area":"Bottom space","observation":"A large blank band remains below the buttons.","change":"Reduce the panel height.","priority":"P2"},{"id":"15","kind":"proposal","area":"Modal boundary","observation":"The dark panel has little separation from the dimmed background.","change":"Add a subtle outline or shadow.","priority":"P2"},{"id":"16","kind":"proposal","area":"Backdrop content","observation":"Editor is shown above display-setting rows.","change":"Use a document-editor preview behind the fixture.","priority":"P2"},{"id":"17","kind":"proposal","area":"Backdrop navigation","observation":"Display remains selected for an editor warning.","change":"Use a matching Documents or Editor navigation item.","priority":"P2"},{"id":"18","kind":"proposal","area":"Unsaved cue","observation":"No background document tab or dirty marker identifies pending edits.","change":"Add an unsaved marker to the previewed document.","priority":"P2"}],"sha256":"f5c5a1e0d5fc04b61888ef4d7c8bc6502e1f5ee5819a71f2349cba386e0f54d8","has_mock":false,"reference":null,"legacy":[]},{"id":"dialog_info","baseline":"screenshot-baselines/screens/dialog_info_720p.png","summary":"This one-button connection notice supports sixteen distinct refinements. More would require inventing interaction defects or padding a sparse specimen.","findings":[{"id":"01","kind":"proposal","area":"Action label","observation":"OK does not name the destination described in the message.","change":"Use Return to main menu.","priority":"P2"},{"id":"02","kind":"proposal","area":"Action timing","observation":"Returning to the main menu sounds automatic despite the acknowledgment button.","change":"State whether pressing the button starts the return.","priority":"P2"},{"id":"03","kind":"proposal","area":"Connection identity","observation":"The message names only the host.","change":"Show the session or host name when available.","priority":"P2"},{"id":"04","kind":"proposal","area":"Loss explanation","observation":"Disconnected from the host repeats Connection lost.","change":"Use the body to explain the known consequence.","priority":"P2"},{"id":"05","kind":"proposal","area":"Progress consequence","observation":"The notice does not say whether match progress is retained.","change":"Add a concise save/progress statement where supported.","priority":"P2"},{"id":"06","kind":"proposal","area":"Recovery option","observation":"The visible action offers no reconnect path.","change":"If the demo supports it, add Retry beside return.","priority":"P2"},{"id":"07","kind":"proposal","area":"Connection symbol","observation":"No icon distinguishes the notice from ordinary information.","change":"Add a small disconnected-network symbol.","priority":"P2"},{"id":"08","kind":"proposal","area":"Body spacing","observation":"Two short lines sit far below the title.","change":"Reduce title-to-body spacing.","priority":"P2"},{"id":"09","kind":"proposal","area":"Action alignment","observation":"The single button is offset toward the right of the panel.","change":"Align it consistently with the content column or center it deliberately.","priority":"P2"},{"id":"10","kind":"proposal","area":"Action type","observation":"OK is tiny inside the teal button.","change":"Increase its label size.","priority":"P2"},{"id":"11","kind":"proposal","area":"Panel height","observation":"The panel has substantial empty space below the action.","change":"Fit its height to the content.","priority":"P2"},{"id":"12","kind":"proposal","area":"Panel boundary","observation":"The notice lacks strong edge separation from the dark backdrop.","change":"Add a subtle border or shadow.","priority":"P2"},{"id":"13","kind":"proposal","area":"Backdrop section","observation":"Multiplayer appears above display settings.","change":"Use a lobby or session list behind the fixture.","priority":"P2"},{"id":"14","kind":"proposal","area":"Sidebar selection","observation":"Display remains selected under a multiplayer notice.","change":"Use a Multiplayer navigation item.","priority":"P2"},{"id":"15","kind":"proposal","area":"Session context","observation":"No visible lobby identifies the disconnected session.","change":"Show its selected session row behind the scrim.","priority":"P2"},{"id":"16","kind":"proposal","area":"Heading style","observation":"Connection lost uses the same handwritten face as generic demo text.","change":"Use a clearer UI heading face.","priority":"P2"}],"sha256":"02a6bcee771ca3e86d5a818c38925a8afb96a088d0833a7d95f84af6d0f27fd1","has_mock":false,"reference":null,"legacy":[]},{"id":"dialog_prompt","baseline":"screenshot-baselines/screens/dialog_prompt_720p.png","summary":"The rename field is visibly preselected, which is appropriate for this fixture. Twenty proposals improve target identity, field layout and supporting context without judging unseen validation.","findings":[{"id":"01","kind":"proposal","area":"Current file","observation":"Rename file does not show the existing name outside the editable field.","change":"Add a current-file caption.","priority":"P2"},{"id":"02","kind":"proposal","area":"File location","observation":"The prompt does not identify the file's folder.","change":"Show a compact parent-folder path.","priority":"P2"},{"id":"03","kind":"proposal","area":"Field label","observation":"Enter a new name for this file is a long instruction.","change":"Use the persistent label New name.","priority":"P2"},{"id":"04","kind":"proposal","area":"Input alignment","observation":"The input begins farther right than the title and instruction.","change":"Align the field to the content column.","priority":"P2"},{"id":"05","kind":"proposal","area":"Input width","observation":"The field ends before the action group's right edge.","change":"Use a shared right alignment.","priority":"P2"},{"id":"06","kind":"proposal","area":"Filename typography","observation":"untitled_map uses handwritten characters.","change":"Use a clear filename text face.","priority":"P2"},{"id":"07","kind":"proposal","area":"Selection fill","observation":"The selected text has a low-contrast blue highlight over purple.","change":"Increase selected-text foreground/background separation.","priority":"P2"},{"id":"08","kind":"proposal","area":"Field boundary","observation":"The purple field has no distinct border against its surrounding panel.","change":"Add a subtle input border.","priority":"P2"},{"id":"09","kind":"proposal","area":"Field color","observation":"Purple is stronger than the primary Rename action.","change":"Use a quieter field fill while preserving selection visibility.","priority":"P2"},{"id":"10","kind":"proposal","area":"Extension handling","observation":"The visible name has no extension context.","change":"Show the preserved extension separately if the fixture represents a file with one.","priority":"P2"},{"id":"11","kind":"proposal","area":"Name constraints","observation":"No filename rules are displayed.","change":"Add concise supported-name guidance below the input.","priority":"P2"},{"id":"12","kind":"proposal","area":"Duplicate context","observation":"The prompt has no space reserved for a duplicate-name message.","change":"Reserve a compact validation line without asserting a current error.","priority":"P2"},{"id":"13","kind":"proposal","area":"Rename preview","observation":"Only the editable value communicates the result.","change":"Add a small resulting-filename preview when extension handling matters.","priority":"P2"},{"id":"14","kind":"proposal","area":"Rename label","observation":"Rename is clear but small.","change":"Increase action-label size.","priority":"P2"},{"id":"15","kind":"proposal","area":"Cancel placement","observation":"Cancel begins well inside the input's left edge.","change":"Align the action group to the field's right edge with a regular gap.","priority":"P2"},{"id":"16","kind":"proposal","area":"Bottom space","observation":"The panel leaves a large empty region below the actions.","change":"Reduce dialog height.","priority":"P2"},{"id":"17","kind":"proposal","area":"Title spacing","observation":"The heading and instruction are separated by a large gap.","change":"Tighten the vertical spacing.","priority":"P2"},{"id":"18","kind":"proposal","area":"Backdrop content","observation":"Files appears above Resolution and Refresh rate rows.","change":"Use a compact file list behind the fixture.","priority":"P2"},{"id":"19","kind":"proposal","area":"Backdrop navigation","observation":"Display is selected despite a file rename.","change":"Select Files in the demo navigation.","priority":"P2"},{"id":"20","kind":"proposal","area":"Target selection","observation":"No background file row matches untitled_map.","change":"Highlight the renamed file in the backdrop.","priority":"P2"}],"sha256":"412549308ed04ca639a1f080295d87809a6208253e88efafcea28235ba13c299","has_mock":false,"reference":null,"legacy":[]},{"id":"divider_lab","baseline":"screenshot-baselines/screens/divider_lab_720p.png","summary":"The two draggable dividers and the non-moving rule are intentional. Twenty-two grounded proposals make sizing and the distinction between specimens clearer.","findings":[{"id":"01","kind":"defect","area":"Pane labels","observation":"left 300px, right fills the rest, top 150px and bottom fills the rest touch pane edges.","change":"Add a consistent small text inset.","priority":"P2"},{"id":"02","kind":"proposal","area":"Title","observation":"The title combines the component name and all instructions.","change":"Separate Divider examples from a short instruction.","priority":"P2"},{"id":"03","kind":"proposal","area":"Vertical divider","observation":"The narrow bar has no visible grip.","change":"Add a centered grip marker.","priority":"P2"},{"id":"04","kind":"proposal","area":"Horizontal divider","observation":"The horizontal bar is a plain line like the non-moving rule.","change":"Add a grip marker to distinguish it.","priority":"P2"},{"id":"05","kind":"proposal","area":"Divider labels","observation":"Neither draggable bar has its own caption.","change":"Label Width divider and Height divider outside the panes.","priority":"P2"},{"id":"06","kind":"proposal","area":"Left dimension","observation":"left 300px omits whether 300 is requested or actual width.","change":"Show the measured width explicitly.","priority":"P2"},{"id":"07","kind":"proposal","area":"Right dimension","observation":"right fills the rest gives no resolved measurement.","change":"Display the current right-pane width.","priority":"P2"},{"id":"08","kind":"proposal","area":"Top dimension","observation":"top 150px omits a measurement guide.","change":"Add a vertical dimension bracket.","priority":"P2"},{"id":"09","kind":"proposal","area":"Bottom dimension","observation":"bottom fills the rest gives no resulting height.","change":"Display the current bottom-pane height.","priority":"P2"},{"id":"10","kind":"proposal","area":"Pane total","observation":"The total split width is not shown.","change":"Add the overall container width beside the first example.","priority":"P2"},{"id":"11","kind":"proposal","area":"Height total","observation":"The total split height is not shown.","change":"Add the overall height beside the second example.","priority":"P2"},{"id":"12","kind":"proposal","area":"Minimum widths","observation":"No boundary values are visible for the vertical split.","change":"Show its configured min/max values.","priority":"P2"},{"id":"13","kind":"proposal","area":"Minimum heights","observation":"No range is given for the horizontal split.","change":"Show its configured height limits.","priority":"P2"},{"id":"14","kind":"proposal","area":"Ratio comparison","observation":"Only pixel measurements appear.","change":"Add the resulting percentage split beside each pixel value.","priority":"P2"},{"id":"15","kind":"proposal","area":"Reset control","observation":"No visible action restores 300px and 150px.","change":"Add Reset dividers.","priority":"P2"},{"id":"16","kind":"proposal","area":"Drag feedback","observation":"No numeric delta is reserved near the bars.","change":"Add a drag-delta readout beside each specimen.","priority":"P2"},{"id":"17","kind":"proposal","area":"Pane content","observation":"The large empty panes provide little reflow evidence.","change":"Add a short paragraph or grid that responds to resizing.","priority":"P2"},{"id":"18","kind":"proposal","area":"Vertical specimen height","observation":"The first split consumes a large area for two short labels.","change":"Reduce its height enough to fit measurement captions.","priority":"P2"},{"id":"19","kind":"proposal","area":"Horizontal specimen labeling","observation":"Top and bottom text float at vertical centers.","change":"Place labels in consistent top-left positions.","priority":"P2"},{"id":"20","kind":"proposal","area":"Rule caption","observation":"The bottom API explanation is tiny.","change":"Increase its size and use monospace for divider().","priority":"P2"},{"id":"21","kind":"proposal","area":"Rule semantics","observation":"Movement ignored describes implementation rather than visual purpose.","change":"Label it Static 1px separator.","priority":"P2"},{"id":"22","kind":"proposal","area":"Rule boundary","observation":"The thin bottom rule blends into the black background.","change":"Add endpoint markers outside it for inspection.","priority":"P2"}],"sha256":"39a242480c241637e3e611c5ac408eb11681f5c73870d3f88c7d64f1bcee449b","has_mock":false,"reference":null,"legacy":[]},{"id":"drag_drop","baseline":"screenshot-baselines/screens/drag_drop_720p.png","summary":"The three-column board is a drag-and-drop demonstration. Proposals improve card affordance and board information without asserting unseen drag or keyboard failures.","findings":[{"id":"01","kind":"defect","area":"Card padding","observation":"Design mockups, API endpoints and other titles begin almost on their card borders.","change":"Add comfortable horizontal text padding.","priority":"P2"},{"id":"02","kind":"proposal","area":"Board title","observation":"Sprint Board uses a large handwritten heading.","change":"Use a clearer heading face while retaining the casual style.","priority":"P2"},{"id":"03","kind":"proposal","area":"Instruction type","observation":"The instruction is almost as large as column headings.","change":"Reduce it slightly and improve hierarchy.","priority":"P2"},{"id":"04","kind":"proposal","area":"Instruction scope","observation":"Drag cards between columns omits reordering within a column.","change":"Mention reorder behavior if supported by this demo.","priority":"P2"},{"id":"05","kind":"proposal","area":"Card grip","observation":"Cards have no visible drag-handle cue.","change":"Add a small grip on each card.","priority":"P2"},{"id":"06","kind":"proposal","area":"Column counts","observation":"Counts are embedded in oversized headings.","change":"Use compact count badges beside the titles.","priority":"P2"},{"id":"07","kind":"proposal","area":"To Do heading","observation":"To Do differs in capitalization from In Progress.","change":"Use consistent sentence casing.","priority":"P2"},{"id":"08","kind":"proposal","area":"Column boundaries","observation":"Columns and cards are close gray tones.","change":"Increase boundary distinction modestly.","priority":"P2"},{"id":"09","kind":"proposal","area":"Card borders","observation":"Very thin outlines are hard to see.","change":"Use a slightly stronger card border or subtle shadow.","priority":"P2"},{"id":"10","kind":"proposal","area":"Card density","observation":"Tall cards contain only one short text line.","change":"Reduce card height or add useful metadata.","priority":"P2"},{"id":"11","kind":"proposal","area":"Board whitespace","observation":"Large empty areas remain under all three stacks.","change":"Add a quiet drop-area cue at each stack's end.","priority":"P2"},{"id":"12","kind":"proposal","area":"Done status","observation":"Done cards look identical to unfinished cards.","change":"Add a completion mark or quieter completed treatment.","priority":"P2"},{"id":"13","kind":"proposal","area":"Task type","observation":"Fix login bug is visually identical to design and documentation tasks.","change":"Add a small labeled task-type tag.","priority":"P2"},{"id":"14","kind":"proposal","area":"Priority","observation":"The board has no visible priority distinction.","change":"Add a concise priority marker to representative sample cards.","priority":"P2"},{"id":"15","kind":"proposal","area":"Assignees","observation":"No card shows who owns a task.","change":"Add compact assignee initials to enrich the realistic specimen.","priority":"P2"},{"id":"16","kind":"proposal","area":"Task identity","observation":"Titles are the only card identifiers.","change":"Add short task IDs for tracking moves.","priority":"P2"},{"id":"17","kind":"proposal","area":"Column accent","observation":"All columns share the same color despite distinct states.","change":"Add restrained status accents to headers.","priority":"P2"},{"id":"18","kind":"proposal","area":"Active target explanation","observation":"The screenshot gives no preview of valid drop locations.","change":"Add a static annotated example or separate drag-state capture.","priority":"P2"},{"id":"19","kind":"proposal","area":"Move feedback","observation":"No visible status area is available to report a completed move.","change":"Add a small last-move message below the board.","priority":"P2"},{"id":"20","kind":"proposal","area":"Alternative action","observation":"Only dragging is advertised.","change":"Add a visible Move to control for an accessible alternative.","priority":"P2"},{"id":"21","kind":"proposal","area":"Reset demo","observation":"There is no visible way to restore the initial arrangement.","change":"Add Reset board.","priority":"P2"},{"id":"22","kind":"proposal","area":"Sprint context","observation":"Sprint Board has no sprint name or dates.","change":"Add a compact sample sprint identifier.","priority":"P2"},{"id":"23","kind":"proposal","area":"Progress overview","observation":"3, 3, 2 counts require mental aggregation.","change":"Add an overall 2 of 8 completed summary.","priority":"P2"},{"id":"24","kind":"proposal","area":"Column spacing","observation":"Wide gutters consume space that could improve card padding.","change":"Reduce gutter width modestly.","priority":"P2"},{"id":"25","kind":"proposal","area":"Outer frame","observation":"The board ends above a broad black bottom band.","change":"Center the board vertically or use the space for instructions and move feedback.","priority":"P2"}],"sha256":"e65a7d9f2c2b1c78ce6b397b586481a1d4e5fb0705af045f1b93a8605bab8293","has_mock":false,"reference":null,"legacy":[]},{"id":"dropdowns","baseline":"screenshot-baselines/screens/dropdowns_720p.png","summary":"All six controls are closed, including an intentionally disabled specimen. Findings improve labeling and comparison; open-menu behavior is not inferred.","findings":[{"id":"01","kind":"proposal","area":"Title inset","observation":"Dropdown Showcase begins at the header's left edge.","change":"Add internal title padding.","priority":"P2"},{"id":"02","kind":"proposal","area":"Section header treatment","observation":"Card headings use the same teal fill as dropdown controls.","change":"Use neutral headings so controls are identifiable.","priority":"P2"},{"id":"03","kind":"proposal","area":"Basic label","observation":"Alpha names the value without the selected category.","change":"Add a persistent external label.","priority":"P2"},{"id":"04","kind":"proposal","area":"Basic chevron","observation":"The closed indicator is a literal v.","change":"Use a consistent chevron glyph.","priority":"P2"},{"id":"05","kind":"proposal","area":"With Label row","observation":"Pet and Cat share one teal pill with weak separation.","change":"Separate label and control visually.","priority":"P2"},{"id":"06","kind":"proposal","area":"Pet alignment","observation":"Pet is centered in a wide label region.","change":"Left-align the label near its control.","priority":"P2"},{"id":"07","kind":"proposal","area":"Many options","observation":"Many Options 12 does not name the month category.","change":"Use Month, 12 options.","priority":"P2"},{"id":"08","kind":"proposal","area":"Month control width","observation":"January occupies a narrower field than its card header.","change":"Use a shared field width across comparable examples.","priority":"P2"},{"id":"09","kind":"proposal","area":"Scrolling explanation","observation":"Twelve options, so the list scrolls does not give the visible-row limit.","change":"State the menu's visible-row count.","priority":"P2"},{"id":"10","kind":"proposal","area":"Custom marker","observation":"Option A[-] uses punctuation whose meaning is unexplained.","change":"Show a small open/closed marker legend.","priority":"P2"},{"id":"11","kind":"proposal","area":"Custom variant label","observation":"Option A is generic beside the concrete Pet and Month examples.","change":"Use a meaningful category label.","priority":"P2"},{"id":"12","kind":"proposal","area":"Disabled specimen","observation":"Frozen is deliberately dim but only its heading explains availability.","change":"Add a readable external state caption.","priority":"P2"},{"id":"13","kind":"proposal","area":"Disabled explanation","observation":"Not focusable and does not open describes internal behavior.","change":"Use Disabled example with concise supporting detail.","priority":"P2"},{"id":"14","kind":"proposal","area":"Custom style caption","observation":"Custom border, fill and corner radius omits values.","change":"List the configured style values.","priority":"P2"},{"id":"15","kind":"proposal","area":"Ruby naming","observation":"Ruby implies a gemstone or color but has no category label.","change":"Add Gemstone as its external label.","priority":"P2"},{"id":"16","kind":"proposal","area":"Custom comparison","observation":"Ruby has no adjacent default-styled control.","change":"Add a matched default specimen for comparison.","priority":"P2"},{"id":"17","kind":"proposal","area":"Description type","observation":"All six descriptions are very small.","change":"Increase body text size.","priority":"P2"},{"id":"18","kind":"proposal","area":"Description placement","observation":"Descriptions sit far below controls in tall cards.","change":"Tighten the control-to-description gap.","priority":"P2"},{"id":"19","kind":"proposal","area":"Card height","observation":"Each card contains substantial unused lower space.","change":"Reduce height or add useful parameter captions.","priority":"P2"},{"id":"20","kind":"proposal","area":"Card outlines","observation":"Bright thin outlines compete with subtle custom control borders.","change":"Quiet the card outline and preserve specimen emphasis.","priority":"P2"},{"id":"21","kind":"proposal","area":"Footer padding","observation":"The selection summary begins at its bar's edge.","change":"Inset it consistently.","priority":"P2"},{"id":"22","kind":"proposal","area":"Footer coverage","observation":"The summary mentions Alpha, Cat and January but omits other selectable specimens.","change":"Include all active example values or label the summary scope.","priority":"P2"},{"id":"23","kind":"proposal","area":"Footer phrasing","observation":"A long sentence is harder to scan than labeled values.","change":"Use Basic: Alpha, Pet: Cat, Month: January as separate fields.","priority":"P2"},{"id":"24","kind":"proposal","area":"Open-state evidence","observation":"The gallery shows no expanded menu.","change":"Add a separate baseline with one representative menu open.","priority":"P2"},{"id":"25","kind":"proposal","area":"Menu placement context","observation":"Closed controls do not reveal the intended popup direction or bounds.","change":"Add a small placement diagram outside the specimens.","priority":"P2"}],"sha256":"b54aa692fcd71d11e5f288d32dddeb502353d5bad29835ca1962c6e23f982c73","has_mock":false,"reference":null,"legacy":[]},{"id":"empire_tycoon","baseline":"screenshot-baselines/screens/empire_tycoon_720p.png","summary":"The dashboard follows the Dream Incorporated mock. Proposals improve metric semantics, project actions and readability within the playful illustrated design.","findings":[{"id":"01","kind":"proposal","area":"Happiness face","observation":"The 85% happiness gauge uses a neutral or unhappy-looking face.","change":"Use an expression consistent with high happiness.","priority":"P2"},{"id":"02","kind":"proposal","area":"Resources symbol","observation":"Resources repeats a face-like center symbol.","change":"Use a gear or resource icon matching the mock.","priority":"P2"},{"id":"03","kind":"proposal","area":"Gauge values","observation":"85% and 60% appear in very small outlined text.","change":"Use solid readable numeric labels.","priority":"P2"},{"id":"04","kind":"proposal","area":"Gauge scale","observation":"The semicircles have ticks but no endpoint labels.","change":"Mark 0 and 100 consistently.","priority":"P2"},{"id":"05","kind":"proposal","area":"Gauge fill distinction","observation":"Resources fill is close in color to its track.","change":"Increase filled-versus-unfilled contrast.","priority":"P2"},{"id":"06","kind":"proposal","area":"Cash emphasis","observation":"The large balance dominates the actionable dashboard.","change":"Reduce its scale slightly or strengthen section headings.","priority":"P2"},{"id":"07","kind":"proposal","area":"Currency symbol","observation":"A star coin accompanies a dollar amount.","change":"Choose one coherent currency convention.","priority":"P2"},{"id":"08","kind":"proposal","area":"Selected department","observation":"Rides has no strong selected marker distinct from the other colored tabs.","change":"Add an inset selection outline or check marker.","priority":"P2"},{"id":"09","kind":"proposal","area":"Department icons","observation":"Thin line icons are small inside large tab buttons.","change":"Increase icon weight and optical size.","priority":"P2"},{"id":"10","kind":"proposal","area":"Upgrade badge","observation":"The red exclamation overlaps the tab edge.","change":"Inset it or reserve a badge corner.","priority":"P2"},{"id":"11","kind":"proposal","area":"Production units","observation":"5,200/min etc. do not identify units produced.","change":"Use items/min or an appropriate explicit unit.","priority":"P2"},{"id":"12","kind":"proposal","area":"Production arrows","observation":"Green up arrows lack a stated comparison period.","change":"Add a trend caption such as versus previous minute.","priority":"P2"},{"id":"13","kind":"proposal","area":"Production status","observation":"All systems running smoothly is extremely small.","change":"Increase its size and move it into a clear status row.","priority":"P2"},{"id":"14","kind":"proposal","area":"Project title bars","observation":"Cyan title backgrounds resemble progress fills.","change":"Separate titles from progress tracks more clearly.","priority":"P2"},{"id":"15","kind":"proposal","area":"Project progress","observation":"80% and 10% sit far from the bars' starting edges.","change":"Align values consistently at each track's end.","priority":"P2"},{"id":"16","kind":"proposal","area":"Robot subtitle","observation":"3,100/min under a mascot project has no named metric.","change":"Label the rate or replace it with remaining time.","priority":"P2"},{"id":"17","kind":"proposal","area":"Rollercoaster subtitle","observation":"Expand the fun is promotional rather than useful status.","change":"Show remaining time or expected benefit.","priority":"P2"},{"id":"18","kind":"proposal","area":"Project selection","observation":"No project is visibly selected for Prioritize.","change":"Add a selected-project marker.","priority":"P2"},{"id":"19","kind":"proposal","area":"Prioritize action","observation":"Prioritize does not name its target.","change":"Show Prioritize rollercoaster or a target caption.","priority":"P2"},{"id":"20","kind":"proposal","area":"Speed Up action","observation":"Speed Up gives no cost or duration.","change":"Show its resource cost and effect before activation.","priority":"P2"},{"id":"21","kind":"proposal","area":"New Project action","observation":"All three actions share equal yellow emphasis.","change":"Give New Project or the principal action a clear hierarchy.","priority":"P2"},{"id":"22","kind":"proposal","area":"Milestone identity","observation":"Next Milestone 65% does not name the milestone.","change":"Show its goal and reward.","priority":"P2"},{"id":"23","kind":"proposal","area":"Milestone number","observation":"65% is tiny inside the progress bar.","change":"Increase the numeric label or place it above.","priority":"P2"},{"id":"24","kind":"proposal","area":"Chat channels","observation":"GlobalChat and DevTeam messages are very small in a corner panel.","change":"Increase text size and distinguish channel labels.","priority":"P2"},{"id":"25","kind":"proposal","area":"Bottom navigation","observation":"Shop, Settings and Leaderboard labels are tiny outlined text.","change":"Use solid text at a readable size and equal icon spacing.","priority":"P2"}],"sha256":"6b4ca431ea1b1b5d34a5f0d0a8a115102b559643e63ca20359f4296ac7815a61","has_mock":true,"reference":"inspiration/example_tycoon_game.png","legacy":[]},{"id":"entity_index_lab","baseline":"screenshot-baselines/screens/entity_index_lab_720p.png","summary":"The device-to-port relationship reads clearly. The performance comparison that motivates this demo is visually subordinate; proposals preserve its index demonstration.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Patch Bay title","observation":"The title names an audio tool but not the indexing demonstration.","change":"Add a small Secondary index demo subtitle beside Patch Bay."},{"id":"02","kind":"proposal","priority":"P2","area":"Introductory sentence","observation":"The single sentence stretches across most of the screen in small spaced lettering.","change":"Break the instruction and implementation explanation into separate lines."},{"id":"03","kind":"proposal","priority":"P2","area":"Metric footer","observation":"The green sentence places 6228 and 24 inside prose.","change":"Present Scan 6,228 and Index 24 as adjacent labeled counters."},{"id":"04","kind":"proposal","priority":"P2","area":"Collection size","observation":"The collection size 1030 sits at the end of the metric sentence.","change":"Give collection size its own neutral counter beside the comparison."},{"id":"05","kind":"proposal","priority":"P2","area":"Equality statement","observation":"The result-equivalence statement is detached below the performance line.","change":"Place a Results match: 24 indicator with the counters."},{"id":"06","kind":"proposal","priority":"P3","area":"Footer explanation","observation":"Both spellings return 24 requires knowledge of two code expressions.","change":"Name Scan and Indexed lookup explicitly in the explanation."},{"id":"07","kind":"proposal","priority":"P2","area":"Mixer A card","observation":"The selected device is communicated only through its blue fill.","change":"Add a selected marker at the leading edge of Mixer A."},{"id":"08","kind":"proposal","priority":"P3","area":"Device count","observation":"DEVICES does not state the number of listed devices.","change":"Label the section Devices · 6."},{"id":"09","kind":"proposal","priority":"P2","area":"Port table title","observation":"Mixer A has the same small type scale as device names.","change":"Increase the table title and pair it with a 4 ports summary."},{"id":"10","kind":"proposal","priority":"P3","area":"Port slot header","observation":"SLOT numbers start at 0 with no explanation.","change":"Label the column Slot index to explain zero-based numbering."},{"id":"11","kind":"proposal","priority":"P2","area":"Slot column","observation":"The SLOT heading begins left of the numeric cell alignment.","change":"Align the heading and all slot numbers to one inset."},{"id":"12","kind":"proposal","priority":"P2","area":"Port column","observation":"PORT starts noticeably left of Input L and Input R.","change":"Align the PORT heading with the port-name cells."},{"id":"13","kind":"proposal","priority":"P2","area":"State column","observation":"STATE starts left of connected and idle.","change":"Align the STATE heading with its cell labels."},{"id":"14","kind":"proposal","priority":"P2","area":"Status encoding","observation":"Connected is green while idle is muted italic text.","change":"Add a filled status dot for connected and an outlined dot for idle."},{"id":"15","kind":"proposal","priority":"P3","area":"Device names","observation":"Mixer A and Preamp 1 mix letter and number identifiers without explanation.","change":"Use a secondary device-type label to distinguish names from categories."},{"id":"16","kind":"proposal","priority":"P2","area":"Device badges","observation":"Each 4 ports count is pale blue and distant from the device name.","change":"Use a compact count badge with brighter text at the same trailing inset."},{"id":"17","kind":"proposal","priority":"P3","area":"List panel","observation":"The device list has about 100 pixels of empty space below Monitor.","change":"Reduce its height or add a compact total of 24 ports there."},{"id":"18","kind":"proposal","priority":"P2","area":"Detail panel","observation":"Four short table rows occupy less than half the tall panel.","change":"Fit the table panel to its content and bring comparison counters upward."},{"id":"19","kind":"proposal","priority":"P3","area":"Panel spacing","observation":"The gap between device and detail panels is wider than either panel's internal padding.","change":"Use a consistent 24-pixel inter-panel gap."},{"id":"20","kind":"proposal","priority":"P2","area":"Metric hierarchy","observation":"The main learning result is near the bottom, below a large empty panel region.","change":"Move the scan/index comparison directly under the table."},{"id":"21","kind":"proposal","priority":"P3","area":"Port relationship","observation":"Device and port panels have no shared visual connector.","change":"Add a small Selected device label or connector between Mixer A and its table."},{"id":"22","kind":"proposal","priority":"P2","area":"Technical typography","observation":"The numeric counters and device slots use the same handwritten face as titles.","change":"Use a readable tabular face for slot indices and measurements."},{"id":"23","kind":"proposal","priority":"P3","area":"Send row","observation":"Send is the only idle port but looks otherwise identical to connected rows.","change":"Give idle status a small neutral badge while retaining the same row geometry."},{"id":"24","kind":"proposal","priority":"P3","area":"Comparison scale","observation":"The footer states vastly different work counts without a visual scale.","change":"Add proportionate scan and index bars under their counters."},{"id":"25","kind":"proposal","priority":"P3","area":"Selection instruction","observation":"Pick a device appears only in the page-wide sentence.","change":"Place the short instruction directly under DEVICES."}],"sha256":"5b64ec912ff78533d2eab5f8b937f66c47909529a1ed0bfd6b9f1bdb6b6f96b7","has_mock":false,"reference":null,"legacy":[]},{"id":"example_borders","baseline":"screenshot-baselines/screens/example_borders_720p.png","summary":"Border variations are intentional fixtures. Improve labels and comparison framing; do not normalize the borders, colors, corners, or shadows under test.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Thin Medium Thick cards","observation":"The width examples show names without numeric widths.","change":"Add 1 px, 3 px, and 6 px captions outside the samples."},{"id":"02","kind":"proposal","priority":"P2","area":"Blue Cyan Orange cards","observation":"Color names are visible but exact tested values are absent.","change":"Add small color-code captions below these samples."},{"id":"03","kind":"proposal","priority":"P2","area":"Width and color row","observation":"Width variants and hue variants share one undivided row.","change":"Separate the row into labeled Width and Color groups."},{"id":"04","kind":"proposal","priority":"P2","area":"Rounded card","observation":"Rounded names the effect without its radius.","change":"Show the configured roundness in an external caption."},{"id":"05","kind":"proposal","priority":"P2","area":"Pill card","observation":"The pill demonstration is nearly square.","change":"Add a wider companion pill to demonstrate the same corner treatment on an elongated shape."},{"id":"06","kind":"proposal","priority":"P2","area":"Top Only corner card","observation":"Top Only is also used in the per-side row for a different property.","change":"Rename this sample Top corners only."},{"id":"07","kind":"proposal","priority":"P2","area":"Diagonal corner card","observation":"Diagonal does not say which opposite corners are rounded.","change":"Add a miniature corner diagram or explicit corner names."},{"id":"08","kind":"proposal","priority":"P2","area":"Hard Shadow card","observation":"The shadow parameter is not identified in its label.","change":"Caption the offset and spread below the sample."},{"id":"09","kind":"proposal","priority":"P2","area":"Soft Shadow card","observation":"The soft shadow blends into the dark page without a comparison reference.","change":"Place a neutral comparison backdrop behind the shadow examples only."},{"id":"10","kind":"proposal","priority":"P3","area":"Corner and shadow grouping","observation":"Two different properties share the Corners & Shadows label.","change":"Create separate subgroup captions for corners and shadows."},{"id":"11","kind":"proposal","priority":"P2","area":"Dark Mode sample","observation":"Dark Mode blends into the page around its thin outline.","change":"Give it an external sample-name caption so its boundary remains the test subject."},{"id":"12","kind":"proposal","priority":"P3","area":"Neon Glow sample","observation":"The glow label and glow border use the same bright cyan.","change":"Move the descriptive label below the sample to leave the glow unobscured."},{"id":"13","kind":"proposal","priority":"P3","area":"Cozy sample","observation":"Cozy describes a mood instead of border behavior.","change":"Add a subtitle naming its warm fill and soft border treatment."},{"id":"14","kind":"proposal","priority":"P2","area":"Danger and Success","observation":"The two semantic samples use different punctuation prefixes.","change":"Use a consistent icon-and-label pattern for both examples."},{"id":"15","kind":"proposal","priority":"P2","area":"Outline Only sample","observation":"Outline Only uses much smaller text than neighboring themed samples.","change":"Move the long name into an external caption at the shared caption size."},{"id":"16","kind":"proposal","priority":"P2","area":"Interactive Button","observation":"Only the button's resting state is shown.","change":"Add labeled static Rest, Hover, and Pressed previews beside the live control."},{"id":"17","kind":"proposal","priority":"P2","area":"Interactive row","observation":"The large button and nested panel have different heights and top edges.","change":"Align their sample frames while preserving each component's intrinsic dimensions."},{"id":"18","kind":"proposal","priority":"P2","area":"Nested Panel","observation":"The nested example has no indication of which borders belong to parent and children.","change":"Add a parent/child key outside the outlined panel."},{"id":"19","kind":"proposal","priority":"P3","area":"Inner Card and Second","observation":"Second gives no information about the second inner border.","change":"Rename it Outline child to distinguish its treatment."},{"id":"20","kind":"proposal","priority":"P2","area":"Per-Side row","observation":"Top Only and Bottom Only omit the line widths.","change":"Add edge-width captions outside each sample."},{"id":"21","kind":"proposal","priority":"P2","area":"Left+Right sample","observation":"The label uses a compact plus sign unlike the other edge names.","change":"Use Left and right with a tiny two-edge diagram."},{"id":"22","kind":"proposal","priority":"P2","area":"Mixed sample","observation":"Three colors appear without identifying their edge assignment.","change":"Add a four-edge legend naming each color and width."},{"id":"23","kind":"proposal","priority":"P2","area":"Dotted samples","observation":"Thin, Medium, and Thick do not expose dash size or spacing.","change":"Add numeric dash and gap captions beneath the dotted examples."},{"id":"24","kind":"proposal","priority":"P2","area":"Dotted row placement","observation":"The last row sits only about 12 pixels above the bottom edge.","change":"Increase the bottom safe margin or fit the gallery into a scrollable frame with a visible boundary."},{"id":"25","kind":"proposal","priority":"P3","area":"Gallery subtitle","observation":"The small pipe-separated subtitle repeats the row names.","change":"Replace it with a brief explanation that samples intentionally vary one property at a time."}],"sha256":"51cc14cf36b1a5a35d88dae3865353f39c1c53f782121bb1553552f40e49a64c","has_mock":false,"reference":null,"legacy":[]},{"id":"fighter_menu","baseline":"screenshot-baselines/screens/fighter_menu_720p.png","summary":"The selected category is recognizable, but competing neon layers and decorative shapes weaken the menu hierarchy. Proposals retain the fighting-game composition represented in mocks.html.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"MainMenu heading","observation":"MainMenu visually joins the two words.","change":"Set the heading as Main Menu with visible word spacing."},{"id":"02","kind":"proposal","priority":"P2","area":"Heading shadow","observation":"The green offset duplicates large white letterforms.","change":"Reduce the green offset to keep the title silhouette crisp."},{"id":"03","kind":"proposal","priority":"P2","area":"Currency counter","observation":"25000 P$ appears without numeric grouping.","change":"Format the amount as 25,000 P$."},{"id":"04","kind":"proposal","priority":"P3","area":"Currency panel","observation":"The currency banner has two faint decorative lines above the amount.","change":"Simplify the panel to one top rule and align the value vertically."},{"id":"05","kind":"proposal","priority":"P2","area":"Tab labels","observation":"Offline, Online, and Customize are low-contrast gray on black.","change":"Increase inactive-tab label contrast while preserving the active green underline."},{"id":"06","kind":"proposal","priority":"P2","area":"Selected Options tab","observation":"Orange letters on a pale cyan fill compete with the neon underline.","change":"Use a dark label and reserve neon green for the active indicator."},{"id":"07","kind":"proposal","priority":"P2","area":"Shoulder hints","observation":"The L and R key boxes differ in spacing from the adjacent tabs.","change":"Use equal inset and equal-size keycaps at both ends."},{"id":"08","kind":"proposal","priority":"P3","area":"Tab row","observation":"The active tab is taller than inactive tabs without a consistent baseline.","change":"Align all tab label baselines and express selection with the top edge or underline."},{"id":"09","kind":"proposal","priority":"P2","area":"Offline Mode backdrop label","observation":"The central Offline Mode label is partially covered by the selected menu ribbon.","change":"Move or remove this secondary label so its full text remains visible."},{"id":"10","kind":"proposal","priority":"P2","area":"System Options ribbon","observation":"The bright green selected row is far wider than its text.","change":"Shorten its point and keep a predictable menu-column width."},{"id":"11","kind":"proposal","priority":"P2","area":"Menu icon column","observation":"Slanted dark icon tiles use different apparent icon sizes.","change":"Normalize the visual size and center each icon in its tile."},{"id":"12","kind":"proposal","priority":"P2","area":"Game Options icon","observation":"Game Options and Button Settings share essentially the same controller silhouette.","change":"Use a distinct button-mapping icon for Button Settings."},{"id":"13","kind":"proposal","priority":"P2","area":"Unselected menu labels","observation":"Widely spaced gray serif labels require effort against black ribbons.","change":"Raise contrast and reduce letter spacing in the six menu labels."},{"id":"14","kind":"proposal","priority":"P3","area":"Menu row spacing","observation":"Thin pale gaps between the black ribbons vary in visual weight because of angled ends.","change":"Use consistent row separation across the left column."},{"id":"15","kind":"proposal","priority":"P2","area":"System preview heading","observation":"System Options appears twice in adjacent large and small treatments.","change":"Keep one strong title and use the second line for category context."},{"id":"16","kind":"proposal","priority":"P2","area":"Large System Options text","observation":"The white title uses a bright green offset over pale green; the web mock gives it a dark outline.","change":"Use a dark outline or solid backing so System Options stays legible over the pale preview."},{"id":"17","kind":"proposal","priority":"P2","area":"Gear illustration","observation":"The gear dominates the right preview while the category caption is very small.","change":"Reduce the gear slightly and enlarge SYSTEM to a legible supporting label."},{"id":"18","kind":"proposal","priority":"P3","area":"Preview frame","observation":"Several translucent green frames overlap at the right edge.","change":"Keep one primary frame and one subtle offset accent."},{"id":"19","kind":"proposal","priority":"P2","area":"Description text","observation":"The description occupies three centered lines with large letter spacing.","change":"Left-align the description with a shorter measure and normal spacing."},{"id":"20","kind":"proposal","priority":"P3","area":"Description panel","observation":"The black description panel has a large protruding diagonal left point.","change":"Reduce the point so the reading area has a more regular shape."},{"id":"21","kind":"proposal","priority":"P2","area":"Background character","observation":"The small character intersects the menu ribbons and pale floor geometry.","change":"Place the character within an unobstructed central background zone."},{"id":"22","kind":"proposal","priority":"P3","area":"Background pattern","observation":"Crosshairs and diagonal patterns remain strong around the navigation row.","change":"Lower their contrast behind interactive labels."},{"id":"23","kind":"proposal","priority":"P2","area":"Footer Select hint","observation":"A plus sign stands in for directional input while other actions use keycaps.","change":"Use a consistent directional-pad glyph with the same keycap styling."},{"id":"24","kind":"proposal","priority":"P2","area":"Footer change entry hint","observation":"L R share one wide keycap unlike the separate top shoulder hints.","change":"Use two individual L and R keycaps consistently."},{"id":"25","kind":"proposal","priority":"P2","area":"Footer spacing","observation":"The hints run across a dark gradient with uneven gaps around colons.","change":"Use evenly spaced icon-label groups without colon punctuation."}],"sha256":"7e2e44add4913a4c124d23fbf2d3630ca98ca208f6a3ad0b720dc9442d3ad6c8","has_mock":true,"reference":"inspiration/example_cross_tag.jpg","legacy":[]},{"id":"file_tree","baseline":"screenshot-baselines/screens/file_tree_720p.png","summary":"The sample tree is stable and readable, but its information density and hierarchy are weak for the large window. Suggestions keep the synthetic tree behavior intact.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"File Tree heading","observation":"The title is small within a wide gray title bar.","change":"Increase its size and give the bar a clear window-title treatment."},{"id":"02","kind":"proposal","priority":"P2","area":"Outer panel","observation":"The top of the rounded panel touches the viewport boundary.","change":"Add a consistent top margin around the complete window."},{"id":"03","kind":"proposal","priority":"P2","area":"Tree body","observation":"Files occupy the left quarter of a very wide empty panel.","change":"Reduce the panel width or add a selected-file detail pane."},{"id":"04","kind":"proposal","priority":"P2","area":"File sizes","observation":"47.1 KB, 6.0 KB, and 21.0 KB begin at different horizontal positions.","change":"Right-align sizes in a dedicated column."},{"id":"05","kind":"proposal","priority":"P2","area":"Column labels","observation":"The filename and size values have no column headers.","change":"Add Name and Size headings above the first tree row."},{"id":"06","kind":"proposal","priority":"P2","area":"Folder indicators","observation":"Expanded folders use a small handwritten v.","change":"Replace it with a crisp disclosure chevron at a consistent size."},{"id":"07","kind":"proposal","priority":"P2","area":"File versus folder rows","observation":"Folder identity relies mostly on a trailing slash.","change":"Add folder and file icons while retaining the slash convention if desired."},{"id":"08","kind":"proposal","priority":"P2","area":"Nested engine files","observation":"Indentation is the only guide connecting renderer files to engine.","change":"Add subtle vertical hierarchy guides."},{"id":"09","kind":"proposal","priority":"P2","area":"Filename typography","observation":"Handwritten letters make renderer.cpp and renderer.h less scannable.","change":"Use a compact readable face for filenames and tabular numerals for sizes."},{"id":"10","kind":"proposal","priority":"P2","area":"Root path","observation":"~/projects/harbour is tiny inside a nearly full-width dark pill.","change":"Increase its text size and present the path as a breadcrumb."},{"id":"11","kind":"proposal","priority":"P2","area":"Sample tree control","observation":"Sample tree resembles an ordinary action with no mode status.","change":"Show Sample data as a selected mode beside the path."},{"id":"12","kind":"proposal","priority":"P3","area":"Home control","observation":"Home is detached from any visible location hierarchy.","change":"Pair it with a home icon and align it with the breadcrumb start."},{"id":"13","kind":"proposal","priority":"P3","area":"Up control","observation":"The short Up label has the same emphasis as Refresh.","change":"Group Home and Up as navigation, separated from refresh actions."},{"id":"14","kind":"proposal","priority":"P3","area":"Refresh control","observation":"Refresh has no icon in a toolbar of small text pills.","change":"Add a compact refresh glyph to improve scanning."},{"id":"15","kind":"proposal","priority":"P2","area":"Toolbar dimensions","observation":"The toolbar buttons are short relative to the file row text.","change":"Increase button height and maintain a common label baseline."},{"id":"16","kind":"proposal","priority":"P2","area":"Toolbar background","observation":"The dark toolbar strip spans empty space far past the last button.","change":"Use a compact toolbar group or add a right-aligned mode indicator."},{"id":"17","kind":"proposal","priority":"P2","area":"No selection footer","observation":"The status text is extremely small and low contrast.","change":"Increase it to the same supporting-text size as the path."},{"id":"18","kind":"proposal","priority":"P3","area":"Selection guidance","observation":"No selection reports state without suggesting the next step.","change":"Use Select a file to view details in the empty detail region."},{"id":"19","kind":"proposal","priority":"P3","area":"Tree summary","observation":"The window contains no summary of the visible sample.","change":"Add a footer count of folders and files."},{"id":"20","kind":"proposal","priority":"P2","area":"src assets tests hierarchy","observation":"Top-level folders share the same weight as leaf files.","change":"Give top-level folder labels a slightly stronger weight."},{"id":"21","kind":"proposal","priority":"P3","area":"Directory groups","observation":"assets and tests follow immediately after the preceding subtree.","change":"Add a small gap before each top-level directory."},{"id":"22","kind":"proposal","priority":"P3","area":"README and makefile","observation":"Root-level files visually blend into the preceding tests subtree.","change":"Separate the root-file group with a small consistent gap."},{"id":"23","kind":"proposal","priority":"P2","area":"Font asset size","observation":"Archivo.ttf and atlas.png sizes share the same tone as their names.","change":"Use a muted but legible size column to emphasize names."},{"id":"24","kind":"proposal","priority":"P3","area":"Window border","observation":"A thin gray outline and nearly identical surrounding grays flatten the window.","change":"Use a clearer surface contrast with a restrained border."},{"id":"25","kind":"proposal","priority":"P3","area":"Bottom whitespace","observation":"A broad unused strip remains below the tree window.","change":"Center the reduced window vertically or expand useful content into that space."}],"sha256":"6ea213320a8544e7e4d099d449dedf3f3d022b0258684235b7525f41fe203dda","has_mock":false,"reference":null,"legacy":[]},{"id":"fit_content_lab","baseline":"screenshot-baselines/screens/fit_content_lab_720p.png","summary":"Both columns correctly demonstrate content-sized bubbles with different caps. Only 16 distinct design proposals are defensible from this intentionally minimal fixture; no wrapping defect is claimed.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Page heading","observation":"The heading combines an API name and a long explanation at one small size.","change":"Use Fit-content bubbles as the title and a separate concise API subtitle."},{"id":"02","kind":"proposal","priority":"P2","area":"Column labels","observation":"cap 380px and cap 200px are much smaller than the already small body text.","change":"Increase the labels and use consistent spacing before px."},{"id":"03","kind":"proposal","priority":"P2","area":"Column framing","observation":"The two repeated conversations have no visible panel boundary.","change":"Place each conversation in a subtle labeled frame."},{"id":"04","kind":"proposal","priority":"P2","area":"Column comparison","observation":"The narrow cap is only described in text.","change":"Add 380 px and 200 px measurement guides above the longest bubbles."},{"id":"05","kind":"proposal","priority":"P2","area":"Short hi bubbles","observation":"The hi background hugs the letters with almost no visible inset.","change":"Add equal minimum horizontal and vertical bubble padding while preserving content sizing."},{"id":"06","kind":"proposal","priority":"P2","area":"Long technical message","observation":"The long message has tightly packed lines and a handwritten face.","change":"Use a readable body face and more line height for both comparisons."},{"id":"07","kind":"proposal","priority":"P2","area":"Speaker distinction","observation":"Left and right alignment plus fill color are the only speaker cues.","change":"Label the two roles outside the samples with a compact legend."},{"id":"08","kind":"proposal","priority":"P3","area":"Repeated content","observation":"The columns do not explicitly say they contain identical messages.","change":"Add Same text, different maximum width beneath the title."},{"id":"09","kind":"proposal","priority":"P2","area":"Horizontal empty space","observation":"The short left and right messages sit at opposite edges of very wide columns.","change":"Use narrower comparison frames that keep message relationships easy to follow."},{"id":"10","kind":"proposal","priority":"P3","area":"Bottom empty region","observation":"Most of the viewport below the six messages is unused.","change":"Add a compact explanation of intrinsic width versus maximum width below the examples."},{"id":"11","kind":"proposal","priority":"P3","area":"Wide long bubble","observation":"Its exact three-line wrap is visible but unannotated.","change":"Add an external line-count caption to support comparison with the narrow bubble."},{"id":"12","kind":"proposal","priority":"P3","area":"Narrow long bubble","observation":"Its increased height is visible without a height reference.","change":"Add an external height guide beside the narrow example."},{"id":"13","kind":"proposal","priority":"P2","area":"Message ordering","observation":"The second conversation ends lower because of wrapping, obscuring one-to-one row comparison.","change":"Add unobtrusive message numbers beside matching bubbles."},{"id":"14","kind":"proposal","priority":"P3","area":"Code-oriented prose","observation":"The example story mentions a layout bug but does not identify the tested sizing rule.","change":"Place the technical story in a sample badge and explain the sizing rule separately."},{"id":"15","kind":"proposal","priority":"P3","area":"Title strip","observation":"The near-full-width title strip has rounded ends unrelated to the bubble comparison.","change":"Reduce the strip to a plain header with a divider above the frames."},{"id":"16","kind":"proposal","priority":"P2","area":"Final bubbles","observation":"Anyway it is fixed appears far from the preceding incoming message.","change":"Use consistent vertical conversation spacing after wrapped messages."}],"sha256":"dc9a3cba8c9defc7e15b17a922be3563fad2e164a915178f37a504e58298960a","has_mock":false,"reference":null,"legacy":[{"id":"fit_content_lab","screen":"fit_content_lab","baseline":"baseline_screenshots/fit_content_lab.png","current":"screenshot-baselines/screens/fit_content_lab_720p.png","pixel_identical":true,"size":[1280,720],"summary":"Pixel-identical. Narrow chat bubbles, tiny copy and unlabeled wide gutters are the same. Preserve the 380px and 200px cap behavior while improving its explanation.","sha256":"dc9a3cba8c9defc7e15b17a922be3563fad2e164a915178f37a504e58298960a","additional_findings":[]}]},{"id":"flex_alignment","baseline":"screenshot-baselines/screens/flex_alignment_720p.png","summary":"The alignment examples expose their intended differences. Improve the explanatory frame without moving the sample items away from the alignment positions under test.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Tab typography","observation":"Vertical and Horizontal are tiny beside the large page title.","change":"Increase all six tab labels to a readable supporting size."},{"id":"02","kind":"proposal","priority":"P2","area":"All tab","observation":"Selection uses a muted underline at the far bottom of a tall tab.","change":"Bring a brighter active indicator closer to the All label."},{"id":"03","kind":"proposal","priority":"P2","area":"Gap category","observation":"Gap appears in navigation but is absent from the All overview.","change":"Add a compact gap comparison or rename All to Overview."},{"id":"04","kind":"proposal","priority":"P2","area":"Section headings","observation":"Long API names compete with the plain-language titles.","change":"Put API names in smaller secondary captions."},{"id":"05","kind":"proposal","priority":"P2","area":"Vertical examples","observation":"Start, End, and Center omit the main-axis direction.","change":"Add a downward main-axis arrow beside the column samples."},{"id":"06","kind":"proposal","priority":"P2","area":"Horizontal examples","observation":"The row direction is named only in a long heading.","change":"Add a rightward main-axis arrow over the row samples."},{"id":"07","kind":"proposal","priority":"P2","area":"Cross-axis examples","observation":"Cross-Axis Align has no visual axis reference.","change":"Add a vertical cross-axis guide outside the sample boxes."},{"id":"08","kind":"proposal","priority":"P2","area":"SelfAlign panel","observation":"Auto and Center occupy the same height without explaining why.","change":"Caption the parent AlignItems::Center setting above the panel."},{"id":"09","kind":"proposal","priority":"P3","area":"Auto item","observation":"Auto has a unique purple fill with no legend.","change":"Label it Inherits parent in an external caption."},{"id":"10","kind":"proposal","priority":"P3","area":"SelfAlign colors","observation":"Start, Auto, Center, and End use four colors without a key.","change":"Add a small legend mapping colors to the four overrides."},{"id":"11","kind":"proposal","priority":"P2","area":"Vertical item numerals","observation":"Numbers sit near the left edge of teal rounded boxes.","change":"Center the numerals without changing the box positions."},{"id":"12","kind":"proposal","priority":"P2","area":"Horizontal numerals","observation":"Tiny numerals are tightly packed inside narrow pink pills.","change":"Use a more legible numeral face at the same sample dimensions."},{"id":"13","kind":"proposal","priority":"P2","area":"Between label","observation":"Between abbreviates the actual spacing mode.","change":"Use Space between in a caption outside the narrow sample."},{"id":"14","kind":"proposal","priority":"P2","area":"Around label","observation":"Around leaves the relationship between edge and internal gaps implicit.","change":"Add an edge-gap diagram beneath the sample."},{"id":"15","kind":"proposal","priority":"P3","area":"Start versus End","observation":"Their leftover space is visible but unmeasured.","change":"Add subtle brackets showing the unused region for both cases."},{"id":"16","kind":"proposal","priority":"P3","area":"Center column","observation":"The centered group's relationship to the container midpoint is implicit.","change":"Draw a faint midpoint guide behind the sample."},{"id":"17","kind":"proposal","priority":"P3","area":"Between column","observation":"The distribution is visible without identifying equal internal gaps.","change":"Add equal-gap markers alongside the three items."},{"id":"18","kind":"proposal","priority":"P3","area":"Cross-axis item heights","observation":"The three varied heights are unexplained.","change":"Caption the fixed test heights outside the comparison."},{"id":"19","kind":"proposal","priority":"P2","area":"Start cross-axis sample","observation":"The top edges align but no reference line marks that edge.","change":"Add a subtle alignment guide along the tested top edge."},{"id":"20","kind":"proposal","priority":"P2","area":"End cross-axis sample","observation":"The common bottom edge is hard to compare against rounded framing.","change":"Add a straight bottom reference guide inside the frame."},{"id":"21","kind":"proposal","priority":"P3","area":"Horizontal sample frames","observation":"Their large empty lower halves make the short row hard to inspect.","change":"Reduce framing height while preserving the row's measured container."},{"id":"22","kind":"proposal","priority":"P2","area":"Nested panel fills","observation":"Four similar blue-gray surface layers obscure grouping.","change":"Remove one decorative background layer around each example group."},{"id":"23","kind":"proposal","priority":"P3","area":"Lower panel space","observation":"Both outer columns extend well below their content.","change":"Fit the panels to their sections or use the spare space for a legend."},{"id":"24","kind":"proposal","priority":"P3","area":"Heading insets","observation":"Section headings begin almost at the rounded panel edges.","change":"Use consistent horizontal padding in every section header."},{"id":"25","kind":"proposal","priority":"P2","area":"Overview explanation","observation":"No short sentence states what changes and what stays fixed between samples.","change":"Add a one-line comparison rule under Flexbox Alignment Demo."}],"sha256":"4ad0674ff17ce937b4896b21d705318a37a01e9381c3de0f50c6e904c9f9ca8f","has_mock":false,"reference":null,"legacy":[{"id":"flex_alignment","screen":"flex_alignment","baseline":"baseline_screenshots/flex_alignment.png","current":"screenshot-baselines/screens/flex_alignment_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Current capture removes initial All focus outline. The two-column specimen arrangement remains the same; tiny tab labels and terse 1/2/3 samples remain hard to scan.","sha256":"b1ba382b98073b170d2457be7c755fef95d93612c250873fd6593b19b3442b84","additional_findings":[]}]},{"id":"flight_options","baseline":"screenshot-baselines/screens/flight_options_720p.png","summary":"The sparse flight-menu composition matches the existing mock. The main opportunities are more legible secondary options and clearer relationships among navigation, settings, and help.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Flight System suboptions","observation":"Four setting names are much smaller than category navigation.","change":"Increase suboption text while retaining the two-level hierarchy."},{"id":"02","kind":"proposal","priority":"P2","area":"Suboption spacing","observation":"Control Type and High-G Turn Settings sit in tightly spaced rows.","change":"Increase row height to form distinct selection targets."},{"id":"03","kind":"proposal","priority":"P2","area":"Suboption location","observation":"The suboptions start beside the middle of the navigation list.","change":"Align their heading with the selected Flight System category."},{"id":"04","kind":"proposal","priority":"P2","area":"Submenu heading","observation":"No heading identifies the short list as Flight System settings.","change":"Add a restrained Flight System subheading over the controls."},{"id":"05","kind":"proposal","priority":"P2","area":"Control Type value","observation":"Control Type shows no current value.","change":"Add a right-aligned current setting value."},{"id":"06","kind":"proposal","priority":"P2","area":"High-G Turn value","observation":"High-G Turn Settings shows only its name.","change":"Expose the current mode beside the label."},{"id":"07","kind":"proposal","priority":"P2","area":"Collision damage value","observation":"Reduced Collision Damage has no visible on/off state.","change":"Show a compact On or Off value with the setting."},{"id":"08","kind":"proposal","priority":"P2","area":"Vibration row","observation":"Vibration is extremely dim even though its unavailable status is useful information.","change":"Raise disabled text contrast while keeping it visibly inactive."},{"id":"09","kind":"proposal","priority":"P2","area":"Unavailable explanation","observation":"Vibration says Unavailable without a reason.","change":"Add a short requirement note beneath the disabled row."},{"id":"10","kind":"proposal","priority":"P3","area":"Selected category","observation":"A thin gold marker identifies Flight System but stops short of its full row height.","change":"Use a taller marker aligned with the row's text block."},{"id":"11","kind":"proposal","priority":"P3","area":"Selection wash","observation":"The faint gold wash stretches far beyond Flight System.","change":"Limit it to the navigation column width."},{"id":"12","kind":"proposal","priority":"P2","area":"Options heading","observation":"OPTIONS is only slightly larger than category labels.","change":"Increase its size or weight to establish a clearer page heading."},{"id":"13","kind":"proposal","priority":"P2","area":"Main navigation width","observation":"Category labels sit beside overlapping technical wire lines.","change":"Provide a quiet text zone behind the navigation list."},{"id":"14","kind":"proposal","priority":"P3","area":"Menu spacing","observation":"The nine category rows form a dense uninterrupted block.","change":"Add subtle groups for input, display, and audio/language settings."},{"id":"15","kind":"proposal","priority":"P2","area":"Help sentence","observation":"Select the in-flight system is far below the related list.","change":"Move the help closer to the settings panel."},{"id":"16","kind":"proposal","priority":"P3","area":"Help content","observation":"The help sentence repeats the selected category without explaining it.","change":"Describe the currently highlighted setting in one concise sentence."},{"id":"17","kind":"proposal","priority":"P2","area":"Footer Enter key","observation":"Enter is very small inside a narrow outlined keycap.","change":"Widen the keycap enough for the full label at readable size."},{"id":"18","kind":"proposal","priority":"P2","area":"Footer Esc key","observation":"Esc uses a tiny type size compared with BACK.","change":"Use a consistent readable key-label size for Enter and Esc."},{"id":"19","kind":"proposal","priority":"P2","area":"Footer OK label","observation":"OK does not describe whether it opens or confirms the selected item.","change":"Use Select or Apply according to the action represented."},{"id":"20","kind":"proposal","priority":"P3","area":"Footer grouping","observation":"Enter OK and Esc BACK have little separation from one another.","change":"Increase the gap between action groups."},{"id":"21","kind":"proposal","priority":"P3","area":"Footer background lines","observation":"Diagonal wire lines pass behind the footer keycaps.","change":"Clear the wire treatment from the footer's reading area."},{"id":"22","kind":"proposal","priority":"P3","area":"Right-side radar","observation":"A large faint ellipse occupies much of the empty right half.","change":"Use the radar area for a restrained setting preview or explanatory illustration."},{"id":"23","kind":"proposal","priority":"P3","area":"Right angular outline","observation":"An isolated L-shaped outline has no relation to the displayed settings.","change":"Integrate it into the preview frame or simplify it."},{"id":"24","kind":"proposal","priority":"P3","area":"Page balance","observation":"Nearly all informative content sits within the left 500 pixels.","change":"Give the setting detail area more width while retaining the sparse background."},{"id":"25","kind":"proposal","priority":"P3","area":"Technical grid","observation":"Grid lines remain equally visible under text and empty areas.","change":"Reduce grid contrast behind navigation and descriptions."}],"sha256":"b323899f546bd6e5e1c9abe7da6f33f563fc94945b281d07e3cd85c8e7d569f0","has_mock":true,"reference":"inspiration/example_ace_combat.jpg","legacy":[]},{"id":"font_weight","baseline":"screenshot-baselines/screens/font_weight_720p.png","summary":"The Light fallback is intentional and explicitly documented in source. Sixteen grounded presentation proposals are recorded; extra defects would require inventing problems in this small typography fixture.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Title","observation":"The family name and test instruction share one long small heading.","change":"Separate Font weight from Archivo Narrow and the comparison instruction."},{"id":"02","kind":"proposal","priority":"P2","area":"Weight labels","observation":"Light 300 through Bold 700 use a handwritten face unlike the samples.","change":"Use a neutral label face so letterform style does not distract from weight comparison."},{"id":"03","kind":"proposal","priority":"P2","area":"Light fallback label","observation":"The fallback explanation is packed into the long row label.","change":"Separate Requested 300 from Rendered 400 in adjacent columns."},{"id":"04","kind":"proposal","priority":"P2","area":"Row headers","observation":"No headers distinguish weight metadata from sample text.","change":"Add Requested weight and Rendered sample column headings."},{"id":"05","kind":"proposal","priority":"P2","area":"Sample size","observation":"The pangram is small relative to the available canvas.","change":"Add a larger companion specimen while preserving the current-size test."},{"id":"06","kind":"proposal","priority":"P3","area":"Baseline reference","observation":"The rows have no visible baseline guides.","change":"Add optional subtle guides beneath each specimen."},{"id":"07","kind":"proposal","priority":"P3","area":"Weight progression","observation":"Rows have equal spacing but no connecting visual scale.","change":"Add a compact 300-to-700 weight scale beside the labels."},{"id":"08","kind":"proposal","priority":"P3","area":"Fallback comparison","observation":"Light and Regular look alike as expected, but the connection is textual only.","change":"Group those rows with a fallback bracket."},{"id":"09","kind":"proposal","priority":"P2","area":"SemiBold label","observation":"SemiBold capitalization differs from familiar sentence-style naming.","change":"Use Semibold 600 consistently with the other row names."},{"id":"10","kind":"proposal","priority":"P3","area":"Pangram numbers","observation":"Only 0123 represent numeric glyphs.","change":"Add a separate 0123456789 line for number-weight comparison."},{"id":"11","kind":"proposal","priority":"P3","area":"Pangram punctuation","observation":"The sample includes little punctuation.","change":"Add a short punctuation specimen in the unused right area."},{"id":"12","kind":"proposal","priority":"P2","area":"Mixed-weight example","observation":"theme.h appears below a large gap without a section heading.","change":"Label this section Mixed weights on one baseline."},{"id":"13","kind":"proposal","priority":"P2","area":"Mixed-weight alignment","observation":"theme.h and src/ui are separated by a wide blank gap.","change":"Bring the runs closer while keeping the shared baseline test."},{"id":"14","kind":"proposal","priority":"P2","area":"Mixed-weight explanation","observation":"Regular weight, same baseline is small and dim.","change":"Move it into a legible caption below the specimen."},{"id":"15","kind":"proposal","priority":"P3","area":"Right empty region","observation":"The entire right half is unused.","change":"Use a second specimen column for a close-up comparison of 500 and 600."},{"id":"16","kind":"proposal","priority":"P3","area":"Specimen metadata","observation":"The screenshot names the family but not the rendered size.","change":"Add the font size and loaded-face names in a compact footer."}],"sha256":"4628ab71e38244ce6cffd58397280bf934c356638851311dfd407fdb471d189a","has_mock":false,"reference":null,"legacy":[]},{"id":"forms","baseline":"screenshot-baselines/screens/forms_720p.png","summary":"The page demonstrates sliders, checkboxes, progress, scrolling, and clipboard state. Its scroll clipping is intentional; clearer control anatomy and section hierarchy would make the examples easier to inspect.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Page title","observation":"Form Components touches the top of its cyan strip.","change":"Add a top safe margin and consistent title padding."},{"id":"02","kind":"proposal","priority":"P2","area":"Slider labels","observation":"Volume, Brightness, and Difficulty are embedded inside the filled halves.","change":"Place labels above their tracks so fills remain visually measurable."},{"id":"03","kind":"proposal","priority":"P2","area":"Slider thumb contrast","observation":"Teal thumbs sit on teal filled tracks.","change":"Use a brighter outlined thumb that remains distinct on both track colors."},{"id":"04","kind":"proposal","priority":"P2","area":"Slider values","observation":"Percent values are buried inside the labels.","change":"Place values in a shared trailing column."},{"id":"05","kind":"proposal","priority":"P2","area":"Volume track","observation":"The thick track resembles a segmented button.","change":"Reduce the track height while preserving a generous thumb."},{"id":"06","kind":"proposal","priority":"P3","area":"Difficulty percentage","observation":"Difficulty is represented as 30% without a scale explanation.","change":"Add Easy and Hard endpoint labels or a named level."},{"id":"07","kind":"proposal","priority":"P3","area":"Brightness control","observation":"Brightness has no low/high endpoint references.","change":"Add a dim-to-bright icon pair outside the track."},{"id":"08","kind":"proposal","priority":"P2","area":"Progress section header","observation":"Progress Bars uses a red strip while Sliders uses cyan, without a legend.","change":"Use a shared header style and reserve colors for the sample contents."},{"id":"09","kind":"proposal","priority":"P2","area":"Audio progress label","observation":"Audio Level 75% sits on the colored bar.","change":"Move the text outside the bar for an unobstructed progress comparison."},{"id":"10","kind":"proposal","priority":"P2","area":"Level progress label","observation":"Level Progress 75/100 is embedded in the fill.","change":"Separate the label and numeric value from the progress track."},{"id":"11","kind":"proposal","priority":"P3","area":"Progress units","observation":"One bar uses percent and the other a fraction without explanation.","change":"Caption the two demos Percentage and Custom range."},{"id":"12","kind":"proposal","priority":"P2","area":"Checkbox marks","observation":"Checked states appear as literal [x] strings.","change":"Use a clear square checkbox and centered check glyph."},{"id":"13","kind":"proposal","priority":"P2","area":"Checkbox position","observation":"Checkbox marks sit near the center of long cyan rows.","change":"Place each mark consistently before its label or at the trailing edge."},{"id":"14","kind":"proposal","priority":"P2","area":"Checkbox label size","observation":"Music and Fullscreen are much smaller than section headings.","change":"Increase checkbox labels to match slider-label readability."},{"id":"15","kind":"proposal","priority":"P3","area":"Checkbox grouping","observation":"Audio and display options form one undifferentiated list.","change":"Add small Audio and Display group labels."},{"id":"16","kind":"proposal","priority":"P3","area":"SFX label","observation":"SFX is abbreviated while Music is spelled out.","change":"Use Sound effects for clearer scanning."},{"id":"17","kind":"proposal","priority":"P3","area":"V-Sync label","observation":"V-Sync has no supporting description.","change":"Add a short explanatory subtitle in the demo's available width."},{"id":"18","kind":"proposal","priority":"P2","area":"Scroll boundary","observation":"A sliver of the next checkbox appears at the bottom edge.","change":"Keep clipping intentional but add a fade or More options cue at the boundary."},{"id":"19","kind":"proposal","priority":"P2","area":"Scrollbar","observation":"The thin light thumb sits far to the right of the option rows.","change":"Move it closer to the checkbox list and give its track a clearer boundary."},{"id":"20","kind":"proposal","priority":"P2","area":"Status strip","observation":"Volume, Resolution, and Quality appear as one small pipe-separated line.","change":"Use three labeled value groups at a readable size."},{"id":"21","kind":"proposal","priority":"P3","area":"Status relation","observation":"Resolution and Quality are summarized while their controls are offscreen.","change":"Label the strip Current settings to explain that it summarizes the whole form."},{"id":"22","kind":"proposal","priority":"P2","area":"Clipboard explanation","observation":"The clipboard help sentence is tiny and widely spaced.","change":"Increase it and wrap the copy/paste explanation into two short clauses."},{"id":"23","kind":"proposal","priority":"P2","area":"Copy Status action","observation":"Copy Status and Paste use unrelated cyan and red fills.","change":"Use a clear primary/secondary pairing without danger-like red for Paste."},{"id":"24","kind":"proposal","priority":"P2","area":"Clipboard result","observation":"Clipboard empty is small inline text without a visible output boundary.","change":"Place the result in a labeled read-only output field."},{"id":"25","kind":"proposal","priority":"P2","area":"Clipboard bottom row","observation":"Buttons sit flush against the bottom edge of their enclosing panel.","change":"Add bottom padding without reducing the scrollable test region."}],"sha256":"c5492252702fa3fc71ea0aa3fb5e1a79549d8456edd5e45a88eba07a0394464d","has_mock":false,"reference":null,"legacy":[{"id":"forms","screen":"forms","baseline":"baseline_screenshots/forms.png","current":"screenshot-baselines/screens/forms_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Current capture removes Volume focus outline. The same fixed-height scroller clips the next control row and the metadata footer remains small. Keep intentional scroll behavior when revising its presentation.","sha256":"4a4bbefd7be0f55bf0571b147c046a89fb2df787800f634f5e90ad3f439991ba","additional_findings":[]}]},{"id":"grid_lab","baseline":"screenshot-baselines/screens/grid_lab_720p.png","summary":"The table geometry and ragged content are intentional tests. Eighteen distinct proposals improve inspection; the sparse fixture does not support 25 independent defects.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Header strip","observation":"The API explanation is a small single-line title.","change":"Use Grid layout as a heading and keep the explanation as a subtitle."},{"id":"02","kind":"proposal","priority":"P2","area":"Equal-track caption","observation":"Equal columns, ragged text is tiny relative to the table width.","change":"Increase the caption and identify this as Example 1."},{"id":"03","kind":"proposal","priority":"P2","area":"Equal-track cell text","observation":"Cell text is very small despite broad columns.","change":"Increase the specimen text or add a larger companion specimen."},{"id":"04","kind":"proposal","priority":"P2","area":"Cell insets","observation":"id, name, role, and notes sit almost against grid lines.","change":"Add consistent horizontal cell padding."},{"id":"05","kind":"proposal","priority":"P2","area":"Column headings","observation":"Header text has little weight distinction from the body.","change":"Use a stronger header face while preserving track dimensions."},{"id":"06","kind":"proposal","priority":"P3","area":"ID column","observation":"The short numeric column occupies the same width as long role text by design.","change":"Add an Equal 1fr tracks annotation above the table."},{"id":"07","kind":"proposal","priority":"P3","area":"Ragged name example","observation":"a and a much longer name illustrate width variation without a reference.","change":"Add a caption explaining that content length does not move column boundaries."},{"id":"08","kind":"proposal","priority":"P3","area":"Notes dash","observation":"The dash in the first notes row has no explanatory context.","change":"Label it as an empty-value fixture in the caption."},{"id":"09","kind":"proposal","priority":"P2","area":"Second caption","observation":"Explicit tracks does not show the actual track widths.","change":"Display the four numeric track sizes above their corresponding columns."},{"id":"10","kind":"proposal","priority":"P2","area":"Spanning header","observation":"One cell, spanning three tracks is only communicated through text.","change":"Add a subtle three-column bracket above the merged cell."},{"id":"11","kind":"proposal","priority":"P3","area":"Blank corner cell","observation":"The second table's first header cell is empty.","change":"Caption it as the row-index gutter outside the table."},{"id":"12","kind":"proposal","priority":"P2","area":"r1c1 labels","observation":"Coordinate-style content is harder to scan in the small handwritten face.","change":"Use a compact monospaced face for the coordinate fixtures."},{"id":"13","kind":"proposal","priority":"P3","area":"Striped second table","observation":"The middle body row has a distinct blue fill without an explanation.","change":"Label the alternating-row treatment in the sample metadata."},{"id":"14","kind":"proposal","priority":"P2","area":"Thick-border claim","observation":"The caption says thick border but the thin displayed lines are hard to judge at this scale.","change":"Add an enlarged border detail and the requested border width."},{"id":"15","kind":"proposal","priority":"P3","area":"Table comparison","observation":"The first table spans the viewport while the second occupies less than half.","change":"Give each a clearly bounded sample frame with its own width annotation."},{"id":"16","kind":"proposal","priority":"P3","area":"Unused lower area","observation":"Most of the screen below the second table is empty.","change":"Place a compact track-definition diagram below the rendered examples."},{"id":"17","kind":"proposal","priority":"P3","area":"Grid-line contrast","observation":"Grid lines and small pale text compete for attention.","change":"Reduce internal line emphasis while keeping the outer test border unchanged."},{"id":"18","kind":"proposal","priority":"P2","area":"Expected result","observation":"The page describes setup without a short success criterion.","change":"Add Columns stay aligned across every row beneath the examples."}],"sha256":"78badc2c90a1d684e23b14a11efd4510aff84c81ae292ff8884de95680a2b868","has_mock":false,"reference":null,"legacy":[{"id":"grid_lab","screen":"grid_lab","baseline":"baseline_screenshots/grid_lab.png","current":"screenshot-baselines/screens/grid_lab_720p.png","pixel_identical":true,"size":[1280,720],"summary":"Pixel-identical. Two top-aligned table examples occupy little of the canvas. Unequal sample widths illustrate explicit tracks and must not be normalized as a supposed alignment defect.","sha256":"78badc2c90a1d684e23b14a11efd4510aff84c81ae292ff8884de95680a2b868","additional_findings":[]}]},{"id":"guess_who_lab","baseline":"screenshot-baselines/screens/guess_who_lab_720p.png","summary":"The full board is readable and the illustrated cast supports the game. Refine question composition, note controls, and turn feedback while retaining the playful mock design.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"New game label","observation":"The reset glyph touches the end of New game.","change":"Add a visible gap between the label and reset icon."},{"id":"02","kind":"defect","priority":"P2","area":"Ask question label","observation":"The arrow touches the final letter of question.","change":"Separate the arrow with consistent button-icon spacing."},{"id":"03","kind":"proposal","priority":"P2","area":"Question sentence","observation":"DOES YOUR PERSON runs directly into the first dropdown.","change":"Add a clear gap between the prompt and trait field."},{"id":"04","kind":"proposal","priority":"P2","area":"Answer field","observation":"Yes has no visible label explaining whose answer it represents.","change":"Label the field Answer above the compact selector."},{"id":"05","kind":"proposal","priority":"P2","area":"Trait selector","observation":"The selector ends with a literal v.","change":"Replace it with a crisp down chevron aligned to the trailing inset."},{"id":"06","kind":"proposal","priority":"P2","area":"Per-face note selectors","observation":"Twenty-four Not sure v labels use very small text.","change":"Increase note text and give the arrow a separate trailing slot."},{"id":"07","kind":"proposal","priority":"P2","area":"Note versus elimination","observation":"Each face has both a portrait and note control without a local distinction.","change":"Label the note row as a note and keep the flip instruction beside the board."},{"id":"08","kind":"proposal","priority":"P2","area":"Remaining count","observation":"24 faces left is isolated at the right of the question bar.","change":"Pair it with a small board-status label or progress indicator."},{"id":"09","kind":"proposal","priority":"P3","area":"Turn indicator","observation":"A red dot accompanies YOUR TURN without explaining red's meaning.","change":"Use an active-player token or arrow consistent with the board palette."},{"id":"10","kind":"proposal","priority":"P2","area":"Turn heading","observation":"YOUR TURN and Find the mystery person lack player identity.","change":"Add Player 1 or the active player's name beside the turn label."},{"id":"11","kind":"proposal","priority":"P2","area":"Game objective","observation":"Find the mystery person does not explain the question-and-answer sequence.","change":"Add a short first-turn instruction near the question bar."},{"id":"12","kind":"proposal","priority":"P3","area":"Logo scale","observation":"The stacked logo fills nearly the entire header height.","change":"Reduce its height slightly to give the header a calmer top margin."},{"id":"13","kind":"proposal","priority":"P2","area":"Portrait details","observation":"Glasses, eye color, and hair details are small within the 8-column board.","change":"Increase facial-detail contrast while retaining all 24 visible cards."},{"id":"14","kind":"proposal","priority":"P3","area":"Hat cropping","observation":"Tall hats touch or disappear beneath the top card edge.","change":"Provide consistent headroom for hatted portraits."},{"id":"15","kind":"proposal","priority":"P2","area":"Name strips","observation":"Names sit in narrow cream bands very close to portrait art.","change":"Increase the name-strip separation from each face."},{"id":"16","kind":"proposal","priority":"P3","area":"Card borders","observation":"Thick yellow double borders compete with distinguishing facial features.","change":"Reduce border emphasis and reserve stronger framing for a chosen candidate."},{"id":"17","kind":"proposal","priority":"P2","area":"Board frame","observation":"Multiple blue bevel bands consume height around the grid.","change":"Simplify the frame to reclaim space for portraits and notes."},{"id":"18","kind":"proposal","priority":"P3","area":"Card row gaps","observation":"The note bar nearly touches the next row's top border.","change":"Increase vertical gap between complete card groups."},{"id":"19","kind":"proposal","priority":"P2","area":"Footer help","observation":"Click a face to flip it down is far from the card controls.","change":"Place the instruction immediately above or below the board near its leading edge."},{"id":"20","kind":"proposal","priority":"P3","area":"Feedback sentence","observation":"A little question. A big clue. occupies the feedback area without showing game state.","change":"Use an instructional starting message until the first question is asked."},{"id":"21","kind":"proposal","priority":"P2","area":"Question history","observation":"The composition has no visible record area for previous clues.","change":"Reserve a compact clue-history strip near the remaining count."},{"id":"22","kind":"proposal","priority":"P3","area":"Trait grammar","observation":"Does your person plus wear glasses is clear but tightly merged with answer and action.","change":"Group trait selection separately from answer confirmation through spacing."},{"id":"23","kind":"proposal","priority":"P2","area":"Reset action hierarchy","observation":"New game has a large outline pill near the turn status.","change":"Reduce its visual emphasis so the question action remains primary."},{"id":"24","kind":"proposal","priority":"P3","area":"Card coordinate reference","observation":"The dense grid provides only personal names for locating faces.","change":"Add subtle row markers to support discussing or testing a specific card."},{"id":"25","kind":"proposal","priority":"P2","area":"Board status semantics","observation":"All note rows say Not sure while the header says 24 faces left.","change":"Add a legend distinguishing note state from eliminated state."}],"sha256":"b938b2f8802a0c099a5107bcdae43c1a4882b638c6d013acba4ff1ac1ee94cbc","has_mock":true,"reference":null,"legacy":[]},{"id":"horizontal_drag","baseline":"screenshot-baselines/screens/horizontal_drag_720p.png","summary":"Three priority lanes and seven tags form a small drag demonstration. Twenty distinct proposals are supported by the baseline; none assumes a failure of unseen drag behavior.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Page title","observation":"Horizontal Drag & Drop dominates the small amount of content.","change":"Reduce the title size and give the lanes more visual emphasis."},{"id":"02","kind":"proposal","priority":"P2","area":"Subtitle","observation":"Drag tags between priority lanes is almost title-sized.","change":"Use a smaller supporting size with a clear gap below the heading."},{"id":"03","kind":"proposal","priority":"P2","area":"Lane counts","observation":"Counts are embedded in handwritten heading text.","change":"Use compact count badges aligned consistently after each priority name."},{"id":"04","kind":"proposal","priority":"P2","area":"Lane labels","observation":"Red, yellow, and green headings communicate priority mainly through color and words.","change":"Add a severity icon or short High/Medium/Low marker beside each heading."},{"id":"05","kind":"proposal","priority":"P2","area":"Tag affordance","observation":"The colored tags look like ordinary buttons in the resting image.","change":"Add a small drag grip to each tag."},{"id":"06","kind":"proposal","priority":"P2","area":"Tag color meaning","observation":"Seven unrelated tag fills have no visible legend.","change":"Use a shared neutral tag fill or explain the tag-color categories."},{"id":"07","kind":"proposal","priority":"P2","area":"Drop-space cue","observation":"Large blank areas to the right of the tags have no instruction.","change":"Add a faint Drop here cue within each lane's empty region."},{"id":"08","kind":"proposal","priority":"P2","area":"Lane dimensions","observation":"All lanes span nearly the entire viewport while holding two or three tags.","change":"Reduce lane width or use the space for a visible drop target boundary."},{"id":"09","kind":"proposal","priority":"P2","area":"Empty lower region","observation":"The bottom quarter of the panel contains no content.","change":"Fit the panel to the three lanes and center it vertically."},{"id":"10","kind":"proposal","priority":"P3","area":"Row borders","observation":"Thin outlines are nearly invisible against the dark lane fill.","change":"Increase lane boundary contrast slightly."},{"id":"11","kind":"proposal","priority":"P2","area":"High-priority tags","observation":"Security patch and Data loss fix use two different red tones without distinct meanings.","change":"Use one high-priority tag treatment or label their separate categories."},{"id":"12","kind":"proposal","priority":"P3","area":"Refactor auth label","observation":"Auth is abbreviated in an otherwise plain-language board.","change":"Use Refactor authentication if space permits."},{"id":"13","kind":"proposal","priority":"P3","area":"Update deps label","observation":"Deps is a developer abbreviation.","change":"Use Update dependencies for a self-contained sample."},{"id":"14","kind":"proposal","priority":"P3","area":"Rename var label","observation":"Var is abbreviated despite the wide empty lane.","change":"Use Rename variable."},{"id":"15","kind":"proposal","priority":"P3","area":"Readme typo label","observation":"Readme differs from the conventional filename styling.","change":"Use README typo to identify the document clearly."},{"id":"16","kind":"proposal","priority":"P2","area":"Tag spacing","observation":"The gap between tags varies because each group uses different widths.","change":"Use one fixed inter-tag gap across the three lanes."},{"id":"17","kind":"proposal","priority":"P3","area":"Lane heading gap","observation":"Headings sit very close to their first tag row.","change":"Add a consistent gap between lane title and tags."},{"id":"18","kind":"proposal","priority":"P2","area":"Demo result","observation":"Only lane counts report the result of moving a tag.","change":"Reserve a small Last moved status line beneath the lanes."},{"id":"19","kind":"proposal","priority":"P3","area":"Starting arrangement","observation":"The screen shows no reference for restoring the initial priority distribution.","change":"Add a compact Reset example action near the subtitle."},{"id":"20","kind":"proposal","priority":"P2","area":"Instruction specificity","observation":"The subtitle says move between lanes but does not mention ordering within a lane.","change":"State whether the demonstration also supports horizontal reordering."}],"sha256":"e2d3f3912f5c3cf5bad163eddd4409883d83e9cf12794fe1e4a528abbff2a51d","has_mock":false,"reference":null,"legacy":[]},{"id":"hover_lab","baseline":"screenshot-baselines/screens/hover_lab_720p.png","summary":"All three rows are captured at rest. Their hover and click differences are intentional. Eighteen proposals improve the experiment presentation without claiming that the unseen interactions are broken.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Title","observation":"The title mixes Hover Lab with two technical concepts on one line.","change":"Use a short title and a separate experiment summary."},{"id":"02","kind":"proposal","priority":"P2","area":"Case captions","observation":"The three long captions use tiny handwritten text.","change":"Increase caption size and wrap each explanation above its row."},{"id":"03","kind":"proposal","priority":"P2","area":"Case naming","observation":"Cases are identified by code expressions before their purpose.","change":"Add names Direct hover, Subtree hover, and Pointer passthrough."},{"id":"04","kind":"proposal","priority":"P2","area":"Star glyphs","observation":"The interactive stars are rendered as small asterisks.","change":"Use a recognizable star glyph while preserving the hit-test geometry."},{"id":"05","kind":"proposal","priority":"P2","area":"Row labels","observation":"Thread row 1 through 3 do not name the tested behavior.","change":"Use concise behavior names in the row labels."},{"id":"06","kind":"proposal","priority":"P2","area":"Caption and row grouping","observation":"Each caption sits close to the preceding blank gap without a enclosing group.","change":"Frame each case with a consistent sample boundary."},{"id":"07","kind":"proposal","priority":"P2","area":"Diagnostic table","observation":"Three diagnostic lines have no column headings.","change":"Add Case, Row lit, Star hot, and Clicks headings."},{"id":"08","kind":"proposal","priority":"P2","area":"Diagnostic values","observation":"lit=n and star_hot=n use terse boolean abbreviations.","change":"Show Yes and No badges beside the API terms."},{"id":"09","kind":"proposal","priority":"P2","area":"Diagnostic alignment","observation":"Variable-length expressions push values into uneven columns.","change":"Use fixed-width columns for the three state fields."},{"id":"10","kind":"proposal","priority":"P2","area":"Diagnostics separation","observation":"All diagnostics sit below all samples.","change":"Place each case's live status directly beneath its row."},{"id":"11","kind":"proposal","priority":"P2","area":"Row 1 explanation","observation":"The phrase star steals hotness requires internal terminology.","change":"Explain that entering the star removes the row highlight."},{"id":"12","kind":"proposal","priority":"P2","area":"Row 2 explanation","observation":"The subtree behavior is described in a long code-heavy sentence.","change":"State Row stays highlighted; star still receives clicks."},{"id":"13","kind":"proposal","priority":"P2","area":"Row 3 explanation","observation":"The star looks identical to the other two despite intentionally ignoring input.","change":"Add an external Pointer passthrough badge to identify the test variant."},{"id":"14","kind":"proposal","priority":"P2","area":"Footer instruction","observation":"Click each star is small and far below the actual stars.","change":"Move the instruction above the samples near the title."},{"id":"15","kind":"proposal","priority":"P3","area":"Initial-state capture","observation":"All rows have the same resting appearance.","change":"Add labeled expected-state thumbnails beside the live examples."},{"id":"16","kind":"proposal","priority":"P3","area":"Unused right area","observation":"Most of the canvas is blank.","change":"Use the right half for a simple row-versus-child hit-test diagram."},{"id":"17","kind":"proposal","priority":"P3","area":"Comparison outcome","observation":"No visual legend explains which case keeps the row wash.","change":"Add a small expected-results matrix covering hover and clicks."},{"id":"18","kind":"proposal","priority":"P3","area":"Click counter readability","observation":"star_clicks=0 is embedded at the end of each small diagnostic line.","change":"Give each click count a compact, prominent numeric badge."}],"sha256":"51653f821997a6d6cba947ea89bba9905964c7e243d56a14d5fac41750bc6e09","has_mock":false,"reference":null,"legacy":[]},{"id":"hstack_showcase","baseline":"screenshot-baselines/screens/hstack_showcase_720p.png","summary":"The intentional colors and item positions demonstrate hstack behavior. Improve semantic labels and comparison guides without standardizing the alignment samples.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Heading","observation":"hstack() Showcase has no plain-language explanation.","change":"Add Horizontal stack layout as a subtitle."},{"id":"02","kind":"proposal","priority":"P2","area":"Basic row","observation":"Item 1, Item 2, and Item 3 have no section label.","change":"Label this row Equal-width children."},{"id":"03","kind":"proposal","priority":"P3","area":"Basic-row gaps","observation":"Large gaps are visible but their configured size is not.","change":"Add an external gap measurement caption."},{"id":"04","kind":"proposal","priority":"P2","area":"Justification section","observation":"Five pink headers appear without a shared section title.","change":"Add Main-axis distribution above the five examples."},{"id":"05","kind":"proposal","priority":"P2","area":"Between and Around","observation":"The shortened names omit Space.","change":"Use Space between and Space around in external captions."},{"id":"06","kind":"proposal","priority":"P2","area":"Pink header text","observation":"Small black handwritten labels sit close to the left edge.","change":"Increase caption size and apply equal horizontal padding."},{"id":"07","kind":"proposal","priority":"P2","area":"Unnumbered cyan boxes","observation":"The repeated boxes contain no identity markers.","change":"Add 1, 2, and 3 labels to reveal item order."},{"id":"08","kind":"proposal","priority":"P3","area":"Start example","observation":"Its packed group has no left-edge reference.","change":"Add a faint tested-edge guide in the frame."},{"id":"09","kind":"proposal","priority":"P3","area":"End example","observation":"The right-aligned group has no right-edge reference.","change":"Add a faint right-edge guide."},{"id":"10","kind":"proposal","priority":"P3","area":"Center example","observation":"The centered group lacks a midpoint marker.","change":"Add a subtle centerline behind the sample."},{"id":"11","kind":"proposal","priority":"P3","area":"Between example","observation":"Equal gaps are shown without measurement cues.","change":"Add small equal-gap brackets outside the item row."},{"id":"12","kind":"proposal","priority":"P3","area":"Around example","observation":"The half-size edge gaps are not explained.","change":"Annotate edge versus internal spacing beneath the frame."},{"id":"13","kind":"proposal","priority":"P2","area":"Cross-axis section","observation":"Green headers Start, Center, and End lack a group label.","change":"Add Cross-axis alignment above them."},{"id":"14","kind":"proposal","priority":"P3","area":"Unequal item heights","observation":"Green, orange, and purple item heights vary without a legend.","change":"Caption their fixed heights as part of the test setup."},{"id":"15","kind":"proposal","priority":"P2","area":"Alignment guides","observation":"Rounded frames make common top and bottom edges less obvious.","change":"Add straight reference guides inside the three samples."},{"id":"16","kind":"proposal","priority":"P2","area":"Toolbar Pattern heading","observation":"The label is tiny relative to the blue title strip.","change":"Increase its text and align it with toolbar content."},{"id":"17","kind":"proposal","priority":"P2","area":"Toolbar commands","observation":"File, Edit, and View are much smaller than the large surrounding examples.","change":"Use a readable command size within the toolbar specimen."},{"id":"18","kind":"proposal","priority":"P3","area":"Settings placement","observation":"The right-aligned Settings button demonstrates spare-space use without explanation.","change":"Annotate it as the trailing action using remaining width."},{"id":"19","kind":"proposal","priority":"P2","area":"Card Row title","observation":"The title does not explain which hstack behavior it demonstrates.","change":"Rename it Four equal cards with fixed gaps."},{"id":"20","kind":"proposal","priority":"P2","area":"A B C D cards","observation":"Single letters sit against the left edges of the small cards.","change":"Center the letters or add a consistent inset."},{"id":"21","kind":"proposal","priority":"P2","area":"Dashboard row","observation":"Users, Revenue, Orders, Growth, Active, and Churn appear without a section heading.","change":"Label the row Six expanding cards."},{"id":"22","kind":"proposal","priority":"P2","area":"Dashboard text","observation":"Each metric label sits flush against its card's left edge.","change":"Add a consistent text inset without changing the card widths."},{"id":"23","kind":"proposal","priority":"P3","area":"Dashboard values","observation":"The metric cards have labels but no sample values.","change":"Add small fixed values to make the dashboard example recognizable."},{"id":"24","kind":"proposal","priority":"P3","area":"Dashboard color key","observation":"Six bright colors suggest meaning without a legend.","change":"Caption them as identity colors or reduce unrelated semantic associations."},{"id":"25","kind":"proposal","priority":"P3","area":"Bottom empty space","observation":"A broad blank region remains below the dashboard row.","change":"Use it for the stack width and gap configuration summary."}],"sha256":"4c617c180b93c99ff752743f13c381255ffb23e04a1c9a3bee3477a14945ec57","has_mock":false,"reference":null,"legacy":[]},{"id":"images","baseline":"screenshot-baselines/screens/images_720p.png","summary":"The sprites render cleanly, and the resting button examples are intact. Proposals clarify icon semantics and the differences among the four demonstrations.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"Play sprite","observation":"The icon labeled Play shows two right-pointing triangles, conventionally fast-forward.","change":"Use a single play triangle or rename the specimen Fast forward."},{"id":"02","kind":"proposal","priority":"P2","area":"Page title","observation":"Image & Sprite Components uses small text across a wide title bar.","change":"Increase the heading and shorten the bar to the content width."},{"id":"03","kind":"proposal","priority":"P2","area":"Section label styles","observation":"Sprites and With Background are cyan while Image Buttons and Icon Row are red.","change":"Use one section-label treatment unless color has a documented meaning."},{"id":"04","kind":"proposal","priority":"P2","area":"Sprite names","observation":"Gear and Trophy become Settings and Awards in the icon row.","change":"Show glyph name and intended action as separate consistent labels."},{"id":"05","kind":"proposal","priority":"P2","area":"Favorite naming","observation":"Favorite in the button row becomes Favorites in the icon row.","change":"Choose one action label across both examples."},{"id":"06","kind":"proposal","priority":"P2","area":"Sprite row alignment","observation":"Captions are offset left of the apparent icon centers.","change":"Center each caption directly beneath its sprite."},{"id":"07","kind":"proposal","priority":"P2","area":"Icon-row captions","observation":"Settings and Play use small widely spaced lettering.","change":"Increase caption size and reduce tracking."},{"id":"08","kind":"proposal","priority":"P3","area":"Gear visual size","observation":"The gear appears smaller than the home and play silhouettes.","change":"Normalize optical icon size in the comparison row."},{"id":"09","kind":"proposal","priority":"P3","area":"Star specimen","observation":"The star has a smaller visual footprint than the trophy.","change":"Add consistent image bounds behind the specimens to expose size differences."},{"id":"10","kind":"proposal","priority":"P2","area":"Sprite metadata","observation":"The first row provides no source dimensions or scale.","change":"Add a compact 100 × 100 source metadata caption."},{"id":"11","kind":"proposal","priority":"P3","area":"Image-button frame","observation":"The three buttons use unrelated fill colors.","change":"Use a shared frame color or label each theme variant."},{"id":"12","kind":"proposal","priority":"P2","area":"Button versus sprite","observation":"The difference between the first and second rows is implied only by titles.","change":"Add Static image and Clickable image badges beside their headings."},{"id":"13","kind":"proposal","priority":"P2","area":"Click counter","observation":"Clicks: 0 sits in open space away from the three buttons.","change":"Place it in a visible shared result badge adjacent to the button group."},{"id":"14","kind":"proposal","priority":"P3","area":"Counter scope","observation":"Clicks: 0 does not say whether all buttons share the counter.","change":"Label it Total image-button clicks."},{"id":"15","kind":"proposal","priority":"P2","area":"With Background sample","observation":"The purple Settings rectangle is not described as a compound image-and-label control.","change":"Rename the section Image with text background."},{"id":"16","kind":"proposal","priority":"P2","area":"Compound Settings spacing","observation":"The gear and Settings text have a large unstructured gap.","change":"Use a consistent icon-to-label gap and centered vertical alignment."},{"id":"17","kind":"proposal","priority":"P3","area":"Third row height","observation":"A single small sample sits in a long full-width panel.","change":"Fit the sample panel to its contents or add its geometry annotation."},{"id":"18","kind":"proposal","priority":"P3","area":"Icon row interaction","observation":"The icon row looks similar to the button row but its role is unclear.","change":"Label whether these are static icons or actions."},{"id":"19","kind":"proposal","priority":"P2","area":"Section label widths","observation":"Sprites and Icon Row use narrower labels than the other rows.","change":"Use a fixed section-label column to align all sample starts."},{"id":"20","kind":"proposal","priority":"P2","area":"Sample columns","observation":"The first and fourth rows place matching icons at different x positions.","change":"Align matching glyphs vertically across both rows."},{"id":"21","kind":"proposal","priority":"P3","area":"Right empty space","observation":"Each row leaves a broad unused area on the right.","change":"Use the area for source-rectangle and scale annotations."},{"id":"22","kind":"proposal","priority":"P3","area":"Bottom empty space","observation":"The page leaves a large empty band beneath Icon Row.","change":"Center the gallery vertically or add a concise rendering-specification footer."},{"id":"23","kind":"proposal","priority":"P2","area":"Home silhouette","observation":"The filled house is a strong shape compared with the detailed outlined gear.","change":"Use consistent visual weight in the action row while retaining raw sprites in the first row."},{"id":"24","kind":"proposal","priority":"P3","area":"Sprite background contrast","observation":"All raw sprites are white on dark with no alternative backdrop reference.","change":"Add a small light-background companion sample for transparency inspection."},{"id":"25","kind":"proposal","priority":"P3","area":"Image boundaries","observation":"The visible glyphs do not expose their rectangular image bounds.","change":"Offer thin optional bounds around the raw sprite samples for inspection."}],"sha256":"71d7b50a816120335ffcbc75e3c765af1e147812c32cf300572f43703604c81a","has_mock":false,"reference":null,"legacy":[{"id":"images","screen":"images","baseline":"baseline_screenshots/images.png","current":"screenshot-baselines/screens/images_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Current capture removes the Settings image-button focus ring. Row layout is unchanged. The Play glyph resembles fast-forward and the click tally is detached from its buttons in both.","sha256":"47379831e154a3b266225a3141a25c83593b33ae77d02b3652fe6daac20b91e9","additional_findings":[]}]},{"id":"islands_trains_settings","baseline":"screenshot-baselines/screens/islands_trains_settings_720p.png","summary":"The paper-strip settings design matches the mock. Its muted palette and compact rows need stronger reading hierarchy and clearer value displays.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Settings title","observation":"The title is small and muted at the top of the tall paper.","change":"Increase title contrast and size while retaining the hand-lettered style."},{"id":"02","kind":"proposal","priority":"P2","area":"Section headings","observation":"DISPLAY, CONTROLS, AUDIO, and TUTORIAL are pale cyan on cream.","change":"Darken the section-heading color for clearer grouping."},{"id":"03","kind":"proposal","priority":"P2","area":"Setting labels","observation":"Olive-gray labels have little contrast against sage rows.","change":"Use darker olive text on the same soft row backgrounds."},{"id":"04","kind":"proposal","priority":"P2","area":"Row height","observation":"Display and audio controls occupy very short strips.","change":"Increase row height and vertical text padding."},{"id":"05","kind":"proposal","priority":"P2","area":"Mode value","observation":"Borderless is not visually distinguished from Mode.","change":"Use a stronger value weight and a fixed value column."},{"id":"06","kind":"proposal","priority":"P2","area":"Resolution formatting","observation":"2560x1440 uses a cramped lowercase x.","change":"Use 2560 × 1440 with readable spacing."},{"id":"07","kind":"proposal","priority":"P2","area":"Cycle arrows","observation":"Small angle-bracket characters sit near the values.","change":"Use consistent chevron buttons with visible hit-area framing."},{"id":"08","kind":"proposal","priority":"P2","area":"Camera labels","observation":"Cam panning speed nearly touches its decrease arrow.","change":"Increase the label-to-control gap or shorten the label to Pan speed."},{"id":"09","kind":"proposal","priority":"P2","area":"Camera capitalization","observation":"Cam rotating Speed capitalizes Speed inconsistently.","change":"Use Camera rotation speed in sentence case."},{"id":"10","kind":"proposal","priority":"P2","area":"Segment contrast","observation":"Active cyan and inactive tan segments are similar in lightness.","change":"Increase their distinction while keeping the pastel palette."},{"id":"11","kind":"proposal","priority":"P2","area":"Camera values","observation":"The two camera controls display segments without numeric values.","change":"Add current step numbers beside both segment groups."},{"id":"12","kind":"proposal","priority":"P2","area":"Effects value","observation":"Effects Volume has no numeric percentage.","change":"Show its percentage in a compact trailing value field."},{"id":"13","kind":"proposal","priority":"P2","area":"Music value","observation":"Music Volume has no numeric percentage.","change":"Show its percentage aligned with the effects value."},{"id":"14","kind":"proposal","priority":"P3","area":"Segment scale","observation":"Ten short bars have no minimum or maximum annotation.","change":"Add one shared Low to High legend for the segmented controls."},{"id":"15","kind":"proposal","priority":"P2","area":"Keyboard action","observation":"KEYBOARD resembles another passive setting row.","change":"Give it a navigation arrow and label it Keyboard controls."},{"id":"16","kind":"proposal","priority":"P2","area":"Tutorial action","observation":"PLAY TUTORIAL has the same subdued appearance as the setting rows.","change":"Use a distinct secondary-action style with a play icon."},{"id":"17","kind":"proposal","priority":"P3","area":"Tutorial section","observation":"The section contains only an action with no explanatory text.","change":"Add a brief note describing what the tutorial covers."},{"id":"18","kind":"proposal","priority":"P2","area":"Reset placement","observation":"RESET TO DEFAULTS sits almost on the bottom edge.","change":"Move it upward into a clear footer safe area."},{"id":"19","kind":"proposal","priority":"P2","area":"Reset affordance","observation":"The reset action is plain low-contrast text.","change":"Give it a bordered secondary-button treatment."},{"id":"20","kind":"proposal","priority":"P3","area":"Reset scope","observation":"Reset to defaults does not state which settings it affects.","change":"Add a short All settings caption beside the action."},{"id":"21","kind":"proposal","priority":"P2","area":"Close control","observation":"The X is isolated far from the narrow paper panel.","change":"Align it with the panel's top corner or add a clear Close label."},{"id":"22","kind":"proposal","priority":"P3","area":"Paper width","observation":"The narrow panel leaves large blank side fields.","change":"Widen the paper enough to accommodate readable controls and labels."},{"id":"23","kind":"proposal","priority":"P3","area":"Lower paper void","observation":"A large blank region separates Play tutorial from Reset.","change":"Reduce that gap and group reset within the settings footer."},{"id":"24","kind":"proposal","priority":"P3","area":"Section spacing","observation":"The gap before AUDIO is notably larger than before CONTROLS.","change":"Use a consistent section-spacing rhythm."},{"id":"25","kind":"proposal","priority":"P3","area":"Save behavior communication","observation":"No visible note explains whether changes apply immediately.","change":"Add a small Changes apply immediately message if that matches behavior."}],"sha256":"1869c9b236db424413262914b45f4859eacccf71486cc54ca5019f84852f75d4","has_mock":true,"reference":"inspiration/example_islands_trains.jpg","legacy":[]},{"id":"kart_select","baseline":"screenshot-baselines/screens/kart_select_720p.png","summary":"The selected racer and vehicle are visible. Improve consistency between the portrait, kart preview, selection badges, and stat presentation.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Preview driver cap","observation":"The Drift portrait carries a P on its cap while the large driver cap is blank.","change":"Repeat the portrait cap detail in the large driver preview to strengthen character continuity."},{"id":"02","kind":"proposal","priority":"P2","area":"Vehicle thumbnails","observation":"Each vehicle thumbnail includes a differently colored driver, suggesting a racer change.","change":"Render the selected racer consistently across all vehicle thumbnails."},{"id":"03","kind":"proposal","priority":"P2","area":"Selected vehicle color","observation":"Standard shows a red kart while the large preview is orange.","change":"Match the thumbnail to the selected vehicle's preview appearance."},{"id":"04","kind":"proposal","priority":"P2","area":"Selected racer badge","observation":"P1 floats above the card and interrupts its border.","change":"Place the badge within a reserved top corner of the selected card."},{"id":"05","kind":"proposal","priority":"P2","area":"Player indicator duplication","observation":"P1 appears in both the header and selected portrait with different shapes.","change":"Use a consistent badge shape and color in both locations."},{"id":"06","kind":"proposal","priority":"P2","area":"Racer identity","observation":"Large Drift text appears below the vehicle without a clear section label.","change":"Label the preview Selected racer and vehicle."},{"id":"07","kind":"proposal","priority":"P2","area":"Vehicle identity","observation":"The preview names Drift but does not repeat Standard.","change":"Add Standard beneath the racer name."},{"id":"08","kind":"proposal","priority":"P2","area":"Stats values","observation":"Four segmented bars have no numeric scores.","change":"Add values such as 6/10 in a trailing column."},{"id":"09","kind":"proposal","priority":"P2","area":"Stats scale","observation":"The bars contain many narrow ticks without a labeled range.","change":"Use a clearly stated common maximum scale."},{"id":"10","kind":"proposal","priority":"P2","area":"Stat labels","observation":"Speed and Acceleration are small compared with the preview name.","change":"Increase stat labels and align their baselines with the bars."},{"id":"11","kind":"proposal","priority":"P3","area":"Weight interpretation","observation":"Weight uses the same positive yellow fill as speed without context.","change":"Add a short tradeoff description for heavier handling."},{"id":"12","kind":"proposal","priority":"P2","area":"Portrait name strips","observation":"Racer names are small in thin pale strips.","change":"Increase name text or strip height slightly."},{"id":"13","kind":"proposal","priority":"P3","area":"Portrait art","observation":"Eight racers share nearly identical facial silhouettes.","change":"Add more distinct facial or costume features to aid recognition."},{"id":"14","kind":"proposal","priority":"P2","area":"Selected portrait border","observation":"Yellow fill and a thick yellow border share little contrast.","change":"Add a dark selected outline or check marker inside the card."},{"id":"15","kind":"proposal","priority":"P2","area":"Vehicle selection","observation":"Standard relies largely on yellow fill to mark selection.","change":"Add a check or Selected label to its card."},{"id":"16","kind":"proposal","priority":"P2","area":"Vehicle section title","observation":"CHOOSE YOUR VEHICLE is small and close to the cards.","change":"Increase the label and add a clear section gap."},{"id":"17","kind":"proposal","priority":"P3","area":"Vehicle naming","observation":"Off-Road is styled differently from plain one-word names.","change":"Use consistent title casing across all vehicle labels."},{"id":"18","kind":"proposal","priority":"P2","area":"Preview illustration","observation":"The preview driver is far less detailed than the selection portraits.","change":"Bring the large driver art to the same character style as the cards."},{"id":"19","kind":"proposal","priority":"P3","area":"Preview platform","observation":"The oversized pale oval occupies substantial vertical space.","change":"Reduce platform thickness to give the stat card more breathing room."},{"id":"20","kind":"proposal","priority":"P2","area":"Footer hints","observation":"Arrows to choose and A Confirm B Back are tiny beside the Back button.","change":"Increase the hint size and use clearer keycaps."},{"id":"21","kind":"proposal","priority":"P2","area":"Back duplication","observation":"A large Back action and a B Back hint repeat the same function side by side.","change":"Combine them into one labeled action with its key hint."},{"id":"22","kind":"proposal","priority":"P2","area":"Ready action","observation":"READY! does not state the next step.","change":"Add a small Start Grand Prix or Continue caption appropriate to behavior."},{"id":"23","kind":"proposal","priority":"P3","area":"Ready button padding","observation":"The action text and trailing arrow are spread across the large skewed button.","change":"Use a controlled icon-to-label gap."},{"id":"24","kind":"proposal","priority":"P3","area":"Header context","observation":"Grand Prix · Mushroom Cup is smaller and distant from the screen title.","change":"Group race context under the title or closer to the player indicator."},{"id":"25","kind":"proposal","priority":"P3","area":"Background checks","observation":"The checker texture is strong behind the portrait grid.","change":"Lower texture contrast behind cards and stat text."}],"sha256":"856192ba3e5d5faea51a2cf4c47839fd73618d02fcb2c3d4f94a1cfdb2598fe6","has_mock":true,"reference":null,"legacy":[]},{"id":"kirby_options","baseline":"screenshot-baselines/screens/kirby_options_720p.png","summary":"The stationery-board composition matches the mock. Refine the interactive hierarchy so decorative notebook elements and large category tiles do not compete with profile editing.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Name control","observation":"Name is a generic placeholder in the largest yellow control.","change":"Display a sample profile name and a smaller Edit name cue."},{"id":"02","kind":"proposal","priority":"P2","area":"Name icon","observation":"The large profile silhouette consumes much of the name pill.","change":"Reduce it to make room for the actual profile value."},{"id":"03","kind":"proposal","priority":"P2","area":"Delete Data action","observation":"A small pawn-like symbol does not communicate deletion.","change":"Use a clear delete-data icon with the existing label."},{"id":"04","kind":"proposal","priority":"P2","area":"Delete action hierarchy","observation":"Delete Data sits beside the primary name control without a destructive distinction.","change":"Use a restrained warning accent and separate it from profile editing."},{"id":"05","kind":"proposal","priority":"P2","area":"Delete label","observation":"The label is much smaller than all other action names.","change":"Increase it to a readable secondary-action size."},{"id":"06","kind":"proposal","priority":"P2","area":"Common section tag","observation":"Common is white on a pale gray strip and small.","change":"Increase its contrast and use a stronger section-label treatment."},{"id":"07","kind":"proposal","priority":"P2","area":"Bottom help","observation":"The long help sentence sits outside the board near the viewport edge.","change":"Move it into a padded footer region inside the board."},{"id":"08","kind":"proposal","priority":"P2","area":"Help context","observation":"Enter a new name and customize your controls describes multiple actions at once.","change":"Use one specific description for the current selection."},{"id":"09","kind":"proposal","priority":"P2","area":"Top tabs","observation":"Network, controller, home, mail, and star are icon-only.","change":"Add compact text labels beneath each icon or a visible selected-tab caption."},{"id":"10","kind":"proposal","priority":"P2","area":"Options selection","observation":"Options is indicated by a purple tab and separate purple banner.","change":"Connect the banner visually to the selected gear tab."},{"id":"11","kind":"proposal","priority":"P3","area":"Tab spacing","observation":"The top icon tabs have irregular apparent gaps due to rotation.","change":"Use a consistent transformed baseline and gap rhythm."},{"id":"12","kind":"proposal","priority":"P2","area":"L and R hints","observation":"Small purple key labels float outside the tabs.","change":"Use consistent keycap boxes aligned with the tab row."},{"id":"13","kind":"proposal","priority":"P2","area":"Controller tile","observation":"The controller icon is tilted independently from the text and board.","change":"Use a consistent icon orientation within each tile."},{"id":"14","kind":"proposal","priority":"P2","area":"Display tile","observation":"Display uses a thin monitor outline beside heavier filled icons.","change":"Normalize icon stroke and visual weight."},{"id":"15","kind":"proposal","priority":"P2","area":"Accessibility tile","observation":"The wide Accessibility label approaches the cell edges.","change":"Increase label room or reduce its size slightly within the shared type scale."},{"id":"16","kind":"proposal","priority":"P2","area":"Sound and Online layout","observation":"Bottom-row labels sit beside icons while top-row labels sit below them.","change":"Use one icon-label layout or explicitly distinguish the two groups."},{"id":"17","kind":"proposal","priority":"P3","area":"Tile grid proportions","observation":"Two broad bottom cells differ strongly from the three upper cells.","change":"Use consistent cell proportions or make the grouping meaningful with labels."},{"id":"18","kind":"proposal","priority":"P2","area":"Grid lines","observation":"Thin beige dividers are faint against off-white paper.","change":"Increase divider contrast slightly to clarify the clickable tile boundaries."},{"id":"19","kind":"proposal","priority":"P3","area":"Notebook checkboxes","observation":"Five empty notebook boxes resemble interactive tasks without readable labels.","change":"Render them as clearly decorative sketches or add meaningful task labels."},{"id":"20","kind":"proposal","priority":"P3","area":"Notebook block text","observation":"Opaque square marks substitute for writing.","change":"Use believable low-emphasis handwritten lines to support the stationery theme."},{"id":"21","kind":"proposal","priority":"P2","area":"Notebook star button","observation":"The green oval star looks interactive but has no visible label.","change":"Add a Profile customization caption near the oval."},{"id":"22","kind":"proposal","priority":"P3","area":"Pencil decoration","observation":"Large outlined pencils cover the notebook's last two rows.","change":"Move them into a margin where they do not obscure the faux content."},{"id":"23","kind":"proposal","priority":"P3","area":"Notebook footprint","observation":"The decorative notebook occupies almost a third of the screen.","change":"Reduce it slightly to give the options board more whitespace."},{"id":"24","kind":"proposal","priority":"P3","area":"Board shadow","observation":"Strong paper shadows and dark notebook shadows compete with tile boundaries.","change":"Soften decorative shadows around the main reading area."},{"id":"25","kind":"proposal","priority":"P3","area":"Footer underline","observation":"The purple line extends nearly to the screen edge below the help text.","change":"Align it with the inner board margins and shorten it to the help region."}],"sha256":"283ee819fc76147bc7c685b06a0b33c0360f4fe1d8bb6a822d3e7ac1f25496ce","has_mock":true,"reference":"inspiration/example_kirby_airriders.jpg","legacy":[]},{"id":"language_demo","baseline":"screenshot-baselines/screens/language_demo_720p.png","summary":"The three scripts render in the current baseline. Twenty distinct proposals improve language selection and the comparison display; no missing-glyph or switching failure is inferred.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Language selectors","observation":"EN, KO, and JA show ISO codes without native names.","change":"Add English, 한국어, and 日本語 in a wider selector group."},{"id":"02","kind":"proposal","priority":"P2","area":"Selected language","observation":"EN is blue while the other languages are green, without a legend.","change":"Use one control palette and a clear selected marker."},{"id":"03","kind":"proposal","priority":"P2","area":"Selector spacing","observation":"The three language pills touch one another.","change":"Add small uniform gaps between the controls."},{"id":"04","kind":"proposal","priority":"P2","area":"Keyboard hints","observation":"[1], [2], and [3] are part of each label string.","change":"Show the digits in separate compact keycaps."},{"id":"05","kind":"proposal","priority":"P2","area":"Title bar","observation":"The title occupies an oversized blue region that merges into EN.","change":"Separate the heading visually from the language picker."},{"id":"06","kind":"proposal","priority":"P2","area":"Active panel heading","observation":"Hello! occupies a large mustard strip without saying it is the active language.","change":"Add Current language: English above the greeting specimen."},{"id":"07","kind":"proposal","priority":"P2","area":"Greeting typography","observation":"Hello! is left-aligned while all menu labels are centered.","change":"Use a deliberate specimen alignment with consistent content insets."},{"id":"08","kind":"proposal","priority":"P2","area":"Menu comparison scope","observation":"The left panel shows five actions while the right compares only Hello and Start.","change":"Add aligned translations for the same set of menu labels."},{"id":"09","kind":"proposal","priority":"P2","area":"Comparison rows","observation":"EN, KO, and JA text are embedded in unstructured sentences.","change":"Use Language, Greeting, and Start columns."},{"id":"10","kind":"proposal","priority":"P2","area":"Script scale","observation":"Korean appears markedly smaller than the handwritten English example.","change":"Normalize optical reading size while retaining appropriate fonts per script."},{"id":"11","kind":"proposal","priority":"P2","area":"Japanese baseline","observation":"The Japanese sample uses a different apparent vertical alignment.","change":"Align row baselines or document the script-specific metrics in captions."},{"id":"12","kind":"proposal","priority":"P2","area":"Comparison heading","observation":"All Languages is small above a broad empty panel.","change":"Increase the heading and add a short font-comparison subtitle."},{"id":"13","kind":"proposal","priority":"P3","area":"Unused comparison area","observation":"Most of the right panel below the three examples is empty.","change":"Add a multiline localized specimen to use the available area."},{"id":"14","kind":"proposal","priority":"P2","area":"Continue action","observation":"Continue shares the same styling as Start, Settings, About, and Exit.","change":"Separate the primary action from the menu specimen list."},{"id":"15","kind":"proposal","priority":"P2","area":"Exit ordering","observation":"Exit appears directly above Continue without grouping.","change":"Move Exit into a distinct secondary action group."},{"id":"16","kind":"proposal","priority":"P2","area":"Font metadata","observation":"Active: ENGLISH and Font: Gaegu-Bold share one footer line.","change":"Split language and active-font metadata into labeled values."},{"id":"17","kind":"proposal","priority":"P3","area":"Font coverage","observation":"Only the active English font is named.","change":"Show the font used for each script in the comparison rows."},{"id":"18","kind":"proposal","priority":"P2","area":"Footer instructions","observation":"Press 1/2/3 to switch languages repeats the key labels without mapping them.","change":"Show 1 English · 2 Korean · 3 Japanese in the footer."},{"id":"19","kind":"proposal","priority":"P3","area":"Panel junction","observation":"The two side panels meet the footer with small triangular background gaps.","change":"Use consistent panel corner treatment at their junction."},{"id":"20","kind":"proposal","priority":"P3","area":"Viewport composition","observation":"The content ends well above the bottom of the black viewport.","change":"Center the complete demo panel vertically or fit its background to the viewport."}],"sha256":"396cda5942420cb0978a10f28f21a6979b322f60303c88cc33b393755ceb110d","has_mock":false,"reference":null,"legacy":[{"id":"language_demo","screen":"language_demo","baseline":"baseline_screenshots/language_demo.png","current":"screenshot-baselines/screens/language_demo_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Current capture removes the EN focus outline. English, Korean and Japanese examples still use visibly different text scales. Missing focus styling cannot be inferred from the current idle image.","sha256":"5b69b21813db4ddea54686fef948a7ff4ff060e0fe4c92516372b92e43330be4","additional_findings":[]}]},{"id":"layout","baseline":"screenshot-baselines/screens/layout_720p.png","summary":"The row and column arrangements are intentional examples. Sixteen distinct proposals improve teaching and measurements; additional findings would be arbitrary changes to this small fixture.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Page title","observation":"Layout System Demo does not identify the two demonstrated arrangements.","change":"Add Row and column layouts as a concise subtitle."},{"id":"02","kind":"proposal","priority":"P2","area":"Top sample","observation":"Left, Center, and Right panels have no local section heading.","change":"Label the top frame Row · centered children."},{"id":"03","kind":"proposal","priority":"P2","area":"Lower sample","observation":"Stacked Item 1 through 3 have no local section heading.","change":"Label the lower frame Column · stacked children."},{"id":"04","kind":"proposal","priority":"P2","area":"Guide order","observation":"The footer describes Column before Row while the examples show Row first.","change":"Order the guide descriptions to match the examples."},{"id":"05","kind":"proposal","priority":"P2","area":"Guide proximity","observation":"Row and Column descriptions are far below their corresponding samples.","change":"Place each explanation directly beneath its sample."},{"id":"06","kind":"proposal","priority":"P3","area":"Panel names","observation":"Left Panel and Right Panel describe position rather than the layout rule.","change":"Use numbered items and keep position names in the frame caption."},{"id":"07","kind":"proposal","priority":"P3","area":"Top row gaps","observation":"The gaps between three fixed-width panels are visible but unmeasured.","change":"Add a fixed-gap annotation outside the samples."},{"id":"08","kind":"proposal","priority":"P3","area":"Column gaps","observation":"The tightly stacked items have no spacing caption.","change":"Add a vertical gap bracket with the configured value."},{"id":"09","kind":"proposal","priority":"P3","area":"Margins statement","observation":"Margins control spacing has no visual reference.","change":"Draw an external margin guide around one sample frame."},{"id":"10","kind":"proposal","priority":"P2","area":"Column inner frame","observation":"A gray rounded panel nests inside a large white panel without naming their roles.","change":"Label Parent and Child stack outside their boundaries."},{"id":"11","kind":"proposal","priority":"P3","area":"Sample color mapping","observation":"Green, brown, and rust are reused without an explicit item-identity key.","change":"Add a small color key linking the same three items across both layouts."},{"id":"12","kind":"proposal","priority":"P2","area":"Sample typography","observation":"Panel names and stacked-item text are small relative to their large colored blocks.","change":"Increase sample-label size with equal insets."},{"id":"13","kind":"proposal","priority":"P3","area":"Divider lengths","observation":"The thin separators are narrower than the white sample panels.","change":"Align divider endpoints with the shared content inset."},{"id":"14","kind":"proposal","priority":"P2","area":"Theme footer","observation":"Using Sage Natural theme with responsive layouts is tiny at the bottom.","change":"Increase footer readability and separate theme metadata from the layout lesson."},{"id":"15","kind":"proposal","priority":"P3","area":"Responsive claim","observation":"The footer names responsive layouts without exposing container dimensions.","change":"Show current viewport and parent widths as demo metadata."},{"id":"16","kind":"proposal","priority":"P3","area":"Vertical composition","observation":"The demo's pale root panel leaves a black band below it.","change":"Center the complete composition vertically within the viewport."}],"sha256":"4b54ed57c809259cea0fdfdcb280df7c001d2a498583d57454596ea2f2feead3","has_mock":false,"reference":null,"legacy":[{"id":"layout","screen":"layout","baseline":"baseline_screenshots/layout.png","current":"screenshot-baselines/screens/layout_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Current capture removes Left Panel focus outline. Same widely separated row and stack examples, small explanatory footer and detached separator lines.","sha256":"ece2b824a9b680b137809855afed1e3cbcfcc0a3aeaec08c91e19dba4466909b","additional_findings":[]}]},{"id":"layout_bug_repros","baseline":"screenshot-baselines/screens/layout_bug_repros_720p.png","summary":"Preserve all repro geometry, diagnostic colors, origin marker, overlap, and intentional differences. Findings concern presentation and misleading expectation copy rather than declaring historical bugs still active.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"Z-order caption","observation":"Case 4 says NOT A BUG but its expected-result line calls the visible blue-on-top order a bug.","change":"Rewrite the expectation to state creation-order rendering and identify blue-on-top as the expected result."},{"id":"02","kind":"proposal","priority":"P2","area":"Case status labels","observation":"FIXED and NOT A BUG are embedded in long small captions.","change":"Use separate status badges outside the test geometry."},{"id":"03","kind":"proposal","priority":"P2","area":"Case headings","observation":"All seven descriptions use small handwritten text.","change":"Increase heading readability without changing the repro coordinates."},{"id":"04","kind":"proposal","priority":"P2","area":"Expected-result lines","observation":"The expected and bug descriptions are tiny and dense.","change":"Put expected behavior in a clear two-line caption beneath each case."},{"id":"05","kind":"proposal","priority":"P2","area":"Number sequence","observation":"Cases 1–5 run down the left and 6–7 start again at the top right.","change":"Add clear column labels or a numbered index to establish reading order."},{"id":"06","kind":"proposal","priority":"P2","area":"Origin marker","observation":"The red plus at the top-left looks like an unexplained floating control.","change":"Add an Origin 0,0 caption nearby outside its measured location."},{"id":"07","kind":"proposal","priority":"P3","area":"Percent sample","observation":"Red and cyan overlap by design but their dimensions are not shown.","change":"Add parent 300 × 80 and child 100% dimension captions."},{"id":"08","kind":"proposal","priority":"P3","area":"Percent expectation","observation":"Red fits inside cyan is stated in prose only.","change":"Add a small expected-geometry diagram outside the live sample."},{"id":"09","kind":"proposal","priority":"P3","area":"Row sample","observation":"A, B, and C show fixed boxes without width annotations.","change":"Caption each child's fixed 100-pixel width."},{"id":"10","kind":"proposal","priority":"P3","area":"Row leftover space","observation":"The gray parent extends far beyond C without explanation.","change":"Label the parent's full width to explain the unused region."},{"id":"11","kind":"proposal","priority":"P2","area":"Flow sample caption","observation":"The flow sample is far to the right of its case heading.","change":"Connect the heading to the yellow parent with a subtle leader outside the test bounds."},{"id":"12","kind":"proposal","priority":"P3","area":"Flow coordinates","observation":"The heading embeds 400,310 without units or a coordinate key.","change":"Show x and y labels explicitly in the metadata."},{"id":"13","kind":"proposal","priority":"P3","area":"Flow children","observation":"Child 1 and Child 2 have no dimension metadata.","change":"Add external child-height and gap labels."},{"id":"14","kind":"proposal","priority":"P2","area":"Z-order label obstruction","observation":"The red box's identifier is covered by the blue box as part of the test.","change":"Repeat both entity identifiers in an unobstructed external legend."},{"id":"15","kind":"proposal","priority":"P2","area":"Z-order question","observation":"BLUE mk(2000) ON TOP? reads as unresolved despite the status badge.","change":"Use a neutral Blue entity · created second label outside the overlap."},{"id":"16","kind":"proposal","priority":"P3","area":"Sizing comparison","observation":"The green and blue buttons are stacked far below their explanation.","change":"Add explicit Auto width and 250 px reference captions beside them."},{"id":"17","kind":"proposal","priority":"P3","area":"Sizing difference","observation":"The two button widths are close but difficult to compare vertically.","change":"Add aligned width guides extending from their outer edges."},{"id":"18","kind":"proposal","priority":"P2","area":"Tab fixture","observation":"Tab A's yellow underline has no textual selected-state caption.","change":"Add Selected: Tab A in the fixture metadata."},{"id":"19","kind":"proposal","priority":"P3","area":"Tab container bounds","observation":"The green outline is thin and hard to distinguish from surrounding dark space.","change":"Add an external labeled outline key instead of altering the tested border."},{"id":"20","kind":"proposal","priority":"P2","area":"Toggle labels","observation":"Toggle A, B, and C are far from their switches across a wide panel.","change":"Add light row guides outside the toggle geometry to connect labels and controls."},{"id":"21","kind":"proposal","priority":"P3","area":"Toggle state","observation":"The yellow/gray switch states are not named.","change":"Add an external On, Off, On state summary."},{"id":"22","kind":"proposal","priority":"P3","area":"Toggle measurement","observation":"The vertical-fit case names the concept without showing measured height.","change":"Display the declared container height and summed child heights."},{"id":"23","kind":"proposal","priority":"P2","area":"Right empty region","observation":"Most of the lower-right canvas is unused.","change":"Use it for a compact fixture legend and expected-results summary."},{"id":"24","kind":"proposal","priority":"P3","area":"Diagnostic color key","observation":"Red, cyan, green, yellow, blue, and purple carry different roles across cases.","change":"Add a per-case parent/child color key."},{"id":"25","kind":"proposal","priority":"P2","area":"Page purpose","observation":"Layout Bug Repros alone does not distinguish current regressions from retained historical cases.","change":"Add Retained regression fixtures; badges describe current expectations beneath the title."}],"sha256":"e7daac628b2df245860ce0969569516aa7511f9c52dbfd9a2f51a795b673e8ef","has_mock":false,"reference":null,"legacy":[]},{"id":"layout_patterns","baseline":"screenshot-baselines/screens/layout_patterns_720p.png","summary":"Source identifies this as a minimal fixed-size fixture for assert_ui checks. Ten external presentation proposals are defensible; preserve the three boxes and their exact geometry rather than inventing 25 defects.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Page identification","observation":"The screenshot contains three numbered boxes with no title.","change":"Add a caption outside the measured fixture naming the fixed horizontal layout test."},{"id":"02","kind":"proposal","priority":"P2","area":"Test purpose","observation":"Nothing visible explains why the three boxes exist.","change":"Add a one-line explanation of the expected row arrangement."},{"id":"03","kind":"proposal","priority":"P2","area":"Parent dimensions","observation":"The gray parent has no dimension annotation.","change":"Show its width and height outside the tested rectangle."},{"id":"04","kind":"proposal","priority":"P3","area":"Child dimensions","observation":"The three equal boxes have no size labels.","change":"Add an external 120-pixel child-width annotation."},{"id":"05","kind":"proposal","priority":"P3","area":"Gap measurement","observation":"The equal spaces between boxes are visible but unnamed.","change":"Add a 12-pixel gap marker outside the fixture."},{"id":"06","kind":"proposal","priority":"P3","area":"Padding measurement","observation":"The gray parent padding is visible without a value.","change":"Add a 16-pixel padding guide outside the test geometry."},{"id":"07","kind":"proposal","priority":"P2","area":"Fixture position","observation":"The sample sits at the upper-left of a mostly blank canvas.","change":"Mark its fixed origin in an external caption so the placement reads as intentional."},{"id":"08","kind":"proposal","priority":"P3","area":"Expected result","observation":"No visual statement describes the successful geometry.","change":"Add Three equal children fit without overflow beneath the sample."},{"id":"09","kind":"proposal","priority":"P3","area":"Number legibility","observation":"Black handwritten numerals are small within the bright boxes.","change":"Provide matching enlarged number labels in the external legend while preserving the tested content."},{"id":"10","kind":"proposal","priority":"P3","area":"Color meaning","observation":"Cyan, pink, and green are not explained.","change":"Add an external legend stating that colors identify child order."}],"sha256":"617fc8c69a4f01dd6f0db1589d22318d151422289cbd9e617d4a8c3f1c1aa042","has_mock":false,"reference":null,"legacy":[{"id":"layout_patterns","screen":"layout_patterns","baseline":"baseline_screenshots/layout_patterns.png","current":"screenshot-baselines/screens/layout_patterns_720p.png","pixel_identical":true,"size":[1280,720],"summary":"Pixel-identical. Only an unlabeled horizontal triplet numbered 1, 2, 3 is visible near the top-left. Current recommendations concern framing and explanation, not a claim the layout engine failed.","sha256":"617fc8c69a4f01dd6f0db1589d22318d151422289cbd9e617d4a8c3f1c1aa042","additional_findings":[]}]},{"id":"marlo_kart","baseline":"screenshot-baselines/screens/marlo_kart_720p.png","summary":"The title state is recognizable and the selected engine class is visible. Refine the title-screen hierarchy and racing illustration without assuming anything about later game phases.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Engine-class group","observation":"50cc, 100cc, and 150cc have no group label.","change":"Add Engine class above the three choices."},{"id":"02","kind":"proposal","priority":"P2","area":"Engine explanation","observation":"The classes provide displacement values without difficulty context.","change":"Add short speed/difficulty descriptors below each option."},{"id":"03","kind":"proposal","priority":"P2","area":"Selected 150cc","observation":"The selected state relies on yellow fill.","change":"Add a check or Selected label to 150cc."},{"id":"04","kind":"proposal","priority":"P3","area":"Engine typography","observation":"The labels combine number and cc tightly.","change":"Use consistent spacing and tabular numerals for the three values."},{"id":"05","kind":"proposal","priority":"P2","area":"Start label","observation":"START YOUR ENGINES is broad promotional copy for entering the next phase.","change":"Add a concise Select racer sublabel to clarify the next step."},{"id":"06","kind":"proposal","priority":"P2","area":"Start control size","observation":"The start button is much wider than the engine selector group.","change":"Align its outer width with the group above."},{"id":"07","kind":"proposal","priority":"P2","area":"Start text padding","observation":"The long label nearly fills the button width.","change":"Increase horizontal padding or reduce the text size slightly."},{"id":"08","kind":"proposal","priority":"P2","area":"Control group spacing","observation":"The class buttons almost touch the large action beneath them.","change":"Increase the gap between selection and confirmation."},{"id":"09","kind":"proposal","priority":"P2","area":"Keyboard hints","observation":"Arrows: engine class and Enter: start are tiny near the bottom.","change":"Use readable keycap-and-label groups beside the controls."},{"id":"10","kind":"proposal","priority":"P3","area":"Keyboard alignment","observation":"The two keyboard hints have uneven separation and no shared structure.","change":"Align them on one baseline with equal group spacing."},{"id":"11","kind":"proposal","priority":"P2","area":"Game-format sentence","observation":"Four tracks. Eight racers. One trophy. is very small.","change":"Increase supporting-copy size and contrast."},{"id":"12","kind":"proposal","priority":"P3","area":"Subtitle","observation":"AFTERHOURS GRAND PRIX is tiny under the oversized logo.","change":"Give the subtitle a stronger size and stable baseline."},{"id":"13","kind":"proposal","priority":"P3","area":"Logo spacing","observation":"MARLO and KART have a large irregular vertical gap.","change":"Tighten the two-line logo while retaining its playful tilt."},{"id":"14","kind":"proposal","priority":"P3","area":"Logo outline","observation":"The heavy dark outline creates uneven visual weight around the letters.","change":"Use a more consistent outline and shadow treatment."},{"id":"15","kind":"proposal","priority":"P2","area":"Kart badge","observation":"The red kart has a blank white nose badge; the web mock places a red M inside it.","change":"Restore the red M brand emblem inside the white nose badge."},{"id":"16","kind":"proposal","priority":"P2","area":"Driver face","observation":"The large driver has a single dot and no other facial detail.","change":"Bring the illustration closer to the expressive racer portrait style."},{"id":"17","kind":"proposal","priority":"P3","area":"Driver hands","observation":"Broad overlapping arm shapes obscure the steering wheel.","change":"Clarify hand positions and the wheel silhouette."},{"id":"18","kind":"proposal","priority":"P3","area":"Kart wheel perspective","observation":"Front and rear wheels use noticeably different angle and scale cues.","change":"Refine their perspective to match the chassis plane."},{"id":"19","kind":"proposal","priority":"P3","area":"Exhaust","observation":"The pale exhaust shape resembles a detached rectangular strip.","change":"Add a clearer pipe connection and consistent shading."},{"id":"20","kind":"proposal","priority":"P3","area":"Kart shadow","observation":"A large dark green oval competes with the wheel shapes.","change":"Soften and reduce the shadow to ground the kart."},{"id":"21","kind":"proposal","priority":"P2","area":"Racing context","observation":"The vehicle sits on flat green ground with no visible track.","change":"Add a restrained road or track curve behind the kart."},{"id":"22","kind":"proposal","priority":"P3","area":"Mountain backdrop","observation":"Large flat triangles create a static horizon behind the logo.","change":"Add depth through a second subdued ridge layer."},{"id":"23","kind":"proposal","priority":"P3","area":"Horizon stripe","observation":"A bright horizontal green band cuts through the class controls.","change":"Place controls on a consistent backing or move the horizon away from them."},{"id":"24","kind":"proposal","priority":"P3","area":"Composition balance","observation":"The kart dominates the right while controls cluster low on the left.","change":"Move the controls slightly upward to balance the logo and vehicle."},{"id":"25","kind":"proposal","priority":"P2","area":"Secondary navigation","observation":"The title state exposes only engine class and start.","change":"Add compact Settings and Quit/Back actions if available in this title flow."}],"sha256":"3a6553a940a4bfb68d6d7c185750570b125c09d79cd80260deaf1c38ff0d2397","has_mock":true,"reference":null,"legacy":[]},{"id":"media_library","baseline":"screenshot-baselines/screens/media_library_720p.png","summary":"The library has a useful grid-detail structure and coherent artwork. Improve readability, selection alignment, and the distinction between navigation, filtering, and media metadata.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Search placeholder","observation":"Search your library is tiny inside a wide field.","change":"Increase placeholder size and add a recognizable search icon."},{"id":"02","kind":"proposal","priority":"P2","area":"Header actions","observation":"Home, Server, and Settings are small and low contrast.","change":"Increase their text size and separate them with consistent spacing."},{"id":"03","kind":"proposal","priority":"P2","area":"Profile badge","observation":"The lone G appears in a square without context.","change":"Use a recognizable avatar treatment and a visible account label when space permits."},{"id":"04","kind":"proposal","priority":"P2","area":"Sidebar headings","observation":"YOUR MEDIA and SERVER are extremely small.","change":"Increase their size and contrast without competing with navigation."},{"id":"05","kind":"proposal","priority":"P2","area":"Sidebar alignment","observation":"Navigation text is centered while server text is left-aligned.","change":"Left-align navigation labels to the same sidebar inset."},{"id":"06","kind":"proposal","priority":"P2","area":"Library count","observation":"24 is detached from Library and faint.","change":"Present it as a compact 24 items badge beside the heading."},{"id":"07","kind":"proposal","priority":"P2","area":"Repeated Library names","observation":"Library appears in the sidebar, page heading, and a tab.","change":"Rename the inner tab All titles or another distinct view name."},{"id":"08","kind":"proposal","priority":"P2","area":"Recommended selection","observation":"The selected tab uses only a thin yellow underline.","change":"Increase selected label contrast and keep the underline tightly aligned."},{"id":"09","kind":"proposal","priority":"P2","area":"All media filter","observation":"All media looks like static text without a dropdown indicator.","change":"Add a trailing chevron and visible filter-control boundary."},{"id":"10","kind":"proposal","priority":"P2","area":"By title sort","observation":"By title appears as another loose label.","change":"Show Sort: Title with a chevron or direction indicator."},{"id":"11","kind":"proposal","priority":"P2","area":"Grid List switch","observation":"Grid and List use tiny text with a faint selected background.","change":"Use a clear segmented control with icons and readable labels."},{"id":"12","kind":"proposal","priority":"P2","area":"Selected poster frame","observation":"The Harbour Lights outline spans the whole tile width while the poster is narrower.","change":"Wrap the selection frame around the actual poster or the full card including its metadata."},{"id":"13","kind":"proposal","priority":"P2","area":"Poster gutters","observation":"Portrait posters sit within wide dark horizontal gutters.","change":"Use consistent poster-width cards to give the grid a stronger rhythm."},{"id":"14","kind":"proposal","priority":"P2","area":"Media titles","observation":"Harbour Lights and other titles are small relative to their artwork.","change":"Increase title size and weight slightly."},{"id":"15","kind":"proposal","priority":"P2","area":"Year and type rows","observation":"Years sit left while Feature and Series sit far right in each tile.","change":"Group metadata with a dot separator beneath the title."},{"id":"16","kind":"proposal","priority":"P2","area":"Type distinctions","observation":"Feature, Series, and Album are tiny plain words.","change":"Use compact type badges to distinguish mixed-media results."},{"id":"17","kind":"proposal","priority":"P3","area":"Grid spacing","observation":"The second-row poster begins close to the first row's metadata.","change":"Increase the vertical gap between complete cards."},{"id":"18","kind":"proposal","priority":"P2","area":"Selected detail metadata","observation":"2019 - 118 min - Feature is small and dim.","change":"Increase size and use clear centered-dot separators."},{"id":"19","kind":"proposal","priority":"P2","area":"Rating stars","observation":"Four yellow stars and one gray star have no numeric label.","change":"Add 4/5 or the intended rating value beside the stars."},{"id":"20","kind":"proposal","priority":"P2","area":"Description","observation":"The plot sentence is small and occupies a long narrow line.","change":"Increase body size and allow a readable two-line description."},{"id":"21","kind":"proposal","priority":"P2","area":"Director credit","observation":"dir. Ana Weir is faint and abbreviated.","change":"Use Directed by Ana Weir with legible supporting contrast."},{"id":"22","kind":"proposal","priority":"P2","area":"Play action","observation":"The main Play button has small text and no play glyph.","change":"Increase its label and add a single-triangle play icon."},{"id":"23","kind":"proposal","priority":"P2","area":"Watchlist action","observation":"A tiny plus floats beside Play with no visible label.","change":"Use an outlined Add to watchlist button or labeled icon."},{"id":"24","kind":"proposal","priority":"P2","area":"Pagination","observation":"Page numbers 1–4 are tiny and close to the bottom edge.","change":"Increase page-control size and bottom padding."},{"id":"25","kind":"proposal","priority":"P2","area":"Server status","observation":"Home server and Local demo library are faint and do not expose connection state.","change":"Add a clear local-library badge or status dot with text."}],"sha256":"b2623fee8eef0f49f715eebe698f084cc77dac22ae09c946f6e042f006cb11b2","has_mock":true,"reference":null,"legacy":[]},{"id":"menu_showcase","baseline":"screenshot-baselines/screens/menu_showcase_720p.png","summary":"The open Bottom menu is intentionally captured to demonstrate upward placement. Eighteen proposals improve anchor, menu, and state explanation without inferring unseen keyboard or corner-menu failures.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Title","observation":"Anchored menus and the behavior explanation share one small line.","change":"Use Anchored menus as a heading with a separate edge-flip subtitle."},{"id":"02","kind":"proposal","priority":"P2","area":"Top menu group","observation":"File and Edit look like two isolated large buttons.","change":"Place them in a modest menu-bar frame."},{"id":"03","kind":"proposal","priority":"P2","area":"Trigger labels","observation":"Bottom and Corner describe position without identifying the demonstrated behavior.","change":"Use Bottom edge and Bottom-right corner."},{"id":"04","kind":"proposal","priority":"P2","area":"Direction cues","observation":"The upper and lower triggers do not show opening directions.","change":"Add small down/up indicators beside their labels."},{"id":"05","kind":"proposal","priority":"P2","area":"Status message","observation":"Click a menu appears near the center far from every trigger.","change":"Move the instruction below the heading."},{"id":"06","kind":"proposal","priority":"P2","area":"Open-state status","observation":"The status still says click a menu while Bottom is already open.","change":"Show Bottom menu open · placed above anchor in the baseline state."},{"id":"07","kind":"proposal","priority":"P2","area":"Open menu text","observation":"New, Open, Save, and Revert are small and widely spaced.","change":"Increase menu-label size and reduce tracking."},{"id":"08","kind":"proposal","priority":"P2","area":"New row padding","observation":"The highlighted New row is tightly bounded by its outline.","change":"Increase internal text inset while preserving the focus treatment."},{"id":"09","kind":"proposal","priority":"P2","area":"Shortcut contrast","observation":"Cmd+N, Cmd+O, and Cmd+S are very dim against teal.","change":"Increase shortcut contrast to a readable secondary level."},{"id":"10","kind":"proposal","priority":"P2","area":"Shortcut alignment","observation":"Shortcuts sit close to the menu's right edge.","change":"Add a consistent trailing inset and a fixed shortcut column."},{"id":"11","kind":"proposal","priority":"P2","area":"Disabled Revert","observation":"Revert is extremely faint inside the gray disabled row.","change":"Keep it inactive but raise label contrast enough to identify the option."},{"id":"12","kind":"proposal","priority":"P3","area":"Disabled explanation","observation":"Revert has no visible reason for its disabled example state.","change":"Add an external demo caption explaining that it is intentionally disabled."},{"id":"13","kind":"proposal","priority":"P2","area":"Menu and trigger boundary","observation":"The open menu and Bottom trigger use the same teal fill and meet directly.","change":"Add a subtle border or separator distinguishing the popup from its anchor."},{"id":"14","kind":"proposal","priority":"P3","area":"Upward-placement proof","observation":"The expected flip is visible without a boundary marker.","change":"Draw a faint viewport-edge guide and an upward placement arrow outside the popup."},{"id":"15","kind":"proposal","priority":"P3","area":"Corner example","observation":"The Corner trigger is closed, so horizontal clamping is not demonstrated in the capture.","change":"Add a labeled expected-placement diagram beside it."},{"id":"16","kind":"proposal","priority":"P3","area":"Empty canvas","observation":"Most of the central viewport is unused.","change":"Use it for a compact placement diagram connecting top, bottom, and corner cases."},{"id":"17","kind":"proposal","priority":"P3","area":"Trigger alignment","observation":"The bottom-left and bottom-right triggers have no shared footer frame.","change":"Add an unobtrusive baseline guide to emphasize their common edge position."},{"id":"18","kind":"proposal","priority":"P2","area":"Sample identification","observation":"The page does not distinguish live triggers from explanatory text.","change":"Add a short Live menu examples label above the trigger area."}],"sha256":"970db7dced46987c72bbefa3238d417a2bdd6cc81f71d70c789195b0138dfac5","has_mock":false,"reference":null,"legacy":[]},{"id":"meters_gauges","baseline":"screenshot-baselines/screens/meters_gauges_720p.png","summary":"The page contains several useful meter forms. The animated 1% capture is a moment in its cycle, not a failure. Improve labels, fill semantics, and linked-control explanation.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"Stacked Bars heading","observation":"Health and Shield are side by side while the heading calls them Stacked Bars.","change":"Rename the section Paired bars or add an actual stacked companion example."},{"id":"02","kind":"proposal","priority":"P2","area":"Inline abbreviations","observation":"HP, MP, and XP have no expanded names.","change":"Add Health, Mana, and Experience captions."},{"id":"03","kind":"proposal","priority":"P2","area":"Inline meter colors","observation":"All three bars use the same blue fill and green remainder.","change":"Give each metric a labeled identity color or explain the common theme treatment."},{"id":"04","kind":"proposal","priority":"P2","area":"Track color","observation":"Green remainder segments look like completed progress as strongly as blue fills.","change":"Use a neutral remainder track and reserve color for the filled portion."},{"id":"05","kind":"proposal","priority":"P2","area":"Inline percentages","observation":"65%, 39%, and 84% sit at the left of their fills.","change":"Move values to a fixed trailing value column."},{"id":"06","kind":"proposal","priority":"P2","area":"Inline row grouping","observation":"HP, MP, and XP labels sit close to the preceding bar.","change":"Increase inter-meter group spacing and tighten each label-to-bar gap."},{"id":"07","kind":"proposal","priority":"P2","area":"Health label","observation":"Health: 65% is embedded in the track.","change":"Place label and value outside the bar."},{"id":"08","kind":"proposal","priority":"P2","area":"Shield label","observation":"Shield: 29% is embedded in its smaller filled region.","change":"Use the same external label/value pattern as Health."},{"id":"09","kind":"proposal","priority":"P3","area":"Health-shield relationship","observation":"The heading joins the two metrics but gives no shared total or relation.","change":"Add a short caption explaining independent health and shield values."},{"id":"10","kind":"proposal","priority":"P2","area":"Animated value","observation":"1% sits in a tiny sliver of blue fill.","change":"Keep the animated percentage in a stable field beside the bar."},{"id":"11","kind":"proposal","priority":"P2","area":"Animation spinner","observation":"An unlabeled ring sits next to Animated Progress.","change":"Label it as a spinner or circular progress companion according to its role."},{"id":"12","kind":"proposal","priority":"P3","area":"Animation timing","observation":"The screenshot does not describe the animation cycle.","change":"Add a small 0–100% looping caption with duration."},{"id":"13","kind":"proposal","priority":"P3","area":"Animated sample width","observation":"The long bar and small ring leave a large blank right region.","change":"Align the pair within a compact sample frame."},{"id":"14","kind":"proposal","priority":"P2","area":"Gauge labels","observation":"The circular gauges show only 25%, 50%, and 90%.","change":"Add meaningful sample names or Low, Half, and High labels."},{"id":"15","kind":"proposal","priority":"P2","area":"Gauge value placement","observation":"Values sit below empty ring centers.","change":"Move the percentages into the centers for a tighter readout."},{"id":"16","kind":"proposal","priority":"P2","area":"Gauge track contrast","observation":"The unfilled ring segments blend into the navy panel.","change":"Increase track contrast while preserving colored arcs."},{"id":"17","kind":"proposal","priority":"P3","area":"Gauge color semantics","observation":"Red, gold, and green suggest thresholds without naming them.","change":"Add a threshold legend outside the gauges."},{"id":"18","kind":"proposal","priority":"P3","area":"Gauge spacing","observation":"Three small rings are spread across almost the entire panel.","change":"Bring them closer into a comparison group."},{"id":"19","kind":"proposal","priority":"P2","area":"Interactive control label","observation":"Value: 65% does not say which meters the control affects.","change":"Name the controlled metric and list linked examples."},{"id":"20","kind":"proposal","priority":"P2","area":"Slider thumb","observation":"The blue thumb sits on a blue-and-green track with weak separation.","change":"Use a contrasting thumb outline and a distinct handle shape."},{"id":"21","kind":"proposal","priority":"P2","area":"Slider anatomy","observation":"The interactive slider resembles the progress bars above it.","change":"Use a thinner track and explicit drag handle to distinguish input from output."},{"id":"22","kind":"proposal","priority":"P3","area":"Slider endpoints","observation":"The control has no minimum or maximum labels.","change":"Add 0% and 100% endpoint captions."},{"id":"23","kind":"proposal","priority":"P2","area":"Section typography","observation":"Section labels are small and widely spaced compared with available panel area.","change":"Increase their size and use consistent left insets."},{"id":"24","kind":"proposal","priority":"P3","area":"Panel heights","observation":"Large dark panels contain small low-height examples.","change":"Reduce decorative vertical padding and allocate more room to labels."},{"id":"25","kind":"proposal","priority":"P3","area":"Demo footer","observation":"No legend explains shared values or theme behavior.","change":"Add a compact setup summary below the interactive control."}],"sha256":"4238f42dec031f8b73b99813d1e2516871137477ee5fbe535f74cafb1b57b7ee","has_mock":false,"reference":null,"legacy":[]},{"id":"minesweeper_lab","baseline":"screenshot-baselines/screens/minesweeper_lab_720p.png","summary":"The retro desktop styling is deliberate and should remain. Proposals improve game-state explanation and pixel-art consistency without replacing the classic Windows frame.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Mine counter","observation":"The red 038 counter has no label.","change":"Add a small Mines remaining caption in the status area or beside the display."},{"id":"02","kind":"proposal","priority":"P2","area":"Timer","observation":"The 000 display has no time unit or label.","change":"Add Time · seconds beneath or above the timer."},{"id":"03","kind":"proposal","priority":"P2","area":"Counter typography","observation":"The thick pixel digits make 038 visually dense.","change":"Tune segment spacing so each digit is distinct while preserving the digital style."},{"id":"04","kind":"proposal","priority":"P2","area":"Reset face","observation":"The smiley button has no visible reset label.","change":"Add a small New game caption near the face control."},{"id":"05","kind":"proposal","priority":"P2","area":"Difficulty identity","observation":"The 16-by-16 board is visible but the difficulty is unnamed.","change":"Show Intermediate · 16 × 16 in the game status area."},{"id":"06","kind":"proposal","priority":"P2","area":"Starting state","observation":"Some cells are revealed and two flags are placed while the timer reads zero.","change":"Mark the baseline as a prepared sample state in the demo frame."},{"id":"07","kind":"proposal","priority":"P2","area":"Status instruction","observation":"Left click to reveal. Right click to mark a mine uses small text at the bottom.","change":"Increase status text readability within the classic status bar."},{"id":"08","kind":"proposal","priority":"P2","area":"Flagging wording","observation":"Mark a mine could imply certainty rather than a player annotation.","change":"Use Place or remove a flag in the instruction."},{"id":"09","kind":"proposal","priority":"P2","area":"Board coordinates","observation":"The dense grid has no row or column reference.","change":"Offer subtle external coordinate labels for demo inspection."},{"id":"10","kind":"proposal","priority":"P3","area":"Flag glyphs","observation":"Tiny red flags have little separation from the dark mast.","change":"Increase flag silhouette clarity within the existing cell size."},{"id":"11","kind":"proposal","priority":"P3","area":"Revealed numbers","observation":"Blue 1 and green 2 are thin compared with the surrounding bevels.","change":"Increase numeral weight while keeping classic number colors."},{"id":"12","kind":"proposal","priority":"P2","area":"Revealed-cell state","observation":"Empty revealed cells and numbered cells use almost the same flat gray as recessed boundaries.","change":"Clarify the exposed-cell fill without changing covered-cell bevels."},{"id":"13","kind":"proposal","priority":"P3","area":"Cell bevel weight","observation":"Bright repeated bevels dominate the board more than the few revealed numbers.","change":"Slightly reduce bevel contrast while preserving the retro grid structure."},{"id":"14","kind":"proposal","priority":"P3","area":"Board outer frame","observation":"Several nested bevels consume space around the cells.","change":"Reduce one redundant outer inset while retaining the classic sunken frame."},{"id":"15","kind":"proposal","priority":"P2","area":"Game menu","observation":"Game and Help are small and closely packed.","change":"Use consistent menu-item padding and readable text size."},{"id":"16","kind":"proposal","priority":"P2","area":"Window title","observation":"Minesweeper is small within the blue title bar.","change":"Increase title text slightly and align it cleanly with the app icon."},{"id":"17","kind":"proposal","priority":"P2","area":"Maximize control","observation":"The middle window control appears as an almost blank square.","change":"Render a clear maximize glyph at the pixel grid."},{"id":"18","kind":"proposal","priority":"P3","area":"Close glyph","observation":"The x is tiny compared with its gray button.","change":"Center and enlarge the glyph within the classic control."},{"id":"19","kind":"proposal","priority":"P3","area":"Window-control spacing","observation":"The minimize, maximize, and close buttons nearly touch.","change":"Add one consistent pixel-grid gap between them."},{"id":"20","kind":"proposal","priority":"P3","area":"Desktop icon label","observation":"My Computer uses a different handwritten-looking face from the window chrome.","change":"Use the same retro bitmap text style as the desktop shell."},{"id":"21","kind":"proposal","priority":"P3","area":"Desktop icon scale","observation":"The monitor icon is small compared with the label's wide footprint.","change":"Balance icon scale with the centered label width."},{"id":"22","kind":"proposal","priority":"P3","area":"Taskbar app button","observation":"The Minesweeper task button leaves a large unused interior span.","change":"Use a width closer to the app label or show active-window emphasis more clearly."},{"id":"23","kind":"proposal","priority":"P3","area":"Taskbar clock","observation":"12:00 PM sits in a wide recessed region.","change":"Tighten horizontal padding to match the classic clock treatment."},{"id":"24","kind":"proposal","priority":"P2","area":"Game progress","observation":"The status area shows input instructions but no revealed-cell progress.","change":"Add a compact safe-cells-remaining readout as optional demo metadata."},{"id":"25","kind":"proposal","priority":"P3","area":"Desktop empty space","observation":"The centered window leaves broad blank teal fields.","change":"Use a restrained external demo caption to explain the prepared game state without crowding the board."}],"sha256":"87397a8c2165611f20828963c18f4536a275582430aa244f11b1e03c61354031","has_mock":true,"reference":null,"legacy":[]},{"id":"mini_motorways_settings","baseline":"screenshot-baselines/screens/mini_motorways_settings_720p.png","summary":"The sparse road-map settings composition matches the mock. Improve label contrast, state semantics, and the relationship between navigation and controls.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Inactive navigation","observation":"Video, Audio, and other white labels sit on pale cyan blocks.","change":"Darken the text or backing to improve contrast."},{"id":"02","kind":"proposal","priority":"P2","area":"Selected Game tab","observation":"White Game text sits on a light yellow block.","change":"Use dark selected-tab text while retaining the yellow accent."},{"id":"03","kind":"proposal","priority":"P2","area":"Navigation widths","observation":"Each tab block follows its text width and begins at a different x position.","change":"Give the tabs a consistent alignment edge and controlled padding."},{"id":"04","kind":"proposal","priority":"P2","area":"Language tab","observation":"Language extends far left relative to Video and Audio.","change":"Use a shared navigation width so long labels do not alter the column silhouette."},{"id":"05","kind":"proposal","priority":"P2","area":"Cross-Save label","observation":"Cross-Save is a wide technical term among shorter category names.","change":"Use a consistent text size and add a short account-sync subtitle if needed."},{"id":"06","kind":"proposal","priority":"P2","area":"Back icon","observation":"A large bare arrow floats in the upper-left corner.","change":"Add a Back label or frame it as a consistent navigation control."},{"id":"07","kind":"proposal","priority":"P2","area":"Toggle semantics","observation":"Night Mode and Vibration use an X inside a circle for Off.","change":"Add explicit Off text so the X is not mistaken for an error or close action."},{"id":"08","kind":"proposal","priority":"P2","area":"Enabled toggle","observation":"Hold to Draw/Delete uses a checkmark without an On label.","change":"Pair the check with On using the same state layout as disabled rows."},{"id":"09","kind":"proposal","priority":"P2","area":"Toggle sizing","observation":"Large circular toggles compete with setting names.","change":"Reduce circles slightly and align them in a shared trailing column."},{"id":"10","kind":"proposal","priority":"P2","area":"Hold label","observation":"Hold to Draw/Delete combines two actions in a long phrase.","change":"Use Hold to draw or delete with a short explanation below."},{"id":"11","kind":"proposal","priority":"P2","area":"Night Mode description","observation":"Night Mode has no indication of what changes.","change":"Add a brief preview or description of the darker palette."},{"id":"12","kind":"proposal","priority":"P2","area":"Vibration context","observation":"Vibration has no note about controller applicability.","change":"Add a compact Controller feedback subtitle."},{"id":"13","kind":"proposal","priority":"P2","area":"Sensitivity typography","observation":"Controller Cursor Sensitivity is much smaller than adjacent setting labels.","change":"Use a consistent setting-label scale."},{"id":"14","kind":"proposal","priority":"P2","area":"Sensitivity layout","observation":"The value Default and large arrows span a very wide row.","change":"Bring arrows closer to the value in a compact selector."},{"id":"15","kind":"proposal","priority":"P2","area":"Sensitivity value meaning","observation":"Default gives no measurable or relative value.","change":"Show Default · 1.0× or another meaningful scale if supported."},{"id":"16","kind":"proposal","priority":"P3","area":"Selector arrows","observation":"Solid triangles dominate the sensitivity row.","change":"Use lighter chevrons with consistent button bounds."},{"id":"17","kind":"proposal","priority":"P2","area":"Separator","observation":"The horizontal rule under sensitivity ends before the rightmost controls.","change":"Align it to the full settings column width."},{"id":"18","kind":"proposal","priority":"P2","area":"Colorblind Mode label","observation":"A single binary label does not explain the alternative palette.","change":"Add a short palette preview beside the setting."},{"id":"19","kind":"proposal","priority":"P2","area":"Content heading","observation":"The right-side settings have no Game settings heading.","change":"Add a small heading aligned with the first row."},{"id":"20","kind":"proposal","priority":"P3","area":"Row spacing","observation":"The gap around sensitivity is larger than between the toggles above.","change":"Use a consistent vertical rhythm while keeping a deliberate accessibility group break."},{"id":"21","kind":"proposal","priority":"P2","area":"Tutorial action","observation":"Tutorial is large white text on pale cyan near the bottom edge.","change":"Increase contrast and give it a clear secondary-action treatment."},{"id":"22","kind":"proposal","priority":"P3","area":"Tutorial arrow","observation":"The large arrow is close to the trailing edge.","change":"Use equal horizontal padding around label and arrow."},{"id":"23","kind":"proposal","priority":"P2","area":"Version footer","observation":"A long release identifier occupies prominent bottom-left space.","change":"Reduce its emphasis and shorten the default visible version string."},{"id":"24","kind":"proposal","priority":"P3","area":"Road decoration","observation":"The white road bends directly behind the navigation column.","change":"Lower its prominence where it intersects tab backgrounds."},{"id":"25","kind":"proposal","priority":"P3","area":"Background grid","observation":"Faint grid lines pass through every setting row.","change":"Keep grid detail quieter behind the text column."}],"sha256":"0e4c9f905c109fc046178e22c99369d03be82a60261aacc372f344a0b30ae870","has_mock":true,"reference":"inspiration/example_mini_motorways.jpg","legacy":[]},{"id":"modals","baseline":"screenshot-baselines/screens/modals_720p.png","summary":"No modal is open in this baseline. Findings target the launcher and result display; dialog appearance, focus trapping, and background blocking cannot be judged from this resting image.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Page title","observation":"Modal Dialogs is the only explanation of the page.","change":"Add Choose a dialog example and inspect its result beneath the title."},{"id":"02","kind":"proposal","priority":"P2","area":"Basic category","observation":"Basic does not explain the difference between Simple and Composable.","change":"Add a short description under each launcher."},{"id":"03","kind":"proposal","priority":"P2","area":"Simple Modal label","observation":"The launcher names the implementation rather than the visible behavior.","change":"Add Plain message dialog as its specimen subtitle."},{"id":"04","kind":"proposal","priority":"P2","area":"Composable Modal label","observation":"Composable is technical without describing its content.","change":"Add Form controls with Save and Cancel beneath the label."},{"id":"05","kind":"proposal","priority":"P2","area":"Helpers category","observation":"Helpers is an API term without user-visible meaning.","change":"Rename it Standard dialog types."},{"id":"06","kind":"proposal","priority":"P2","area":"Info Dialog and Notice","observation":"The two launchers have similar names without distinguishing behavior.","change":"Add brief purpose captions for informational acknowledgment and notice."},{"id":"07","kind":"proposal","priority":"P2","area":"Confirmation color","observation":"Confirmation uses dark red although no destructive action is named.","change":"Use a neutral confirmation style or label the destructive scenario."},{"id":"08","kind":"proposal","priority":"P2","area":"Launcher palette","observation":"Cyan, purple, and red fills have no legend.","change":"Use consistent launch-button styling and identify variants through labels."},{"id":"09","kind":"proposal","priority":"P2","area":"Button labels","observation":"Small widely spaced text sits inside broad rectangular buttons.","change":"Increase readable label size and reduce tracking."},{"id":"10","kind":"proposal","priority":"P2","area":"Button heights","observation":"Launch controls are low relative to their wide row panels.","change":"Increase vertical padding within each control."},{"id":"11","kind":"proposal","priority":"P2","area":"Category column","observation":"Basic, Helpers, Stacking, and Blocking share space with long action names.","change":"Use a fixed left category column and align every action group."},{"id":"12","kind":"proposal","priority":"P2","area":"Stacking action","observation":"Settings + Nested Confirm compresses two steps into one label.","change":"Use Open settings and add Then open reset confirmation as a caption."},{"id":"13","kind":"proposal","priority":"P3","area":"Stacking visualization","observation":"The row has no visual indication of two dialog layers.","change":"Add a small two-layer thumbnail beside the launcher."},{"id":"14","kind":"proposal","priority":"P2","area":"Blocking category","observation":"Blocking does not say what is being tested.","change":"Rename it Background input blocking test."},{"id":"15","kind":"proposal","priority":"P2","area":"Background Button","observation":"The label does not tell the user to compare its count with a modal open.","change":"Add an instruction explaining the intended click-count experiment."},{"id":"16","kind":"proposal","priority":"P2","area":"Clicks counter","observation":"Clicks: 0 is left-aligned in an isolated dark rectangle.","change":"Use a compact Background clicks badge adjacent to the button."},{"id":"17","kind":"proposal","priority":"P2","area":"Results strip","observation":"Confirm: Pending, FYI: Pending, OK:0, and X:0 run together.","change":"Use separate labeled result fields."},{"id":"18","kind":"proposal","priority":"P2","area":"FYI result name","observation":"FYI does not match the visible Notice launcher.","change":"Use the same name in launcher and result display."},{"id":"19","kind":"proposal","priority":"P2","area":"OK and X counters","observation":"The counters have no description of what they count.","change":"Label them Acknowledged and Dismissed or the actual events."},{"id":"20","kind":"proposal","priority":"P2","area":"Pending state","observation":"Pending suggests an active request although no dialog is open.","change":"Use Not opened for untouched examples if accurate."},{"id":"21","kind":"proposal","priority":"P2","area":"Default capture","observation":"The screenshot shows no actual dialog specimen.","change":"Add a labeled static preview alongside the launchers or capture a complementary open state."},{"id":"22","kind":"proposal","priority":"P3","area":"Wide empty rows","observation":"Each row extends far beyond its controls.","change":"Use the spare width for short expected-behavior captions."},{"id":"23","kind":"proposal","priority":"P3","area":"Vertical whitespace","observation":"Large black gaps separate identical launcher panels.","change":"Tighten section spacing to create one coherent gallery."},{"id":"24","kind":"proposal","priority":"P3","area":"Results association","observation":"The status strip is detached from the launchers that populate it.","change":"Add matching labels or small result badges beside each relevant launcher."},{"id":"25","kind":"proposal","priority":"P3","area":"Reset experiment","observation":"The page has no visible way to restore result counters.","change":"Add a compact Reset results action in the result strip."}],"sha256":"21f847d8bbbcf7a6c3270902928c1d535a7e57e8ee039f9b3497731e45b627d1","has_mock":false,"reference":null,"legacy":[{"id":"modals","screen":"modals","baseline":"baseline_screenshots/modals.png","current":"screenshot-baselines/screens/modals_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Current capture removes Simple Modal focus outline. Both show the launcher rather than an open dialog. Neither capture establishes the appearance or usability of open and stacked modals.","sha256":"2eaa4cf1d33eb0d86398143458606dc38464d47fb3f9ab57364f92c285715e18","additional_findings":[]}]},{"id":"multiline_text_lab","baseline":"screenshot-baselines/screens/multiline_text_lab_720p.png","summary":"The blocks intentionally compare hard breaks, wrapping, styled runs, preserved blank lines, and resize-derived height. Preserve the text and geometry under test; improve external labels and comparison aids.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Title","observation":"Multi-line Text Lab does not state the success criterion.","change":"Add Text and measured bounds should agree as a subtitle."},{"id":"02","kind":"proposal","priority":"P2","area":"Case captions","observation":"Small handwritten captions are difficult to scan.","change":"Use a larger neutral caption face outside the test boxes."},{"id":"03","kind":"proposal","priority":"P2","area":"Hard-break terminology","observation":"The first two captions use a literal newline escape without a plain-language label.","change":"Label them Explicit line breaks and retain the escape in metadata."},{"id":"04","kind":"proposal","priority":"P2","area":"Auto-fit sample","observation":"Auto-fit size gives no rendered font size.","change":"Add the resulting font size in an external value label."},{"id":"05","kind":"proposal","priority":"P2","area":"Fixed-font sample","observation":"font_size 18 mixes API syntax with human-facing metadata.","change":"Show Fixed font size · 18 px."},{"id":"06","kind":"proposal","priority":"P3","area":"Hard-break comparison","observation":"The two top samples have no shared group title.","change":"Add Same text, different sizing modes above the pair."},{"id":"07","kind":"proposal","priority":"P2","area":"Fixed-wrap dimensions","observation":"280x110 uses cramped dimension formatting.","change":"Show Width 280 px · Height 110 px in the caption."},{"id":"08","kind":"proposal","priority":"P2","area":"Self-sizing label","observation":"Dim::Text appears without explanation.","change":"Use Content-derived height with the API name in smaller text."},{"id":"09","kind":"proposal","priority":"P3","area":"Wrapped-line counts","observation":"The fixed and self-sized samples show three lines without a line-count label.","change":"Add external Rendered lines: 3 values."},{"id":"10","kind":"proposal","priority":"P3","area":"Self-sized bounds","observation":"The short right box ends close to its final line.","change":"Add an external measured-height guide for easier inspection of the intended fit."},{"id":"11","kind":"proposal","priority":"P2","area":"Styled-run legend","observation":"Red removed, green added, and gray context text have no external legend.","change":"Add a small diff-color key outside the sample."},{"id":"12","kind":"proposal","priority":"P3","area":"Styled-run font","observation":"The code-like diff sample uses the same handwritten face as prose.","change":"Add a monospaced companion specimen while preserving the existing test."},{"id":"13","kind":"proposal","priority":"P2","area":"Blank-line caption","observation":"The preserved blank-line explanation uses tiny escape notation.","change":"Label it Two line breaks preserve one blank line."},{"id":"14","kind":"proposal","priority":"P3","area":"Blank-line measurement","observation":"The gap between above and below is not quantified.","change":"Add a faint external line-height bracket beside the blank line."},{"id":"15","kind":"proposal","priority":"P2","area":"Resize instruction","observation":"Drag the corner handle appears in small text above the panel.","change":"Increase the instruction and show a small resize-arrow glyph."},{"id":"16","kind":"proposal","priority":"P2","area":"Resize handle","observation":"The cyan rounded square looks like a generic button.","change":"Add diagonal grip marks inside the existing handle bounds."},{"id":"17","kind":"proposal","priority":"P2","area":"Dynamic dimensions","observation":"300 × 120 appears in parentheses inside the instruction.","change":"Show Width and Height as separate live value badges."},{"id":"18","kind":"proposal","priority":"P2","area":"Comparison distance","observation":"The same-width green sample sits far to the right of the draggable panel.","change":"Bring its explanatory caption closer or connect the two with a labeled comparison line."},{"id":"19","kind":"proposal","priority":"P3","area":"Comparison alignment","observation":"The draggable and content-height samples share a top edge without an explicit guide.","change":"Add a faint alignment guide outside their bounds."},{"id":"20","kind":"proposal","priority":"P3","area":"Green sample meaning","observation":"Only the right sample uses green, without a color key.","change":"Label green as the content-derived-height reference."},{"id":"21","kind":"proposal","priority":"P2","area":"Diagnostic footer","observation":"Mouse, handle, hot, held, and drags values are tiny at the bottom edge.","change":"Move them into a readable diagnostic strip with bottom padding."},{"id":"22","kind":"proposal","priority":"P2","area":"Boolean diagnostics","observation":"hot=n and held=n require decoding.","change":"Display Hot: No and Dragging: No."},{"id":"23","kind":"proposal","priority":"P2","area":"Handle geometry diagnostic","observation":"320,612 28x28 combines position and size without column labels.","change":"Separate X, Y, Width, and Height fields."},{"id":"24","kind":"proposal","priority":"P3","area":"Case identification","observation":"The eight specimens have no stable case numbers.","change":"Number the examples to support visual-regression discussions."},{"id":"25","kind":"proposal","priority":"P3","area":"Right upper empty space","observation":"The upper-right region is unused.","change":"Place a compact expected line-count and sizing-mode summary there."}],"sha256":"a62fba35cf889378fbf68a9fd23b65af5de6e88e289e57420fb6b247866dfaa2","has_mock":false,"reference":null,"legacy":[]},{"id":"navigation_bar_demo","baseline":"screenshot-baselines/screens/navigation_bar_demo_720p.png","summary":"Three legible cycle selectors are under-explained. Sixteen distinct proposals are defensible for this small resting-state fixture; no wraparound or keyboard failure is inferred.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Title","observation":"Navigation Bar Component Showcase is a long technical heading.","change":"Use Cycle selectors with the component name in a subtitle."},{"id":"02","kind":"proposal","priority":"P2","area":"Settings category count","observation":"Graphics appears without the total number of categories.","change":"Add a current-position value such as 1 of N."},{"id":"03","kind":"proposal","priority":"P2","area":"Game mode count","observation":"Arcade gives no clue to the other available modes.","change":"Add an option count or short adjacent option preview."},{"id":"04","kind":"proposal","priority":"P2","area":"Level position","observation":"The caption says 6 options while the bar says Level 1.","change":"Show Level 1 of 6 inside the selector."},{"id":"05","kind":"proposal","priority":"P2","area":"Arrow grouping","observation":"Chevrons sit far from their centered values.","change":"Use bounded arrow buttons around a more compact value field."},{"id":"06","kind":"proposal","priority":"P2","area":"Arrow affordance","observation":"Chevrons share the same blue surface as the value.","change":"Add subtle separators around the arrow buttons."},{"id":"07","kind":"proposal","priority":"P2","area":"Section labels","observation":"Settings Categories and Game Mode Selector are small and muted.","change":"Increase label contrast and use consistent naming."},{"id":"08","kind":"proposal","priority":"P3","area":"Graphics context","observation":"No selected-category result appears below Graphics.","change":"Add a Selected category: Graphics result line."},{"id":"09","kind":"proposal","priority":"P3","area":"Arcade meaning","observation":"The mode name has no description.","change":"Add a short description below the selector."},{"id":"10","kind":"proposal","priority":"P3","area":"Level identity","observation":"Level 1 is generic despite the wide bar.","change":"Add a sample level name or thumbnail."},{"id":"11","kind":"proposal","priority":"P2","area":"Instruction","observation":"No visible text explains the selectors.","change":"Add Use the arrows to cycle through each example."},{"id":"12","kind":"proposal","priority":"P3","area":"Boundary behavior","observation":"The screenshot does not state whether options wrap.","change":"Add Wraps or Stops at ends matching the configuration."},{"id":"13","kind":"proposal","priority":"P2","area":"Control widths","observation":"Wide bars contain only a short value and chevrons.","change":"Reduce their widths for easier visual association."},{"id":"14","kind":"proposal","priority":"P3","area":"Top empty area","observation":"A large blank navy area precedes the title.","change":"Move the group upward or center the whole group vertically."},{"id":"15","kind":"proposal","priority":"P3","area":"Right empty area","observation":"The controls are left-shifted inside the panel.","change":"Center them with equal side margins."},{"id":"16","kind":"proposal","priority":"P3","area":"Value typography","observation":"Graphics, Arcade, and Level 1 use handwritten text.","change":"Use a clearer value face while retaining informal headings."}],"sha256":"42d980e0283b6ee8e8fbe4d519f0bab26f163015c0ad04c7aaf2614b570d6de1","has_mock":false,"reference":null,"legacy":[{"id":"navigation_bar_demo","screen":"navigation_bar_demo","baseline":"baseline_screenshots/navigation_bar_demo.png","current":"screenshot-baselines/screens/navigation_bar_demo_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Current capture removes first left-arrow focus outline. The three blue selector bars and large surrounding margins are unchanged. Current review applies to visible selector composition.","sha256":"1453db0dbcfc353e5062ef66bfd6e1f12798929d1bbf2bca6c8353b45c3e1b47","additional_findings":[]}]},{"id":"neon_strike","baseline":"screenshot-baselines/screens/neon_strike_720p.png","summary":"The tactical HUD intentionally leaves the center clear. Improve peripheral legibility and the grouping of map, health, ammunition, objective, and equipment data.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Grenade count","observation":"The grenade count sits outside its tile while the knife count sits inside; the web mock repeats this asymmetry.","change":"Place both counts at the same lower-right inset inside their tiles."},{"id":"02","kind":"proposal","priority":"P2","area":"Equipment key hints","observation":"G and V are tiny in the tile corners.","change":"Increase their size and use compact keycaps."},{"id":"03","kind":"proposal","priority":"P2","area":"Equipment icons","observation":"Grenade and knife line weights differ from the heavier streak icons.","change":"Normalize optical icon weight within the HUD."},{"id":"04","kind":"proposal","priority":"P2","area":"Selected equipment","observation":"A thin gold outline is the grenade's only selection cue.","change":"Add a small selected marker or brighter bottom rule."},{"id":"05","kind":"proposal","priority":"P2","area":"Ammo readout","observation":"35/210 gives magazine and reserve counts similar emphasis.","change":"Emphasize 35 and reduce reserve-count weight."},{"id":"06","kind":"proposal","priority":"P2","area":"Weapon identity","observation":"The ammo readout has no weapon name.","change":"Add a small current-weapon label above it."},{"id":"07","kind":"proposal","priority":"P2","area":"Health label","observation":"80 HEALTH is tiny beside a large skull tile.","change":"Increase health text and reduce skull emphasis."},{"id":"08","kind":"proposal","priority":"P2","area":"Armor label","observation":"45% ARMOR is extremely small below two thin bars.","change":"Increase text and place it beside its own bar."},{"id":"09","kind":"proposal","priority":"P2","area":"Health and armor bars","observation":"Both bars use similar cyan fills without direct labels.","change":"Give each bar a directly adjacent label or icon."},{"id":"10","kind":"proposal","priority":"P2","area":"Health scale","observation":"80 is shown without a maximum.","change":"Show 80/100 or the actual maximum."},{"id":"11","kind":"proposal","priority":"P2","area":"Map caption","observation":"SECTOR 7B and GRID 042 are tiny along the bottom edge.","change":"Move them into a readable map footer."},{"id":"12","kind":"proposal","priority":"P2","area":"Map markers","observation":"Cyan rings appear without a legend.","change":"Add a compact ally-marker key near the map."},{"id":"13","kind":"proposal","priority":"P2","area":"Objective marker","observation":"B is small inside a thin amber region.","change":"Increase its contrast and label its objective role."},{"id":"14","kind":"proposal","priority":"P3","area":"Player direction","observation":"The white triangle overlaps a tan view cone.","change":"Strengthen the triangle outline and soften the cone."},{"id":"15","kind":"proposal","priority":"P2","area":"Killstreak header","observation":"Three squares follow KILLSTREAK without explanation.","change":"Label them as charge/progress or use a clearer segmented meter."},{"id":"16","kind":"proposal","priority":"P2","area":"Streak hotkeys","observation":"1 through 4 are tiny outside the ability tiles.","change":"Use readable, consistently aligned key badges."},{"id":"17","kind":"proposal","priority":"P3","area":"Gear decorations","observation":"A gear repeats beside each ability without explanation.","change":"Remove repeated gears or label their configuration role."},{"id":"18","kind":"proposal","priority":"P2","area":"Ability labels","observation":"UAV, RECON, SHIELD, and STRIKE are tiny.","change":"Increase their size and reduce tracking."},{"id":"19","kind":"proposal","priority":"P2","area":"Strike icon","observation":"A large X represents STRIKE.","change":"Use a recognizable strike symbol distinct from close or cancel."},{"id":"20","kind":"proposal","priority":"P2","area":"Objective banner","observation":"SECURE OBJECTIVE B sits tight against the right edge.","change":"Add trailing padding inside a stable safe area."},{"id":"21","kind":"proposal","priority":"P2","area":"Score shield","observation":"An unlabeled shield follows SCORE: 15,000.","change":"Separate score from protection status or explain the symbol."},{"id":"22","kind":"proposal","priority":"P2","area":"Kill feed","observation":"Three dense text lines sit beneath the compass.","change":"Distinguish actor, action, and target and increase line spacing."},{"id":"23","kind":"proposal","priority":"P3","area":"Repeated alert","observation":"Alpha_Six Under fire appears in both feed and voice area.","change":"Differentiate radio activity from event history with labels."},{"id":"24","kind":"proposal","priority":"P2","area":"Compass labels","observation":"Bearing values and direction letters are very small.","change":"Increase compass text while retaining thin guide lines."},{"id":"25","kind":"proposal","priority":"P3","area":"Background flecks","observation":"Gold flecks remain visible behind HUD text.","change":"Reduce their density behind peripheral readouts."}],"sha256":"80a906841abee13c2e6b8e27bbbf39c5a7d355ef9a9f3fe406760ad8fd2ff89c","has_mock":true,"reference":"inspiration/example_shooter_game.png","legacy":[]},{"id":"nine_slice_borders","baseline":"screenshot-baselines/screens/nine_slice_borders_720p.png","summary":"Border shapes, colors, and transparency variants are intentional. Improve parameter labels, transparency framing, and specimen spacing.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Title frame","observation":"The full-width white frame outweighs small border specimens.","change":"Use a simpler heading treatment."},{"id":"02","kind":"proposal","priority":"P2","area":"Panel names","observation":"Simple, Ornate, and Heavy omit source identifiers.","change":"Add texture IDs beneath the samples."},{"id":"03","kind":"proposal","priority":"P3","area":"Slice parameters","observation":"The first row does not state corner-slice dimensions.","change":"Add a shared slice-size caption."},{"id":"04","kind":"proposal","priority":"P2","area":"Corner details","observation":"Ornate and Double Line corner details are small.","change":"Add a magnified corner inset beside the row."},{"id":"05","kind":"proposal","priority":"P3","area":"Thick sample","observation":"Thick gives no border measurement.","change":"Show its border or slice width externally."},{"id":"06","kind":"proposal","priority":"P2","area":"Decorative and Heavy","observation":"Broad gold patterns reduce the usable white center.","change":"Add optional content-inset guides for comparison."},{"id":"07","kind":"proposal","priority":"P2","area":"Border-only grouping","observation":"Border A–C have dark centers while Trans A–B have white backing.","change":"Separate the transparency modes with subgroup captions."},{"id":"08","kind":"proposal","priority":"P2","area":"Border A B C names","observation":"Letter names do not explain corner differences.","change":"Add texture names or short corner descriptions."},{"id":"09","kind":"proposal","priority":"P2","area":"Trans labels","observation":"Trans abbreviates the tested behavior.","change":"Spell out Transparent border in external captions."},{"id":"10","kind":"proposal","priority":"P3","area":"Transparency proof","observation":"Flat backgrounds make transparent regions hard to identify.","change":"Add checkerboard companion backgrounds."},{"id":"11","kind":"proposal","priority":"P2","area":"Size metadata","observation":"Small, Medium, and Large have no dimensions.","change":"Add width × height captions."},{"id":"12","kind":"proposal","priority":"P3","area":"Size isolation","observation":"Different styles appear within the stretching row.","change":"Add a same-source comparison across every size."},{"id":"13","kind":"proposal","priority":"P2","area":"Wide panel copy","observation":"Good for menus is packed inside the specimen label.","change":"Move usage advice below the frame."},{"id":"14","kind":"proposal","priority":"P2","area":"Tall alignment","observation":"Tall begins above the other size samples.","change":"Use a shared caption baseline or consistent sample framing."},{"id":"15","kind":"proposal","priority":"P3","area":"Tall caption","observation":"Tall uses much smaller type than neighboring names.","change":"Use uniform external caption sizes."},{"id":"16","kind":"proposal","priority":"P2","area":"Double-width grouping","observation":"Border width and tint share one heading.","change":"Add separate Width and Tint subgroup labels."},{"id":"17","kind":"proposal","priority":"P2","area":"Double-width spacing","observation":"Thick decorations nearly meet adjacent samples.","change":"Increase gaps around these specimens."},{"id":"18","kind":"proposal","priority":"P3","area":"Double metadata","observation":"Double omits its actual slice size.","change":"Caption the 32-pixel slice parameter."},{"id":"19","kind":"proposal","priority":"P3","area":"Tint values","observation":"Gold, Blue, Red, and Green are names without values.","change":"Add exact tint values below them."},{"id":"20","kind":"proposal","priority":"P2","area":"Tint text adaptation","observation":"Text colors vary independently of border tint.","change":"Explain that text contrast adapts separately."},{"id":"21","kind":"proposal","priority":"P2","area":"Interactive button","observation":"Click Me! does not say what response to inspect.","change":"Add an external expected-response caption."},{"id":"22","kind":"proposal","priority":"P2","area":"Dialog specimen","observation":"The small corners-stay-crisp sentence is buried in a large pale box.","change":"Add a clear dialog title and external border caption."},{"id":"23","kind":"proposal","priority":"P2","area":"Nested labels","observation":"Inner and Panel do not distinguish the two children.","change":"Use Gold child and Blue child."},{"id":"24","kind":"proposal","priority":"P3","area":"Nested parent border","observation":"The pale outer border blends with its fill.","change":"Add a companion contrast backdrop without changing the texture."},{"id":"25","kind":"proposal","priority":"P3","area":"Bottom margin","observation":"The last examples end close to the viewport edge.","change":"Add a consistent gallery bottom margin."}],"sha256":"1970c9e49fafdb73a6fb529e47c4d7a75c4ee34bdc9e79fadb1c00a40459106a","has_mock":false,"reference":null,"legacy":[]},{"id":"offsite_backup","baseline":"screenshot-baselines/screens/offsite_backup_720p.png","summary":"The backup overview has a coherent two-column structure. Improve status readability and reconcile total progress with folder progress before treating it as a trustworthy product screen.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"Summary versus folders","observation":"493 GB uploaded is reported, but visible folder sizes and percentages imply about 242 GB uploaded.","change":"Derive totals and ring progress from the same folder data or label differing scopes explicitly."},{"id":"02","kind":"proposal","priority":"P2","area":"Backup ring","observation":"63% has a tiny COMPLETE caption.","change":"Increase the caption and center the value group."},{"id":"03","kind":"proposal","priority":"P2","area":"Pause backup","observation":"Pause backup is tiny and pale.","change":"Use a readable secondary button with a pause icon."},{"id":"04","kind":"proposal","priority":"P2","area":"Transfer speed","observation":"24.8 MB/s is faint in the transfer row.","change":"Increase contrast and emphasize the value."},{"id":"05","kind":"proposal","priority":"P2","area":"Remaining time","observation":"About 3 hours remaining is low-contrast metadata.","change":"Give the estimate a stronger value treatment."},{"id":"06","kind":"proposal","priority":"P2","area":"Healthy badge","observation":"Healthy has tiny text and a square marker.","change":"Use a recognizable status dot and readable text."},{"id":"07","kind":"proposal","priority":"P2","area":"Plan subtitle","observation":"Personal Backup - 2 TB plan is very small.","change":"Increase readability and use a centered-dot separator."},{"id":"08","kind":"proposal","priority":"P2","area":"Folder table headings","observation":"FOLDERS is the only heading above progress, state, and size columns.","change":"Add Progress and Size headings."},{"id":"09","kind":"proposal","priority":"P2","area":"Completed state","observation":"done is plain lowercase text beside green bars.","change":"Use Done with a check icon consistently."},{"id":"10","kind":"proposal","priority":"P2","area":"Uploading state","observation":"Photos, Music, and Archive have no activity distinction.","change":"Mark the active upload and identify queued folders if applicable."},{"id":"11","kind":"proposal","priority":"P2","area":"Folder sizes","observation":"Size values are tiny and pale.","change":"Increase their size and retain right alignment."},{"id":"12","kind":"proposal","priority":"P2","area":"Rescan","observation":"Rescan is tiny red text.","change":"Use a readable refresh action with an icon."},{"id":"13","kind":"proposal","priority":"P2","area":"Schedule selectors","observation":"Every 4 hours and 1 year lack chevrons or strong boundaries.","change":"Add visible select affordances."},{"id":"14","kind":"proposal","priority":"P2","area":"Schedule labels","observation":"Run backup and Keep file versions are faint.","change":"Increase contrast and align both rows."},{"id":"15","kind":"proposal","priority":"P2","area":"Bandwidth meaning","observation":"62% does not identify the full-speed reference.","change":"Pair it directly with the actual 24.8 MB/s cap."},{"id":"16","kind":"proposal","priority":"P2","area":"Bandwidth thumb","observation":"The small coral thumb blends into the fill.","change":"Add a contrasting border and larger grip."},{"id":"17","kind":"proposal","priority":"P2","area":"Slider endpoints","observation":"Slower and Faster are extremely small.","change":"Use readable endpoint labels or measured speeds."},{"id":"18","kind":"proposal","priority":"P2","area":"Battery checkbox","observation":"The checked state is a solid red square without a check.","change":"Render a clear checkmark inside it."},{"id":"19","kind":"proposal","priority":"P2","area":"External-drive checkbox","observation":"The white unchecked square blends into the panel.","change":"Add a visible outline."},{"id":"20","kind":"proposal","priority":"P2","area":"Checkbox labels","observation":"Both settings use tiny text.","change":"Increase label size and row spacing."},{"id":"21","kind":"proposal","priority":"P2","area":"Storage values","observation":"787 GB of 2 TB has weak emphasis.","change":"Strengthen the values and add percent used."},{"id":"22","kind":"proposal","priority":"P2","area":"Manage account","observation":"The link is tiny coral text.","change":"Increase readability and add a navigation cue."},{"id":"23","kind":"proposal","priority":"P2","area":"Last completed backup","observation":"The success line is faint beneath the folders.","change":"Increase contrast and add a checkmark."},{"id":"24","kind":"proposal","priority":"P2","area":"Security footer","observation":"A green square precedes the encryption statement.","change":"Use a recognizable lock and readable text."},{"id":"25","kind":"proposal","priority":"P2","area":"Help button","observation":"The question mark nearly disappears in its white square.","change":"Increase icon contrast and button size."}],"sha256":"64a26a3f494b615b0ef65c4143eb4a63f85aad21adc40294e5bb0c16714382e9","has_mock":true,"reference":null,"legacy":[]},{"id":"pagination","baseline":"screenshot-baselines/screens/pagination_720p.png","summary":"The fixture reuses buttons for pages, difficulty, and named options. Twenty distinct proposals clarify the roles and preserve boundary-state examples.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Title","observation":"Pagination Component Showcase is long and technical.","change":"Use Pagination and option selectors with a short subtitle."},{"id":"02","kind":"proposal","priority":"P2","area":"Page labels","observation":"Page repeats in five wide buttons.","change":"Use compact numeric buttons under a shared Pages label."},{"id":"03","kind":"proposal","priority":"P2","area":"Current page","observation":"Page 1 relies on red fill.","change":"Add a current-page marker or stronger label weight."},{"id":"04","kind":"proposal","priority":"P2","area":"Disabled arrow","observation":"The first previous arrow is very faint.","change":"Keep it disabled but identifiable and caption its boundary state."},{"id":"05","kind":"proposal","priority":"P2","area":"Chevron style","observation":"Thin handwritten-looking arrows differ from geometric control shapes.","change":"Use consistent centered geometric chevrons."},{"id":"06","kind":"proposal","priority":"P2","area":"Page result","observation":"Selected: Page 1 repeats the button without total context.","change":"Show Page 1 of 5."},{"id":"07","kind":"proposal","priority":"P2","area":"Page content","observation":"No sample content connects to the paginator.","change":"Add a small preview reflecting the selected page."},{"id":"08","kind":"proposal","priority":"P2","area":"Difficulty role","observation":"The difficulty group appears under Pagination without explaining the reuse.","change":"Label it Single-choice selector using the same control."},{"id":"09","kind":"proposal","priority":"P2","area":"Difficulty meaning","observation":"Easy through Expert have no descriptions.","change":"Add short descriptions or an intensity scale."},{"id":"10","kind":"proposal","priority":"P2","area":"Selected difficulty","observation":"Medium uses only red fill plus a distant result.","change":"Add an in-control marker matching current-page selection."},{"id":"11","kind":"proposal","priority":"P2","area":"Named color options","observation":"All color names use the same cyan button fill.","change":"State that they are named options or add small swatches."},{"id":"12","kind":"proposal","priority":"P2","area":"Blue selection","observation":"The Blue option has a red selected background.","change":"Use a neutral selection outline to avoid conflicting color meanings."},{"id":"13","kind":"proposal","priority":"P2","area":"Header affordance","observation":"Broad cyan headings resemble cyan option buttons.","change":"Use a quieter noninteractive heading treatment."},{"id":"14","kind":"proposal","priority":"P2","area":"Header widths","observation":"Headings span the panel while controls occupy about half.","change":"Fit frames to controls or use spare width for explanations."},{"id":"15","kind":"proposal","priority":"P2","area":"Status spacing","observation":"Result captions and section gaps lack a consistent rhythm.","change":"Use shared control-to-result and section spacing."},{"id":"16","kind":"proposal","priority":"P3","area":"Boundary behavior","observation":"Arrow wrap behavior is unstated.","change":"Add Stops at first and last option if that matches configuration."},{"id":"17","kind":"proposal","priority":"P3","area":"Counts","observation":"Only difficulty and named options state option counts.","change":"Use consistent counts across all three sections."},{"id":"18","kind":"proposal","priority":"P2","area":"Text tracking","observation":"Widely spaced labels consume unnecessary width.","change":"Reduce tracking and use a clearer option face."},{"id":"19","kind":"proposal","priority":"P3","area":"Outer padding","observation":"The title area and bottom blank region make the panel sparse.","change":"Tighten decorative outer spacing."},{"id":"20","kind":"proposal","priority":"P3","area":"Independent state","observation":"Three selected states are shown without explaining independence.","change":"Add Each row keeps its own selection below the subtitle."}],"sha256":"4df52ecb438e854f893c7fbac734877bdaee6303e295c37dd2011deabb015c97","has_mock":false,"reference":null,"legacy":[{"id":"pagination","screen":"pagination","baseline":"baseline_screenshots/pagination.png","current":"screenshot-baselines/screens/pagination_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Current capture removes the first back-arrow outline. Selected Page 1, Medium and Blue remain magenta. Disabled-back-arrow and selection recommendations require preserving the different semantic states.","sha256":"9fe639a5beb2696c332da6405b4e1aeffa055bbab91178e17a2fa26f01faa3e1","additional_findings":[]}]},{"id":"parcel_corps_settings","baseline":"screenshot-baselines/screens/parcel_corps_settings_720p.png","summary":"The phone settings overlay follows the mock composition. Improve phone-control clarity, reduce HUD competition, and preserve the illustrated courier setting.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Phone title","observation":"Settings is separated from the first row by a large blank gap.","change":"Tighten the gap to give the lower controls more room."},{"id":"02","kind":"proposal","priority":"P2","area":"Text Language value","observation":"King's English is small and close to the right border.","change":"Increase value readability and trailing padding."},{"id":"03","kind":"proposal","priority":"P2","area":"Category symbols","observation":"T, D, X, S, and asterisks form an unexplained icon column.","change":"Use recognizable language, display, motion, sync, and audio symbols."},{"id":"04","kind":"proposal","priority":"P2","area":"Category color meaning","observation":"Green, orange, red, and blue badges have no key.","change":"Group rows by category or add a compact category legend."},{"id":"05","kind":"proposal","priority":"P2","area":"Resolution value","observation":"2560 x 1440 is small in a dense row.","change":"Use a clear multiplication sign and a stable value column."},{"id":"06","kind":"proposal","priority":"P2","area":"Full Screen label","observation":"Full Screen differs from the common single-word setting name.","change":"Use Fullscreen consistently."},{"id":"07","kind":"proposal","priority":"P2","area":"MSAA meaning","observation":"MSAA is shown without an explanation.","change":"Add an Anti-aliasing subtitle or expand the label."},{"id":"08","kind":"proposal","priority":"P2","area":"MSAA arrows","observation":"Small angle-bracket characters fill large dark buttons.","change":"Use centered geometric chevrons and equal button insets."},{"id":"09","kind":"proposal","priority":"P2","area":"Quality value","observation":"High is squeezed between the two arrow buttons.","change":"Give the value a fixed-width centered region."},{"id":"10","kind":"proposal","priority":"P2","area":"Toggle states","observation":"Several vivid green switches have no explicit On text.","change":"Add a consistent state label where space allows."},{"id":"11","kind":"proposal","priority":"P2","area":"Motion Blur icon","observation":"The red X badge resembles an error despite the toggle being on.","change":"Use a motion-blur symbol rather than an error-like X."},{"id":"12","kind":"proposal","priority":"P2","area":"VSync naming","observation":"VSync lacks the spacing and casing used elsewhere in settings.","change":"Use V-sync or Vertical sync consistently."},{"id":"13","kind":"proposal","priority":"P2","area":"Settings open text","observation":"Settings open interrupts the list between VSync and audio controls.","change":"Move this status into a footer or replace it with an Audio section heading."},{"id":"14","kind":"proposal","priority":"P2","area":"Audio sliders","observation":"Thin tracks and small white thumbs sit in short rows.","change":"Increase track and thumb readability while keeping compact row heights."},{"id":"15","kind":"proposal","priority":"P2","area":"Audio values","observation":"Audio Volume and Music Volume have no numeric percentages.","change":"Show the current percentage beside each slider."},{"id":"16","kind":"proposal","priority":"P2","area":"Bottom controls","observation":"Music Volume sits close to the phone's lower inner edge.","change":"Add bottom padding or a visible scroll boundary."},{"id":"17","kind":"proposal","priority":"P2","area":"Phone close path","observation":"The phone shows Settings without a visible back or close control.","change":"Add a back chevron near the title if the settings flow supports it."},{"id":"18","kind":"proposal","priority":"P3","area":"Phone status bar","observation":"A blank white pill and green battery-like shape replace the mock's recognizable signal and battery indicators.","change":"Use recognizable battery and signal symbols with consistent spacing."},{"id":"19","kind":"proposal","priority":"P2","area":"Objective copy","observation":"The business sign-up objective repeats twice in the blue panel.","change":"Combine it into one objective with a distinct completion state."},{"id":"20","kind":"proposal","priority":"P2","area":"Objective marker","observation":"The small Lv0 badge overlaps the objective's last line.","change":"Place the level badge in a dedicated corner outside the text block."},{"id":"21","kind":"proposal","priority":"P2","area":"Live-chat text","observation":"Tiny bright usernames and messages compete with settings.","change":"Reduce chat prominence while the phone is open and keep message text legible."},{"id":"22","kind":"proposal","priority":"P3","area":"Live header","observation":"08, 10, and EDDCOATES form an unexplained compact cluster.","change":"Add clear viewer/chat icons or labels around the counts."},{"id":"23","kind":"proposal","priority":"P2","area":"Speed display","observation":"009 and M/h appear in a small panel at the lower-right edge.","change":"Use a conventional speed unit and a consistent safe-area inset."},{"id":"24","kind":"proposal","priority":"P3","area":"Background rider","observation":"The rider's simplified face and hands are hard to distinguish against the clothing.","change":"Clarify the silhouette and face details without increasing background contrast."},{"id":"25","kind":"proposal","priority":"P3","area":"Overlay competition","observation":"The phone, objective panel, live chat, and speed panel all remain prominent.","change":"Dim secondary HUD elements while settings has visual priority."}],"sha256":"9f13c3a494f26fed9e4769236bd9878efab854a8e06a193827dfbe680e00fae0","has_mock":true,"reference":"inspiration/example_parcel_coro.jpg","legacy":[]},{"id":"pinch_zoom_lab","baseline":"screenshot-baselines/screens/pinch_zoom_lab_720p.png","summary":"The resting square demonstrates 1.00× scale with zero events. Fifteen proposals improve gesture instructions and diagnostic clarity; no unsupported-gesture or input failure is inferred.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Title","observation":"Pinch Zoom - trackpad magnification mixes title and explanation.","change":"Use Pinch zoom with a separate gesture instruction."},{"id":"02","kind":"proposal","priority":"P2","area":"Gesture instruction","observation":"No visible text says how to perform the gesture.","change":"Add Pinch two fingers on the trackpad to resize the square."},{"id":"03","kind":"proposal","priority":"P2","area":"Diagnostic row","observation":"Zoom, events, and pinching state are tiny.","change":"Increase their text size and separate them into labeled fields."},{"id":"04","kind":"proposal","priority":"P2","area":"Scale formatting","observation":"1.00x uses a lowercase x.","change":"Use 1.00× consistently for magnification."},{"id":"05","kind":"proposal","priority":"P2","area":"Square label","observation":"1.00x sits against the square's left edge.","change":"Center the value inside the square or add a consistent inset."},{"id":"06","kind":"proposal","priority":"P3","area":"Reference size","observation":"The square has no fixed-size comparison reference.","change":"Add a faint 1.00× outline behind the scaling sample."},{"id":"07","kind":"proposal","priority":"P3","area":"Dimension metadata","observation":"Only scale is shown, not the resulting square dimensions.","change":"Add Width and Height readouts beside zoom."},{"id":"08","kind":"proposal","priority":"P2","area":"Event counter meaning","observation":"events 0 does not explain what increments it.","change":"Label it Pinch updates received."},{"id":"09","kind":"proposal","priority":"P2","area":"Gesture state","observation":"pinching no is terse and visually indistinct from the counter.","change":"Use a clear Idle or Pinching state badge."},{"id":"10","kind":"proposal","priority":"P2","area":"Build requirement footer","observation":"A long compiler-flags sentence is tiny at the bottom.","change":"Move requirements into a readable Demo prerequisites panel."},{"id":"11","kind":"proposal","priority":"P2","area":"Unsupported ambiguity","observation":"Reads 0 otherwise means no gesture and unavailable support can look the same.","change":"Show a separate Gesture support available/unavailable diagnostic based on capability."},{"id":"12","kind":"proposal","priority":"P3","area":"Technical footer hierarchy","observation":"AppKit and a long feature flag dominate the only supporting explanation.","change":"Keep the user gesture instruction primary and build details secondary."},{"id":"13","kind":"proposal","priority":"P3","area":"Reset reference","observation":"No visible action restores the square to the reference scale.","change":"Add Reset to 1.00× near the scale readout."},{"id":"14","kind":"proposal","priority":"P3","area":"Scale limits","observation":"The screenshot gives no minimum or maximum zoom range.","change":"Add the configured range to the sample metadata."},{"id":"15","kind":"proposal","priority":"P3","area":"Empty space","observation":"A small square occupies the center of a nearly empty canvas.","change":"Use an unobtrusive grid or ruler to make changes in scale easier to judge."}],"sha256":"74d40e1d470b9e8fc4ad2bc5eb7b72acca341f33b0f7f91218ab85468199e1f2","has_mock":false,"reference":null,"legacy":[]},{"id":"popover_lab","baseline":"screenshot-baselines/screens/popover_lab_720p.png","summary":"The Branch panel is intentionally pinned open and placement examples are fixtures. Improve sample labeling and control hierarchy without treating the resting Commit options trigger or focus behavior as broken.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Page title","observation":"The heading is a long sentence combining component name and purpose.","change":"Use Popovers with a separate Anchored panels containing controls subtitle."},{"id":"02","kind":"proposal","priority":"P2","area":"Instruction","observation":"Click a trigger to open its panel appears even though Branch is already open.","change":"Explain that Branch is pinned open for comparison."},{"id":"03","kind":"proposal","priority":"P2","area":"Commit options trigger","observation":"The closed trigger gives no preview of its form contents.","change":"Add a short Amend and sign-off form caption beneath it."},{"id":"04","kind":"proposal","priority":"P2","area":"Branch trigger","observation":"Branch does not identify the current branch.","change":"Show Branch: main or a separate current-branch badge."},{"id":"05","kind":"proposal","priority":"P2","area":"Branch heading","observation":"Switch to is tiny above the four branch buttons.","change":"Increase its size and clarify Switch branch."},{"id":"06","kind":"proposal","priority":"P2","area":"Branch names","observation":"main and release/2.4 use small handwritten text.","change":"Use a readable monospaced face for branch names."},{"id":"07","kind":"proposal","priority":"P2","area":"Current branch","observation":"All four branch rows have identical cyan fills.","change":"Mark the current branch with a check or Current label."},{"id":"08","kind":"proposal","priority":"P2","area":"Branch row padding","observation":"Branch names sit close to the left edges of their pills.","change":"Add consistent horizontal insets."},{"id":"09","kind":"proposal","priority":"P2","area":"Popover anchor relationship","observation":"The panel begins directly below the trigger without a pointer or gap.","change":"Add a small anchor cue or consistent offset that makes ownership clear."},{"id":"10","kind":"proposal","priority":"P2","area":"Explanation heading","observation":"What a popover is for is small within the large dark panel.","change":"Give it a stronger heading size."},{"id":"11","kind":"proposal","priority":"P2","area":"Explanation body","observation":"The body is tiny, widely spaced, and broken into isolated lines.","change":"Use readable body text with paragraph spacing."},{"id":"12","kind":"proposal","priority":"P2","area":"Focus explanation","observation":"Focus landing inside must not close it describes an internal rule.","change":"Rephrase as You can use controls inside without dismissing the panel."},{"id":"13","kind":"proposal","priority":"P3","area":"Menu comparison","observation":"The note mentions menus without showing the difference.","change":"Add a small static menu-versus-form illustration."},{"id":"14","kind":"proposal","priority":"P2","area":"Placement heading","observation":"Placement, and what happens when there is no room is a long low-emphasis line.","change":"Use Placement and edge flipping as a clear section heading."},{"id":"15","kind":"proposal","priority":"P2","area":"Above sample caption","observation":"anchored Above is tiny and left-flush inside its panel.","change":"Use a centered readable caption with consistent inset."},{"id":"16","kind":"proposal","priority":"P2","area":"Right sample caption","observation":"anchored Right touches the panel's left edge.","change":"Add internal padding without changing its anchor placement."},{"id":"17","kind":"proposal","priority":"P2","area":"Left sample caption","observation":"anchored Left sits close to the outlined boundary.","change":"Inset the caption while retaining the diagnostic focus outline."},{"id":"18","kind":"proposal","priority":"P3","area":"Placement direction","observation":"Above, Right, and Left labels require mentally tracking their panels.","change":"Add small directional arrows outside each trigger-panel pair."},{"id":"19","kind":"proposal","priority":"P3","area":"Placement grouping","observation":"The three examples occupy irregular widths and alignments.","change":"Frame each pair within a labeled comparison region without changing its anchor geometry."},{"id":"20","kind":"proposal","priority":"P2","area":"Bottom trigger","observation":"near the bottom is lowercase and differs from the other trigger labels.","change":"Rename it Bottom-edge flip using the shared label style."},{"id":"21","kind":"proposal","priority":"P2","area":"Bottom expected result","observation":"The bottom panel is closed, so its flipping behavior is not visible.","change":"Add a small expected-placement diagram or companion open-state capture."},{"id":"22","kind":"proposal","priority":"P3","area":"Trigger versus panel colors","observation":"Cyan triggers and dark panels lack a shared legend.","change":"Add a compact Trigger / Popover color key."},{"id":"23","kind":"proposal","priority":"P3","area":"Pinned-state identity","observation":"The Branch panel resembles a user-opened panel without stating its fixture role.","change":"Add Pinned example as a small external badge."},{"id":"24","kind":"proposal","priority":"P3","area":"Empty central space","observation":"Broad blank regions separate the upper and lower demonstrations.","change":"Use the space for anchor and fallback-placement guides."},{"id":"25","kind":"proposal","priority":"P2","area":"Result feedback","observation":"The only status text is the initial instruction.","change":"Reserve a labeled Last action line for branch or commit outcomes."}],"sha256":"a477f7db51342b7777f22a5893b51934b900793e8d7ea0b76772cca07238cff3","has_mock":false,"reference":null,"legacy":[]},{"id":"potion_crafting","baseline":"screenshot-baselines/screens/potion_crafting_720p.png","summary":"The parchment workshop composition is coherent. Improve text contrast, ingredient accounting, and the distinction between an active brew and a new brewing action.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Parchment texture","observation":"Fine horizontal lines run directly behind every label.","change":"Reduce texture contrast in text-heavy regions."},{"id":"02","kind":"proposal","priority":"P2","area":"Recipe descriptions","observation":"Restores 30 MP and other effects are small and pale.","change":"Increase effect-text size and contrast."},{"id":"03","kind":"proposal","priority":"P2","area":"Recipe times","observation":"30s to brew and 45s to brew are tiny.","change":"Use readable duration labels with consistent spacing before seconds."},{"id":"04","kind":"proposal","priority":"P2","area":"Selected recipe","observation":"Mana Elixir uses a pale rectangular border with little contrast.","change":"Add a clear selected marker or stronger leading rule."},{"id":"05","kind":"proposal","priority":"P2","area":"Recipe icons","observation":"Small potion icons occupy different visual weights by fill color.","change":"Normalize bottle scale and outline weight across recipes."},{"id":"06","kind":"proposal","priority":"P2","area":"Center subtitle","observation":"The remedy for an exhausted mind is faint under Mana Elixir.","change":"Increase contrast and keep it subordinate to the recipe title."},{"id":"07","kind":"proposal","priority":"P2","area":"Brew state","observation":"65% brewed appears above a button still labeled Brew potion.","change":"Label the active state Brewing and make the action reflect the current process."},{"id":"08","kind":"proposal","priority":"P2","area":"Progress value","observation":"65% brewed is tiny below a thin low-contrast bar.","change":"Increase value size and give the fill stronger separation from the track."},{"id":"09","kind":"proposal","priority":"P2","area":"Progress placement","observation":"A thick wooden shelf is more prominent than the progress bar beneath it.","change":"Reduce shelf emphasis or increase progress-bar prominence."},{"id":"10","kind":"proposal","priority":"P2","area":"Required ingredient counts","observation":"Sea Salt x 3 and Star Dust x 1 are small below the illustration.","change":"Use readable names and multiplication signs."},{"id":"11","kind":"proposal","priority":"P2","area":"Availability states","observation":"Available is pale green without the mock's clear checkmark.","change":"Add a check icon and stronger text contrast."},{"id":"12","kind":"proposal","priority":"P2","area":"Inventory relation","observation":"Required counts and inventory counts are far apart without a shared notation.","change":"Show Required 3 / Owned 12 and Required 1 / Owned 1 beside the recipe."},{"id":"13","kind":"proposal","priority":"P2","area":"Last Star Dust","observation":"The recipe requires the entire visible Star Dust stock of one.","change":"Add a small After brew: 0 note to make the inventory consequence visible."},{"id":"14","kind":"proposal","priority":"P2","area":"Brew action contrast","observation":"The olive button blends with the brown parchment palette.","change":"Increase text and border contrast while keeping the muted aesthetic."},{"id":"15","kind":"proposal","priority":"P2","area":"Brew duration footer","observation":"45 seconds / Produces 1 potion is tiny near the bottom edge.","change":"Move it closer to the action and use a readable size."},{"id":"16","kind":"proposal","priority":"P2","area":"Ingredient tile names","observation":"Moonpetal and Fire Root use small centered serif labels.","change":"Increase label size and maintain equal bottom padding."},{"id":"17","kind":"proposal","priority":"P2","area":"Inventory quantity placement","observation":"x 5, x 3, and other quantities sit tiny in tile corners.","change":"Use consistent compact quantity badges."},{"id":"18","kind":"proposal","priority":"P3","area":"Herb silhouettes","observation":"Moonpetal, Fire Root, Honey Dew, and Shadow Moss share very similar stem shapes.","change":"Make their leaf silhouettes more distinct in addition to color."},{"id":"19","kind":"proposal","priority":"P2","area":"Ingredient selection","observation":"All six inventory tiles use the same frame with no indication of which are required.","change":"Highlight Sea Salt and Star Dust as recipe ingredients."},{"id":"20","kind":"proposal","priority":"P2","area":"Alchemist note","observation":"The instruction is small and faint beneath a decorative heading.","change":"Increase body contrast and line height."},{"id":"21","kind":"proposal","priority":"P3","area":"Note instruction sequence","observation":"Add Star Dust only after the water turns clear is detached from the brewing status.","change":"Pair the note with a visible current brewing step."},{"id":"22","kind":"proposal","priority":"P2","area":"Recipe-book quotation","observation":"Three faint lines compete for space below the recipe list.","change":"Reduce decorative quote prominence or move it to a smaller note block."},{"id":"23","kind":"proposal","priority":"P2","area":"Footer statistics","observation":"Alchemy Level, recipes known, and potions brewed are tiny.","change":"Use a consistent readable metadata scale and clearer group spacing."},{"id":"24","kind":"proposal","priority":"P2","area":"Keyboard footer","observation":"Tab: move Enter: choose is small and omits the mock's Close workshop action.","change":"Add readable keycaps and a visible close/back action if available."},{"id":"25","kind":"proposal","priority":"P3","area":"Currency identity","observation":"2,450 has a generic circular icon without a currency name.","change":"Add Gold as a small caption or a clearer coin symbol."}],"sha256":"4998d4b25be8c71676d896bbceacaebe36f66ebf36da4b2f907cf6d3cfb42da2","has_mock":true,"reference":null,"legacy":[]},{"id":"powerwash_settings","baseline":"screenshot-baselines/screens/powerwash_settings_720p.png","summary":"The tablet hierarchy is readable, but value padding, tiny symbols and weak action guidance need attention. Product proposals preserve the blue tablet design in mocks.html. Compared visually with the rendered mocks.html target at 1280 × 720.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"Resolution value","observation":"2560 x 1440 touches the value box left border.","change":"Inset every value 10 px from its border."},{"id":"02","kind":"defect","priority":"P2","area":"Footer Select hint","observation":"The Enter keycap nearly touches Select.","change":"Add an 8 px keycap-to-label gap."},{"id":"03","kind":"defect","priority":"P2","area":"Footer Reset hint","observation":"Reset and the next Enter keycap sit nearly together.","change":"Give each action group a 20 px trailing gap."},{"id":"04","kind":"defect","priority":"P2","area":"Top counters","observation":"O 10.00, O 200 and [] 1 are barely legible.","change":"Render recognizable resource icons and increase counter text to 14 px actual size."},{"id":"05","kind":"proposal","priority":"P2","area":"Dropdown arrows","observation":"Nine values end in tiny v glyphs.","change":"Use consistent 12 px chevrons aligned to a shared inset."},{"id":"06","kind":"proposal","priority":"P2","area":"Anti-Aliasing selection","observation":"Only the label half gets the pale selection treatment.","change":"Extend a selection outline around the complete label and value row."},{"id":"07","kind":"proposal","priority":"P2","area":"Selected label","observation":"The Anti-Aliasing text is subdued blue on pale gray.","change":"Use the dark navy text token for the selected label."},{"id":"08","kind":"proposal","priority":"P2","area":"Help heading","observation":"Anti-Aliasing is close in size to its body copy.","change":"Increase the heading weight and add 8 px before the paragraph."},{"id":"09","kind":"proposal","priority":"P2","area":"Help explanation","observation":"The help text spans several long lines across the right pane.","change":"Constrain paragraphs to about 48 characters per line."},{"id":"10","kind":"proposal","priority":"P2","area":"FPS wording","observation":"The explanation says reduce FPS load.","change":"Replace with reduce graphics processing load so the performance effect is clear."},{"id":"11","kind":"proposal","priority":"P2","area":"Render Scale value","observation":"Off appears in a control otherwise associated with scaling percentages.","change":"Display the actual native scale, such as 100%, with a native label."},{"id":"12","kind":"proposal","priority":"P3","area":"Resolution notation","observation":"Resolution uses a lowercase x between dimensions.","change":"Use the multiplication sign with consistent spacing."},{"id":"13","kind":"proposal","priority":"P3","area":"Vsync label","observation":"Vsync is styled differently from the familiar VSync spelling.","change":"Use VSync and expand it in the associated help."},{"id":"14","kind":"proposal","priority":"P2","area":"SSAO row","observation":"SSAO is the only unexplained acronym in the list.","change":"Expose Ambient occlusion in the label or a short adjacent qualifier."},{"id":"15","kind":"proposal","priority":"P3","area":"Model and texture quality","observation":"High and Highest use different quality vocabularies.","change":"Use one consistent scale across both quality controls."},{"id":"16","kind":"proposal","priority":"P2","area":"Settings categories","observation":"The category tabs sit below a tall content block.","change":"Add a small Video settings breadcrumb by SETTINGS to identify the current section immediately."},{"id":"17","kind":"proposal","priority":"P2","area":"Header icons","observation":"Six unlabeled symbols appear above the settings rows.","change":"Add short captions or an explicit application-navigation group label."},{"id":"18","kind":"proposal","priority":"P3","area":"Active gear icon","observation":"The selected gear has a brighter tile but no text.","change":"Add a small Settings caption to establish what the selected icon represents."},{"id":"19","kind":"proposal","priority":"P3","area":"Tablet backdrop","observation":"Large peach tiles surround a dense blue panel.","change":"Add the soft tablet shadow from mocks.html to separate the panel from the scene."},{"id":"20","kind":"proposal","priority":"P3","area":"Watermark","observation":"FUTURLAB / POWERWASH SIMULATOR is very faint at the pane bottom.","change":"Increase the watermark size modestly while keeping it secondary."},{"id":"21","kind":"proposal","priority":"P2","area":"Tab controls A and D","observation":"A and D keycaps sit alone at opposite ends of the strip.","change":"Add a concise Change category hint alongside the footer controls."},{"id":"22","kind":"proposal","priority":"P2","area":"Close button","observation":"A plain X in a blue square is separated from its footer explanation.","change":"Use a standard close glyph with a stable centered alignment."},{"id":"23","kind":"proposal","priority":"P2","area":"Reset action","observation":"The footer says Reset without naming its scope.","change":"Rename to Reset video settings to match the active tab."},{"id":"24","kind":"proposal","priority":"P2","area":"Change status","observation":"No visible saved or pending state appears beside the settings.","change":"Add a compact Changes apply immediately message near the footer if that is the actual behavior."},{"id":"25","kind":"proposal","priority":"P3","area":"Row borders","observation":"Every row has strong double blue divisions.","change":"Reduce inactive border weight and reserve the strongest edge for selection."},{"id":"26","kind":"proposal","priority":"P2","area":"Product typography parity","observation":"The current help and row labels are more widely spaced and lighter than the compact condensed type in the rendered mock.","change":"Match the target font face, weight and tracking, then recheck wrapping and value padding."},{"id":"27","kind":"proposal","priority":"P3","area":"Scene perspective parity","observation":"The current peach background is a flat grid while the target shows a receding tiled corner around the tablet.","change":"Restore the target's perspective planes and tile geometry."},{"id":"28","kind":"proposal","priority":"P3","area":"Active Video tab parity","observation":"The current Video tab has a strong four-sided outline; the target uses a blue fill and bright bottom edge.","change":"Match the target tab treatment with a clear bottom selection rule."}],"sha256":"083a89475060533ed215da2150839f6e60c4ae38c41907054637817230d2ee01","has_mock":true,"reference":"inspiration/example_powerwash.jpg","legacy":[]},{"id":"race_results","baseline":"screenshot-baselines/screens/race_results_720p.png","summary":"The result table has a strong player highlight. Smaller text, skewed table geometry and ambiguous standings context weaken an otherwise clear results screen. Compared visually with the rendered mocks.html target at 1280 × 720.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"Table headers","observation":"POS., RACER, TIME and PTS are tiny beside the racer names.","change":"Increase headers to a readable 12 to 14 px actual size."},{"id":"02","kind":"defect","priority":"P2","area":"Points column","observation":"The +4 and +3 values almost touch the sloping right edge.","change":"Give the points column a constant 20 px right inset."},{"id":"03","kind":"defect","priority":"P2","area":"Personal best caption","observation":"New personal best! is extremely small under 0:48.220.","change":"Increase the caption to at least 12 px and place it closer to the time."},{"id":"04","kind":"defect","priority":"P2","area":"Controller help","observation":"Arrows to choose A Confirm B Back is tiny in the footer.","change":"Increase help text and separate key labels into readable groups."},{"id":"05","kind":"proposal","priority":"P2","area":"Position headline","observation":"2nd appears above CUP STANDINGS without a race or cup qualifier.","change":"Label it Race finish or Cup position according to the intended metric."},{"id":"06","kind":"proposal","priority":"P2","area":"Player chip","observation":"P1 in the top-right competes with the second-place result.","change":"Label it Player 1 so it cannot read as finishing position."},{"id":"07","kind":"proposal","priority":"P2","area":"Table shape","observation":"Rows progressively shift left while column content does not follow the same edge.","change":"Keep decorative skew on a backing panel and align the data table to a rectangular grid."},{"id":"08","kind":"proposal","priority":"P3","area":"Bottom table gap","observation":"An empty pale band remains below Pebble.","change":"End the table after the last row or use the band for a labeled total."},{"id":"09","kind":"proposal","priority":"P2","area":"Race progress","observation":"Race 3/4 is embedded in the circuit title.","change":"Give race progress a small four-step marker near the title."},{"id":"10","kind":"proposal","priority":"P2","area":"Race context","observation":"Rainbow Circuit shares one line with progress.","change":"Separate circuit name from championship progress with clear hierarchy."},{"id":"11","kind":"proposal","priority":"P2","area":"Points label","observation":"PTS does not distinguish earned points from cumulative standings points.","change":"Rename the left column Race points."},{"id":"12","kind":"proposal","priority":"P2","area":"Time label","observation":"TIME does not say whether this is total race time.","change":"Use Race time as the column heading."},{"id":"13","kind":"proposal","priority":"P2","area":"Player identity","observation":"The highlighted racer is only named YOU.","change":"Include the driver's name with a You tag for continuity with other screens."},{"id":"14","kind":"proposal","priority":"P3","area":"Player portrait","observation":"The player portrait has the same visual treatment as every opponent.","change":"Add a small player badge next to the green portrait."},{"id":"15","kind":"proposal","priority":"P2","area":"Standings subset","observation":"Only four of eight racers are shown in CUP STANDINGS.","change":"Label the section Top 4 of 8 or provide a compact full-standings affordance."},{"id":"16","kind":"proposal","priority":"P2","area":"Championship gap","observation":"38 pts and 42 pts require mental subtraction.","change":"Add 4 points behind leader beside the player's cumulative score."},{"id":"17","kind":"proposal","priority":"P2","area":"Race gap","observation":"The player's 2:33.812 requires comparison with 2:31.450.","change":"Show a +2.362 gap alongside the player time."},{"id":"18","kind":"proposal","priority":"P3","area":"Best lap association","observation":"The right card does not identify whose best lap is shown.","change":"Rename BEST LAP to YOUR BEST LAP."},{"id":"19","kind":"proposal","priority":"P2","area":"Best lap achievement","observation":"Personal best is shown with no prior benchmark.","change":"Add the previous best or improvement delta when available."},{"id":"20","kind":"proposal","priority":"P3","area":"Standings row separators","observation":"Thin separators are weak against the landscape-tinted panel.","change":"Increase separator contrast slightly and use even row padding."},{"id":"21","kind":"proposal","priority":"P3","area":"Side-panel background","observation":"The landscape silhouette crosses the standings and lap areas.","change":"Use a more opaque backing behind text for consistent contrast."},{"id":"22","kind":"proposal","priority":"P2","area":"Next race action","observation":"NEXT RACE gives no destination context.","change":"Add the upcoming track name as secondary button text or adjacent copy."},{"id":"23","kind":"proposal","priority":"P3","area":"Back action","observation":"Back uses a text less-than symbol while Next uses a greater-than symbol.","change":"Use matching navigation chevrons with equal label spacing."},{"id":"24","kind":"proposal","priority":"P3","area":"Footer balance","observation":"The help text hugs Back while a large empty middle area remains.","change":"Align help centrally between Back and Next race."},{"id":"25","kind":"proposal","priority":"P3","area":"Standings emphasis","observation":"YOU is yellow but has no shape-based indicator in the side list.","change":"Add a small player marker to match the highlighted result row."},{"id":"26","kind":"proposal","priority":"P2","area":"Result typography parity","observation":"The current title and 2nd are upright, while the rendered target uses italic racing typography.","change":"Match the italic display treatment for the title, finish position and standings heading."},{"id":"27","kind":"proposal","priority":"P3","area":"Footer action geometry parity","observation":"Back and Next race are rectangular in the current image; the target uses slanted button silhouettes.","change":"Apply the target slant to button backings while keeping labels level and padded."},{"id":"28","kind":"proposal","priority":"P2","area":"Result-row separators parity","observation":"The current table relies on alternating pale fills, while the target adds visible cyan row rules.","change":"Add the target row separators to strengthen horizontal scanning."}],"sha256":"236c7b0761d04da724a163adc1673d9c4a4f06db34bd3dcad8261b284552b69b","has_mock":true,"reference":null,"legacy":[]},{"id":"radio_buttons","baseline":"screenshot-baselines/screens/radio_buttons_720p.png","summary":"The three groups clearly demonstrate single selection. Eighteen defensible proposals improve comparison and documentation; a static initial state does not justify 25 distinct defects. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Group card height","observation":"Fruit and Size leave over half their card empty.","change":"Size cards to their options and reserve a shared footer for demo notes."},{"id":"02","kind":"proposal","priority":"P2","area":"Main heading","observation":"Radio Button Groups sits flush against its teal bar left edge.","change":"Add a consistent 16 px text inset."},{"id":"03","kind":"proposal","priority":"P2","area":"Group headings","observation":"Favorite Fruit, Size and Color hug their header left edges.","change":"Align headings with the option-label column or apply a clear shared inset."},{"id":"04","kind":"proposal","priority":"P2","area":"Selected markers","observation":"Orange, Small and Blue use a dark magenta dot on a dark card.","change":"Add an adjacent selected badge or stronger outline while retaining the theme swatch."},{"id":"05","kind":"proposal","priority":"P3","area":"Color options","observation":"Red, Green, Blue and Yellow are all text-only.","change":"Add small labeled color swatches without changing the radio selection color."},{"id":"06","kind":"proposal","priority":"P2","area":"Summary syntax","observation":"The footer reads Fruit=Orange, Size=Small, Color=Blue.","change":"Use human-readable labeled values separated into three columns."},{"id":"07","kind":"proposal","priority":"P2","area":"Summary alignment","observation":"Selected begins flush against the footer edge.","change":"Add 16 px inner padding consistent with the title."},{"id":"08","kind":"proposal","priority":"P2","area":"Selection instructions","observation":"The title gives no explanation of one choice per group.","change":"Add a one-line instruction above the cards."},{"id":"09","kind":"proposal","priority":"P2","area":"Keyboard guidance","observation":"No key guide is visible beside the groups.","change":"Add a footer note describing the actual Tab and arrow behavior confirmed in source."},{"id":"10","kind":"proposal","priority":"P3","area":"Group numbering","observation":"Three equal cards have no explicit group identifiers beyond names.","change":"Add small independent group labels so the comparison purpose is evident."},{"id":"11","kind":"proposal","priority":"P3","area":"Defaults","observation":"Orange, Small and Blue are selected with no default annotation.","change":"Mark the initial selection as the fixture default in the summary."},{"id":"12","kind":"proposal","priority":"P2","area":"Fruit label width","observation":"Watermelon is much longer than Apple and Orange.","change":"Add a visible long-label example caption that explains the width test."},{"id":"13","kind":"proposal","priority":"P3","area":"Size labels","observation":"Small, Medium and Large contain no size context.","change":"Name the group Item size so the choices read as a coherent sample form."},{"id":"14","kind":"proposal","priority":"P3","area":"Unequal option counts","observation":"Color has four rows while the other cards have three.","change":"Align card bottoms to the option region and label option counts for comparison."},{"id":"15","kind":"proposal","priority":"P3","area":"Card border semantics","observation":"All three cards use the same magenta as selected radio dots.","change":"Use neutral card outlines so magenta is reserved for selection."},{"id":"16","kind":"proposal","priority":"P3","area":"Unused lower screen","observation":"A broad black band remains below the main panel.","change":"Vertically center the compact demo within the viewport."},{"id":"17","kind":"proposal","priority":"P2","area":"Summary association","observation":"The status line is separated from the cards by a large gutter.","change":"Move each selected value directly beneath its group and keep a compact combined summary."},{"id":"18","kind":"proposal","priority":"P3","area":"Spec visibility","observation":"The enlarged circles and dots are visible but their dimensions are undocumented.","change":"Add a small ring 28 px / dot 18 px caption outside the test controls."}],"sha256":"fd1b3220deab73516389f0046c0cb0d0f48f4f1c62bcf77acdd002a4ce68c8bb","has_mock":false,"reference":null,"legacy":[{"id":"radio_buttons","screen":"radio_buttons","baseline":"baseline_screenshots/radio_buttons.png","current":"screenshot-baselines/screens/radio_buttons_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Current capture removes Apple focus outline. Orange is selected independently of Apple focus in the old image. Large empty lower areas within groups remain visible.","sha256":"49838a9e898865c28f09ca09cb927191ddd422c60b206a88fb534c684eceebda","additional_findings":[]}]},{"id":"real_world_modals","baseline":"screenshot-baselines/screens/real_world_modals_720p.png","summary":"This baseline shows launchers rather than open modal states. Sixteen proposals improve the launcher composition; modal contents and behavior cannot be judged from this screenshot. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"Status line","observation":"No action yet is dark green on the navy background.","change":"Use a readable neutral status color until an action completes."},{"id":"02","kind":"proposal","priority":"P2","area":"Page framing","observation":"The six launchers occupy only the upper third of a large panel.","change":"Use a compact centered launcher panel or fill the lower area with pattern descriptions."},{"id":"03","kind":"proposal","priority":"P2","area":"Introductory copy","observation":"Real-World Modals gives no instruction for opening examples.","change":"Add Choose a pattern to preview its dialog beneath the heading."},{"id":"04","kind":"proposal","priority":"P2","area":"Delete Item button","observation":"Delete Item sounds like an immediate destructive action on the launcher screen.","change":"Label it Preview delete confirmation."},{"id":"05","kind":"proposal","priority":"P2","area":"Command Palette button","observation":"The launcher names the pattern but gives no example of its purpose.","change":"Add Search commands as secondary copy beneath it."},{"id":"06","kind":"proposal","priority":"P2","area":"Terms of Service button","observation":"The label does not reveal that the demo includes scrollable legal text.","change":"Add a short Scrollable agreement description."},{"id":"07","kind":"proposal","priority":"P2","area":"Side Drawer button","observation":"The name gives no placement preview.","change":"Add a miniature right-edge drawer diagram beside the caption."},{"id":"08","kind":"proposal","priority":"P2","area":"Bottom Sheet button","observation":"The launcher has the same visual weight as centered modal examples.","change":"Add a bottom-edge preview diagram to distinguish placement."},{"id":"09","kind":"proposal","priority":"P2","area":"Cookie Banner button","observation":"The launcher does not identify this as a noncentral banner pattern.","change":"Add a narrow banner preview below its label."},{"id":"10","kind":"proposal","priority":"P3","area":"Pattern grouping","observation":"All six buttons form an undifferentiated grid.","change":"Group centered dialogs separately from edge overlays with small headings."},{"id":"11","kind":"proposal","priority":"P2","area":"Status context","observation":"No action yet sits alone without a label.","change":"Place it in an Action result region with a visible heading."},{"id":"12","kind":"proposal","priority":"P3","area":"Destructive accent","observation":"The red Delete Item launcher dominates the otherwise blue grid.","change":"Reserve solid red for the destructive action inside the preview and use a red outline here."},{"id":"13","kind":"proposal","priority":"P3","area":"Button widths","observation":"Delete Item is visibly narrower than the other launcher buttons.","change":"Use equal column widths for the three-column grid."},{"id":"14","kind":"proposal","priority":"P2","area":"Page title scale","observation":"The title is only moderately larger than the letter-spaced button text.","change":"Increase title size and reduce letter spacing on launcher labels."},{"id":"15","kind":"proposal","priority":"P2","area":"Dismiss instructions","observation":"No guidance explains how demo overlays can be closed.","change":"Add a short dismissal note matched to the actual supported controls."},{"id":"16","kind":"proposal","priority":"P3","area":"Initial-state documentation","observation":"The baseline contains no visual specimen of any modal.","change":"Add a labeled static pattern thumbnail region or separate open-state baselines for review."}],"sha256":"2417d8153cdac1cbaba619981da860c49c184ba098ea950997db4ba7dd224e98","has_mock":false,"reference":null,"legacy":[]},{"id":"rect_algebra_lab","baseline":"screenshot-baselines/screens/rect_algebra_lab_720p.png","summary":"The geometry matches the deliberate rect operations in source. Twenty proposals add explanatory framing without treating fixed strips, ticks or empty panes as layout defects. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Left diagram heading","observation":"The tiled rectangle has no local title.","change":"Label it Window tiling above the drawing."},{"id":"02","kind":"proposal","priority":"P2","area":"Right diagram heading","observation":"The orange box diagram has no local title.","change":"Label it Cut header, pad body, center box."},{"id":"03","kind":"proposal","priority":"P2","area":"Sidebar rectangle","observation":"The tall narrow left pane has no identifier.","change":"Place Sidebar in an external callout tied to that rectangle."},{"id":"04","kind":"proposal","priority":"P2","area":"Main canvas","observation":"The largest blue rectangle is unlabeled.","change":"Add a Canvas label outside its measured geometry."},{"id":"05","kind":"proposal","priority":"P2","area":"Inspector pane","observation":"The right narrow blue pane cannot be distinguished by purpose.","change":"Add an Inspector callout with its 110 px cut width."},{"id":"06","kind":"proposal","priority":"P2","area":"Bottom strip","observation":"The gray strip along the bottom has no description.","change":"Label it Status strip, cut_bottom 26 px."},{"id":"07","kind":"proposal","priority":"P2","area":"Top strip","observation":"The short gray strip above the canvas has no description.","change":"Label it Tabs, cut_top 24 px."},{"id":"08","kind":"proposal","priority":"P2","area":"Operation order","observation":"The left result shows no sequence for the nested cuts.","change":"Add a numbered sequence in a small legend under the diagram."},{"id":"09","kind":"proposal","priority":"P2","area":"Right header strip","observation":"The blue top strip has no stated height.","change":"Add a callout for the 22 px header cut."},{"id":"10","kind":"proposal","priority":"P2","area":"Inner outline","observation":"The purple rectangle does not explain the 6 px inset.","change":"Annotate the inset distance outside the outline."},{"id":"11","kind":"proposal","priority":"P2","area":"Orange box","observation":"The centered orange box has no dimensions.","change":"Label it 64 × 36 near the diagram."},{"id":"12","kind":"proposal","priority":"P2","area":"Orange outer outline","observation":"The dim orange outline can read as a decorative border.","change":"Label it expand 12 px hit target."},{"id":"13","kind":"proposal","priority":"P2","area":"Top green tick","observation":"The green marker is unnamed.","change":"Add align_top to the legend with its green swatch."},{"id":"14","kind":"proposal","priority":"P2","area":"Edge marker system","observation":"Four green markers indicate alignment without named edges.","change":"Add a compact legend naming top, bottom, left and right alignment."},{"id":"15","kind":"proposal","priority":"P3","area":"Diagram key","observation":"Blue, purple, orange and green have no semantic key.","change":"Provide one legend mapping each color to its operation."},{"id":"16","kind":"proposal","priority":"P2","area":"Center verification","observation":"The orange rectangle appears centered but has no reference axes.","change":"Add faint optional center guides that intersect at the box center."},{"id":"17","kind":"proposal","priority":"P3","area":"Root title","observation":"rect algebra: cut, pad, align omits expand despite showing it.","change":"Include expand in the title or subtitle."},{"id":"18","kind":"proposal","priority":"P3","area":"Unused lower area","observation":"A large dark strip remains below both diagrams.","change":"Use that area for the operation legend and formulas."},{"id":"19","kind":"proposal","priority":"P2","area":"Static demo framing","observation":"The diagram looks like an empty application shell.","change":"Add a Static geometry demonstration caption."},{"id":"20","kind":"proposal","priority":"P3","area":"Measured padding","observation":"The outer and inner margins are visible but undocumented.","change":"Label the 10 px left-panel and 20 px right-panel padding in the legend."}],"sha256":"82930845574da68b09e7c22afcba18e6b82d6eb4b8844c20c1435ab0b88cb119","has_mock":false,"reference":null,"legacy":[{"id":"rect_algebra_lab","screen":"rect_algebra_lab","baseline":"baseline_screenshots/rect_algebra_lab.png","current":"screenshot-baselines/screens/rect_algebra_lab_720p.png","pixel_identical":true,"size":[1280,720],"summary":"Pixel-identical. Left blue cut regions and right inset bounds are operation visualizations. Improvements should label those operations and dimensions without treating different rectangles as a layout error.","sha256":"82930845574da68b09e7c22afcba18e6b82d6eb4b8844c20c1435ab0b88cb119","additional_findings":[]}]},{"id":"rubber_bandits_menu","baseline":"screenshot-baselines/screens/rubber_bandits_menu_720p.png","summary":"The menu captures the playful yellow and turquoise direction, but small utility text and crowded character-selection framing need work. Compared visually with the rendered mocks.html target at 1280 × 720.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"Version label","observation":"1.6.0 / RUBBER BANDITS is nearly microscopic at bottom left.","change":"Increase it to a readable 11 px actual size."},{"id":"02","kind":"defect","priority":"P2","area":"Character favorite label","observation":"FAVOURITE is squeezed between the name and bottom strip.","change":"Give it a dedicated line with at least 12 px readable text."},{"id":"03","kind":"proposal","priority":"P2","area":"Top account strip","observation":"The user name and Online status share one tiny line.","change":"Separate account name from a labeled connection badge."},{"id":"04","kind":"proposal","priority":"P2","area":"Top-right counters","observation":"A circled 1 and green 20 have no meaning labels.","change":"Add level and currency captions or recognizable matching icons."},{"id":"05","kind":"proposal","priority":"P2","area":"Selected Options item","observation":"The selected word starts nearly at the turquoise pill edge.","change":"Add equal left padding to match the other menu labels."},{"id":"06","kind":"proposal","priority":"P3","area":"Selection marker","observation":"The diamond at the right of Options has little association with navigation.","change":"Use a consistent selection pointer with the same size as the menu text cap height."},{"id":"07","kind":"proposal","priority":"P2","area":"Back spacing","observation":"Back is separated from Play Credits by a much larger gap.","change":"Make the separation an explicit secondary navigation group with a divider."},{"id":"08","kind":"proposal","priority":"P2","area":"Play Credits wording","observation":"Play Credits reads like gameplay next to Armory.","change":"Use Credits unless the action actually starts a distinct playable mode."},{"id":"09","kind":"proposal","priority":"P2","area":"Leaderboard width","observation":"LEADERBOARD is considerably longer than other entries.","change":"Maintain a common menu text width and align the selection pill to that width."},{"id":"10","kind":"proposal","priority":"P2","area":"Supporter promo","observation":"Get more bandits shares three equally emphasized lines.","change":"Use a clear Supporter pack heading and one supporting sentence."},{"id":"11","kind":"proposal","priority":"P2","area":"Promo action","observation":"The supporter card has no explicit action label.","change":"Add View pack within the card."},{"id":"12","kind":"proposal","priority":"P3","area":"Promo icon","observation":"The lightning coin uses yellow against pale yellow.","change":"Add a darker outline so its silhouette reads at a glance."},{"id":"13","kind":"proposal","priority":"P2","area":"Character name","observation":"EARL THE BIRD overlaps a busy trail of banknotes.","change":"Put the name on a solid or translucent backing panel."},{"id":"14","kind":"proposal","priority":"P2","area":"LB and RB hints","observation":"The bumper hints are separated by the character name and currency art.","change":"Align both on a quiet common baseline around the selection panel."},{"id":"15","kind":"proposal","priority":"P2","area":"Selected character","observation":"The large bird overlaps several surrounding characters.","change":"Add a subtle ground marker to identify the selected character without hiding the lineup."},{"id":"16","kind":"proposal","priority":"P3","area":"Character count","observation":"The lineup contains several figures but no selected index.","change":"Show Earl the Bird with a position indicator such as 3 of 7."},{"id":"17","kind":"proposal","priority":"P3","area":"Background crown","observation":"A flat yellow block shape rises behind the center figures.","change":"Refine its crown silhouette or reduce its prominence to avoid a placeholder appearance."},{"id":"18","kind":"proposal","priority":"P3","area":"Ground shadows","observation":"Several characters appear to float above disconnected oval shadows.","change":"Align each shadow beneath its feet using the scene perspective."},{"id":"19","kind":"proposal","priority":"P3","area":"Cash props","observation":"Dense banknotes cross the bottom selection controls.","change":"Reserve a clear lower control band and keep props above it."},{"id":"20","kind":"proposal","priority":"P3","area":"Rightmost prop","observation":"A dark circle sits beside the cowboy and looks detached.","change":"Connect it visually to its prop or remove that ambiguous shape."},{"id":"21","kind":"proposal","priority":"P2","area":"Menu help strip","observation":"Change the game's settings sits at the extreme bottom edge.","change":"Add vertical breathing room around the help text."},{"id":"22","kind":"proposal","priority":"P2","area":"Input guide","observation":"Only character bumpers are shown despite the main menu being selected.","change":"Add compact confirm and back hints beside the menu help."},{"id":"23","kind":"proposal","priority":"P3","area":"Logo prominence","observation":"The large logo outweighs the actual selected menu action.","change":"Reduce its footprint slightly to give the menu more breathing room."},{"id":"24","kind":"proposal","priority":"P2","area":"Online context","observation":"Online appears in the top strip while Back has no destination.","change":"Label Back to main menu when that is the actual destination."},{"id":"25","kind":"proposal","priority":"P3","area":"Character art density","observation":"The right side packs six smaller figures close together.","change":"Increase silhouette separation so hats and faces do not visually merge."},{"id":"26","kind":"proposal","priority":"P2","area":"Menu typography parity","observation":"The current LEADERBOARD and PLAY CREDITS occupy more horizontal space than the rendered target.","change":"Match the target font metrics and tracking so menu labels retain the intended compact width."},{"id":"27","kind":"proposal","priority":"P3","area":"Supporter card border parity","observation":"The current supporter card has one thin white edge; the target has a rounded double outline.","change":"Restore the double border and inner inset to match the promotional-card treatment."}],"sha256":"0f27fae182c9c4efd8f95ebedad7a96029286929a5bc4465f6283cf62ecb7afc","has_mock":true,"reference":"inspiration/example_rubber_bandits.jpg","legacy":[]},{"id":"scroll_click_bug","baseline":"screenshot-baselines/screens/scroll_click_bug_720p.png","summary":"The initial screenshot can document the click fixture but cannot establish a click-offset bug. Fifteen proposals improve reproducibility and visual evidence without changing the clipped list. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Test title","observation":"Scroll Click Bug Test names a bug without a visible expected outcome.","change":"Add a subtitle stating that the clicked label must match the reported index after scrolling."},{"id":"02","kind":"proposal","priority":"P2","area":"Initial status","observation":"No button clicked yet does not identify the output field.","change":"Prefix it with Last clicked and show a neutral empty value."},{"id":"03","kind":"proposal","priority":"P2","area":"List context","observation":"Only Button 0 through part of Button 6 are visible.","change":"Display 20 buttons above the viewport."},{"id":"04","kind":"proposal","priority":"P2","area":"Scroll position","observation":"The initial scrollbar gives no numeric offset.","change":"Add Scroll offset: 0 px beside the status."},{"id":"05","kind":"proposal","priority":"P2","area":"Visible range","observation":"The partial Button 6 has no range summary.","change":"Show the visible range separately from the last-click result."},{"id":"06","kind":"proposal","priority":"P2","area":"Reproduction steps","observation":"The large blank area below the list contains no procedure.","change":"Place a short scroll-then-click procedure there."},{"id":"07","kind":"proposal","priority":"P2","area":"Expected result","observation":"The status line has no comparison target.","change":"Display Expected label and Actual clicked label side by side after selection."},{"id":"08","kind":"proposal","priority":"P3","area":"Title bar alignment","observation":"The title text touches the left of its white backing.","change":"Add 12 px inner padding."},{"id":"09","kind":"proposal","priority":"P3","area":"List inset","observation":"A wide blank gutter separates button ends from the scrollbar.","change":"Reduce the gutter to a consistent 12 to 16 px if it is not part of the hit-test fixture."},{"id":"10","kind":"proposal","priority":"P2","area":"Button identifiers","observation":"Centered Button N labels make row identity far from the left edge.","change":"Add a small left-aligned index column while preserving the button hit area."},{"id":"11","kind":"proposal","priority":"P3","area":"Status legibility","observation":"The initial status is light gray and small.","change":"Increase actual text size and use a darker neutral color."},{"id":"12","kind":"proposal","priority":"P2","area":"Reset control","observation":"The initial composition offers no visible way to return to its starting state.","change":"Add Reset scroll and result outside the viewport."},{"id":"13","kind":"proposal","priority":"P3","area":"Fixture frame","observation":"A large light panel surrounds a comparatively small test area.","change":"Tighten the outer frame around the list and explanatory text."},{"id":"14","kind":"proposal","priority":"P2","area":"Clipping boundary","observation":"The partially visible final button could look accidental to a reviewer.","change":"Label the viewport bottom as the intentional clip boundary."},{"id":"15","kind":"proposal","priority":"P3","area":"Index convention","observation":"Buttons begin at 0 with no explanation.","change":"Add a Zero-based indices note beside the count."}],"sha256":"6beb45fb74e2b9a473a885a1d88bafa2190242fefb9e2fab3af96b17134fd3ea","has_mock":false,"reference":null,"legacy":[]},{"id":"scroll_clip_bug","baseline":"screenshot-baselines/screens/scroll_clip_bug_720p.png","summary":"Four intentional clipping variants are present. Sixteen proposals improve the regression fixture framing; the nested inner container extends below its outer viewport, which requires a dedicated boundary comparison rather than an inferred interaction failure. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Instruction line","observation":"The all-four-panels instruction is extremely small.","change":"Increase it to a readable 13 px actual size."},{"id":"02","kind":"proposal","priority":"P2","area":"Panel labels","observation":"Control, ClipChild rows, Nested wrapper and Scroll in Scroll are tiny colored captions.","change":"Increase caption size and keep text white with a separate colored swatch."},{"id":"03","kind":"proposal","priority":"P2","area":"Control caption","observation":"Control gives no structural explanation.","change":"Add normal rows as its secondary caption."},{"id":"04","kind":"proposal","priority":"P2","area":"ClipChild caption","observation":"ClipChild rows exposes an implementation term without defining it.","change":"Add each row clips its children below the caption."},{"id":"05","kind":"proposal","priority":"P2","area":"Nested wrapper caption","observation":"Nested wrapper does not show which boundary belongs to the wrapper.","change":"Add a small structure diagram above or below the panel."},{"id":"06","kind":"proposal","priority":"P2","area":"Nested scroll caption","observation":"Scroll in Scroll does not distinguish inner and outer scroll regions.","change":"Label both boundaries with matching callout markers."},{"id":"07","kind":"proposal","priority":"P2","area":"Bottom nested border","observation":"The inner dark frame extends below the common outer bottom line.","change":"Add a visible horizontal outer-boundary guide to make intended clipping reviewable."},{"id":"08","kind":"proposal","priority":"P2","area":"Scroll offsets","observation":"No panel reports its current scroll offset.","change":"Add one numeric offset per panel outside the clip region."},{"id":"09","kind":"proposal","priority":"P2","area":"Comparison state","observation":"All panels start at row 1, so the target scrolled state is absent.","change":"Add a companion preset that places all panels at the same nonzero offset."},{"id":"10","kind":"proposal","priority":"P2","area":"Row labels","observation":"Ctrl, Clip, Nest and Inner prefixes differ across comparison panels.","change":"Add matching numeric markers at a common x inset for easier alignment comparison."},{"id":"11","kind":"proposal","priority":"P3","area":"Row text","observation":"Row identifiers are very small inside 40 px colored bands.","change":"Increase label size without changing the measured row dimensions."},{"id":"12","kind":"proposal","priority":"P2","area":"Test count","observation":"The screenshot does not state the total rows per pane.","change":"Add total count to each pane caption."},{"id":"13","kind":"proposal","priority":"P2","area":"Expected boundary rule","observation":"The top note mentions colored borders, which are thin and subtle.","change":"Add a clearly keyed boundary legend outside the fixture."},{"id":"14","kind":"proposal","priority":"P2","area":"Nested scrolling instructions","observation":"The screenshot gives no way to distinguish moving inner versus outer content.","change":"Add a concise two-step nested-scroll procedure beneath the title."},{"id":"15","kind":"proposal","priority":"P3","area":"Bottom margin","observation":"The test panes run nearly to the viewport edge.","change":"Reserve a small external margin for boundary labels without resizing the test viewports."},{"id":"16","kind":"proposal","priority":"P2","area":"Reset comparison","observation":"No reset or synchronized positioning control is visible.","change":"Add Reset all and Set comparison offset controls above the four panes."}],"sha256":"b6523f529fdbfa843935c27539c10429561613560e0ffd0a42a582113aa2a0ab","has_mock":false,"reference":null,"legacy":[]},{"id":"scroll_view","baseline":"screenshot-baselines/screens/scroll_view_720p.png","summary":"The two-axis demo is understandable, but its inversion control and position indicators are ambiguous. Nineteen distinct improvements are supportable; intentional partial rows remain part of the scroll demonstration. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"Vertical row text","observation":"Item labels touch their blue cards' left edges.","change":"Inset the labels by 12 px."},{"id":"02","kind":"defect","priority":"P2","area":"Horizontal item text","observation":"Numbers 1 through 5 sit flush against card left edges.","change":"Center the numbers or use the same 12 px inset as vertical rows."},{"id":"03","kind":"proposal","priority":"P2","area":"Invert Scroll control","observation":"Invert Scroll is a gray rectangle with no visible on/off state.","change":"Render a labeled toggle with an explicit current state."},{"id":"04","kind":"proposal","priority":"P2","area":"Horizontal progress bar","observation":"A blue segment sits in a gray bar below a 0% label.","change":"Label it visible fraction or scroll position according to what it represents."},{"id":"05","kind":"proposal","priority":"P2","area":"Duplicate horizontal bars","observation":"The horizontal view has a scrollbar and another unlabeled bar below it.","change":"Explain the second indicator or combine the redundant visualizations."},{"id":"06","kind":"proposal","priority":"P2","area":"Position labels","observation":"Item 1 of 20 and Item 1 of 15 can imply one visible item.","change":"Use First visible item and include the full visible range."},{"id":"07","kind":"proposal","priority":"P3","area":"Panel heights","observation":"The vertical viewport is taller than the horizontal viewport.","change":"Align outer demo cards while retaining different internal viewport heights."},{"id":"08","kind":"proposal","priority":"P2","area":"Horizontal blank space","observation":"A large empty white area sits below the horizontal cards.","change":"Reduce the viewport to content height or label the intentional spare area."},{"id":"09","kind":"proposal","priority":"P2","area":"Scroll hints","observation":"A long instruction line blends both axis gestures together.","change":"Place the vertical gesture near Vertical Scroll and the horizontal gesture near Horizontal Scroll."},{"id":"10","kind":"proposal","priority":"P3","area":"Header padding","observation":"Scroll View Demo touches its backing bar left edge.","change":"Add a consistent 12 px title inset."},{"id":"11","kind":"proposal","priority":"P2","area":"Instruction contrast","observation":"The gray gesture instruction is faint on the light panel.","change":"Use a darker neutral text token."},{"id":"12","kind":"proposal","priority":"P2","area":"Vertical clip sample","observation":"Item 5 is partly shown without explanatory framing.","change":"Add an intentional partial item caption below the viewport."},{"id":"13","kind":"proposal","priority":"P2","area":"Horizontal extent","observation":"Five cards are fully visible even though more items exist.","change":"Add a right-edge continuation cue or adjust the viewport to reveal a partial sixth card."},{"id":"14","kind":"proposal","priority":"P2","area":"Scroll counts","observation":"The total counts appear only below the panes.","change":"Add 20 items and 15 items beside the pane headings."},{"id":"15","kind":"proposal","priority":"P3","area":"Content balance","observation":"Both demos occupy the top half with a large unused lower panel.","change":"Tighten the page height or add a concise behavior comparison there."},{"id":"16","kind":"proposal","priority":"P2","area":"Reset position","observation":"No visible control returns either view to its start.","change":"Add a shared Reset position action outside both panes."},{"id":"17","kind":"proposal","priority":"P2","area":"Inversion scope","observation":"The single Invert Scroll control does not name affected axes.","change":"Label it Invert both scroll axes if that matches the implementation."},{"id":"18","kind":"proposal","priority":"P3","area":"Indicator alignment","observation":"The extra horizontal indicator is centered while text aligns left.","change":"Align the indicator with the horizontal viewport left edge."},{"id":"19","kind":"proposal","priority":"P2","area":"Demonstration state","observation":"Both panes show only the initial zero-percent state.","change":"Add a labeled scrolled-state preset for side-by-side verification."}],"sha256":"ceee72c7cf0d82f36ff893392d462cfa7439720586f9f8efd807fdddd0826780","has_mock":false,"reference":null,"legacy":[]},{"id":"scrollbar_style_lab","baseline":"screenshot-baselines/screens/scrollbar_style_lab_720p.png","summary":"The four styling variants are intentional, including the low-contrast accent and transparent track. Sixteen proposals make the comparison measurable without replacing those specimens. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Main title","observation":"The long title begins at the extreme left edge.","change":"Inset it by 16 px to align with the first pane."},{"id":"02","kind":"proposal","priority":"P2","area":"Variant captions","observation":"default, usage: Accent thumb, explicit colours and thicker, no track are small.","change":"Increase caption size to a readable 13 px actual size."},{"id":"03","kind":"proposal","priority":"P2","area":"Default variant","observation":"The default pane does not name its track or thumb tokens.","change":"Add a two-line token caption beneath it."},{"id":"04","kind":"proposal","priority":"P2","area":"Accent variant","observation":"The magenta thumb is a deliberate theme usage but its token is only in the title.","change":"Add an Accent swatch and resolved color value outside the pane."},{"id":"05","kind":"proposal","priority":"P2","area":"Explicit colors variant","observation":"The orange thumb and dark red track have no color values shown.","change":"Label both RGBA values beneath the pane."},{"id":"06","kind":"proposal","priority":"P2","area":"Thicker variant","observation":"The thicker teal thumb has no numeric width annotation.","change":"Label its 14 px thickness."},{"id":"07","kind":"proposal","priority":"P2","area":"Transparent track","observation":"No track can be mistaken for a missing renderer.","change":"Add an explicit Track alpha 0 caption."},{"id":"08","kind":"proposal","priority":"P2","area":"Row count","observation":"Rows 00 through 13 are visible with no total count.","change":"Add the full row count to each pane's metadata."},{"id":"09","kind":"proposal","priority":"P2","area":"Scroll state","observation":"Equal thumb positions are shown without reported offsets.","change":"Add a shared scroll offset readout for comparison."},{"id":"10","kind":"proposal","priority":"P2","area":"Thumb size","observation":"Thumb length is visibly comparable but undocumented.","change":"Show viewport/content ratio below the columns."},{"id":"11","kind":"proposal","priority":"P3","area":"Row text","observation":"Row identifiers are tiny relative to the empty pane width.","change":"Increase their type size while keeping row heights fixed."},{"id":"12","kind":"proposal","priority":"P2","area":"Comparison controls","observation":"No control sets every variant to the same scrolled position.","change":"Add shared start, middle and end presets outside the panes."},{"id":"13","kind":"proposal","priority":"P2","area":"Track/thumb distinction","observation":"The title mentions track and thumb without a diagram.","change":"Use a small annotated scrollbar key in the lower empty area."},{"id":"14","kind":"proposal","priority":"P3","area":"Unused lower area","observation":"Nearly half the screen is blank.","change":"Use it for the variant specification table."},{"id":"15","kind":"proposal","priority":"P2","area":"Baseline variant naming","observation":"default is lowercase while Accent uses a token-like capital.","change":"Use consistent human-readable headings and put API tokens in smaller metadata."},{"id":"16","kind":"proposal","priority":"P3","area":"Width comparison","observation":"The thick variant changes both color and width.","change":"Add a width-only comparison swatch alongside its metadata to isolate thickness."}],"sha256":"28fcd043a647faca491c9ab3417db32e881454fb884762f82a0135e2b145e205","has_mock":false,"reference":null,"legacy":[{"id":"scrollbar_style_lab","screen":"scrollbar_style_lab","baseline":"baseline_screenshots/scrollbar_style_lab.png","current":"screenshot-baselines/screens/scrollbar_style_lab_720p.png","pixel_identical":true,"size":[1280,720],"summary":"Pixel-identical. Four tracks deliberately compare default, accent, explicit-color and no-track styles. Preserve those differences. Small headers and nearly identical repeated row text hinder the comparison.","sha256":"28fcd043a647faca491c9ab3417db32e881454fb884762f82a0135e2b145e205","additional_findings":[]}]},{"id":"secure_tunnel","baseline":"screenshot-baselines/screens/secure_tunnel_720p.png","summary":"The disconnected state and chosen server are visible, but tiny metadata and approximate map/icon artwork fall short of the clearer product framing in mocks.html. Compared visually with the rendered mocks.html target at 1280 × 720.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"Server metadata","observation":"Countries and latency values are very small and pale.","change":"Increase them to readable 12 to 13 px actual text with darker contrast."},{"id":"02","kind":"defect","priority":"P2","area":"Simulation disclaimer","observation":"Network simulation only is tiny at the bottom center.","change":"Place a readable Demo mode badge near the connection state."},{"id":"03","kind":"proposal","priority":"P2","area":"Protocol control","observation":"WireGuard appears as plain text with no visible change affordance.","change":"Add Change protocol or a cycle icon beside the value to explain the existing cycle action."},{"id":"04","kind":"defect","priority":"P2","area":"Privacy icon","observation":"The shield illustration looks like overlapping thin geometric fragments.","change":"Replace it with a recognizable centered shield outline."},{"id":"05","kind":"proposal","priority":"P2","area":"Rail navigation","observation":"Five icon controls have no visible text labels.","change":"Add short labels or an expanded navigation legend for VPN, protection, routing, diagnostics and settings."},{"id":"06","kind":"proposal","priority":"P2","area":"Active rail icon","observation":"The active concentric-ring symbol does not identify VPN.","change":"Use a recognizable connection or globe icon matching the map heading."},{"id":"07","kind":"proposal","priority":"P3","area":"Brand mark","observation":"The top rail logo reads as a thin triangle.","change":"Refine it into a consistent solid brand mark with balanced stroke weight."},{"id":"08","kind":"proposal","priority":"P2","area":"Connection indicator","observation":"Not connected has a tiny orange diamond.","change":"Use a larger status dot and explicit Disconnected text."},{"id":"09","kind":"proposal","priority":"P2","area":"Quick-connect recommendation","observation":"Fastest available server says Lisbon while Reykjavik shows a lower latency.","change":"Explain the recommendation criterion or recommend the displayed lowest-latency server."},{"id":"10","kind":"proposal","priority":"P2","area":"Recommendation copy","observation":"Fastest available server - Lisbon is faint under the button.","change":"Increase contrast and separate server name with stronger weight."},{"id":"11","kind":"proposal","priority":"P2","area":"Search affordance","observation":"Search locations looks like a blank pale field without a search icon.","change":"Add a leading search icon and a stronger field border."},{"id":"12","kind":"proposal","priority":"P3","area":"Location count","observation":"The number 6 floats at the far right of ALL LOCATIONS.","change":"Use a compact 6 locations label or count badge beside the heading."},{"id":"13","kind":"proposal","priority":"P2","area":"Selected server","observation":"Lisbon is tinted but its selected state has only color.","change":"Add a checkmark or Selected label."},{"id":"14","kind":"proposal","priority":"P2","area":"Selected-server latency","observation":"27 ms is near the row chevron with little room.","change":"Use a fixed right-aligned latency column and separate chevron gutter."},{"id":"15","kind":"proposal","priority":"P3","area":"Flag artwork","observation":"The small rectangular flags are simplified and visually inconsistent.","change":"Use a consistent flag asset set at equal dimensions."},{"id":"16","kind":"proposal","priority":"P2","area":"Map geography","observation":"The current screenshot and rendered mock both use coarse continent polygons that obscure recognizable regions.","change":"Refine the shared map artwork with clearer continental silhouettes while retaining its muted visual weight."},{"id":"17","kind":"proposal","priority":"P2","area":"Map markers","observation":"Several dots have no labels or visual connection to listed servers.","change":"Use a selected marker plus restrained labeled server markers."},{"id":"18","kind":"proposal","priority":"P2","area":"Lisbon callout","observation":"The callout sits below the marker without a connector.","change":"Add a small pointer anchored to the selected marker."},{"id":"19","kind":"proposal","priority":"P2","area":"Callout status dot","observation":"A tiny blue dot appears at the right of Lisbon metadata.","change":"Give it a meaning label or remove it as redundant decoration."},{"id":"20","kind":"proposal","priority":"P3","area":"Callout metadata","observation":"Portugal - pt-04 - 27 ms is narrow and faint.","change":"Increase its size and use clear separators with equal spacing."},{"id":"21","kind":"proposal","priority":"P2","area":"Account button","observation":"GO in a pale circle could be an action or initials.","change":"Show an account avatar with an Account label or recognizable profile icon."},{"id":"22","kind":"proposal","priority":"P2","area":"Footer IP state","observation":"Not hidden is visually as quiet as other metadata.","change":"Emphasize IP not hidden while disconnected."},{"id":"23","kind":"proposal","priority":"P2","area":"Footer route state","observation":"No route is technical language for a consumer connection screen.","change":"Use Not connected as the route summary, retaining route details in diagnostics."},{"id":"24","kind":"proposal","priority":"P2","area":"Diagnostics link","observation":"View diagnostics is faint at the far right footer.","change":"Increase contrast and add the outward arrow shown in the target."},{"id":"25","kind":"proposal","priority":"P3","area":"Privacy card size","observation":"The large card carries a short heading and one line of copy.","change":"Reduce its height or add a clear connection-status detail within the reserved space."},{"id":"26","kind":"proposal","priority":"P2","area":"Application font parity","observation":"The current title and body labels mix narrow display text and widely spaced metadata, while the target uses a compact sans-serif hierarchy.","change":"Match the target sans-serif family and weights across titles, location rows and metadata."},{"id":"27","kind":"proposal","priority":"P2","area":"Map marker parity","observation":"Current map dots have very thin outlines and fewer visible points than the target's white-ring markers.","change":"Restore the target marker set and use its consistent white ring thickness."},{"id":"28","kind":"proposal","priority":"P3","area":"Map backdrop parity","observation":"A large pale circular disk is visible behind the current map but absent from the rendered target.","change":"Use the target's smooth pale background without the prominent circular boundary."}],"sha256":"b00daf8458f69f7850ec3a7cf335d77472c52b9e4f23f4efc053d7893fef0052","has_mock":true,"reference":null,"legacy":[]},{"id":"self_align","baseline":"screenshot-baselines/screens/self_align_720p.png","summary":"The staggered positions are intentional SelfAlign examples. Fourteen proposals clarify the geometry and labels; the screenshot does not support 25 independent issues. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Parent frame","observation":"The outlined parent has no label identifying its alignment.","change":"Label it Column parent with its default align-items value."},{"id":"02","kind":"proposal","priority":"P2","area":"Axis context","observation":"The subtitle says alignment but does not identify the horizontal cross axis.","change":"Add a horizontal cross-axis arrow above the frame."},{"id":"03","kind":"proposal","priority":"P2","area":"Vertical stacking","observation":"The three examples descend diagonally without explaining stacking.","change":"Add a vertical main-axis arrow outside the frame."},{"id":"04","kind":"proposal","priority":"P2","area":"Start specimen","observation":"FlexStart left is separated from the border by an unlabeled inset.","change":"Annotate the intentional inset so it is not mistaken for alignment error."},{"id":"05","kind":"proposal","priority":"P2","area":"Center specimen","observation":"Center has no guide showing the parent's center.","change":"Add a faint center guide behind the specimen."},{"id":"06","kind":"proposal","priority":"P2","area":"End specimen","observation":"FlexEnd right has no guide tying its edge to the parent.","change":"Add a small right-edge alignment tick."},{"id":"07","kind":"proposal","priority":"P2","area":"API naming","observation":"FlexStart and FlexEnd are mixed with plain Center.","change":"Use consistent API names and put plain-language translations below them."},{"id":"08","kind":"proposal","priority":"P3","area":"Legend duplication","observation":"Left, Center and Right repeat the box labels without new information.","change":"Replace the pills with a small mapping from SelfAlign values to resulting positions."},{"id":"09","kind":"proposal","priority":"P2","area":"Specimen text","observation":"Text inside the large colored boxes is small.","change":"Increase labels to 14 px actual size while preserving box geometry."},{"id":"10","kind":"proposal","priority":"P2","area":"Inherited comparison","observation":"All three children override alignment, so inheritance is unseen.","change":"Add a separate labeled default-alignment comparison outside the existing fixture."},{"id":"11","kind":"proposal","priority":"P3","area":"Title wording","observation":"SelfAlign Feature Demo repeats generic demo wording.","change":"Use SelfAlign: child alignment overrides."},{"id":"12","kind":"proposal","priority":"P3","area":"Summary line","observation":"Each element picks its own position repeats the subtitle.","change":"Replace it with a concrete explanation that the parent remains a column."},{"id":"13","kind":"proposal","priority":"P2","area":"Color key","observation":"Green, brown and orange have no reason beyond position.","change":"Add textual value labels to the legend so color is optional for interpretation."},{"id":"14","kind":"proposal","priority":"P3","area":"Page footprint","observation":"The compact diagram floats inside broad empty margins.","change":"Center the complete title-diagram-legend group vertically with even top and bottom space."}],"sha256":"716c7715cb4afb29a2f24882f5c07448f7ba994f9e2e2c81fa4b01a239f55167","has_mock":false,"reference":null,"legacy":[{"id":"self_align","screen":"self_align","baseline":"baseline_screenshots/self_align.png","current":"screenshot-baselines/screens/self_align_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Current capture removes FlexStart focus outline. The three staggered blocks intentionally demonstrate self alignment. Improve reference guides and labels rather than placing all three on one row.","sha256":"a731cee983c262b160a9bee54bee24b52ce3464afa0250e213e7756ed66896a5","additional_findings":[]}]},{"id":"separators","baseline":"screenshot-baselines/screens/separators_720p.png","summary":"The screen clearly presents horizontal, labeled and vertical separators. Seventeen proposals improve specimen organization while preserving deliberate thickness and color differences. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Right card heading","observation":"Vertical Separators also contains a horizontal color gallery.","change":"Rename the card Mixed separator examples or split the gallery into its own subsection."},{"id":"02","kind":"proposal","priority":"P2","area":"Default sample label","observation":"Basic separator - default style omits the actual thickness.","change":"Add the default pixel thickness to its label."},{"id":"03","kind":"proposal","priority":"P2","area":"Six-pixel sample","observation":"The thick line has a dimension in text but no direct ruler.","change":"Add a small thickness marker beside the line."},{"id":"04","kind":"proposal","priority":"P2","area":"Partial-width sample","observation":"60% centered has no full-width reference.","change":"Show a faint full-width guide behind the purple specimen."},{"id":"05","kind":"proposal","priority":"P2","area":"Labeled OR sample","observation":"OR has no explanation of its text gap behavior.","change":"Add a caption naming automatic label gap sizing."},{"id":"06","kind":"proposal","priority":"P2","area":"Labeled Settings sample","observation":"Settings differs from OR in color and word length simultaneously.","change":"Add a note identifying the long-label and accent-color variation."},{"id":"07","kind":"proposal","priority":"P2","area":"Navigation sample","observation":"Home, Settings, Profile and Help look like a working navigation bar.","change":"Label the row Static navigation example unless it is interactive."},{"id":"08","kind":"proposal","priority":"P2","area":"Vertical color changes","observation":"Three vertical dividers use different colors without a key.","change":"Add small color names below the sample or a concise caption."},{"id":"09","kind":"proposal","priority":"P3","area":"Vertical dimensions","observation":"The vertical separators have no stated height or thickness.","change":"Display their dimensions beneath the navigation example."},{"id":"10","kind":"proposal","priority":"P3","area":"Color gallery width","observation":"The four color lines are long but have no width specification.","change":"Add one shared Full width label for the gallery."},{"id":"11","kind":"proposal","priority":"P2","area":"Color gallery semantics","observation":"Blue, Green, Purple and Orange identify hues but not tokens.","change":"Include token names or hex values beside the color labels."},{"id":"12","kind":"proposal","priority":"P2","area":"Section hierarchy","observation":"Color Gallery is embedded in a separator while Labeled Separators is a heading.","change":"Use a consistent subsection-heading treatment for both."},{"id":"13","kind":"proposal","priority":"P3","area":"Footer sentence","observation":"Separators help organize and structure UI content states no testable detail.","change":"Replace it with a note that line dimensions remain fixed across color variants."},{"id":"14","kind":"proposal","priority":"P2","area":"Sample grouping","observation":"Descriptions and lines are separated only by white space.","change":"Use consistent labeled specimen rows with equal text-to-line gaps."},{"id":"15","kind":"proposal","priority":"P3","area":"Left card density","observation":"The left card has six samples while the right has a large navigation sample and four colors.","change":"Align subsection baselines to make comparison easier."},{"id":"16","kind":"proposal","priority":"P3","area":"Heading size","observation":"The page title is much larger than sample metadata.","change":"Slightly reduce the title and give the specifications more readable space."},{"id":"17","kind":"proposal","priority":"P2","area":"Decorative-versus-structural distinction","observation":"The screen gives no example of a separator in ordinary content.","change":"Add a small labeled before/after content grouping example outside the existing specimens."}],"sha256":"dbea58271005366101f89dd8efa4b79f9962c06847ee207aa89d151068759a36","has_mock":false,"reference":null,"legacy":[{"id":"separators","screen":"separators","baseline":"baseline_screenshots/separators.png","current":"screenshot-baselines/screens/separators_720p.png","pixel_identical":true,"size":[1280,720],"summary":"Pixel-identical. Horizontal and vertical examples share current findings. Blue, green, purple and orange strokes intentionally illustrate customization, not an inconsistent product palette.","sha256":"dbea58271005366101f89dd8efa4b79f9962c06847ee207aa89d151068759a36","additional_findings":[]}]},{"id":"setting_row_showcase","baseline":"screenshot-baselines/screens/setting_row_showcase_720p.png","summary":"The rows demonstrate several control families, but the visible footer advertises specimens that are absent. Twenty proposals and observed layout issues are supportable without inferring control behavior. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"Footer inventory","observation":"Toggle, Stepper, Slider, Dropdown, Display lists dropdown and display examples that are not visible.","change":"Show those specimen rows or restrict the footer to the three visible families."},{"id":"02","kind":"proposal","priority":"P2","area":"Control columns","observation":"Toggles and steppers align at the right edge, while sliders sit near the center.","change":"Use one shared control column across row types."},{"id":"03","kind":"proposal","priority":"P2","area":"Value column","observation":"80% and 65% sit far from their sliders.","change":"Place percentages immediately after each slider in a consistent value column."},{"id":"04","kind":"proposal","priority":"P2","area":"Slider track","observation":"The dark tracks do not show a filled portion.","change":"Add a visible value fill while retaining the green thumb."},{"id":"05","kind":"proposal","priority":"P2","area":"Master slider mapping","observation":"The 80% thumb appears only about two-thirds across the visible track.","change":"Add labeled endpoints or fix the visual mapping so the reported percentage matches the usable range."},{"id":"06","kind":"proposal","priority":"P2","area":"Music slider mapping","observation":"65% appears just right of the track midpoint.","change":"Use the same explicit range mapping as Master Volume and label its endpoints."},{"id":"07","kind":"proposal","priority":"P2","area":"Toggle state text","observation":"Music and Sound Effects are blue and Vibration gray, without state words.","change":"Add On and Off text beside the switches."},{"id":"08","kind":"proposal","priority":"P2","area":"Label hierarchy","observation":"Master Volume and Music Volume are larger than Music, Sound Effects and Vibration.","change":"Use one label size for all setting rows."},{"id":"09","kind":"proposal","priority":"P2","area":"Language arrows","observation":"The thin chevrons around English are small and faint.","change":"Use clearer chevrons with consistent visible button bounds."},{"id":"10","kind":"proposal","priority":"P2","area":"Graphics arrows","observation":"High floats between two tiny chevrons with no grouping.","change":"Put the three elements in a compact outlined stepper group."},{"id":"11","kind":"proposal","priority":"P3","area":"Language option context","observation":"English has no indication of position within available choices.","change":"Add a small option count in the specimen caption."},{"id":"12","kind":"proposal","priority":"P2","area":"Graphics label","observation":"Graphics is broad while the selected value is High.","change":"Rename it Graphics quality."},{"id":"13","kind":"proposal","priority":"P2","area":"Section spacing","observation":"Large blank gaps separate Toggles, Options and Volume.","change":"Reduce gaps and add thin neutral dividers to clarify grouping."},{"id":"14","kind":"proposal","priority":"P3","area":"Title panel","observation":"The title bar blends into the larger content panel.","change":"Add a modest gap or divider below the title."},{"id":"15","kind":"proposal","priority":"P2","area":"Section captions","observation":"TOGGLES, OPTIONS and VOLUME are small muted labels.","change":"Increase caption size and align their baselines to a consistent inset."},{"id":"16","kind":"proposal","priority":"P2","area":"Music relationship","observation":"Music appears as both a toggle and Music Volume in separate groups.","change":"Add a brief note explaining the relationship between enablement and volume."},{"id":"17","kind":"proposal","priority":"P2","area":"Row boundaries","observation":"Wide empty space separates labels and controls with no row guides.","change":"Add subtle full-width row separators to aid horizontal scanning."},{"id":"18","kind":"proposal","priority":"P3","area":"Slider size","observation":"The 152 px tracks occupy a small fraction of the wide panel.","change":"Increase track width to make percentage differences easier to compare."},{"id":"19","kind":"proposal","priority":"P2","area":"Initial values","observation":"The screen has no summary of the demonstrated defaults.","change":"Add a compact default-state summary below the specimen panel."},{"id":"20","kind":"proposal","priority":"P3","area":"Footer contrast","observation":"The small family list is dim on the black margin.","change":"Increase its contrast after correcting the inventory."}],"sha256":"9634e0131a8695bb1d4acabafa4ba52ae6843cb28cf7e9e5aafa9a23c8017620","has_mock":false,"reference":null,"legacy":[]},{"id":"shop_interface","baseline":"screenshot-baselines/screens/shop_interface_720p.png","summary":"The store has a coherent parchment treatment. Small metadata, basket controls and alignment need refinement against the richer mocks.html target. Compared visually with the rendered mocks.html target at 1280 × 720.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"List headings","observation":"TYPE, STOCK and PRICE do not align with their data columns.","change":"Align headings to the same column grid as the rows."},{"id":"02","kind":"defect","priority":"P2","area":"Basket count","observation":"5 items is tiny in the basket heading corner.","change":"Increase it to readable 12 px text and bring it closer to Your basket."},{"id":"03","kind":"defect","priority":"P2","area":"Gold remaining","observation":"Gold remaining: 3,570 G is very small beneath Total.","change":"Increase it to 13 px and give it its own line spacing."},{"id":"04","kind":"defect","priority":"P2","area":"Guild note","observation":"The note almost touches the item panel's bottom border.","change":"Add at least 10 px bottom inset."},{"id":"05","kind":"defect","priority":"P2","area":"Footer input hints","observation":"A Select, X Add to cart and Y Remove are tiny against the dark wood.","change":"Use readable text and distinct keycaps."},{"id":"06","kind":"proposal","priority":"P2","area":"Market context","observation":"WILLOWBROOK - MARKET DISTRICT is widely spaced and small.","change":"Increase actual text size and reduce tracking."},{"id":"07","kind":"proposal","priority":"P2","area":"Day status","observation":"Day 12 and its tiny sun mark are difficult to read.","change":"Use a readable day label and a recognizable sun icon."},{"id":"08","kind":"proposal","priority":"P3","area":"Store ornaments","observation":"The title is flanked by asterisks rather than the richer target ornaments.","change":"Replace them with balanced decorative motifs matching the parchment style."},{"id":"09","kind":"proposal","priority":"P2","area":"Gold total","observation":"3,750 lacks a visible unit beside the number.","change":"Add G or a labeled coin unit while retaining YOUR GOLD below."},{"id":"10","kind":"proposal","priority":"P2","area":"Buy and Sell tabs","observation":"Sell is text on the header with a weak tab boundary.","change":"Give both tabs equal dimensions and a clearer active underline."},{"id":"11","kind":"proposal","priority":"P2","area":"Selected item","observation":"The potion row uses a pale fill and thin outline only.","change":"Add a small selected marker or stronger left accent."},{"id":"12","kind":"proposal","priority":"P3","area":"Item artwork","observation":"Sword, armor and shield icons are tiny simplified shapes.","change":"Use consistent item artwork with stronger silhouettes at equal visual size."},{"id":"13","kind":"proposal","priority":"P2","area":"Stock values","observation":"Ordinary stock numbers are small and far from their heading.","change":"Increase size and right-align them in a fixed column."},{"id":"14","kind":"proposal","priority":"P2","area":"Low stock","observation":"3 left and 2 left use red text but no additional marker.","change":"Add a Low stock badge while retaining the numeric count."},{"id":"15","kind":"proposal","priority":"P2","area":"Price formatting","observation":"Prices combine amount and G with inconsistent perceived spacing.","change":"Use a fixed gap and align all numeric values to the right."},{"id":"16","kind":"proposal","priority":"P2","area":"Detail category","observation":"Consumable is extremely letter-spaced and small.","change":"Use a readable uppercase category label with normal tracking."},{"id":"17","kind":"proposal","priority":"P2","area":"Detail potion art","observation":"The large potion is a sparse outline compared with dense text styling.","change":"Add fill, highlights and a grounded shadow consistent with the target art."},{"id":"18","kind":"proposal","priority":"P2","area":"Detail price","observation":"50 G sits below the description without a Unit price label.","change":"Label it Price per item."},{"id":"19","kind":"proposal","priority":"P2","area":"Add to cart button","observation":"The button says Add to cart while the destination is called Your basket.","change":"Use Add to basket consistently."},{"id":"20","kind":"proposal","priority":"P2","area":"Basket quantities","observation":"x 3 and x 2 are small text with no visible adjustment controls.","change":"Add compact minus and plus controls beside each quantity."},{"id":"21","kind":"proposal","priority":"P2","area":"Remove action","observation":"Remove appears only in the footer with no visible basket affordance.","change":"Add a remove control to each basket line."},{"id":"22","kind":"proposal","priority":"P2","area":"Basket line pricing","observation":"150 G and 30 G are shown without explicit line-total context.","change":"Add a small Line total heading or unit-price detail."},{"id":"23","kind":"proposal","priority":"P2","area":"Purchase action","observation":"Purchase goods uses the same dark style as Add to cart.","change":"Give checkout the stronger primary emphasis and include 180 G in its label."},{"id":"24","kind":"proposal","priority":"P2","area":"Checkout spacing","observation":"Purchase goods nearly touches the basket panel bottom.","change":"Increase the lower inset to match the side padding."},{"id":"25","kind":"proposal","priority":"P3","area":"Footer status","observation":"Welcome, adventurer! repeats the greeting at the top.","change":"Use that status area for selected-item or basket feedback instead."},{"id":"26","kind":"proposal","priority":"P2","area":"Detail-title typography parity","observation":"Health Potion is light in the current detail panel while the rendered target uses a bold product heading.","change":"Increase the detail title weight and keep the description subordinate."},{"id":"27","kind":"proposal","priority":"P3","area":"Wood backdrop parity","observation":"The current background has broad angled dark facets behind the cards; the target uses an even wood-grain field.","change":"Match the target backdrop so geometric facets do not compete with the parchment panels."},{"id":"28","kind":"proposal","priority":"P2","area":"Basket amount emphasis parity","observation":"150 G and 30 G are light in the current basket while the target uses bold line totals.","change":"Use the target's stronger amount weight to align basket scanning with the bold overall total."}],"sha256":"371f2b8c669479b5327342849c1389870297bed2d6823ab136d900dea26c5b4a","has_mock":true,"reference":null,"legacy":[]},{"id":"simple_button","baseline":"screenshot-baselines/screens/simple_button_720p.png","summary":"The compact card is coherent. Sixteen distinct proposals improve the button specimens and feedback; the static image does not justify 25 separate issues. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Main action label","observation":"Click Me! names the input gesture rather than the counter action.","change":"Use Add a click or Increment counter."},{"id":"02","kind":"proposal","priority":"P2","area":"Counter state","observation":"No clicks yet... hides the numeric initial value.","change":"Show Click count: 0 in a stable-width result region."},{"id":"03","kind":"proposal","priority":"P2","area":"Counter association","observation":"The gray pill has no label identifying it as button feedback.","change":"Add a small Result caption above the count."},{"id":"04","kind":"proposal","priority":"P2","area":"Subtitle","observation":"Go ahead, give it a click! repeats the main button wording.","change":"Explain that the main action increments the count."},{"id":"05","kind":"proposal","priority":"P2","area":"More Styles heading","observation":"More Styles is much smaller than surrounding labels.","change":"Increase it to a readable subsection heading."},{"id":"06","kind":"proposal","priority":"P2","area":"Secondary specimen","observation":"Secondary identifies a style but not its relationship to the counter.","change":"Add a caption stating whether variant buttons share the counter behavior."},{"id":"07","kind":"proposal","priority":"P2","area":"Outline specimen","observation":"The white button has a very fine lavender edge.","change":"Strengthen its outline without changing the outline-style specimen."},{"id":"08","kind":"proposal","priority":"P2","area":"Bottom specimen labels","observation":"Small, Pill and Buttons form a phrase instead of naming three variations.","change":"Give each specimen a standalone label describing its style."},{"id":"09","kind":"proposal","priority":"P2","area":"Pill specimen","observation":"Pill appears almost as rectangular as Small and Buttons.","change":"Label the intended radius numerically or render an unmistakable capsule in that specimen."},{"id":"10","kind":"proposal","priority":"P3","area":"Size comparison","observation":"Small is shown without a dimension reference.","change":"Add its height below the row and the main button height in the same legend."},{"id":"11","kind":"proposal","priority":"P3","area":"Button alignment","observation":"The main button and lower rows use slightly different left insets.","change":"Align all specimen groups to a shared inner card grid."},{"id":"12","kind":"proposal","priority":"P2","area":"Color comparison","observation":"Pastel green, pink and gold buttons change hue and label simultaneously.","change":"Use a small legend that names each token so comparison is explicit."},{"id":"13","kind":"proposal","priority":"P2","area":"Reset action","observation":"No reset control is visible for the click count.","change":"Add a quiet Reset count action near the result."},{"id":"14","kind":"proposal","priority":"P3","area":"Footer space","observation":"A large blank region remains beneath the small buttons inside the card.","change":"Use it for specimen dimensions and shared behavior notes."},{"id":"15","kind":"proposal","priority":"P3","area":"Decoration distribution","observation":"Confetti dots are scattered far from the central card.","change":"Group them closer to the card or reduce their number to keep attention on the examples."},{"id":"16","kind":"proposal","priority":"P2","area":"Initial-state coverage","observation":"Only the zero-click state is visible.","change":"Add a companion activated-state baseline showing the counter feedback."}],"sha256":"82cc31ae8fe0da493612dcabbf7bb074e203bbea5aac2edded40cf392a50b3b9","has_mock":false,"reference":null,"legacy":[]},{"id":"split_pane_lab","baseline":"screenshot-baselines/screens/split_pane_lab_720p.png","summary":"The nested split geometry is deliberate. Sixteen proposals expose the dimensions and draggable boundaries without claiming unobserved dragging failures. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"Pane labels","observation":"sidebar, preview and details touch their panes' left edges.","change":"Inset each label by 12 px without changing split geometry."},{"id":"02","kind":"proposal","priority":"P2","area":"Vertical divider","observation":"The narrow vertical separator is hard to distinguish from a pane edge.","change":"Add a centered grip indicator within the divider."},{"id":"03","kind":"proposal","priority":"P2","area":"Horizontal divider","observation":"The horizontal bar has no visible drag handle.","change":"Add a short centered grip with a contrasting stroke."},{"id":"04","kind":"proposal","priority":"P2","area":"Ratio caption","observation":"sidebar 28% preview 62% is tiny beneath the title.","change":"Increase it to 13 px actual text."},{"id":"05","kind":"proposal","priority":"P2","area":"Ratio meaning","observation":"Preview 62% could be interpreted as a share of the whole screen.","change":"Label it Preview height: 62% of right pane."},{"id":"06","kind":"proposal","priority":"P2","area":"Sidebar ratio","observation":"Sidebar 28% has no dimension unit context.","change":"Label it Sidebar width: 28% of workspace."},{"id":"07","kind":"proposal","priority":"P2","area":"Details ratio","observation":"The details pane has no corresponding size readout.","change":"Show its complementary height percentage."},{"id":"08","kind":"proposal","priority":"P2","area":"Minimum limits","observation":"The screenshot shows no allowed resize range.","change":"Display the actual minimum and maximum ratios beside the readouts."},{"id":"09","kind":"proposal","priority":"P2","area":"Reset geometry","observation":"No reset action is visible.","change":"Add Reset to 28% / 62% above the workspace."},{"id":"10","kind":"proposal","priority":"P2","area":"Pixel dimensions","observation":"Large empty panes do not show how resizing affects their size.","change":"Display live width × height in each pane center."},{"id":"11","kind":"proposal","priority":"P2","area":"Nesting explanation","observation":"The title says drag either divider without explaining the nested split.","change":"Add a small diagram that shows the horizontal split belongs only to the right pane."},{"id":"12","kind":"proposal","priority":"P3","area":"Footer hint","observation":"The resize-cursor instruction is very small.","change":"Increase its size and align it with the workspace inset."},{"id":"13","kind":"proposal","priority":"P2","area":"Grip hit region","observation":"Thin visual dividers give little indication of their draggable extent.","change":"Show an external annotation describing the actual hit-region width."},{"id":"14","kind":"proposal","priority":"P3","area":"Pane headings","observation":"Lowercase labels are visually weak over large blank fields.","change":"Use consistent sentence-case headings with slightly larger type."},{"id":"15","kind":"proposal","priority":"P2","area":"Static review evidence","observation":"Only one split ratio is captured.","change":"Add labeled narrow-sidebar and tall-preview presets for additional baselines."},{"id":"16","kind":"proposal","priority":"P3","area":"Title line","observation":"The instruction is embedded in the page title.","change":"Separate Split Pane Lab from a short interaction subtitle."}],"sha256":"013a4fc6c2231b2592e8411cf135e089508fae079c51f060bcec76af4a996383","has_mock":false,"reference":null,"legacy":[]},{"id":"sports_settings","baseline":"screenshot-baselines/screens/sports_settings_720p.png","summary":"The sports settings preserve the mint accent and blurred scene, but unusual value markers, unclear units and dense metadata need refinement. Compared visually with the rendered mocks.html target at 1280 × 720.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"Controller tab hints","observation":"LB and RB labels are nearly microscopic in pale keycaps.","change":"Increase glyph size and keycap dimensions."},{"id":"02","kind":"proposal","priority":"P2","area":"Screen percentage value","observation":"100 appears without a percent symbol.","change":"Display 100%."},{"id":"03","kind":"proposal","priority":"P2","area":"Resolution formatting","observation":"2,560x1,440 uses thousands separators and a lowercase x.","change":"Use 2560 × 1440."},{"id":"04","kind":"proposal","priority":"P2","area":"Window mode value","observation":"Borderless window is followed by small dot marks.","change":"Replace ambiguous dots with clear cycling chevrons or a dropdown indicator."},{"id":"05","kind":"proposal","priority":"P2","area":"V Sync value","observation":"Enabled is followed by dots instead of a recognizable control.","change":"Use a consistent on/off control treatment."},{"id":"06","kind":"proposal","priority":"P2","area":"Anti-aliasing method","observation":"TSR is an unexplained acronym.","change":"Expand the method name in the help pane when selected."},{"id":"07","kind":"proposal","priority":"P2","area":"Dynamic resolution","observation":"Enabled has the same dot pattern as multi-choice settings.","change":"Distinguish binary settings from multi-choice selectors."},{"id":"08","kind":"proposal","priority":"P2","area":"Motion blur value","observation":"Motion blur shows 1 with no unit or scale.","change":"Use On or a labeled intensity percentage according to the real value meaning."},{"id":"09","kind":"proposal","priority":"P2","area":"Max FPS units","observation":"120 has no FPS suffix in the selected row.","change":"Display 120 FPS."},{"id":"10","kind":"proposal","priority":"P2","area":"Framerate target units","observation":"60 has no FPS suffix.","change":"Display 60 FPS and explain its relationship to dynamic resolution."},{"id":"11","kind":"proposal","priority":"P2","area":"Gamma endpoints","observation":"The gamma slider shows 2.2 without range labels.","change":"Show minimum and maximum values beneath the track."},{"id":"12","kind":"proposal","priority":"P2","area":"FPS endpoints","observation":"The Max FPS track has no endpoint labels.","change":"Label its supported range and any unlimited endpoint."},{"id":"13","kind":"proposal","priority":"P2","area":"Slider fill","observation":"Each mint track looks fully filled regardless of thumb position.","change":"Use distinct filled and remaining segments."},{"id":"14","kind":"proposal","priority":"P2","area":"Selected thumb","observation":"The dark thumb is small against the mint selection row.","change":"Increase thumb size or give it a light outline."},{"id":"15","kind":"proposal","priority":"P2","area":"Selection frame","observation":"The selected row touches the divider with little trailing space.","change":"Add a consistent gutter between the row edge and the help separator."},{"id":"16","kind":"proposal","priority":"P2","area":"Help title","observation":"Max FPS is smaller than the explanatory body text.","change":"Increase heading prominence and separate it from the body."},{"id":"17","kind":"proposal","priority":"P2","area":"Help line length","observation":"The explanation spans a wide, two-line measure.","change":"Constrain it to about 45 to 55 characters per line."},{"id":"18","kind":"proposal","priority":"P2","area":"Default value","observation":"Default value: 120 is visually similar to the body copy.","change":"Style the default as a labeled value pair with the FPS unit."},{"id":"19","kind":"proposal","priority":"P2","area":"Backdrop readability","observation":"The fence and figure remain visible behind all setting labels.","change":"Increase the opacity of the left backing panel for consistent text contrast."},{"id":"20","kind":"proposal","priority":"P3","area":"Divider accent","observation":"The mint vertical segment resembles a scrollbar without a label.","change":"Use a uniform pane divider or label the scroll indicator if it represents position."},{"id":"21","kind":"proposal","priority":"P2","area":"Category context","observation":"GRAPHICS appears under the active VIDEO tab but no page title is shown.","change":"Add Video settings as the local heading."},{"id":"22","kind":"proposal","priority":"P2","area":"Reset scope","observation":"Reset to default does not identify whether it affects the tab or all settings.","change":"Name the actual scope in the footer action."},{"id":"23","kind":"proposal","priority":"P2","area":"Ready status","observation":"Ready is indistinguishable from generic footer text.","change":"Use a clear Saved or No pending changes status if supported by the state model."},{"id":"24","kind":"proposal","priority":"P3","area":"Footer grouping","observation":"Ready, Y Reset and B Back are crowded at the right edge.","change":"Separate status from action groups and use consistent keycap spacing."},{"id":"25","kind":"proposal","priority":"P2","area":"Graphics quality relationship","observation":"Graphics quality and Texture quality both show Ultra with no hierarchy.","change":"Clarify whether texture is an override of the overall preset."},{"id":"26","kind":"proposal","priority":"P2","area":"Settings typography parity","observation":"The current settings labels are lighter and more widely spaced than the target's compact sans-serif labels.","change":"Match target font metrics and weight while preserving the existing row positions."},{"id":"27","kind":"proposal","priority":"P3","area":"Selected-row treatment parity","observation":"The current Max FPS row is uniformly mint while the target shades its label half darker.","change":"Restore the target's distinct label and value backgrounds within the selected row."},{"id":"28","kind":"proposal","priority":"P3","area":"Selection accent parity","observation":"The current Video underline and tall mint indicator are solid; the target uses a diagonal stripe detail.","change":"Match the target stripe treatment without changing indicator dimensions."}],"sha256":"f4147107cdcb705670f6843646fcb157139a6042cef16627e4b7980ba50763f4","has_mock":true,"reference":"inspiration/example_rematch.jpg","legacy":[]},{"id":"stepper_showcase","baseline":"screenshot-baselines/screens/stepper_showcase_720p.png","summary":"The value and card selectors are visible, but grouping and specimen metadata are weak. Eighteen actionable proposals are supported by this static state. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Left steppers","observation":"Thin arrows float around values without visible grouping.","change":"Place each arrow-value-arrow group in a subtle outlined region."},{"id":"02","kind":"proposal","priority":"P2","area":"Resolution text","observation":"2560x1440 uses a compact lowercase x.","change":"Use 2560 × 1440."},{"id":"03","kind":"proposal","priority":"P2","area":"Framerate value","observation":"60 lacks a unit.","change":"Show 60 FPS."},{"id":"04","kind":"proposal","priority":"P2","area":"Stepper arrows","observation":"All arrow glyphs are small and muted.","change":"Increase glyph size and contrast while retaining consistent spacing."},{"id":"05","kind":"proposal","priority":"P2","area":"Choice count","observation":"None of the five steppers reveals its number of options.","change":"Add a compact index/count in specimen metadata."},{"id":"06","kind":"proposal","priority":"P2","area":"Boundary behavior","observation":"The initial values do not explain whether arrows wrap.","change":"Add a footer note stating the actual wrap or clamp behavior."},{"id":"07","kind":"proposal","priority":"P2","area":"Card-selector labels","observation":"Healer Warrior Mage reads as one line of words.","change":"Separate choices into clear segments with consistent spacing."},{"id":"08","kind":"proposal","priority":"P2","area":"Selected class","observation":"Warrior is distinguished mainly by brighter text.","change":"Add a selected underline or compact marker."},{"id":"09","kind":"proposal","priority":"P2","area":"Card text hierarchy","observation":"Warrior and the description are separated by a large empty gap.","change":"Bring the description closer to the title."},{"id":"10","kind":"proposal","priority":"P2","area":"Card description","observation":"Heavy armor, melee attacks, high defense is small for the card size.","change":"Increase it to 14 to 16 px actual size."},{"id":"11","kind":"proposal","priority":"P3","area":"Card artwork","observation":"A large solid coral card contains only two text blocks.","change":"Add a restrained class emblem or compact stat row."},{"id":"12","kind":"proposal","priority":"P2","area":"Card association","observation":"The Warrior card has no connector to the selector above.","change":"Align its title with the active tab and keep the active accent consistent."},{"id":"13","kind":"proposal","priority":"P3","area":"Card color meaning","observation":"The coral fill has no explanatory legend.","change":"Identify it as Warrior accent in the specimen notes."},{"id":"14","kind":"proposal","priority":"P2","area":"Section comparison","observation":"Stepper Variants and Card Selector do not state the shared underlying behavior.","change":"Add a subtitle explaining that both cycle through a finite option list."},{"id":"15","kind":"proposal","priority":"P3","area":"Panel whitespace","observation":"Both panels leave substantial empty space below their controls.","change":"Use the lower area for option counts and interaction notes."},{"id":"16","kind":"proposal","priority":"P2","area":"Default state","observation":"Medium, English, Normal and 60 appear without default markers.","change":"Add a compact Current defaults summary or reset control."},{"id":"17","kind":"proposal","priority":"P3","area":"Heading alignment","observation":"The left heading aligns left while Card Selector is centered.","change":"Use a consistent heading alignment across the two panes."},{"id":"18","kind":"proposal","priority":"P2","area":"Keyboard guidance","observation":"No visible hint explains how the active selector changes choices.","change":"Add a guide matched to the implemented arrow and focus behavior."}],"sha256":"a86885f7ca278450b8e862de3b2f8b4bc1f0e5da5522374987de6dc823856aa0","has_mock":false,"reference":null,"legacy":[]},{"id":"styled_text_lab","baseline":"screenshot-baselines/screens/styled_text_lab_720p.png","summary":"The font-weight and fallback cases are intentional and confirmed in source. Eighteen proposals improve annotation and legibility without treating fallback-to-regular as a defect. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Top specimen caption","observation":"DGOne + DGOne@bold is tiny above the sample.","change":"Increase metadata to a readable 12 to 13 px actual size."},{"id":"02","kind":"proposal","priority":"P2","area":"Regular/bold sample","observation":"Text begins flush against the colored block edge.","change":"Inset the specimen text while preserving its measured available width."},{"id":"03","kind":"proposal","priority":"P2","area":"Weight-only specimen","observation":"one colour two weights does not identify which words request bold.","change":"Add a run-by-run weight legend beneath the sample."},{"id":"04","kind":"proposal","priority":"P2","area":"Colored bold specimen","observation":"BOLD changes both weight and color.","change":"Explicitly label this as a combined weight-and-color example."},{"id":"05","kind":"proposal","priority":"P2","area":"Wrap specimen","observation":"The bold span crosses the line break without a visible run boundary key.","change":"Add a source-text caption marking the bold span."},{"id":"06","kind":"proposal","priority":"P2","area":"Wrap width","observation":"The wrapping block has no width value shown.","change":"Annotate the exact content width used for measurement."},{"id":"07","kind":"proposal","priority":"P2","area":"Wrap line spacing","observation":"Pixel-text lines are tightly packed.","change":"Add a separate comparison with increased line height while preserving the current baseline specimen."},{"id":"08","kind":"proposal","priority":"P2","area":"Hard-break caption","observation":"The caption exposes a literal backslash-n token without explanation.","change":"Label it Explicit newline and show the escaped source in metadata."},{"id":"09","kind":"proposal","priority":"P2","area":"Hard-break sample","observation":"Heading and body text have very little vertical separation.","change":"Add line boxes or baseline guides to make the hard-break behavior inspectable."},{"id":"10","kind":"proposal","priority":"P2","area":"Second heading","observation":"Another heading continues close to the preceding body line.","change":"Use a small external run label to distinguish separate weighted spans."},{"id":"11","kind":"proposal","priority":"P2","area":"Fallback caption","observation":"The no-@bold explanation is tiny and stretches across the block.","change":"Use a readable two-line caption with the expected regular fallback emphasized."},{"id":"12","kind":"proposal","priority":"P2","area":"Fallback comparison","observation":"asks for regular and asks for bold also change color.","change":"Add a same-color comparison so the weight fallback can be assessed directly."},{"id":"13","kind":"proposal","priority":"P2","area":"Font identity","observation":"The fallback sample names default face without a readable font-family label.","change":"Show the actual registered family in the caption."},{"id":"14","kind":"proposal","priority":"P3","area":"Sample numbering","observation":"Five test cases have captions but no stable identifiers.","change":"Number them so screenshots can be compared with test definitions."},{"id":"15","kind":"proposal","priority":"P2","area":"Expected results","observation":"No case states its expected visual outcome beside the specimen.","change":"Add one short expected-result line per case."},{"id":"16","kind":"proposal","priority":"P3","area":"Page balance","observation":"All samples occupy the left side, leaving a large blank right region.","change":"Use the right region for source spans and resolved weights."},{"id":"17","kind":"proposal","priority":"P2","area":"Glyph metric comparison","observation":"Different weights are visible but baseline and advance differences are not annotated.","change":"Add optional baseline and advance-width guides outside the existing text."},{"id":"18","kind":"proposal","priority":"P3","area":"Title hierarchy","observation":"Styled Text Lab and sample captions are similarly letter-spaced.","change":"Use a clearer title size and neutral metadata typography."}],"sha256":"e24fbf539d8d6ee7e258d13f2d497c72e2b525e0fc41118f39afeb6d1d3db698","has_mock":false,"reference":null,"legacy":[]},{"id":"sync_scroll_lab","baseline":"screenshot-baselines/screens/sync_scroll_lab_720p.png","summary":"The unequal document lengths and header-only horizontal synchronization are deliberate. Eighteen proposals clarify the measured comparison; the zero-offset image cannot prove or disprove synchronization. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Group-one subtitle","observation":"The explanation of the short pane stopping is tiny.","change":"Increase explanatory text to 12 to 13 px actual size."},{"id":"02","kind":"proposal","priority":"P2","area":"Document text","observation":"Line numbers and code are very small in all three panes.","change":"Increase specimen text size while retaining the row-height relationship."},{"id":"03","kind":"proposal","priority":"P2","area":"Before/after content","observation":"Both sides visibly show value = compute(x) on highlighted rows.","change":"Use a small actual code difference so before and after are meaningful labels."},{"id":"04","kind":"proposal","priority":"P2","area":"Change colors","observation":"Before is green and after is red without a key.","change":"Add a legend explaining the color mapping or use conventional removed/added mapping."},{"id":"05","kind":"proposal","priority":"P2","area":"Short-pane role","observation":"Short has fewer rows but the same visible viewport height.","change":"Label it Short content, 24 rows to distinguish content length from viewport height."},{"id":"06","kind":"proposal","priority":"P2","area":"Y status","observation":"y: before 0 after 0 short 0 is tiny and compressed.","change":"Use three labeled offset cells with px units."},{"id":"07","kind":"proposal","priority":"P2","area":"Sync state","observation":"y-in-sync and short-following are terse implementation-like phrases.","change":"Use readable badges such as Matching offsets and Short pane following."},{"id":"08","kind":"proposal","priority":"P2","area":"Clamped state","observation":"The initial frame does not show the short pane at its endpoint.","change":"Add a preset that scrolls the long panes beyond the short pane maximum."},{"id":"09","kind":"proposal","priority":"P2","area":"Group-two explanation","observation":"Header tracks the table's x is a long tiny line.","change":"Use a clear heading and one readable instruction line."},{"id":"10","kind":"proposal","priority":"P2","area":"Header cells","observation":"col 1 through col 8 are tiny and flush to their cell starts.","change":"Increase text size and use consistent inner padding."},{"id":"11","kind":"proposal","priority":"P2","area":"Table cells","observation":"r1c1-style labels are hard to scan across wide empty cells.","change":"Add faint column guides and readable row/column identifiers."},{"id":"12","kind":"proposal","priority":"P2","area":"Header scrollbar","observation":"The header shows its own horizontal scrollbar above the table.","change":"Label it as a synchronized independent scrollbar so the duplicate bars are intentional."},{"id":"13","kind":"proposal","priority":"P2","area":"X status","observation":"x: header 0 table 0 is difficult to read below the table.","change":"Use the same offset-cell treatment as the Y group."},{"id":"14","kind":"proposal","priority":"P2","area":"Axis distinction","observation":"Group 1 and Group 2 are named numerically rather than by tested axis.","change":"Use Vertical group and Horizontal header/table group headings."},{"id":"15","kind":"proposal","priority":"P2","area":"Reset control","observation":"No visible control returns both groups to a known state.","change":"Add Reset all offsets outside the scroll regions."},{"id":"16","kind":"proposal","priority":"P3","area":"Right-side space","observation":"The fixture ends around three-quarters of the screen width.","change":"Use the remaining area for the synchronization rules and expected clamping behavior."},{"id":"17","kind":"proposal","priority":"P2","area":"Viewport metrics","observation":"The thumbnail-like panes have no viewport dimensions shown.","change":"Display viewport and content sizes in a compact spec table."},{"id":"18","kind":"proposal","priority":"P2","area":"Driver instruction","observation":"The page does not say which pane the reviewer should scroll first.","change":"Add a concrete before-pane and table-pane test sequence."}],"sha256":"825c267f26c6c4ed5287f8901368c5e682946dd468d3aeb29513e1270e7108ce","has_mock":false,"reference":null,"legacy":[]},{"id":"system_profile_lab","baseline":"screenshot-baselines/screens/system_profile_lab_720p.png","summary":"The profiler is stopped with no samples, so zero data and unavailable process metrics are not evidence of a runtime failure. Twenty proposals improve the empty-state design and measurement labels. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Empty FPS metric","observation":"0.0 FPS is shown before any frames are recorded.","change":"Use an em dash or No data until samples exist."},{"id":"02","kind":"proposal","priority":"P2","area":"Empty frame timing","observation":"Avg 0.00 ms/frame reads as a measured zero.","change":"Render an explicit unmeasured state consistently across timing values."},{"id":"03","kind":"proposal","priority":"P2","area":"Percentile labels","observation":"p50, p95 and p99 are packed into one line.","change":"Use separate labeled metric blocks with ms units on each."},{"id":"04","kind":"proposal","priority":"P2","area":"Sample window","observation":"Last 0 frames is appended to the metric sentence.","change":"Give sample count and collection window their own metadata label."},{"id":"05","kind":"proposal","priority":"P2","area":"Recording state","observation":"Recording stopped is small and visually detached from Start recording.","change":"Place a status badge beside the recording control."},{"id":"06","kind":"proposal","priority":"P2","area":"Primary action","observation":"Start recording has the same emphasis as Reset and Sort recent.","change":"Make recording the primary action in the stopped state."},{"id":"07","kind":"proposal","priority":"P2","area":"Pause view control","observation":"Pause view appears while no samples exist.","change":"Explain view pause independently of recording or disable it until there is a view to pause."},{"id":"08","kind":"proposal","priority":"P2","area":"Sort action","observation":"Sort recent does not reveal sorting direction or selected column.","change":"Show Sort: recent average, descending with a matching header marker."},{"id":"09","kind":"proposal","priority":"P2","area":"Chart empty state","observation":"No samples is placed near the upper-left of a large empty plot.","change":"Center a helpful empty state with Start recording to collect frame timings."},{"id":"10","kind":"proposal","priority":"P2","area":"Chart identity","observation":"The large plot has no title or axes in its empty state.","change":"Add Frame time history and labeled ms/time axes."},{"id":"11","kind":"proposal","priority":"P2","area":"Table empty state","observation":"No system samples yet repeats the chart's empty message.","change":"Explain that system timings will appear after recording starts."},{"id":"12","kind":"proposal","priority":"P2","area":"CPU unavailable","observation":"Process CPU: unavailable provides no local explanation.","change":"Add a concise platform-support note or diagnostic reason when known."},{"id":"13","kind":"proposal","priority":"P2","area":"Memory unavailable","observation":"Resident memory: unavailable is buried in the same sentence.","change":"Use separate CPU and memory metric cards with clear unavailable values."},{"id":"14","kind":"proposal","priority":"P2","area":"Add load action","observation":"Add load gives no indication of the synthetic load type.","change":"Label it Add synthetic workload and show its enabled state."},{"id":"15","kind":"proposal","priority":"P2","area":"Hide panel action","observation":"Hide panel does not identify what disappears.","change":"Rename it Hide profiler panel."},{"id":"16","kind":"proposal","priority":"P2","area":"Table units","observation":"Recent avg and Overall avg use parentheses while Last frame ms does not.","change":"Use one heading format with ms units consistently."},{"id":"17","kind":"proposal","priority":"P2","area":"System/phase hierarchy","observation":"System / phase combines two concepts in a single column heading.","change":"Clarify the expected hierarchy with a sample or two-line heading."},{"id":"18","kind":"proposal","priority":"P3","area":"Toolbar layout","observation":"Add load and Hide panel occupy a separate top row from the profiler controls.","change":"Group demo controls separately with a small Demo workload caption."},{"id":"19","kind":"proposal","priority":"P2","area":"Reset scope","observation":"Reset is ambiguous between samples, view state and workload.","change":"Rename it Clear samples if that is its actual effect."},{"id":"20","kind":"proposal","priority":"P3","area":"Unused lower area","observation":"The table empty state leaves a broad black field.","change":"Use a compact bordered table shell sized to the available data area."}],"sha256":"0681d6834ac760cf6550b90c194c4a281e06124ce8187822804ce5fb959dc831","has_mock":false,"reference":null,"legacy":[{"id":"system_profile_lab","screen":"system_profile_lab","baseline":"baseline_screenshots/system_profile_lab.png","current":"screenshot-baselines/screens/system_profile_lab_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Current capture removes Add load focus outline. Both are the stopped, empty state with zero timing statistics and unavailable CPU/RAM. Neither demonstrates live refresh rate or recording performance.","sha256":"654d14b638087e160a3bd407807297acd7ac8039098c243437b0d3ae438378bf","additional_findings":[]}]},{"id":"tab_container","baseline":"screenshot-baselines/screens/tab_container_720p.png","summary":"The active Profile tab is clear, but the static profile content and footer actions need stronger demo framing. Eighteen supportable findings avoid claiming unseen tab behavior. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Page identity","observation":"The panel begins directly with tabs and has no demo title.","change":"Add Tab container demo above the tab strip."},{"id":"02","kind":"proposal","priority":"P2","area":"Profile heading","observation":"Profile Settings suggests editable controls but shows only text.","change":"Use Profile details for the displayed read-only state."},{"id":"03","kind":"proposal","priority":"P2","area":"Username row","observation":"Username and player_one share the same weight in one string.","change":"Separate label and value into aligned columns."},{"id":"04","kind":"proposal","priority":"P2","area":"Email row","observation":"The email address is presented as plain prose.","change":"Use a clear value field with a copy affordance if appropriate to the demo."},{"id":"05","kind":"proposal","priority":"P2","area":"Subscription value","observation":"Premium is plain text among metadata.","change":"Use a small subscription badge to distinguish status from identity fields."},{"id":"06","kind":"proposal","priority":"P2","area":"Last login","observation":"Today at 10:30 AM lacks a time-zone or fixed baseline context.","change":"Use a stable sample date/time label or identify it as fixture data."},{"id":"07","kind":"proposal","priority":"P2","area":"Field spacing","observation":"Five short rows are spread across a tall empty content panel.","change":"Reduce row gaps and use a compact details grid."},{"id":"08","kind":"proposal","priority":"P2","area":"Content width","observation":"All content is left-aligned inside a very wide blank white panel.","change":"Constrain the details region or add a second metadata column."},{"id":"09","kind":"proposal","priority":"P2","area":"OK action","observation":"OK is dark gray and visually resembles a disabled action.","change":"Use a clear primary action style if it is enabled."},{"id":"10","kind":"proposal","priority":"P2","area":"Apply action","observation":"Apply appears active despite no visible editable fields.","change":"Show a No pending changes state or omit Apply from this read-only tab."},{"id":"11","kind":"proposal","priority":"P2","area":"Cancel action","observation":"Cancel has no context for what is canceled in the static details view.","change":"Use Close for a read-only demonstration or explain the editable state."},{"id":"12","kind":"proposal","priority":"P2","area":"Footer alignment","observation":"The button group ends before the content panel's right edge.","change":"Align the footer group to the content right inset."},{"id":"13","kind":"proposal","priority":"P2","area":"Tab semantics","observation":"Account and Settings are broad labels that do not describe their contents.","change":"Use labels matching the actual account/audio/display content after checking each pane."},{"id":"14","kind":"proposal","priority":"P3","area":"Tab edges","observation":"All three tabs have rounded top shapes, including internal joins.","change":"Simplify internal joins to create one coherent tab strip."},{"id":"15","kind":"proposal","priority":"P2","area":"Selected tab cue","observation":"A thin blue underline is the only explicit active marker.","change":"Add stronger selected text weight while retaining the underline."},{"id":"16","kind":"proposal","priority":"P2","area":"Demo instructions","observation":"No text explains that changing tabs swaps the content pane.","change":"Add one concise instruction outside the specimen."},{"id":"17","kind":"proposal","priority":"P3","area":"Profile data provenance","observation":"player@example.com appears without a sample-data cue.","change":"Add a small Example profile caption."},{"id":"18","kind":"proposal","priority":"P2","area":"State coverage","observation":"Only Profile content is visible in the baseline.","change":"Capture Account and Settings as named companion states for visual review."}],"sha256":"e8f83335c9f12baf65135a56351884cb4c65d4f805133f7fa4d8ff65f73f3f32","has_mock":false,"reference":null,"legacy":[{"id":"tab_container","screen":"tab_container","baseline":"baseline_screenshots/tab_container.png","current":"screenshot-baselines/screens/tab_container_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Current capture removes Profile focus outline and leaves the blue selected-tab underline clear. The large profile content well and three small footer actions remain unchanged.","sha256":"532df9b9d5a46a43ee8a8076fef5f24e91d4d4a2162075a2577b1a1eb27d11f7","additional_findings":[]}]},{"id":"tabbing","baseline":"screenshot-baselines/screens/tabbing_720p.png","summary":"The initial frame contains no active focus ring, which is not itself a keyboard defect. Fifteen proposals improve the fixture instructions and evidence capture. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Title wording","observation":"KEYBOARD NAV abbreviates the feature name.","change":"Use Keyboard navigation."},{"id":"02","kind":"proposal","priority":"P2","area":"Instruction text","observation":"Use TAB to navigate, ENTER to click is small.","change":"Increase actual instruction size to 13 px."},{"id":"03","kind":"proposal","priority":"P2","area":"Activation language","observation":"ENTER to click uses pointer language for a keyboard action.","change":"Use Enter to activate."},{"id":"04","kind":"proposal","priority":"P2","area":"Reverse navigation","observation":"Only forward Tab navigation is explained.","change":"Add Shift+Tab for reverse navigation if supported."},{"id":"05","kind":"proposal","priority":"P2","area":"Initial focus framing","observation":"No focused option is shown in this initial screenshot.","change":"Add a caption explaining that focus appears after keyboard navigation begins."},{"id":"06","kind":"proposal","priority":"P2","area":"Focus evidence","observation":"All four button borders look alike in this state.","change":"Add a companion baseline with one keyboard-focused option."},{"id":"07","kind":"proposal","priority":"P2","area":"Option identities","observation":"OPTION A through OPTION D name no concrete action.","change":"Add a short demo note that each activation increments the shared counter."},{"id":"08","kind":"proposal","priority":"P2","area":"Counter label","observation":"Total Clicks counts keyboard activations under a mouse-specific name.","change":"Rename it Total activations."},{"id":"09","kind":"proposal","priority":"P2","area":"Counter feedback","observation":"The counter does not identify which option was activated.","change":"Add Last activated: none beside the count."},{"id":"10","kind":"proposal","priority":"P2","area":"Tab order","observation":"The vertical order is visible but not explicitly numbered as focus order.","change":"Add small 1 to 4 order badges outside the interactive buttons."},{"id":"11","kind":"proposal","priority":"P2","area":"Color roles","observation":"Magenta, cyan, lime and amber are unexplained.","change":"Add a note that colors test focus visibility across different backgrounds."},{"id":"12","kind":"proposal","priority":"P3","area":"Focus-ring specification","observation":"The screenshot does not document the configured yellow focus-ring appearance.","change":"Show a noninteractive ring swatch with thickness and offset in a small legend."},{"id":"13","kind":"proposal","priority":"P2","area":"Reset state","observation":"No reset action is visible for the activation counter.","change":"Add Reset count outside the demonstrated four-option order or label its tab-order role."},{"id":"14","kind":"proposal","priority":"P3","area":"Panel border","observation":"The purple outer frame has several close parallel outlines.","change":"Simplify the decorative frame so the keyboard ring is easier to distinguish in active captures."},{"id":"15","kind":"proposal","priority":"P2","area":"Expected outcome","observation":"The page has no explicit success statement for traversing all options.","change":"Add an expected sequence line A, B, C, D and back according to the actual traversal rules."}],"sha256":"bec573360ceb5fe28ebd2b9c68ed790b4bb4559f35d8b4d1c2d7af6f3ea6b396","has_mock":false,"reference":null,"legacy":[{"id":"tabbing","screen":"tabbing","baseline":"baseline_screenshots/tabbing.png","current":"screenshot-baselines/screens/tabbing_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Current capture removes initial Option A focus ring. The old image is useful separate evidence of the yellow-and-white keyboard focus treatment. The four colored choices remain otherwise unchanged.","sha256":"b869ad6f02f36f368112775c8fe581ffd007bf37571ddee895b2df76263e4944","additional_findings":[]}]},{"id":"text","baseline":"screenshot-baselines/screens/text_720p.png","summary":"The typography specimens deliberately vary typeface, size, tracking and color. Twenty proposals improve their documentation and comparison without treating the intentional styling as a defect. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Font families","observation":"Serif headings and handwritten body samples appear without font names.","change":"Label each specimen's font family."},{"id":"02","kind":"proposal","priority":"P2","area":"Display specimen","observation":"Display Text has no size annotation.","change":"Show its point or pixel size beside the specimen."},{"id":"03","kind":"proposal","priority":"P2","area":"Headline specimen","observation":"Headline Style lacks its size and weight.","change":"Add a small metadata row for size and weight."},{"id":"04","kind":"proposal","priority":"P2","area":"Subheading specimen","observation":"Subheading Text is only differentiated visually.","change":"Label the intended semantic role and size."},{"id":"05","kind":"proposal","priority":"P2","area":"Body sample copy","observation":"The sentence claims excellent legibility instead of exposing useful glyphs.","change":"Use a neutral specimen containing uppercase, lowercase, numbers and punctuation."},{"id":"06","kind":"proposal","priority":"P2","area":"Body line measure","observation":"The wrapping sample has no content-width annotation.","change":"Show its line width and line-height values."},{"id":"07","kind":"proposal","priority":"P2","area":"Caption specimen","observation":"Caption & metadata is very small and also serves as its own description.","change":"Place readable explanatory metadata outside the small-text specimen."},{"id":"08","kind":"proposal","priority":"P2","area":"Tracking samples","observation":"TIGHT TRACKING, WIDE TRACKING and ULTRA SPACED use different words.","change":"Repeat the same phrase in all three samples for direct comparison."},{"id":"09","kind":"proposal","priority":"P2","area":"Tracking values","observation":"The three tracking labels provide no numeric letter spacing.","change":"Display exact spacing values in the metadata column."},{"id":"10","kind":"proposal","priority":"P2","area":"Gold color sample","observation":"Primary Gold Text has no color-token value.","change":"Add its token and hex value alongside the card."},{"id":"11","kind":"proposal","priority":"P2","area":"Cream color sample","observation":"Light Cream Text has no contrast measurement context.","change":"Add foreground/background swatches and a measured contrast value in external metadata."},{"id":"12","kind":"proposal","priority":"P2","area":"Silver color sample","observation":"Silver Accent Text resembles the nearby muted treatment.","change":"Show their color values side by side to explain the subtle difference."},{"id":"13","kind":"proposal","priority":"P2","area":"Muted color sample","observation":"Muted Secondary Text is presented without a usage example.","change":"Add a short secondary-metadata context sample outside the color specimen."},{"id":"14","kind":"proposal","priority":"P2","area":"Accent color sample","observation":"Accent Color Highlight uses a reddish color without naming the token.","change":"Label the token and intended accent role."},{"id":"15","kind":"proposal","priority":"P3","area":"Color card labels","observation":"All five cards mix the color name with the sample sentence.","change":"Use identical sample text and move color labels outside the cards."},{"id":"16","kind":"proposal","priority":"P2","area":"Hierarchy comparison","observation":"Size examples are stacked without baseline or cap-height guides.","change":"Add optional faint baseline guides for visual comparison."},{"id":"17","kind":"proposal","priority":"P3","area":"Section heading hierarchy","observation":"Letter Spacing uses the same treatment as Text Size Hierarchy but sits within its column.","change":"Make the specimen grouping explicit with separate section spacing."},{"id":"18","kind":"proposal","priority":"P2","area":"Footer sentence","observation":"Elegant typography creates visual hierarchy is a general claim.","change":"Replace it with the active font families and rendering scale."},{"id":"19","kind":"proposal","priority":"P3","area":"Gold underline","observation":"The heading underline is unlabeled decoration on a specimen-heavy page.","change":"Reduce its prominence so sample rules and guides have a distinct role."},{"id":"20","kind":"proposal","priority":"P2","area":"Baseline rendering context","observation":"The page does not state resolution or scale for the type samples.","change":"Add 1280 × 720 and the effective UI scale in a metadata footer."}],"sha256":"47ec135185d09029d5db399b030d9f8141857693b38b3c6b5ecceb0faa28b649","has_mock":false,"reference":null,"legacy":[{"id":"text","screen":"text","baseline":"baseline_screenshots/text.png","current":"screenshot-baselines/screens/text_720p.png","pixel_identical":true,"size":[1280,720],"summary":"Pixel-identical. Serif display specimens contrast with handwritten body and caption samples. Current typography-review findings apply without assuming the mixed families are accidental.","sha256":"47ec135185d09029d5db399b030d9f8141857693b38b3c6b5ecceb0faa28b649","additional_findings":[]}]},{"id":"text_input","baseline":"screenshot-baselines/screens/text_input_720p.png","summary":"The form fits, but its labels are unusually small and its profile context mixes ordinary fields with test-only specimens. Twenty-two findings are supported by the initial screenshot. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"Field labels","observation":"Username, Email, Password and other labels are extremely small.","change":"Increase actual label size to at least 12 to 14 px."},{"id":"02","kind":"defect","priority":"P2","area":"Footer shortcuts","observation":"Tab / Ctrl+A/C/V/X is barely legible.","change":"Increase shortcut text and spell out the associated actions."},{"id":"03","kind":"proposal","priority":"P2","area":"Page subtitle","observation":"Update your account information is tiny and faint.","change":"Increase its size and contrast below Edit Profile."},{"id":"04","kind":"proposal","priority":"P2","area":"Profile context","observation":"Search, Readonly Field and Disabled Field do not belong to a coherent edit-profile form.","change":"Group those controls under a separate Input states demo section."},{"id":"05","kind":"proposal","priority":"P2","area":"Bio field","observation":"Bio is a single short line despite inviting personal description.","change":"Use a multiline specimen or label it Short bio."},{"id":"06","kind":"proposal","priority":"P2","area":"Email placeholder","observation":"user@example.com can look like a prefilled address.","change":"Use Enter email address and show example formatting as helper text."},{"id":"07","kind":"proposal","priority":"P2","area":"Username guidance","observation":"Enter username gives no visible format or length guidance.","change":"Add concise requirements beneath the label if the form validates them."},{"id":"08","kind":"proposal","priority":"P2","area":"Password context","observation":"A password field is mixed into profile editing without naming the operation.","change":"Use New password and clarify whether leaving it blank preserves the current password."},{"id":"09","kind":"proposal","priority":"P2","area":"Show password control","observation":"Show is small in a narrow gray segment.","change":"Increase label size and use a clear show-password icon with sufficient inset."},{"id":"10","kind":"proposal","priority":"P2","area":"Password segment border","observation":"The Show segment has a different edge treatment from the input.","change":"Unify the shared outer border and use a clean internal divider."},{"id":"11","kind":"proposal","priority":"P2","area":"Search affordance","observation":"Type to search... has no leading search icon.","change":"Add a recognizable search icon and identify what is searched."},{"id":"12","kind":"proposal","priority":"P2","area":"Read-only specimen","observation":"readonly text here is a placeholder-like sample.","change":"Use a realistic fixed value and a Read-only badge."},{"id":"13","kind":"proposal","priority":"P2","area":"Disabled specimen","observation":"The dim text is deliberately disabled but has no reason caption.","change":"Explain why this sample is disabled outside the specimen."},{"id":"14","kind":"proposal","priority":"P2","area":"Input boundaries","observation":"Several field edges have broken-looking corner joins.","change":"Use consistent border joins and document any intentional corner-radius variation."},{"id":"15","kind":"proposal","priority":"P2","area":"Save label size","observation":"Save is tiny inside a strong yellow button.","change":"Increase action text size while preserving the primary color."},{"id":"16","kind":"proposal","priority":"P2","area":"Cancel label size","observation":"Cancel is tiny inside its outlined button.","change":"Match the Save label size and vertical alignment."},{"id":"17","kind":"proposal","priority":"P2","area":"Footer order","observation":"The shortcut hint and action buttons share a sparse line without clear grouping.","change":"Separate input help from the action group with consistent footer spacing."},{"id":"18","kind":"proposal","priority":"P2","area":"Form status","observation":"No visible status explains whether this is unsaved sample data.","change":"Add a small Demo form or No changes status near the actions."},{"id":"19","kind":"proposal","priority":"P3","area":"Title hierarchy","observation":"Edit Profile is only slightly larger than input text.","change":"Increase title size so it clearly leads the form."},{"id":"20","kind":"proposal","priority":"P2","area":"Optional fields","observation":"Username, Email, Password and Bio have no required/optional distinction.","change":"Label optional fields or add a concise required-fields note."},{"id":"21","kind":"proposal","priority":"P3","area":"Panel balance","observation":"The tall narrow panel leaves broad black margins.","change":"Widen the panel modestly to accommodate readable labels and helper text."},{"id":"22","kind":"proposal","priority":"P2","area":"Initial blank form","observation":"Edit Profile contains placeholders rather than visible existing account data.","change":"Populate a clearly labeled sample profile or rename the screen Create profile."}],"sha256":"2442effdca504a050be7f25a5b1e767334aadc34efe700601042d8ea2c194081","has_mock":false,"reference":null,"legacy":[]},{"id":"text_input_lab","baseline":"screenshot-baselines/screens/text_input_lab_720p.png","summary":"The selected hello world text and the clipped overflow field are intentional internal-state fixtures. Sixteen proposals improve state readability and reproducibility. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Primary field label","observation":"The first input has no local label.","change":"Label it Selection and caret specimen."},{"id":"02","kind":"proposal","priority":"P2","area":"State group","observation":"text, cursor, selection, focused and scroll_x sit directly on the black page.","change":"Place them in a compact Inspector panel with aligned value columns."},{"id":"03","kind":"proposal","priority":"P2","area":"Cursor index","observation":"cursor: 11 does not explain index units.","change":"Label it Caret character index and state the indexing convention."},{"id":"04","kind":"proposal","priority":"P2","area":"Selection range","observation":"selection: 0..11 does not explain endpoint semantics.","change":"Show Start 0, End 11 and note whether end is exclusive."},{"id":"05","kind":"proposal","priority":"P2","area":"Selection length","observation":"The full phrase is selected but no count is shown.","change":"Add Selected characters: 11."},{"id":"06","kind":"proposal","priority":"P2","area":"Horizontal scroll","observation":"scroll_x: 0.0 lacks units.","change":"Show Horizontal scroll: 0.0 px."},{"id":"07","kind":"proposal","priority":"P2","area":"Focus readout","observation":"focused: yes is embedded among numeric data.","change":"Use a distinct Focused badge next to the inspected field name."},{"id":"08","kind":"proposal","priority":"P2","area":"Inspector association","observation":"Two inputs are visible but only one state dump appears.","change":"Label the inspector's target or show a separate dump for the overflow field."},{"id":"09","kind":"proposal","priority":"P2","area":"Overflow source text","observation":"The lower text is clipped so its full source cannot be read.","change":"Show the full source string in an external read-only caption."},{"id":"10","kind":"proposal","priority":"P2","area":"Overflow dimensions","observation":"The lower field has no width annotation.","change":"Label its exact viewport width and text width."},{"id":"11","kind":"proposal","priority":"P2","area":"Expected clipping","observation":"The instruction says text must stay inside the box without marking that boundary.","change":"Add external edge ticks at the field's clip limits."},{"id":"12","kind":"proposal","priority":"P2","area":"Initial selection","observation":"The first field starts fully selected with no explanation.","change":"Add a caption Initial state: all text selected."},{"id":"13","kind":"proposal","priority":"P2","area":"Test procedure","observation":"The page gives no sequence for observing caret, selection and scroll changes.","change":"Add a short keyboard procedure beneath the inspector."},{"id":"14","kind":"proposal","priority":"P2","area":"Reset specimen","observation":"No control restores hello world and the initial selection.","change":"Add Reset fixture outside the tested fields."},{"id":"15","kind":"proposal","priority":"P3","area":"Empty right region","observation":"Most of the screen is unused.","change":"Use a second column for expected outcomes and event history."},{"id":"16","kind":"proposal","priority":"P2","area":"Action evidence","observation":"The state dump shows only current values.","change":"Add a small last-action label so captures can be tied to a reproducible input step."}],"sha256":"f2ab6e280cf18132eccf2ac281500a67da3e9dc1e776ccaf71a564b2479aad3c","has_mock":false,"reference":null,"legacy":[]},{"id":"text_input_sizes","baseline":"screenshot-baselines/screens/text_input_sizes_720p.png","summary":"The seven input heights intentionally test caret and selection scaling. Sixteen proposals improve comparison; the small fields themselves should remain as test cases. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"Height labels","observation":"24px through 100px are extremely small.","change":"Increase external dimension labels to readable 12 px text."},{"id":"02","kind":"proposal","priority":"P2","area":"Subtitle","observation":"Cursor and selection scale with field height is very small.","change":"Increase explanatory text to 13 px actual size."},{"id":"03","kind":"proposal","priority":"P2","area":"Initial content","observation":"Every field is empty and displays a placeholder.","change":"Prefill matching sample text in a companion state to expose selection height."},{"id":"04","kind":"proposal","priority":"P2","area":"Caret comparison","observation":"Only the first field shows a caret in this capture.","change":"Add dedicated focus captures for each height rather than implying all carets can appear together."},{"id":"05","kind":"proposal","priority":"P2","area":"Selection comparison","observation":"No selected range is visible.","change":"Add a companion state with a consistent selected word at each target height."},{"id":"06","kind":"proposal","priority":"P2","area":"Dimension notation","observation":"Labels use 24px with no space.","change":"Use a consistent 24 px notation."},{"id":"07","kind":"proposal","priority":"P2","area":"Column identification","observation":"The height labels have no heading.","change":"Add Height above the label column."},{"id":"08","kind":"proposal","priority":"P2","area":"Width metadata","observation":"All fields appear equal width but the width is undocumented.","change":"Show a shared field-width caption above the stack."},{"id":"09","kind":"proposal","priority":"P2","area":"Font metadata","observation":"Placeholder text appears similar in size despite changing field heights.","change":"Document the font size beside the common width caption."},{"id":"10","kind":"proposal","priority":"P2","area":"Padding growth","observation":"Larger fields show progressively larger left insets.","change":"Annotate the padding rule so it can be checked independently of field height."},{"id":"11","kind":"proposal","priority":"P2","area":"Vertical centering","observation":"The specimen lacks guides for checking text centering.","change":"Add optional midline guides outside the active input rendering."},{"id":"12","kind":"proposal","priority":"P2","area":"Height ruler","observation":"The difference between 24 and 32 px is hard to assess precisely.","change":"Add a thin external height ruler beside each specimen."},{"id":"13","kind":"proposal","priority":"P3","area":"Row spacing","observation":"The gaps between fields are tight compared with the large last field.","change":"Use equal labeled specimen gutters while preserving exact field heights."},{"id":"14","kind":"proposal","priority":"P2","area":"Small-input context","observation":"The 24 and 32 px specimens could look like recommended product controls.","change":"Label them compact-size test cases rather than default form guidance."},{"id":"15","kind":"proposal","priority":"P2","area":"Reset content","observation":"No reset action returns all fields to comparable text.","change":"Add a shared Reset sample text control outside the stack."},{"id":"16","kind":"proposal","priority":"P3","area":"Bottom space","observation":"A large blank area remains below the 100 px field.","change":"Use it for caret, selection and padding measurements."}],"sha256":"c00174f90736840d5e4d5f79b10652b8a9a044bf324ca611f1776df7000798e4","has_mock":false,"reference":null,"legacy":[]},{"id":"text_overflow","baseline":"screenshot-baselines/screens/text_overflow_720p.png","summary":"Clipping and shrinking samples are intentional. Twenty proposals improve the debug legend and comparison; the screenshot alone does not establish that the overflow detector is wrong. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Debug instruction","observation":"The note says red corners appear, while entire sample borders are red.","change":"Add a zoomed marker key distinguishing debug corners from specimen borders."},{"id":"02","kind":"proposal","priority":"P2","area":"Good/problem colors","observation":"Green and red headings carry the main classification.","change":"Add explicit Pass specimen and Overflow specimen badges."},{"id":"03","kind":"proposal","priority":"P2","area":"Height specimen","observation":"Height is too small! appears to fit within its red frame.","change":"Annotate requested font size, measured text height and available height to explain the case."},{"id":"04","kind":"proposal","priority":"P2","area":"Tiny box annotation","observation":"Small 44x44 uses a textual arrow and compact notation.","change":"Use a clean callout line and 44 × 44 px label."},{"id":"05","kind":"proposal","priority":"P2","area":"First overflow text","observation":"This is way too ... is truncated without the full source beside it.","change":"Show the source string in external metadata."},{"id":"06","kind":"proposal","priority":"P2","area":"Narrow overflow case","observation":"Long text i... has no dimension annotation.","change":"Label its width and height next to the specimen."},{"id":"07","kind":"proposal","priority":"P2","area":"Ellipsis comparison","observation":"The solution samples are wider than the nearby failing examples.","change":"Add matched-width before/after specimens so ellipsis is the isolated change."},{"id":"08","kind":"proposal","priority":"P2","area":"Ellipsis label","observation":"Solution: Ellipsis Truncation can imply every overflow should truncate.","change":"Rename it Ellipsis behavior and state when wrapping is preferable."},{"id":"09","kind":"proposal","priority":"P2","area":"OK specimen","observation":"The small green OK box has no dimensions shown.","change":"Annotate its width, height and text size."},{"id":"10","kind":"proposal","priority":"P2","area":"Large fit specimen","observation":"This text fits perfectly shows no measurable available space.","change":"Add text bounds and container bounds in a spec caption."},{"id":"11","kind":"proposal","priority":"P2","area":"ABC sequence","observation":"Five shrinking ABC boxes have no individual size labels.","change":"Label each box's dimensions beneath it."},{"id":"12","kind":"proposal","priority":"P2","area":"ABC font changes","observation":"The ABC font shrinks across the sequence as well as the boxes.","change":"Display the font size per sample so two variables are explicit."},{"id":"13","kind":"proposal","priority":"P2","area":"Minimum-size note","observation":"The note links touch target size to text overflow warnings without distinction.","change":"Separate touch-target guidance from text-measurement behavior."},{"id":"14","kind":"proposal","priority":"P2","area":"Debug mode state","observation":"Debug mode is ON is embedded in a long green sentence.","change":"Use a small ON badge next to a Debug overlay label."},{"id":"15","kind":"proposal","priority":"P3","area":"Title scale","observation":"Text Overflow Debug Demo is large relative to tiny diagnostics.","change":"Reduce title footprint and spend space on readable metadata."},{"id":"16","kind":"proposal","priority":"P2","area":"Specimen identifiers","observation":"Individual examples have no stable IDs.","change":"Add small case IDs for screenshot-to-test mapping."},{"id":"17","kind":"proposal","priority":"P2","area":"Expected warning","observation":"Red-bordered examples have no expected-warning text.","change":"Add Expected: overflow or Expected: fits under each case."},{"id":"18","kind":"proposal","priority":"P3","area":"Column alignment","observation":"The two columns begin at different specimen baselines.","change":"Align the first comparison rows while preserving test dimensions."},{"id":"19","kind":"proposal","priority":"P2","area":"Clip boundary","observation":"Truncated text and red borders are close enough to obscure corner markers.","change":"Place debug annotations outside the measured container."},{"id":"20","kind":"proposal","priority":"P2","area":"Rendering scale","observation":"The page shows fixed-size claims without the effective scale.","change":"Add the UI scale and capture resolution to the footer."}],"sha256":"a528046ab0491541c4ebf55fc1b95520fbbffed95717deca72563ca56cef05d0","has_mock":false,"reference":null,"legacy":[{"id":"text_overflow","screen":"text_overflow","baseline":"baseline_screenshots/text_overflow.png","current":"screenshot-baselines/screens/text_overflow_720p.png","pixel_identical":true,"size":[1280,720],"summary":"Pixel-identical. Red oversized and clipped samples are the subject of the demo. Improvements must target their surrounding explanation and distinguish expected warning examples from real failures.","sha256":"a528046ab0491541c4ebf55fc1b95520fbbffed95717deca72563ca56cef05d0","additional_findings":[]}]},{"id":"text_shadow","baseline":"screenshot-baselines/screens/text_shadow_720p.png","summary":"The offset ladder and exaggerated shadows are intentional. Nineteen proposals improve specimen framing; the LIGHT captions also need corrected association and inset. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Page title shadow","observation":"Text Drop Shadow has a heavy offset shadow overlapping its letterforms.","change":"Use a restrained title shadow and reserve extreme offsets for the labeled specimens."},{"id":"02","kind":"proposal","priority":"P2","area":"Subtitle placement","observation":"The subtitle starts at the far left while the title is centered.","change":"Align it beneath the title or make it a clearly separate page introduction."},{"id":"03","kind":"proposal","priority":"P2","area":"No-shadow comparison","observation":"NO SHADOW and WITH SHADOW use different phrases.","change":"Repeat the same text and move variant labels outside the specimens."},{"id":"04","kind":"proposal","priority":"P2","area":"Comparison offset","observation":"The WITH SHADOW specimen does not show its exact offset.","change":"Add x/y offset and opacity metadata."},{"id":"05","kind":"proposal","priority":"P2","area":"Soft/hard comparison","observation":"SOFT and HARD change the words while comparing shadow presets.","change":"Use identical specimen text with separate Soft and Hard captions."},{"id":"06","kind":"proposal","priority":"P2","area":"Soft-shadow metadata","observation":"The glow description omits blur and opacity values.","change":"Show the preset's blur, offset and alpha parameters."},{"id":"07","kind":"proposal","priority":"P2","area":"Hard-shadow metadata","observation":"HARD has no parameter label.","change":"Add its exact offset and opacity for comparison with Soft."},{"id":"08","kind":"proposal","priority":"P2","area":"Colored shadow","observation":"COLORED is cyan/red but no color values are shown.","change":"Display both foreground and shadow color tokens."},{"id":"09","kind":"proposal","priority":"P2","area":"Combo specimen","observation":"COMBO mixes stroke and shadow without separate measurements.","change":"Add stroke width and shadow offset in an external caption."},{"id":"10","kind":"defect","priority":"P2","area":"LIGHT caption placement","observation":"flat look and more depth! both sit beneath the left half of the panel.","change":"Place one caption directly beneath each LIGHT specimen."},{"id":"11","kind":"defect","priority":"P2","area":"LIGHT bottom inset","observation":"The LIGHT captions nearly touch the dark panel's bottom edge.","change":"Increase panel height or move captions up to leave 10 px bottom inset."},{"id":"12","kind":"proposal","priority":"P2","area":"Offset ladder heading","observation":"Shadow Offset Examples does not specify direction.","change":"Label the ladder with the x/y offset convention."},{"id":"13","kind":"proposal","priority":"P2","area":"Offset labels","observation":"1px through 10px are small at the far right.","change":"Increase label size and use 1 px notation."},{"id":"14","kind":"proposal","priority":"P2","area":"Ladder spacing","observation":"Large blank horizontal gaps separate SHADOW from its numeric label.","change":"Bring the values closer or add faint row guides."},{"id":"15","kind":"proposal","priority":"P2","area":"Ladder baseline","observation":"No guide shows the unshadowed glyph baseline.","change":"Add optional baseline ticks outside the text."},{"id":"16","kind":"proposal","priority":"P2","area":"Ladder control","observation":"The ladder begins at 1 px without a 0 px reference.","change":"Add an external zero-offset swatch for comparison."},{"id":"17","kind":"proposal","priority":"P3","area":"Description rhythm","observation":"Descriptions sit at varying distances from their examples.","change":"Use consistent specimen-to-caption spacing."},{"id":"18","kind":"proposal","priority":"P2","area":"Bottom tip","observation":"The tip is far below the specimens in a nearly empty lower region.","change":"Move it closer to the examples or use the region for parameter summaries."},{"id":"19","kind":"proposal","priority":"P2","area":"Font identity","observation":"The bold pixel font is not named.","change":"Add the font family and size to the specimen metadata."}],"sha256":"a3630e5e8b01270685a7fd9cd44562fa743a9c3e382299a52329ed1da84b6759","has_mock":false,"reference":null,"legacy":[{"id":"text_shadow","screen":"text_shadow","baseline":"baseline_screenshots/text_shadow.png","current":"screenshot-baselines/screens/text_shadow_720p.png","pixel_identical":true,"size":[1280,720],"summary":"Pixel-identical. Heading shadow competes with the heading itself, and LIGHT captions sit on the lower panel edge. The 1px to 10px samples deliberately expose strong shadow offsets.","sha256":"a3630e5e8b01270685a7fd9cd44562fa743a9c3e382299a52329ed1da84b6759","additional_findings":[]}]},{"id":"text_stroke","baseline":"screenshot-baselines/screens/text_stroke_720p.png","summary":"The thick outlines and white-on-light control are intentional. Twenty findings preserve those samples while correcting covered captions and adding measurable comparison metadata. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"defect","priority":"P1","area":"WHITE captions","observation":"The invisible and visible! captions are covered by the bottom tip strip.","change":"Move the tip down or the specimen up so both captions are fully readable."},{"id":"02","kind":"proposal","priority":"P2","area":"White control label","observation":"invisible describes text that is faintly visible and frames the example as absolute.","change":"Use Low contrast and Outlined for more precise captions."},{"id":"03","kind":"proposal","priority":"P2","area":"No-stroke comparison","observation":"NO STROKE and WITH STROKE use different strings.","change":"Repeat the same specimen text and place variant labels outside it."},{"id":"04","kind":"proposal","priority":"P2","area":"Comparison width","observation":"The dark outline behind WITH STROKE resembles a rectangular backing.","change":"Add an enlarged glyph detail to distinguish stroke expansion from a background fill."},{"id":"05","kind":"proposal","priority":"P2","area":"Bold specimen","observation":"BOLD uses an 8 px stroke but lacks the font size.","change":"Show font size alongside stroke width to explain relative thickness."},{"id":"06","kind":"proposal","priority":"P2","area":"Contrast colors","observation":"CONTRAST is cyan/red without color token metadata.","change":"Display foreground and outline color values in a separate caption."},{"id":"07","kind":"proposal","priority":"P2","area":"Glow wording","observation":"GLOW uses a hard bright outline while the caption calls it a glow.","change":"Label it Bright outline or add a separate blurred glow comparison."},{"id":"08","kind":"proposal","priority":"P2","area":"Thickness ladder baseline","observation":"The ladder starts at 2 px with no zero-stroke control.","change":"Add a zero-stroke reference above the ladder."},{"id":"09","kind":"proposal","priority":"P2","area":"Thickness labels","observation":"2px through 10px use small distant labels.","change":"Increase label size and use spaced px notation."},{"id":"10","kind":"proposal","priority":"P2","area":"Ladder row alignment","observation":"The text and thickness descriptions are separated by large blank gaps.","change":"Align them within clear specimen rows."},{"id":"11","kind":"proposal","priority":"P2","area":"Ten-pixel outline","observation":"The 10 px sample has visible chunky artifacts that are part of the extreme case.","change":"Label it Extreme thickness specimen and provide a close-up for assessment."},{"id":"12","kind":"proposal","priority":"P2","area":"Stroke algorithm context","observation":"The different outline edges have no rendering-method explanation.","change":"Add a short metadata note identifying the stroke method under test."},{"id":"13","kind":"proposal","priority":"P2","area":"Font identity","observation":"The pixel-like display font is unnamed.","change":"Label BlackOpsOne and its sample size."},{"id":"14","kind":"proposal","priority":"P2","area":"Title effect","observation":"The title also has a stroke but no specification.","change":"Document its settings or use a neutral title to isolate the specimen effects."},{"id":"15","kind":"proposal","priority":"P3","area":"Subtitle size","observation":"The subtitle is small and subdued compared with the large effect samples.","change":"Increase its readable size modestly."},{"id":"16","kind":"proposal","priority":"P2","area":"White panel metadata","observation":"The white-on-light panel does not state its background color.","change":"Add background and foreground values outside the control panel."},{"id":"17","kind":"proposal","priority":"P2","area":"Caption alignment","observation":"Descriptions run across varying widths under the left specimens.","change":"Use a consistent left column and text measure for metadata."},{"id":"18","kind":"proposal","priority":"P2","area":"Thickness advice","observation":"The tip gives absolute widths without relating them to font size.","change":"Express guidance as a stroke-to-font-size ratio or include the reference font size."},{"id":"19","kind":"proposal","priority":"P3","area":"Case numbering","observation":"The effect cases have names but no stable identifiers.","change":"Add small IDs for comparison across captures."},{"id":"20","kind":"proposal","priority":"P2","area":"Rendering scale","observation":"Pixel-width labels do not show whether UI scaling is applied.","change":"Add capture scale and effective stroke units in the footer."}],"sha256":"609191a71324ec3d5a3b7fc5ff28b5384fa1c7be1b82883c5831a58870305653","has_mock":false,"reference":null,"legacy":[{"id":"text_stroke","screen":"text_stroke","baseline":"baseline_screenshots/text_stroke.png","current":"screenshot-baselines/screens/text_stroke_720p.png","pixel_identical":true,"size":[1280,720],"summary":"Pixel-identical. The invisible/visible captions beneath the WHITE sample are covered by the tip strip. Chunky 8px and 10px outlines are intentional stroke specimens.","sha256":"609191a71324ec3d5a3b7fc5ff28b5384fa1c7be1b82883c5831a58870305653","additional_findings":[]}]},{"id":"themes","baseline":"screenshot-baselines/screens/themes_720p.png","summary":"Ocean Navy intentionally recolors the preview. Twenty-two findings improve token identification and specimen clarity while preserving the palette choices. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Checkbox preview","observation":"The checkbox preview uses a V check indicator inside a wide blue row.","change":"For a more familiar checkbox presentation, place the check inside a visible square beside its label."},{"id":"02","kind":"proposal","priority":"P2","area":"Button labels","observation":"P, S, A and D are unexplained one-letter labels.","change":"Expand them to Primary, Secondary, Accent and Disabled."},{"id":"03","kind":"proposal","priority":"P2","area":"Selected theme marker","observation":"Ocean Navy is wrapped in greater-than and less-than text.","change":"Use a checkmark or side marker with readable equal padding."},{"id":"04","kind":"proposal","priority":"P2","area":"Active-theme banner","observation":"Active: Ocean Navy resembles another gold action button.","change":"Style it as a status badge rather than a control."},{"id":"05","kind":"proposal","priority":"P2","area":"Theme selection header","observation":"Select Theme is styled as a blue button.","change":"Use a plain section heading so it is not mistaken for an action."},{"id":"06","kind":"proposal","priority":"P2","area":"Slider preview","observation":"The wide green bar with blue thumb has no label or value.","change":"Add Slider and its current numeric value."},{"id":"07","kind":"proposal","priority":"P2","area":"Slider purpose","observation":"The oversized rectangular thumb does not explain its style configuration.","change":"Add a specimen caption with thumb size and track size."},{"id":"08","kind":"proposal","priority":"P2","area":"Toggle label","observation":"Toggle is centered far from the right-side switch.","change":"Align label left and switch right with a consistent setting-row structure."},{"id":"09","kind":"proposal","priority":"P2","area":"Toggle state","observation":"The gray switch has no visible On/Off text.","change":"Add an explicit state value."},{"id":"10","kind":"proposal","priority":"P2","area":"Shadow specimens","observation":"Hard, Soft and Accent also change background color.","change":"Label shadow type separately and add a same-color comparison for shadow strength."},{"id":"11","kind":"proposal","priority":"P2","area":"Hard card text","observation":"Hard touches the left edge of its blue card.","change":"Add consistent inner padding to all three shadow cards."},{"id":"12","kind":"proposal","priority":"P2","area":"Text swatches","observation":"Primary Text, Secondary Text and Surface Text touch their card edges.","change":"Inset all text swatches equally."},{"id":"13","kind":"proposal","priority":"P2","area":"Surface swatch","observation":"Surface Text sits on a nearly matching navy card.","change":"Add a neutral external border and token metadata without changing the specimen colors."},{"id":"14","kind":"proposal","priority":"P2","area":"Color values","observation":"The preview contains many role colors with no resolved values.","change":"Add a token table showing foreground and background hex values."},{"id":"15","kind":"proposal","priority":"P2","area":"Separator","observation":"A green horizontal rule appears without a label.","change":"Identify it as the separator specimen and show its token."},{"id":"16","kind":"proposal","priority":"P2","area":"Progress state","observation":"Loading: 72% is tiny inside the blue fill.","change":"Place a readable progress label above the bar."},{"id":"17","kind":"proposal","priority":"P2","area":"Progress semantics","observation":"The remaining portion is green, which can look like completion too.","change":"Add an external legend for fill and track tokens rather than silently replacing the theme."},{"id":"18","kind":"proposal","priority":"P2","area":"Preview title","observation":"Component Preview is a small label in a full-width blue bar.","change":"Increase its hierarchy and identify the active theme beside it."},{"id":"19","kind":"proposal","priority":"P3","area":"Left rail space","observation":"The theme list leaves a large unused lower region.","change":"Use it for active-theme metadata or a compact palette summary."},{"id":"20","kind":"proposal","priority":"P2","area":"Theme comparison","observation":"Only the selected theme is shown, making differences hard to review.","change":"Add named companion captures for all five themes."},{"id":"21","kind":"proposal","priority":"P2","area":"Disabled specimen","observation":"D is dim but has no external explanation.","change":"Add a Disabled state caption outside the intentionally dim control."},{"id":"22","kind":"proposal","priority":"P2","area":"Theme effect scope","observation":"The page does not explain that switching a theme recolors all examples.","change":"Add a concise instruction above the preview."}],"sha256":"18190e9f97324b024987873c8fe2ac8b0708c4fede764e1ae32300f4b424895b","has_mock":false,"reference":null,"legacy":[{"id":"themes","screen":"themes","baseline":"baseline_screenshots/themes.png","current":"screenshot-baselines/screens/themes_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Current capture removes Cozy Kraft focus outline while Ocean Navy remains the active theme in both. P/S/A/D abbreviations and the unlabeled slider remain difficult to interpret.","sha256":"86ee9f39226597f6b54e7abbce8d9c26af0bbf6023213c86b7ec1e94915ec858","additional_findings":[]}]},{"id":"toasts","baseline":"screenshot-baselines/screens/toasts_720p.png","summary":"The baseline contains launchers only. Twenty findings improve the launcher design and correct an interactive-undo claim that source shows is only a simulated counter notification. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"Interactive section claim","observation":"INTERACTIVE TOASTS and With Undo Action promise an embedded action, but source only increments a counter and sends a toast.","change":"Rename the section Simulated action feedback or implement an actual undo action in the toast."},{"id":"02","kind":"defect","priority":"P2","area":"Undo counter label","observation":"Undos: 0 labels launcher activations as completed undos.","change":"Rename it Notifications sent unless actual undo operations are introduced."},{"id":"03","kind":"defect","priority":"P2","area":"Title inset","observation":"Toast Notifications starts flush against the title bar's left edge.","change":"Add 16 px inner padding."},{"id":"04","kind":"defect","priority":"P2","area":"Quick duration label","observation":"Quick displays 1s nearly touches both sides of its button.","change":"Add at least 12 px horizontal padding."},{"id":"05","kind":"defect","priority":"P2","area":"Long duration label","observation":"Long displays 10s fills almost the entire button width.","change":"Increase button width or shorten the label to Long, 10 s."},{"id":"06","kind":"proposal","priority":"P2","area":"Success color","observation":"Success Toast is purple without an external severity key.","change":"Add severity icons and text labels so the theme color is not the sole cue."},{"id":"07","kind":"proposal","priority":"P2","area":"Warning color","observation":"Warning Toast is magenta and close to other accents.","change":"Use a warning icon in the launcher and toast specimen."},{"id":"08","kind":"proposal","priority":"P2","area":"Error launcher","observation":"Error Toast uses red but no error symbol.","change":"Add a consistent error icon aligned with the other severity controls."},{"id":"09","kind":"proposal","priority":"P2","area":"Info launcher","observation":"Info Toast has no preview of the resulting message.","change":"Add a short example-message caption below the launcher."},{"id":"10","kind":"proposal","priority":"P2","area":"Duration group title","observation":"DURATION & SPAM uses informal stress-test language.","change":"Rename it Duration and stacking tests."},{"id":"11","kind":"proposal","priority":"P2","area":"Spam action","observation":"Spam x5 (!) obscures the exact outcome.","change":"Use Show five toasts and describe stacking behavior below it."},{"id":"12","kind":"proposal","priority":"P2","area":"Custom color control","observation":"Custom Color uses an orange fill without naming the configured color.","change":"Add an external swatch value or color label."},{"id":"13","kind":"proposal","priority":"P2","area":"Launcher sizing","observation":"Simple toast buttons have uneven widths determined by their labels.","change":"Use an equal-width severity grid for easier comparison."},{"id":"14","kind":"proposal","priority":"P2","area":"Typography scale","observation":"Large letter-spaced launcher labels crowd their backgrounds.","change":"Reduce tracking and use a consistent readable button size."},{"id":"15","kind":"proposal","priority":"P2","area":"Empty toast area","observation":"No toast is visible anywhere in the initial capture.","change":"Add a dedicated labeled preview region or companion shown-toast captures."},{"id":"16","kind":"proposal","priority":"P2","area":"Toast placement","observation":"The launcher page does not state where notifications appear.","change":"Show a small placement diagram in the unused right side of a section."},{"id":"17","kind":"proposal","priority":"P2","area":"Toast lifetime","observation":"Only quick and long launchers show duration values.","change":"Label the default duration used by the simple severity examples."},{"id":"18","kind":"proposal","priority":"P2","area":"Clear action","observation":"No visible action dismisses the stacking test.","change":"Add Clear toasts outside the fixture previews."},{"id":"19","kind":"proposal","priority":"P2","area":"Status reporting","observation":"Only the undo simulation has a counter.","change":"Add a shared Last notification and Active count readout."},{"id":"20","kind":"proposal","priority":"P3","area":"Section space","observation":"Wide cards leave substantial unused right space.","change":"Use that space for concise expected-result and duration metadata."}],"sha256":"09e5c316980c035277c80cb1fcab44194c4a060f73cd2157f48d2bb62c0c024c","has_mock":false,"reference":null,"legacy":[]},{"id":"toggle_switches","baseline":"screenshot-baselines/screens/toggle_switches_720p.png","summary":"Pill toggles and checkbox variants are intentional. Twenty proposals improve alignment, state labels and disabled-example framing without treating disabled colors as failures. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Page title","observation":"Settings hides that this is a component comparison.","change":"Use Toggle and checkbox settings demo."},{"id":"02","kind":"proposal","priority":"P2","area":"General labels","observation":"Notifications, Sound Effects and Vibration are centered far from the left edge.","change":"Left-align labels with the Preferences rows."},{"id":"03","kind":"proposal","priority":"P2","area":"Preference label inset","observation":"Dark Mode, Auto-Save and Cloud Sync touch the row left edge.","change":"Add 12 px inner padding."},{"id":"04","kind":"proposal","priority":"P2","area":"Preference indicators","observation":"The [x] and [ ] glyphs float near the row center.","change":"Align them in the same right-side control column as the switches."},{"id":"05","kind":"proposal","priority":"P2","area":"Checkbox rendering","observation":"Bracketed text resembles terminal output rather than a circular checkbox specimen.","change":"Use a visible checkbox shape with a centered checkmark and retain a caption for its style."},{"id":"06","kind":"proposal","priority":"P2","area":"On-state labels","observation":"Notifications and Vibration rely on magenta fill and thumb position.","change":"Add On text beside the switch."},{"id":"07","kind":"proposal","priority":"P2","area":"Off-state label","observation":"Sound Effects uses a gray track without an Off label.","change":"Add Off text in the state column."},{"id":"08","kind":"proposal","priority":"P2","area":"Section naming","observation":"General and Preferences do not identify the different control families.","change":"Add Pill switches and Checkbox variants as secondary captions."},{"id":"09","kind":"proposal","priority":"P2","area":"Disabled switch","observation":"Locked Setting ON shows a white thumb with an almost invisible track.","change":"Keep the disabled specimen but label track and thumb states in external metadata."},{"id":"10","kind":"proposal","priority":"P2","area":"Disabled reason","observation":"Locked Setting gives no reason for the lock.","change":"Add a short sample explanation such as Managed by administrator."},{"id":"11","kind":"proposal","priority":"P2","area":"Unavailable checkbox","observation":"Unavailable Option OFF has no reason caption.","change":"Add an external Not available in this demo note."},{"id":"12","kind":"proposal","priority":"P2","area":"Disabled text size","observation":"Disabled labels are small as well as dim.","change":"Increase external captions while leaving disabled-state styling intact."},{"id":"13","kind":"proposal","priority":"P2","area":"State vocabulary","observation":"ON/OFF appears only in disabled labels while enabled rows have no words.","change":"Use consistent On and Off state text across all specimens."},{"id":"14","kind":"proposal","priority":"P2","area":"Row geometry","observation":"General rows are square strips while Preferences rows are rounded.","change":"Label the shape variation explicitly or use a common row shell around different controls."},{"id":"15","kind":"proposal","priority":"P2","area":"Section labels","observation":"General, Preferences and Disabled are small and faint.","change":"Increase their readable size and use a consistent heading weight."},{"id":"16","kind":"proposal","priority":"P2","area":"Control association","observation":"Large gaps separate centered labels from the right-side pill controls.","change":"Use a structured label/value row with predictable spacing."},{"id":"17","kind":"proposal","priority":"P3","area":"Separator inset","observation":"Dividers align with the outer row edges but labels do not.","change":"Align headings, labels and dividers to one inner grid."},{"id":"18","kind":"proposal","priority":"P2","area":"Initial state summary","observation":"The mix of on and off states has no compact comparison legend.","change":"Add a small state key outside the controls."},{"id":"19","kind":"proposal","priority":"P2","area":"Reset defaults","observation":"No visible action restores the initial mixture of states.","change":"Add Reset demo defaults below the specimen groups."},{"id":"20","kind":"proposal","priority":"P3","area":"Panel margins","observation":"The main card begins at the viewport top with little title breathing room.","change":"Add a modest top margin while preserving space for the disabled examples."}],"sha256":"c61e6fd9f63b8ee366ead5e8a6db9cd8072803971d14000d0e53f308e7e4e823","has_mock":false,"reference":null,"legacy":[{"id":"toggle_switches","screen":"toggle_switches","baseline":"baseline_screenshots/toggle_switches.png","current":"screenshot-baselines/screens/toggle_switches_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Current capture removes Notifications focus outline. General switches and Preferences bracket markers deliberately compare two representations. Locked Setting ON still loses its track against the dark disabled row.","sha256":"d6af75de471f24d03411947f23c16691d1d58ebc4dea6f554738daf09a9fc61b","additional_findings":[]}]},{"id":"tooltip_lab","baseline":"screenshot-baselines/screens/tooltip_lab_720p.png","summary":"Trigger positions deliberately exercise edge flipping and clamping. Sixteen proposals improve the test legend and capture coverage; no tooltip is open in this baseline. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Page identity","observation":"The top bar is only an instruction sentence.","change":"Add Tooltip placement lab as the title."},{"id":"02","kind":"proposal","priority":"P2","area":"Instruction size","observation":"The hover-and-flip instruction is small.","change":"Increase it to 13 px actual text."},{"id":"03","kind":"proposal","priority":"P2","area":"Header padding","observation":"The instruction starts almost at the bar's left edge.","change":"Add a consistent 12 to 16 px text inset."},{"id":"04","kind":"proposal","priority":"P2","area":"Top-left case","observation":"top left does not say it is the normal-below placement control.","change":"Add Normal below as an external case caption."},{"id":"05","kind":"proposal","priority":"P2","area":"Top-right case","observation":"top right does not identify horizontal clamping.","change":"Add Clamp to right edge as an external caption."},{"id":"06","kind":"proposal","priority":"P2","area":"Bottom-left case","observation":"bottom left does not name the expected flip.","change":"Add Flip above as an external caption."},{"id":"07","kind":"proposal","priority":"P2","area":"Bottom-right case","observation":"bottom right does not name its combined constraints.","change":"Add Flip above and clamp as an external caption."},{"id":"08","kind":"proposal","priority":"P2","area":"Middle case","observation":"middle does not reveal that it tests long tooltip text.","change":"Rename it Long content or add that caption."},{"id":"09","kind":"proposal","priority":"P2","area":"Instant case","observation":"instant gives no numeric delay.","change":"Label it Instant, 0 ms."},{"id":"10","kind":"proposal","priority":"P2","area":"Default delay","observation":"Other triggers do not show their 0.4 s delay.","change":"Add Default delay: 400 ms to the legend."},{"id":"11","kind":"proposal","priority":"P2","area":"Expected tooltip content","observation":"No tooltip text is visible in the initial state.","change":"Add a compact external case table listing trigger, message and expected placement."},{"id":"12","kind":"proposal","priority":"P2","area":"Open-state evidence","observation":"The baseline cannot show whether tooltip boxes stay within bounds.","change":"Capture one shown-tooltip state per edge case."},{"id":"13","kind":"proposal","priority":"P2","area":"Viewport bounds","observation":"The dark field has no visible safe-area guide.","change":"Add an optional edge guide for checking clamping without moving the triggers."},{"id":"14","kind":"proposal","priority":"P2","area":"Trigger geometry","observation":"Button dimensions and edge distances are undocumented.","change":"Show them in a small fixture metadata panel."},{"id":"15","kind":"proposal","priority":"P2","area":"Active-case status","observation":"There is no readout identifying the currently hovered specimen.","change":"Add a read-only Active case status in the header."},{"id":"16","kind":"proposal","priority":"P3","area":"Unused central space","observation":"Large blank regions are available between the fixed edge triggers.","change":"Use a compact central legend without changing trigger positions."}],"sha256":"3da02ddc32405e3289d5458682bad2c56fbff920047f030c2b17f6375437ec9d","has_mock":false,"reference":null,"legacy":[{"id":"tooltip_lab_idle","screen":"tooltip_lab","baseline":"baseline_screenshots/tooltip_lab_idle.png","current":"screenshot-baselines/screens/tooltip_lab_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Current capture removes top-left focus outline. Both idle views show six triggers and no tooltip. Initial focus absence is not proof that keyboard tooltips fail.","sha256":"931a089a7a03173af9d132eb585408c1a9038060161c62ae1f58dbdccbed35ba","additional_findings":[]},{"id":"tooltip_lab_shown","screen":"tooltip_lab","baseline":"baseline_screenshots/tooltip_lab_shown.png","current":"screenshot-baselines/screens/tooltip_lab_720p.png","pixel_identical":false,"size":[1280,720],"summary":"Additional interaction state. The instant trigger is highlighted and a narrow tooltip reads delay 0, shows the moment you arrive. This tooltip is absent from the current idle baseline by design.","sha256":"6e5e2367d37e0d2f096c76afedbdc0c6b8411cafa9d74860c3264fc1ad60d3d8","additional_findings":[{"id":"L01","kind":"proposal","area":"Instant tooltip copy","observation":"The shown tooltip sentence is much smaller than the instant trigger label.","change":"Use at least the readable caption size used by the trigger descriptions; verify the full sentence at 1280×720.","priority":"P2"},{"id":"L02","kind":"proposal","area":"Instant tooltip padding","observation":"The tooltip sentence almost fills its narrow outlined rectangle.","change":"Add horizontal and vertical breathing room around the instant-tooltip sentence.","priority":"P2"},{"id":"L03","kind":"proposal","area":"Tooltip border","observation":"A red outline surrounds a normal informational tooltip.","change":"Use a neutral tooltip edge and reserve red for a documented diagnostic or warning state.","priority":"P3"},{"id":"L04","kind":"proposal","area":"Trigger-to-tooltip relationship","observation":"The instant tooltip appears immediately below the button without a visible anchor cue.","change":"Add a small offset or anchor marker so the tooltip is visually attached to instant rather than a separate control.","priority":"P3"}]}]},{"id":"tray","baseline":"screenshot-baselines/screens/tray_720p.png","summary":"The two tray orientations are visible. Sixteen proposals clarify navigation and feedback; the initial screenshot does not establish keyboard or focus failures. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Page explanation","observation":"Tray Navigation does not explain what a tray changes about focus.","change":"Add a sentence describing grouped arrow-key navigation."},{"id":"02","kind":"proposal","priority":"P2","area":"Horizontal caption","observation":"Horizontal Tray Left/Right uses tiny text.","change":"Increase the caption to readable 13 px actual size."},{"id":"03","kind":"proposal","priority":"P2","area":"Vertical caption","observation":"Vertical Tray Up/Down is similarly small.","change":"Match the horizontal caption's size and spacing."},{"id":"04","kind":"proposal","priority":"P2","area":"Horizontal labels","observation":"H-Alpha, H-Beta and H-Gamma repeat an orientation prefix already in the heading.","change":"Use Alpha, Beta and Gamma with a clearly labeled horizontal group."},{"id":"05","kind":"proposal","priority":"P2","area":"Vertical labels","observation":"V-Alpha, V-Beta and V-Gamma repeat the heading.","change":"Use the same choice labels as the horizontal comparison."},{"id":"06","kind":"proposal","priority":"P2","area":"Color comparison","observation":"The horizontal and vertical groups use different color sets.","change":"Use matching colors for corresponding choices or document the deliberate contrast test."},{"id":"07","kind":"proposal","priority":"P2","area":"Tray boundary","observation":"The groups have no outline showing where tray ownership begins and ends.","change":"Add subtle group frames outside the buttons."},{"id":"08","kind":"proposal","priority":"P2","area":"Entry/exit guidance","observation":"Only arrow directions are shown.","change":"Add Tab guidance for entering and leaving the tray according to actual behavior."},{"id":"09","kind":"proposal","priority":"P2","area":"Activation guide","observation":"No text says how to activate the current tray item.","change":"Add the supported activation key beside the navigation hints."},{"id":"10","kind":"proposal","priority":"P2","area":"Selection feedback","observation":"No status shows the last activated item.","change":"Add Last activated: none beneath the groups."},{"id":"11","kind":"proposal","priority":"P2","area":"Active group feedback","observation":"The initial frame does not identify a keyboard-active tray.","change":"Add a read-only Active tray status that updates during navigation."},{"id":"12","kind":"proposal","priority":"P2","area":"Boundary behavior","observation":"The three-item groups do not explain wrapping at their ends.","change":"Add a concise wrap/clamp note matched to implementation."},{"id":"13","kind":"proposal","priority":"P2","area":"State coverage","observation":"Only the initial unfocused composition is shown.","change":"Add companion captures with a focused item in each tray."},{"id":"14","kind":"proposal","priority":"P3","area":"Bottom panel space","observation":"A large blank band remains beneath V-Gamma.","change":"Use it for the key guide and status readouts."},{"id":"15","kind":"proposal","priority":"P3","area":"Group spacing","observation":"The gap after the horizontal row is much larger than its caption gap.","change":"Use consistent heading-to-group and group-to-group spacing."},{"id":"16","kind":"proposal","priority":"P2","area":"Demo reset","observation":"There is no visible way to restore the initial selection state.","change":"Add a small Reset demo action outside the tray examples."}],"sha256":"55223ab764a9e003c08a9f331d999102f2f0d332c1ca6a26e222aa187a2b4f05","has_mock":false,"reference":null,"legacy":[]},{"id":"virtual_list_lab","baseline":"screenshot-baselines/screens/virtual_list_lab_720p.png","summary":"The 10,000-row count and short scrollbar thumb are intentional. Seventeen proposals make the virtualization claim observable without changing the large-list test. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Instruction size","observation":"The entity-count explanation is tiny beneath the title.","change":"Increase it to 13 px actual size."},{"id":"02","kind":"proposal","priority":"P2","area":"Row identifiers","observation":"row 00000 through row 00019 are very small.","change":"Increase row text size while retaining the fixed row-height test."},{"id":"03","kind":"proposal","priority":"P2","area":"Row padding","observation":"Identifiers begin flush at the list's left edge.","change":"Add 12 px text inset without changing the viewport width."},{"id":"04","kind":"proposal","priority":"P2","area":"Entity-count claim","observation":"The instruction says entity count stays flat but no count is displayed.","change":"Add a live rendered-entity count above the list."},{"id":"05","kind":"proposal","priority":"P2","area":"Visible range","observation":"Twenty rows are visible with no summarized range.","change":"Show Visible rows 0 to 19 of 10,000 outside the viewport."},{"id":"06","kind":"proposal","priority":"P2","area":"Scroll position","observation":"The tiny thumb conveys little precise position information.","change":"Add numeric offset and percentage readouts."},{"id":"07","kind":"proposal","priority":"P2","area":"Total count formatting","observation":"10000 appears without grouping separators.","change":"Display 10,000 in descriptive text while keeping zero-padded row IDs."},{"id":"08","kind":"proposal","priority":"P2","area":"Marked rows","observation":"Rows 00000, 00007 and 00014 say marked but have no separate visual marker.","change":"Add a small marker icon or accent stripe alongside the text."},{"id":"09","kind":"proposal","priority":"P2","area":"Marked rule","observation":"The reason every seventh row is marked is not explained.","change":"Add a caption naming the marker interval."},{"id":"10","kind":"proposal","priority":"P2","area":"Index convention","observation":"The first row is 00000 without an indexing note.","change":"Label row IDs as zero-based."},{"id":"11","kind":"proposal","priority":"P2","area":"Jump controls","observation":"Only manual scrolling is suggested for a very long list.","change":"Add Start, Middle and End presets outside the viewport."},{"id":"12","kind":"proposal","priority":"P2","area":"Jump-to-index","observation":"No direct location entry is visible.","change":"Add a row-index field for reproducible offscreen-range captures."},{"id":"13","kind":"proposal","priority":"P2","area":"Virtualization evidence","observation":"The initial frame cannot show entity reuse across distant ranges.","change":"Add companion captures at a distant offset with the entity-count readout."},{"id":"14","kind":"proposal","priority":"P2","area":"Viewport metrics","observation":"The fixed row height and viewport height are undocumented.","change":"Show both values with the expected visible-row count."},{"id":"15","kind":"proposal","priority":"P3","area":"Row schema","observation":"Each line combines an index and state in loose text.","change":"Use aligned Index and State columns for easier scanning."},{"id":"16","kind":"proposal","priority":"P2","area":"End-state framing","observation":"No indication describes the last row's expected index.","change":"Add Last row: 09999 in the test metadata."},{"id":"17","kind":"proposal","priority":"P3","area":"Unused row width","observation":"Most of every row is empty.","change":"Use a compact content column with a subtle grid while preserving the full-width scroll region."}],"sha256":"ba1f0c8ef168650cbccfbde56c69c550e8a99f62e791f60d6ac1f8a27ab92ce1","has_mock":false,"reference":null,"legacy":[]},{"id":"vstack_showcase","baseline":"screenshot-baselines/screens/vstack_showcase_720p.png","summary":"The stack positions and bright colors are deliberate layout specimens. Twenty-two proposals add readable labels and geometry guides without normalizing away the tested alignment differences. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"defect","priority":"P2","area":"Top title inset","observation":"vstack() Showcase starts at the left edge of the cyan bar.","change":"Add a 12 px title inset."},{"id":"02","kind":"proposal","priority":"P2","area":"Justification section","observation":"The top five cards have no shared JustifyContent heading.","change":"Add a clear main-axis justification heading above the row."},{"id":"03","kind":"proposal","priority":"P2","area":"Top captions","observation":"Start, Center, End, Between and Around are tiny.","change":"Increase their external label size to readable 12 px text."},{"id":"04","kind":"proposal","priority":"P2","area":"Between naming","observation":"Between abbreviates the actual spacing mode.","change":"Use Space between in the label and show the API name in metadata."},{"id":"05","kind":"proposal","priority":"P2","area":"Around naming","observation":"Around omits the meaning of edge spacing.","change":"Use Space around with a small edge-gap diagram."},{"id":"06","kind":"proposal","priority":"P2","area":"Main-axis direction","observation":"The top row demonstrates vertical placement without an axis arrow.","change":"Add a vertical main-axis guide beside the specimens."},{"id":"07","kind":"proposal","priority":"P2","area":"Start specimen","observation":"The three blocks begin at the top but have no start guide.","change":"Add an external top-edge marker."},{"id":"08","kind":"proposal","priority":"P2","area":"Center specimen","observation":"The centered group has no midpoint reference.","change":"Add a faint external centerline tick."},{"id":"09","kind":"proposal","priority":"P2","area":"End specimen","observation":"The block group ends near the bottom without a baseline marker.","change":"Add an external bottom-edge marker."},{"id":"10","kind":"proposal","priority":"P2","area":"Between gaps","observation":"The two interior gaps are not measured.","change":"Annotate the equal interior gap size outside the blocks."},{"id":"11","kind":"proposal","priority":"P2","area":"Around gaps","observation":"The edge gaps and interior gaps are visually different but unexplained.","change":"Label the expected 1:2 edge-to-interior spacing relationship."},{"id":"12","kind":"proposal","priority":"P2","area":"Block dimensions","observation":"Cyan, magenta and green blocks use different heights with no dimensions.","change":"Add a shared legend for their fixed sizes."},{"id":"13","kind":"proposal","priority":"P2","area":"Cross-axis heading","observation":"AlignItems cross-axis is tiny in the green strip.","change":"Increase heading size and reserve enough height for it."},{"id":"14","kind":"proposal","priority":"P2","area":"Cross-axis direction","observation":"The lower specimens do not show the horizontal axis.","change":"Add a horizontal cross-axis arrow above the four cards."},{"id":"15","kind":"proposal","priority":"P2","area":"Stretch specimen","observation":"The blue blocks retain visibly different widths under Stretch.","change":"Annotate their width constraints and add an auto-width control case to explain what stretch can affect."},{"id":"16","kind":"proposal","priority":"P2","area":"Lower specimen colors","observation":"Each alignment mode changes color as well as position.","change":"Use matching specimen colors across modes or label color as decorative."},{"id":"17","kind":"proposal","priority":"P2","area":"Lower captions","observation":"Start, Center, Stretch and End blend into thin green bars.","change":"Increase caption size and inner padding."},{"id":"18","kind":"proposal","priority":"P2","area":"Sidebar example","observation":"Sidebar + Content is a tiny label across a long blue bar.","change":"Increase it and identify this as an applied layout example."},{"id":"19","kind":"proposal","priority":"P2","area":"Navigation labels","observation":"Home, Settings, Profile and Help are very small.","change":"Increase label size without changing the sidebar layout structure."},{"id":"20","kind":"proposal","priority":"P2","area":"Content rows","observation":"Alerts, Activity and Stats touch their colored row edges.","change":"Add 10 to 12 px inner text padding."},{"id":"21","kind":"proposal","priority":"P2","area":"Static example semantics","observation":"The navigation and content rows look like an application without behavior explanation.","change":"Label them Static layout example unless they are interactive."},{"id":"22","kind":"proposal","priority":"P3","area":"Metadata space","observation":"The lower content pane has a large unused area.","change":"Use it for the vstack default width/height rules and measured dimensions."}],"sha256":"90463f83044553876ff635b1be85f7b12bbd04ff10c42ce9b880680e956c5d01","has_mock":false,"reference":null,"legacy":[]},{"id":"widget_gap_gallery","baseline":"screenshot-baselines/screens/widget_gap_gallery_720p.png","summary":"The gallery covers several previously unused widgets. Twenty-three findings clarify API specimen labels, icon choices and grouping without inferring behavior from the initial state. Fewer than 25 are listed because further findings from this static state would duplicate these points or require unseen interaction evidence.","findings":[{"id":"01","kind":"proposal","priority":"P2","area":"Page title","observation":"Widgets that had no caller describes project history rather than the displayed features.","change":"Use Widget integration gallery with the included component names beneath it."},{"id":"02","kind":"proposal","priority":"P2","area":"API headings","observation":"button_group, image and icon_row are terse code names.","change":"Pair each API name with a plain-language specimen title."},{"id":"03","kind":"proposal","priority":"P2","area":"Button group boundaries","observation":"Select, Move, Rotate and Scale touch with rounded edges at every join.","change":"Use clear segmented-group joins or uniform small gaps."},{"id":"04","kind":"proposal","priority":"P2","area":"Tool selection state","observation":"no tool picked yet is small and separated from the group.","change":"Use a labeled Selected tool status directly beneath the buttons."},{"id":"05","kind":"proposal","priority":"P2","area":"Tool action meaning","observation":"Select is both a tool name and a generic action.","change":"Add a short caption that the group chooses an editing tool."},{"id":"06","kind":"proposal","priority":"P2","area":"Pagination label","observation":"pagination is a small API name without content context.","change":"Use Pagination, five pages as the visible section heading."},{"id":"07","kind":"proposal","priority":"P2","area":"Previous arrow","observation":"The previous arrow looks enabled while page 1 is selected.","change":"Document wrap behavior or render a disabled boundary state if previous is unavailable."},{"id":"08","kind":"proposal","priority":"P2","area":"Selected page","observation":"Page 1 has several close white outlines.","change":"Use one clear selected-state outline distinct from keyboard focus styling."},{"id":"09","kind":"proposal","priority":"P2","area":"Page status","observation":"page 1 of 5 is small beneath the controls.","change":"Increase it and align it to the pagination group inset."},{"id":"10","kind":"proposal","priority":"P2","area":"Pagination width","observation":"The page buttons use inconsistent apparent widths beside narrow arrow controls.","change":"Use equal numeral cells with balanced end-control widths."},{"id":"11","kind":"proposal","priority":"P2","area":"Spacer demo label","observation":"spacer pushes the tail to the edge states the effect but not the flexible region.","change":"Add a faint external bracket over the space between head and tail."},{"id":"12","kind":"defect","priority":"P2","area":"Head label","observation":"head touches the left edge of its blue block.","change":"Inset the label by 10 px."},{"id":"13","kind":"defect","priority":"P2","area":"Tail label","observation":"tail touches the left edge of its brown block.","change":"Apply the same 10 px text inset."},{"id":"14","kind":"proposal","priority":"P2","area":"Spacer dimensions","observation":"Head and tail have no fixed-width metadata.","change":"Show fixed item widths and remaining flexible width below the sample."},{"id":"15","kind":"proposal","priority":"P2","area":"Image specimens","observation":"Gear, star and trophy images have no individual names.","change":"Add captions beneath each image tile."},{"id":"16","kind":"proposal","priority":"P2","area":"Image sizing","observation":"The three images have different visual mass inside equal tiles.","change":"Document source dimensions and display size, and center their visible bounds consistently."},{"id":"17","kind":"proposal","priority":"P2","area":"Icon-row repetition","observation":"Three identical home icons reveal little about spritesheet cell selection.","change":"Show three distinct labeled sprites from the same sheet."},{"id":"18","kind":"proposal","priority":"P2","area":"Icon-row spacing","observation":"The home icons lack a visible gap annotation.","change":"Add the configured icon size and gap below the row."},{"id":"19","kind":"proposal","priority":"P2","area":"Save icon","observation":"Save uses a gear icon that usually represents settings.","change":"Use a save icon or rename the action to Configure."},{"id":"20","kind":"proposal","priority":"P2","area":"Next icon","observation":"Next uses a star rather than a directional icon.","change":"Use a right arrow or rename the action to Favorite."},{"id":"21","kind":"proposal","priority":"P2","area":"Icon-side comparison","observation":"Left and right icon placement also changes the icon and label.","change":"Use the same icon and label in both positions for direct comparison."},{"id":"22","kind":"proposal","priority":"P3","area":"Section alignment","observation":"The left and right specimen sections use different vertical baselines.","change":"Align corresponding rows or give each specimen a clearly bounded card."},{"id":"23","kind":"proposal","priority":"P2","area":"Unused lower panels","observation":"Both columns leave large blank regions below the final specimens.","change":"Use them for concise dimensions, source asset names and expected-result notes."}],"sha256":"8abe23cefb8f3c725a04bae2a8d600aa6a493f946535585ef2abe82d30c07b09","has_mock":false,"reference":null,"legacy":[]}]};
